// Hyperrealistic Carved Laterite-Pink Sandstone Relief of an Unmade Bed
// Rendered with layered graphite, chiselled pencil, rose-ochre & grey-green lichen watercolour

const SEED = 48291;

// Heightfield grid covering [-60, 1260] x [-60, 1260] for seamless edge-to-edge bleed
const G_MIN = -60;
const G_MAX = 1260;
const G_SPAN = G_MAX - G_MIN;
const G_RES = 300;
const G_STEP = G_SPAN / (G_RES - 1);

let H_GRID, NX_GRID, NY_GRID, NZ_GRID, CURV_GRID, SHAD_GRID, LIGHT_GRID, LICHEN_GRID, PIT_GRID;

// Gather / tension hubs where the rumpled bedsheet is pinched and pulled
const GATHER_HUBS = [
  { x: 260, y: 290, pull: 1.35, rad: 340, ang: 0.45 },
  { x: 780, y: 250, pull: -1.15, rad: 380, ang: -0.35 },
  { x: 480, y: 560, pull: 1.55, rad: 420, ang: 0.25 },
  { x: 960, y: 610, pull: -1.30, rad: 390, ang: -0.50 },
  { x: 190, y: 740, pull: 1.20, rad: 350, ang: 0.60 },
  { x: 640, y: 890, pull: 1.45, rad: 410, ang: -0.20 },
  { x: 1050, y: 940, pull: -1.10, rad: 330, ang: 0.40 }
];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Add custom chiselled-stone & fine graphite brushes
  brush.add("chisel_edge", {
    type: "default",
    weight: 0.42,
    scatter: 0.04,
    sharpness: 0.92,
    grain: 0.45,
    opacity: 215,
    spacing: 0.14,
    pressure: [0.6, 1.25, 0.5],
    rotate: "natural",
    noise: 0.25
  });

  brush.add("stone_graphite", {
    type: "default",
    weight: 0.55,
    scatter: 0.18,
    sharpness: 0.68,
    grain: 0.78,
    opacity: 150,
    spacing: 0.22,
    pressure: [0.4, 1.15, 0.35],
    rotate: "natural",
    noise: 0.5
  });

  brush.add("mineral_chalk", {
    type: "default",
    weight: 0.52,
    scatter: 0.12,
    sharpness: 0.80,
    grain: 0.72,
    opacity: 195,
    spacing: 0.18,
    pressure: [0.3, 1.3, 0.3],
    rotate: "natural",
    noise: 0.35
  });

  buildSandstoneDraperyField();
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm, vivid sunlit laterite-pink sandstone ground
  background("#f4cbb6");

  // =========================================================================
  // 1. BASE LATERITE STONE UNDERTONE WASHES (Edge-to-Edge)
  // =========================================================================
  renderBaseStoneWashes();

  // =========================================================================
  // 2. LAYERED GRAPHITE UNDERDRAWING (Beneath the Watercolour Washes)
  // =========================================================================
  renderGraphiteUnderdrawing();

  // =========================================================================
  // 3. THIN WATERCOLOUR WASHES: ROSE-OCHRE, LATERITE & GREY-GREEN LICHEN
  // =========================================================================
  renderFoldWatercolourWashes();
  renderLichenWatercolourBlooms();

  // =========================================================================
  // 4. CHISELLED GRAPHITE PRECISION & RAKING-LIGHT RELIEF (Over the Washes)
  // =========================================================================
  renderChiselledSlopeHatching();
  renderIncisedTroughsAndCrevices();
  renderChiselledRidgesAndRakingHighlights();
  renderSandstonePitsSeamsAndLichenCrust();

  noLoop();
}

// ===========================================================================
// MATHEMATICAL DRAPERY & SANDSTONE RELIEF ENGINE
// ===========================================================================

// Sharp cloth fold profile: sculpted chiseled ridge crest + deep V-incised trough
function foldWave(phase, crestSharpness) {
  let s = Math.sin(phase);
  let c = Math.cos(phase);
  // Crisp ridge on top, incised V-cut at trough bottom
  let ridge = Math.pow(0.5 + 0.5 * c, crestSharpness);
  let vCut = -0.42 * Math.pow(1.0 - Math.abs(s), 2.4) * (c < 0 ? 1.0 : 0.15);
  // Asymmetric saw-tilt so folds lean and overlap like real rumpled linen
  let skew = 0.18 * Math.sin(2.0 * phase - 0.55);
  return ridge + vCut + skew;
}

// Sharp origami/linen tension crease (catenary ridge between pull points)
function creaseRidge(phase) {
  let u = Math.abs(Math.sin(phase));
  return 1.0 - Math.pow(u, 0.62);
}

// Smooth step helper
function smoothStep(e0, e1, x) {
  let t = Math.max(0, Math.min(1, (x - e0) / (e1 - e0)));
  return t * t * (3 - 2 * t);
}

function computeHeightAt(x, y) {
  // Multi-scale domain warping from Perlin noise
  let n1 = noise(x * 0.0018 + 11.3, y * 0.0018 + 7.1) - 0.5;
  let n2 = noise(x * 0.0042 + 31.7, y * 0.0042 + 19.4) - 0.5;
  let n3 = noise(x * 0.0095 + 53.2, y * 0.0095 + 41.8) - 0.5;

  // Apply tension/gathering displacement from the bedsheet pinch hubs
  let dx = n1 * 95 + n2 * 38;
  let dy = n1 * 75 + n2 * 42;
  let gatherAmp = 1.0;

  for (let k = 0; k < GATHER_HUBS.length; k++) {
    let g = GATHER_HUBS[k];
    let rx = x - g.x;
    let ry = y - g.y;
    let d2 = rx * rx + ry * ry;
    let r2 = g.rad * g.rad;
    if (d2 < r2 * 2.2) {
      let w = Math.exp(-d2 / r2);
      let ca = Math.cos(g.ang);
      let sa = Math.sin(g.ang);
      // Swirl and pinch folds toward the hub
      dx += w * g.pull * (rx * 0.22 * ca - ry * 0.34 * sa);
      dy += w * g.pull * (rx * 0.28 * sa + ry * 0.18 * ca);
      gatherAmp += 0.28 * w;
    }
  }

  let wx = x + dx;
  let wy = y + dy;

  // -------------------------------------------------------------------------
  // Horizontal Drapery Turnover Bands (The Unmade Bed Sheet Layers)
  // -------------------------------------------------------------------------
  // Band 1: Upper turned-back top sheet lip sweeping horizontally across frame
  let yTurn1 = 255 + 58 * Math.sin(x * 0.0048 + 0.6) + 32 * Math.cos(x * 0.011 - 0.4) + n1 * 65;
  let dTurn1 = y - yTurn1;
  let lip1 = 0.22 * Math.exp(-(dTurn1 * dTurn1) / (42 * 42)) - 0.12 * smoothStep(-35, 35, -dTurn1);

  // Band 2: Central dense rumpled billow (heart of the unmade bed)
  let yTurn2 = 595 + 68 * Math.cos(x * 0.0042 - 0.7) + 38 * Math.sin(x * 0.0105 + 1.1) + n1 * 75;
  let dTurn2 = y - yTurn2;
  let lip2 = 0.26 * Math.exp(-(dTurn2 * dTurn2) / (58 * 58)) + 0.08 * smoothStep(-50, 50, dTurn2);

  // Band 3: Lower bunched cascade near foot of bed
  let yTurn3 = 935 + 52 * Math.sin(x * 0.0052 + 2.0) + 28 * Math.cos(x * 0.013 + 0.3) + n2 * 55;
  let dTurn3 = y - yTurn3;
  let lip3 = 0.20 * Math.exp(-(dTurn3 * dTurn3) / (48 * 48)) - 0.09 * smoothStep(-40, 40, dTurn3);

  // Phase shift across turnover bands so folds step and overlap realistically
  let bandPhaseShift =
    0.85 * smoothStep(-28, 28, dTurn1) +
    0.70 * smoothStep(-36, 36, dTurn2) -
    0.75 * smoothStep(-30, 30, dTurn3);

  // -------------------------------------------------------------------------
  // Primary Rhythmic Temple-Frieze Drapery Folds (Catching Left Raking Light)
  // -------------------------------------------------------------------------
  let pMain =
    wx * 0.036 +
    Math.sin(wy * 0.0062 + n1 * 3.0) * 1.65 +
    bandPhaseShift +
    n2 * 1.35;
  let wMain = foldWave(pMain, 0.72);

  // Secondary bifurcating diagonal folds (forming Y-splits and eye/omega folds)
  let pDiagA =
    (wx * 0.025 - wy * 0.016) +
    1.4 * Math.cos(wy * 0.0075 + x * 0.002) +
    bandPhaseShift * 0.6 +
    n2 * 1.8;
  let wDiagA = foldWave(pDiagA, 0.80);

  let pDiagB =
    (wx * 0.022 + wy * 0.019) +
    1.2 * Math.sin(wx * 0.0065 - y * 0.003) -
    bandPhaseShift * 0.5 +
    n1 * 2.1;
  let wDiagB = foldWave(pDiagB, 0.85);

  // High-frequency pinched linen crinkles & radiating pleats near turnovers
  let pCrinkle1 = wx * 0.072 + wy * 0.028 + n2 * 3.4 + Math.sin(pMain) * 1.1;
  let wCrinkle1 = creaseRidge(pCrinkle1);

  let pCrinkle2 = wx * 0.058 - wy * 0.044 + n3 * 2.8 + Math.cos(pDiagA) * 0.9;
  let wCrinkle2 = creaseRidge(pCrinkle2);

  // Horizontal catenary sag folds between the vertical ridges
  let pCat = wy * 0.029 + Math.sin(pMain * 0.5) * 1.45 + n2 * 1.5;
  let wCat = foldWave(pCat, 0.90);

  // Combine fold systems with cloth interference mechanics
  let hCloth =
    0.42 * wMain +
    0.24 * wDiagA +
    0.19 * wDiagB +
    0.13 * wCat +
    0.11 * wCrinkle1 +
    0.08 * wCrinkle2;

  hCloth = hCloth * gatherAmp + lip1 + lip2 + lip3;

  // -------------------------------------------------------------------------
  // Shallow Sandstone Carving Transfer Function (Chisel Faceting & Terracing)
  // -------------------------------------------------------------------------
  // Subtle planar chisel steps along the slopes so it reads as carved stone
  let chiselSteps = 0.026 * Math.sin(hCloth * 22.0) + 0.012 * Math.sin(hCloth * 46.0);

  // Subtle horizontal sedimentary bedding striations in the sandstone block
  let strata = 0.014 * Math.sin(y * 0.085 + n2 * 4.0 + x * 0.008);

  // Fine vesicular pitting of laterite stone
  let nPit = noise(x * 0.045 + 100, y * 0.045 + 200);
  let pit = nPit < 0.28 ? -0.045 * Math.pow((0.28 - nPit) / 0.28, 1.8) : 0;

  return hCloth + chiselSteps + strata + pit;
}

function buildSandstoneDraperyField() {
  H_GRID = new Array(G_RES);
  NX_GRID = new Array(G_RES);
  NY_GRID = new Array(G_RES);
  NZ_GRID = new Array(G_RES);
  CURV_GRID = new Array(G_RES);
  SHAD_GRID = new Array(G_RES);
  LIGHT_GRID = new Array(G_RES);
  LICHEN_GRID = new Array(G_RES);
  PIT_GRID = new Array(G_RES);

  let minH = 1e9;
  let maxH = -1e9;

  for (let i = 0; i < G_RES; i++) {
    H_GRID[i] = new Float32Array(G_RES);
    NX_GRID[i] = new Float32Array(G_RES);
    NY_GRID[i] = new Float32Array(G_RES);
    NZ_GRID[i] = new Float32Array(G_RES);
    CURV_GRID[i] = new Float32Array(G_RES);
    SHAD_GRID[i] = new Float32Array(G_RES);
    LIGHT_GRID[i] = new Float32Array(G_RES);
    LICHEN_GRID[i] = new Float32Array(G_RES);
    PIT_GRID[i] = new Float32Array(G_RES);

    let x = G_MIN + i * G_STEP;
    for (let j = 0; j < G_RES; j++) {
      let y = G_MIN + j * G_STEP;
      let h = computeHeightAt(x, y);
      H_GRID[i][j] = h;
      if (h < minH) minH = h;
      if (h > maxH) maxH = h;
    }
  }

  // Normalize height to [0, 1]
  let rangeH = maxH - minH || 1;
  for (let i = 0; i < G_RES; i++) {
    for (let j = 0; j < G_RES; j++) {
      H_GRID[i][j] = (H_GRID[i][j] - minH) / rangeH;
    }
  }

  // Compute surface normals & curvature (ridge vs incised trough)
  // Shallow bas-relief vertical exaggeration factor for normal calculation
  const Z_SCALE = 115.0;
  for (let i = 0; i < G_RES; i++) {
    let im = Math.max(0, i - 1);
    let ip = Math.min(G_RES - 1, i + 1);
    for (let j = 0; j < G_RES; j++) {
      let jm = Math.max(0, j - 1);
      let jp = Math.min(G_RES - 1, j + 1);

      let dhdx = ((H_GRID[ip][j] - H_GRID[im][j]) * Z_SCALE) / ((ip - im) * G_STEP);
      let dhdy = ((H_GRID[i][jp] - H_GRID[i][jm]) * Z_SCALE) / ((jp - jm) * G_STEP);

      // Surface normal points (-dhdx, -dhdy, 1)
      let nx = -dhdx;
      let ny = -dhdy;
      let nz = 1.0;
      let len = Math.sqrt(nx * nx + ny * ny + nz * nz);
      NX_GRID[i][j] = nx / len;
      NY_GRID[i][j] = ny / len;
      NZ_GRID[i][j] = nz / len;

      // Mean curvature proxy (-Laplacian): > 0 is convex ridge crest, < 0 is incised trough
      let lap =
        H_GRID[ip][j] +
        H_GRID[im][j] +
        H_GRID[i][jp] +
        H_GRID[i][jm] -
        4.0 * H_GRID[i][j];
      CURV_GRID[i][j] = -lap * 42.0;
    }
  }

  // Ray-march raking cast shadows from the far left (x increasing along each row)
  // Low grazing sun elevation so every ridge throws a crisp temple-frieze shadow
  const SUN_SLOPE_PER_STEP = 0.0115;
  for (let j = 0; j < G_RES; j++) {
    let horizonH = H_GRID[0][j];
    for (let i = 0; i < G_RES; i++) {
      let h = H_GRID[i][j];
      if (h >= horizonH) {
        SHAD_GRID[i][j] = 1.0;
        horizonH = h;
      } else {
        let deficit = horizonH - h;
        // Soft penumbra at the shadow terminator edge
        SHAD_GRID[i][j] = Math.max(0.0, 1.0 - deficit * 16.5);
      }
      horizonH -= SUN_SLOPE_PER_STEP;
    }
  }

  // Compute combined illumination & grey-green lichen weathering field
  // Raking light vector from far left (-x), slightly from top (-y), shallow grazing z
  const LX = -0.925;
  const LY = -0.115;
  const LZ = 0.362;

  for (let i = 0; i < G_RES; i++) {
    let x = G_MIN + i * G_STEP;
    for (let j = 0; j < G_RES; j++) {
      let y = G_MIN + j * G_STEP;

      let nx = NX_GRID[i][j];
      let ny = NY_GRID[i][j];
      let nz = NZ_GRID[i][j];
      let curv = CURV_GRID[i][j];
      let shad = SHAD_GRID[i][j];

      let ndotl = Math.max(0, nx * LX + ny * LY + nz * LZ);
      // Direct raking light modulated by cast shadow
      let direct = ndotl * (0.28 + 0.72 * shad);
      // Ambient occlusion in deep incised troughs + bright crest enhancement
      let ao = Math.max(-0.22, Math.min(0.22, curv * 0.32));
      let lit = Math.max(0.02, Math.min(0.99, direct * 1.18 + 0.14 + ao));
      LIGHT_GRID[i][j] = lit;

      // Grey-green lichen colonizes damp incised troughs, sheltered right slopes, and mottled patches
      let lNoise1 = noise(x * 0.0055 + 77.1, y * 0.0055 + 33.8);
      let lNoise2 = noise(x * 0.016 + 140.2, y * 0.016 + 91.5);
      let troughAffinity = Math.max(0, -curv * 1.35) + Math.max(0, (0.52 - lit) * 0.85);
      let lichenVal = (lNoise1 * 0.68 + lNoise2 * 0.32) * (0.55 + troughAffinity);
      LICHEN_GRID[i][j] = Math.max(0, Math.min(1, (lichenVal - 0.36) * 2.3));

      // Laterite stone pitting field
      let pNoise = noise(x * 0.038 + 310, y * 0.038 + 420);
      PIT_GRID[i][j] = pNoise;
    }
  }
}

// Fast bilinear lookup helpers
function sampleGrid(grid, x, y) {
  let u = (x - G_MIN) / G_STEP;
  let v = (y - G_MIN) / G_STEP;
  let i = Math.floor(u);
  let j = Math.floor(v);
  if (i < 0) { i = 0; u = 0; }
  if (i >= G_RES - 1) { i = G_RES - 2; u = G_RES - 1; }
  if (j < 0) { j = 0; v = 0; }
  if (j >= G_RES - 1) { j = G_RES - 2; v = G_RES - 1; }
  let fu = u - i;
  let fv = v - j;
  let a = grid[i][j] * (1 - fu) + grid[i + 1][j] * fu;
  let b = grid[i][j + 1] * (1 - fu) + grid[i + 1][j + 1] * fu;
  return a * (1 - fv) + b * fv;
}

function getFieldAt(x, y) {
  return {
    h: sampleGrid(H_GRID, x, y),
    nx: sampleGrid(NX_GRID, x, y),
    ny: sampleGrid(NY_GRID, x, y),
    nz: sampleGrid(NZ_GRID, x, y),
    curv: sampleGrid(CURV_GRID, x, y),
    shad: sampleGrid(SHAD_GRID, x, y),
    light: sampleGrid(LIGHT_GRID, x, y),
    lichen: sampleGrid(LICHEN_GRID, x, y)
  };
}

// ===========================================================================
// LAYER 1: BASE LATERITE STONE UNDERTONE WASHES
// ===========================================================================

function renderBaseStoneWashes() {
  brush.noStroke();
  brush.noHatch();

  // Warm rose-ochre and vivid salmon-laterite broad washes covering the whole slab
  const baseBatches = [
    { col: "#f28e6b", alpha: 52, bleed: 0.42, tex: 0.65, border: 0.35, count: 14 },
    { col: "#e6674e", alpha: 48, bleed: 0.38, tex: 0.72, border: 0.42, count: 14 },
    { col: "#d94b4b", alpha: 44, bleed: 0.35, tex: 0.75, border: 0.45, count: 12 },
    { col: "#f09d59", alpha: 42, bleed: 0.40, tex: 0.68, border: 0.38, count: 12 }
  ];

  for (let b = 0; b < baseBatches.length; b++) {
    let batch = baseBatches[b];
    brush.fill(batch.col, batch.alpha);
    brush.fillBleed(batch.bleed, "out");
    brush.fillTexture(batch.tex, batch.border);

    for (let k = 0; k < batch.count; k++) {
      let cx = random(-40, 1240);
      let cy = random(-40, 1240);
      let rx = random(180, 360);
      let ry = random(110, 240);
      let rot = random(-25, 25);

      brush.beginShape(0.45);
      for (let a = 0; a < 360; a += 36) {
        let rad = 0.75 + 0.45 * noise(cx * 0.01 + k, a * 0.05);
        let px = cx + (rx * rad * cos(a)) * cos(rot) - (ry * rad * sin(a)) * sin(rot);
        let py = cy + (rx * rad * cos(a)) * sin(rot) + (ry * rad * sin(a)) * cos(rot);
        brush.vertex(px, py);
      }
      brush.endShape(true);
    }
  }
  brush.noFill();
}

// ===========================================================================
// LAYER 2: LAYERED GRAPHITE UNDERDRAWING (Under the Watercolour Washes)
// ===========================================================================

function renderGraphiteUnderdrawing() {
  brush.noFill();
  brush.noHatch();

  // Pass 2A: Long structural contour splines tracing the fold geometry
  const contourColors = ["#52343b", "#3d242b", "#66434a"];
  for (let cIdx = 0; cIdx < contourColors.length; cIdx++) {
    brush.set("2H", contourColors[cIdx], 0.85);
    for (let n = 0; n < 240; n++) {
      let sx = random(-30, 1230);
      let sy = random(-30, 1230);
      let pts = traceFoldStreamline(sx, sy, 8, 13.0, true);
      if (pts.length >= 4) {
        brush.spline(pts, 0.45);
      }
    }
  }

  // Pass 2B: Cross-contour graphite construction hatches on right-facing slopes
  brush.set("HB", "#452931", 0.75);
  for (let gx = -20; gx <= 1220; gx += 18) {
    for (let gy = -20; gy <= 1220; gy += 18) {
      let jx = gx + random(-6, 6);
      let jy = gy + random(-6, 6);
      let f = getFieldAt(jx, jy);

      // Underdraw shaded slopes and incised troughs
      if (f.light < 0.62) {
        let len = map(f.light, 0, 0.62, 24, 11, true);
        // Quantize angle slightly to give a chiseled planar construction feel
        let slopeAng = atan2(f.ny, f.nx);
        let qAng = Math.round(slopeAng / 12.0) * 12.0;
        let dx = cos(qAng) * len * 0.5;
        let dy = sin(qAng) * len * 0.5;
        brush.line(jx - dx, jy - dy, jx + dx, jy + dy);
      }
    }
  }
}

// Helper: Trace a streamline along the fold contour (-ny, nx)
function traceFoldStreamline(x0, y0, steps, stepLen, bidirectional) {
  let pts = [];
  if (bidirectional) {
    let backPts = [];
    let cx = x0;
    let cy = y0;
    for (let s = 0; s < Math.floor(steps / 2); s++) {
      let f = getFieldAt(cx, cy);
      let tx = -f.ny;
      let ty = f.nx;
      let mag = Math.sqrt(tx * tx + ty * ty) || 1;
      cx -= (tx / mag) * stepLen;
      cy -= (ty / mag) * stepLen;
      if (cx < -55 || cx > 1255 || cy < -55 || cy > 1255) break;
      backPts.push([cx, cy, 0.65 + 0.5 * (1 - f.light)]);
    }
    for (let i = backPts.length - 1; i >= 0; i--) {
      pts.push(backPts[i]);
    }
  }

  let cx = x0;
  let cy = y0;
  let f0 = getFieldAt(cx, cy);
  pts.push([cx, cy, 0.7 + 0.5 * (1 - f0.light)]);

  let fwdSteps = bidirectional ? Math.ceil(steps / 2) : steps;
  for (let s = 0; s < fwdSteps; s++) {
    let f = getFieldAt(cx, cy);
    let tx = -f.ny;
    let ty = f.nx;
    let mag = Math.sqrt(tx * tx + ty * ty) || 1;
    cx += (tx / mag) * stepLen;
    cy += (ty / mag) * stepLen;
    if (cx < -55 || cx > 1255 || cy < -55 || cy > 1255) break;
    pts.push([cx, cy, 0.65 + 0.5 * (1 - f.light)]);
  }
  return pts;
}

// ===========================================================================
// LAYER 3: FOLD-FOLLOWING WATERCOLOUR WASHES & LICHEN WEATHERING
// ===========================================================================

// Helper: Build a custom organic ribbon polygon that hugs a fold along its contour
function drawFoldRibbonPolygon(x0, y0, halfSteps, stepLen, baseHalfWidth) {
  let spine = [];
  let cx = x0;
  let cy = y0;

  // Step backward
  let back = [];
  for (let s = 0; s < halfSteps; s++) {
    let f = getFieldAt(cx, cy);
    let tx = -f.ny;
    let ty = f.nx;
    let mag = Math.sqrt(tx * tx + ty * ty) || 1;
    cx -= (tx / mag) * stepLen;
    cy -= (ty / mag) * stepLen;
    if (cx < -55 || cx > 1255 || cy < -55 || cy > 1255) break;
    back.push({ x: cx, y: cy, nx: f.nx / mag, ny: f.ny / mag });
  }
  for (let i = back.length - 1; i >= 0; i--) spine.push(back[i]);

  let f0 = getFieldAt(x0, y0);
  let m0 = Math.sqrt(f0.nx * f0.nx + f0.ny * f0.ny) || 1;
  spine.push({ x: x0, y: y0, nx: f0.nx / m0, ny: f0.ny / m0 });

  // Step forward
  cx = x0;
  cy = y0;
  for (let s = 0; s < halfSteps; s++) {
    let f = getFieldAt(cx, cy);
    let tx = -f.ny;
    let ty = f.nx;
    let mag = Math.sqrt(tx * tx + ty * ty) || 1;
    cx += (tx / mag) * stepLen;
    cy += (ty / mag) * stepLen;
    if (cx < -55 || cx > 1255 || cy < -55 || cy > 1255) break;
    spine.push({ x: cx, y: cy, nx: f.nx / mag, ny: f.ny / mag });
  }

  if (spine.length < 3) return;

  brush.beginShape(0.38);
  // Left flank of ribbon
  for (let i = 0; i < spine.length; i++) {
    let t = i / (spine.length - 1);
    let taper = Math.sin(t * Math.PI);
    let w = baseHalfWidth * (0.35 + 0.85 * taper) * random(0.82, 1.18);
    let p = spine[i];
    brush.vertex(p.x + p.nx * w, p.y + p.ny * w);
  }
  // Right flank of ribbon
  for (let i = spine.length - 1; i >= 0; i--) {
    let t = i / (spine.length - 1);
    let taper = Math.sin(t * Math.PI);
    let w = baseHalfWidth * (0.35 + 0.85 * taper) * random(0.82, 1.18);
    let p = spine[i];
    brush.vertex(p.x - p.nx * w, p.y - p.ny * w);
  }
  brush.endShape(true);
}

