function drawSeedBatch(seeds, maxCount, halfSteps, stepLen, halfWidth) {
  let step = Math.max(1, Math.floor(seeds.length / maxCount));
  let drawn = 0;
  for (let i = 0; i < seeds.length && drawn < maxCount; i += step) {
    let s = seeds[i];
    drawFoldRibbonPolygon(s.x, s.y, halfSteps, stepLen, halfWidth);
    drawn++;
  }
}

