// LAYER 4: CHISELLED GRAPHITE PRECISION, CROSS-HATCHING & RAKING HIGHLIGHTS
// ===========================================================================

function renderChiselledSlopeHatching() {
  brush.noFill();
  brush.noHatch();

  // Collect hatching tasks by pencil tone so we batch brush.set() calls cleanly
  let lightFacetLines = [];
  let midChiselLines = [];
  let darkSlopeLines = [];
  let crossHatchLines = [];
  let deepShadowLines = [];
  let warmOchrePencilLines = [];

  for (let gx = -18; gx <= 1218; gx += 10) {
    for (let gy = -18; gy <= 1218; gy += 10) {
      let x = gx + random(-3.5, 3.5);
      let y = gy + random(-3.5, 3.5);
      let f = getFieldAt(x, y);

      // Quantize slope angle to 10-degree increments to evoke flat-chisel facets in sandstone
      let slopeAng = atan2(f.ny, f.nx);
      let facetAng = Math.round(slopeAng / 10.0) * 10.0;
      let contourAng = facetAng + 90.0;

      // 1. Subtle 2H chisel-tooth marks on lit & turning facets
      if (f.light >= 0.52 && f.light < 0.78 && random() < 0.55) {
        let len = random(8, 15);
        let dx = cos(facetAng) * len * 0.5;
        let dy = sin(facetAng) * len * 0.5;
        if (random() < 0.45) {
          warmOchrePencilLines.push([x - dx, y - dy, x + dx, y + dy]);
        } else {
          lightFacetLines.push([x - dx, y - dy, x + dx, y + dy]);
        }
      }

      // 2. Crisp HB cross-contour hatching on mid-tone and right-facing slopes
      if (f.light < 0.58) {
        let len = map(f.light, 0, 0.58, 19, 10, true);
        let dx = cos(facetAng) * len * 0.5;
        let dy = sin(facetAng) * len * 0.5;
        midChiselLines.push([x - dx, y - dy, x + dx, y + dy]);
      }

      // 3. Denser 2B slope hatching in shadowed folds
      if (f.light < 0.40) {
        let len = map(f.light, 0, 0.40, 21, 11, true);
        let ang2 = facetAng + random(-6, 6);
        let dx = cos(ang2) * len * 0.5;
        let dy = sin(ang2) * len * 0.5;
        darkSlopeLines.push([x - dx, y - dy, x + dx, y + dy]);
      }

      // 4. Longitudinal cross-hatching following the trough axis in deeper shadows
      if (f.light < 0.32) {
        let len = random(13, 22);
        let cAng = contourAng + 18;
        let dx = cos(cAng) * len * 0.5;
        let dy = sin(cAng) * len * 0.5;
        crossHatchLines.push([x - dx, y - dy, x + dx, y + dy]);
      }

      // 5. Velvety deep graphite-umber hatching in the sharpest undercuts & cast shadows
      if (f.light < 0.20 || f.shad < 0.25) {
        let len = random(11, 18);
        let uAng = facetAng - 24;
        let dx = cos(uAng) * len * 0.5;
        let dy = sin(uAng) * len * 0.5;
        deepShadowLines.push([x - dx, y - dy, x + dx, y + dy]);
      }
    }
  }

  // Execute batched pencil hatching passes
  brush.set("cpencil", "#b5483c", 0.72);
  for (let i = 0; i < warmOchrePencilLines.length; i++) {
    let l = warmOchrePencilLines[i];
    brush.line(l[0], l[1], l[2], l[3]);
  }

  brush.set("2H", "#6b474e", 0.72);
  for (let i = 0; i < lightFacetLines.length; i++) {
    let l = lightFacetLines[i];
    brush.line(l[0], l[1], l[2], l[3]);
  }

  brush.set("HB", "#472931", 0.80);
  for (let i = 0; i < midChiselLines.length; i++) {
    let l = midChiselLines[i];
    brush.line(l[0], l[1], l[2], l[3]);
  }

  brush.set("stone_graphite", "#2e1820", 0.92);
  for (let i = 0; i < darkSlopeLines.length; i++) {
    let l = darkSlopeLines[i];
    brush.line(l[0], l[1], l[2], l[3]);
  }

  brush.set("2B", "#26131a", 0.85);
  for (let i = 0; i < crossHatchLines.length; i++) {
    let l = crossHatchLines[i];
    brush.line(l[0], l[1], l[2], l[3]);
  }

  brush.set("chisel_edge", "#170b10", 0.95);
  for (let i = 0; i < deepShadowLines.length; i++) {
    let l = deepShadowLines[i];
    brush.line(l[0], l[1], l[2], l[3]);
  }
}

function renderIncisedTroughsAndCrevices() {
  brush.noFill();
  brush.noHatch();

  let primaryTroughs = [];
  let hairlineCuts = [];
  let shadowTerminators = [];

  // Scan the field for concave incised V-troughs and sharp cast-shadow terminators
  for (let gx = -15; gx <= 1215; gx += 14) {
    for (let gy = -15; gy <= 1215; gy += 14) {
      let x = gx + random(-4, 4);
      let y = gy + random(-4, 4);
      let f = getFieldAt(x, y);

      // Deep incised V-troughs where two folds pinch together
      if (f.curv < -0.17) {
        let pts = traceFoldStreamline(x, y, 6, 9.5, true);
        if (pts.length >= 4) {
          primaryTroughs.push(pts);
          // Offset by 2px to the right for the lit inner bevel of the incised V-cut
          if (f.curv < -0.26) {
            let bevelPts = [];
            for (let k = 0; k < pts.length; k++) {
              bevelPts.push([pts[k][0] - 1.8, pts[k][1], pts[k][2] * 1.1]);
            }
            hairlineCuts.push(bevelPts);
          }
        }
      }

      // Cast-shadow terminator edges thrown across the troughs
      if (f.shad > 0.18 && f.shad < 0.72 && f.light < 0.42 && random() < 0.55) {
        let pts = traceFoldStreamline(x, y, 5, 8.5, true);
        if (pts.length >= 4) {
          shadowTerminators.push(pts);
        }
      }
    }
  }

  // Draw soft graphite shadow-terminator edges
  brush.set("stone_graphite", "#381d26", 0.88);
  for (let i = 0; i < shadowTerminators.length; i++) {
    brush.spline(shadowTerminators[i], 0.45);
  }

  // Draw incised trough graphite lines
  brush.set("2B", "#241118", 0.95);
  for (let i = 0; i < primaryTroughs.length; i++) {
    brush.spline(primaryTroughs[i], 0.35);
  }

  // Draw razor-sharp burin/chisel V-cuts in the deepest fold crevices
  brush.set("chisel_edge", "#14080d", 1.05);
  for (let i = 0; i < hairlineCuts.length; i++) {
    brush.spline(hairlineCuts[i], 0.28);
  }
}

function renderChiselledRidgesAndRakingHighlights() {
  brush.noFill();
  brush.noHatch();

  let sunlitCrests = [];
  let blindingRimCrests = [];
  let ridgeArrisGraphite = [];
  let secondaryCreases = [];

  for (let gx = -15; gx <= 1215; gx += 13) {
    for (let gy = -15; gy <= 1215; gy += 13) {
      let x = gx + random(-3.5, 3.5);
      let y = gy + random(-3.5, 3.5);
      let f = getFieldAt(x, y);

      // Sharp convex chiseled ridges
      if (f.curv > 0.15) {
        let pts = traceFoldStreamline(x, y, 6, 9.0, true);
        if (pts.length >= 4) {
          // Left lip of ridge catches raking light from far left
          let litPts = [];
          // Right arris of ridge gets a crisp graphite chisel line where the plane turns away
          let arrisPts = [];
          for (let k = 0; k < pts.length; k++) {
            let p = pts[k];
            litPts.push([p[0] - 1.6, p[1] - 0.3, 0.95]);
            arrisPts.push([p[0] + 1.8, p[1] + 0.3, 0.85]);
          }

          if (f.light > 0.58) {
            sunlitCrests.push(litPts);
            if (f.light > 0.74 && f.curv > 0.24) {
              blindingRimCrests.push(litPts);
            }
          } else {
            secondaryCreases.push(litPts);
          }
          ridgeArrisGraphite.push(arrisPts);
        }
      } else if (f.light > 0.78 && f.nx < -0.45 && random() < 0.42) {
        // Steep left-facing slopes struck directly by raking light
        let pts = traceFoldStreamline(x, y, 5, 8.5, true);
        if (pts.length >= 4) {
          sunlitCrests.push(pts);
        }
      }
    }
  }

  // 1. Warm coral-ochre highlight strokes on secondary ridges
  brush.set("cpencil", "#ffad89", 0.90);
  for (let i = 0; i < secondaryCreases.length; i++) {
    brush.spline(secondaryCreases[i], 0.38);
  }

  // 2. Luminous sunlit pink-sandstone mineral highlights along primary ridge lips
  brush.set("mineral_chalk", "#ffd8c2", 1.05);
  for (let i = 0; i < sunlitCrests.length; i++) {
    brush.spline(sunlitCrests[i], 0.35);
  }

  // 3. Blinding raking-light rim edge on the highest chiseled crests
  brush.set("chisel_edge", "#fff3e8", 0.95);
  for (let i = 0; i < blindingRimCrests.length; i++) {
    brush.spline(blindingRimCrests[i], 0.30);
  }

  // 4. Crisp 2H/chisel graphite line immediately to the right of every ridge crest
  // This pairing (bright left lip + sharp dark right arris) creates razor-sharp 3D relief
  brush.set("chisel_edge", "#381e26", 0.82);
  for (let i = 0; i < ridgeArrisGraphite.length; i++) {
    brush.spline(ridgeArrisGraphite[i], 0.32);
  }
}

function renderSandstonePitsSeamsAndLichenCrust() {
  brush.noFill();
  brush.noHatch();

  // -------------------------------------------------------------------------
  // A. Ancient Sandstone Block Joints / Hairline Weathering Fissures
  // -------------------------------------------------------------------------
  // Subtle masonry/geological hairline seams crossing the relief
  const seamY = [342, 796];
  for (let s = 0; s < seamY.length; s++) {
    let baseY = seamY[s];
    let seamDark = [];
    let seamLit = [];
    for (let x = -40; x <= 1240; x += 18) {
      let f = getFieldAt(x, baseY);
      // Seam deflects slightly over the 3D relief height
      let y = baseY - f.h * 16.0 + (noise(x * 0.015, s * 10) - 0.5) * 9.0;
      seamDark.push([x, y, 0.75 + 0.35 * (1 - f.light)]);
      seamLit.push([x, y + 1.8, 0.70 * f.light]);
    }
    brush.set("chisel_edge", "#261219", 0.72);
    brush.spline(seamDark, 0.35);
    brush.set("chisel_edge", "#ffcfb5", 0.62);
    brush.spline(seamLit, 0.35);
  }

  // -------------------------------------------------------------------------
  // B. Crustose Lichen Thallus Stippling & Botanical Colony Margins
  // -------------------------------------------------------------------------
  let lichenDarkDots = [];
  let lichenSageTicks = [];
  let lichenLimeHighlights = [];
  let pitShadows = [];
  let pitLitRims = [];

  for (let gx = -12; gx <= 1212; gx += 16) {
    for (let gy = -12; gy <= 1212; gy += 16) {
      let x = gx + random(-6, 6);
      let y = gy + random(-6, 6);
      let f = getFieldAt(x, y);

      // Lichen crust detail where lichen watercolour washes settled
      if (f.lichen > 0.34) {
        let clusterCount = Math.floor(map(f.lichen, 0.34, 1, 2, 6));
        for (let c = 0; c < clusterCount; c++) {
          let lx = x + random(-9, 9);
          let ly = y + random(-9, 9);
          let len = random(2.2, 4.8);
          let ang = random(360);
          let dx = cos(ang) * len * 0.5;
          let dy = sin(ang) * len * 0.5;

          if (c % 3 === 0) {
            lichenDarkDots.push([lx - dx, ly - dy, lx + dx, ly + dy]);
          } else if (c % 3 === 1) {
            lichenSageTicks.push([lx - dx, ly - dy, lx + dx, ly + dy]);
          } else if (f.light > 0.35) {
            lichenLimeHighlights.push([lx - dx, ly - dy, lx + dx, ly + dy]);
          }
        }
      }

      // Vesicular laterite stone pits:
      // In raking light from the left, a sunken pit is shadowed on its LEFT inner wall
      // and catches a tiny bright rim on its RIGHT edge!
      let pVal = sampleGrid(PIT_GRID, x, y);
      if (pVal < 0.29 && random() < 0.65) {
        let pr = random(1.4, 3.2);
        pitShadows.push([x - pr, y - pr * 0.6, x - pr * 0.2, y + pr * 0.8]);
        if (f.light > 0.38) {
          pitLitRims.push([x + pr * 0.3, y - pr * 0.7, x + pr, y + pr * 0.7]);
        }
      }
    }
  }

  // Render lichen crust marks
  brush.set("chisel_edge", "#234034", 0.82);
  for (let i = 0; i < lichenDarkDots.length; i++) {
    let l = lichenDarkDots[i];
    brush.line(l[0], l[1], l[2], l[3]);
  }

  brush.set("cpencil", "#6ea67c", 0.88);
  for (let i = 0; i < lichenSageTicks.length; i++) {
    let l = lichenSageTicks[i];
    brush.line(l[0], l[1], l[2], l[3]);
  }

  brush.set("mineral_chalk", "#b8d46c", 0.82);
  for (let i = 0; i < lichenLimeHighlights.length; i++) {
    let l = lichenLimeHighlights[i];
    brush.line(l[0], l[1], l[2], l[3]);
  }

  // Render sunken sandstone pits (left shadow + right lit rim)
  brush.set("chisel_edge", "#210e15", 0.85);
  for (let i = 0; i < pitShadows.length; i++) {
    let l = pitShadows[i];
    brush.line(l[0], l[1], l[2], l[3]);
  }

  brush.set("chisel_edge", "#ffe2cc", 0.78);
  for (let i = 0; i < pitLitRims.length; i++) {
    let l = pitLitRims[i];
    brush.line(l[0], l[1], l[2], l[3]);
  }
}

// Hyperrealism in p5.brush: Steamed Bathroom Mirror, Diagonal Palm Wipe,
// Coloured-Pencil Lathered Jaw, Razor Mid-Stroke & Nick of Carmine

const WIPE_AX = 165, WIPE_AY = 855;
const WIPE_BX = 995, WIPE_BY = 315;
const WIPE_DX = WIPE_BX - WIPE_AX;
const WIPE_DY = WIPE_BY - WIPE_AY;
const WIPE_LEN = Math.hypot(WIPE_DX, WIPE_DY);
const WIPE_UX = WIPE_DX / WIPE_LEN;
const WIPE_UY = WIPE_DY / WIPE_LEN;
const WIPE_NX = -WIPE_UY; // Points down-right
const WIPE_NY = WIPE_UX;
const WIPE_ANGLE = -33.05;

// Signed distance and local coordinates relative to the diagonal palm wipe
function getWipeData(x, y) {
  let vx = x - WIPE_AX;
  let vy = y - WIPE_AY;
  let t = (vx * WIPE_UX + vy * WIPE_UY) / WIPE_LEN;
  let sRaw = vx * WIPE_NX + vy * WIPE_NY;

  // Natural upward ergonomic arc of a palm swipe across glass
  let arcShift = -38 * Math.sin(constrain(t, 0, 1.05) * Math.PI);
  let s = sRaw - arcShift;

  // Base half-width of the palm swath
  let halfW = 192;
  if (t < 0.16) {
    let u = constrain(t / 0.16, 0, 1);
    halfW = 192 * Math.sqrt(max(0.01, u * (2 - u)));
  } else if (t > 0.72) {
    // 4 distinct finger tracks at the upper-right termination of the swipe
    let fingerCenters = [-132, -44, 44, 130];
    let fingerRadii = [48, 52, 50, 44];
    let fingerReaches = [0.96, 1.04, 0.99, 0.89];
    let minD = 9999;
    for (let i = 0; i < 4; i++) {
      let fc = fingerCenters[i];
      let fr = fingerRadii[i];
      let tmax = fingerReaches[i];
      let dt = max(0, (t - 0.72) / (tmax - 0.72));
      let ds = (s - fc) / fr;
      let dFinger = ( Math.hypot(dt, ds) - 1.0 ) * fr;
      if (dFinger < minD) minD = dFinger;
    }
    let edgeNoise = (noise(x * 0.015, y * 0.015) - 0.5) * 14;
    return { d: minD + edgeNoise, t, s };
  }

  // Lower-left palm heel rounding
  let d = Math.abs(s) - halfW;
  if (t < 0) {
    d = Math.hypot(-t * WIPE_LEN * 0.85, max(0, Math.abs(s) - 65)) - 115;
  }

  // Subtle organic skin-contact edge variation
  let n = (noise(x * 0.018, y * 0.018) - 0.5) * 16 + (noise(x * 0.06, y * 0.06) - 0.5) * 6;
  return { d: d + n, t, s };
}

function isInsideWipe(x, y, margin = 0) {
  return getWipeData(x, y).d < margin;
}

// Helper for drawing filled/washed shapes with brush.beginShape
function drawShapePoly(pts, curvature = 0.15, close = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(close);
}

// Helper to clip a polygon against the wipe boundary by clamping vertices inside
function clampPointToWipe(x, y, margin = -2) {
  let cx = x, cy = y;
  for (let iter = 0; iter < 5; iter++) {
    let wd = getWipeData(cx, cy);
    if (wd.d <= margin) break;
    let push = wd.d - margin;
    if (wd.t < 0.05) {
      cx += WIPE_UX * push * 0.7;
      cy += WIPE_UY * push * 0.7;
    } else if (wd.t > 0.88) {
      cx -= WIPE_UX * push * 0.7;
      cy -= WIPE_UY * push * 0.7;
    }
    let signS = wd.s >= 0 ? -1 : 1;
    cx += WIPE_NX * signS * push * 0.85;
    cy += WIPE_NY * signS * push * 0.85;
  }
  return [cx, cy];
}

// Jawline lower boundary function y(x) for anatomical alignment
function getJawY(x) {
  // Gonion at (310, 590), sweeps down to chin prominence at (570, 706), then up right cheek to (760, 540)
  if (x < 310) return 590 - (310 - x) * 1.4;
  if (x <= 570) {
    let u = (x - 310) / 260;
    return 590 + 116 * Math.pow(u, 0.78) + 12 * Math.sin(u * Math.PI);
  }
  let u = constrain((x - 570) / 195, 0, 1.2);
  return 706 - 168 * Math.pow(u, 1.35);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7391);
  noiseSeed(7391);

  // Add custom surgical hyperrealism brushes after scaleBrushes(3)
  brush.add("fine_cpencil", {
    type: "default",
    weight: 0.9,
