  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm breath-white / pearl base ground
  background("#eaeff0");

  // =========================================================================
  // 1. STEAMED MIRROR BACKGROUND: WET-INTO-WET WATERCOLOUR FOG, TILES & TOWEL
  // =========================================================================
  drawSteamedEnvironment();

  // =========================================================================
  // 2. SURGICAL WINDOW BASE: HIGH-CONTRAST OPAQUE WASHES & WATERCOLOUR PLANES
  // =========================================================================
  drawWipeBasePlanes();

  // =========================================================================
  // 3. CRISP COLOURED-PENCIL HYPERREALISM INSIDE THE WIPE
  // =========================================================================
  drawClearTilesInWipe();
  drawNeckAndSubmandibularShadow();
  drawFreshlyShavedJawAndLip();
  drawShavingFoamMasses();
  drawStubbleAndPores();
  drawCarmineNickAndBleed();
  drawSafetyRazorMidStroke();

  // =========================================================================
  // 4. WIPE BOUNDARY SMEAR, CONDENSATION RIDGE & SHARP DRIP CHANNELS
  // =========================================================================
  drawWipeBoundaryAndDripChannels();

  // =========================================================================
  // 5. FINAL ATMOSPHERIC BREATH MIST & GLASS MICRO-BEADS
  // =========================================================================
  drawFinalSteamMistAndDroplets();

  noLoop();
}

// ---------------------------------------------------------------------------
// 1. WET-INTO-WET WATERCOLOUR STEAM, SWALLOWED TEAL TILES & TOWEL
// ---------------------------------------------------------------------------
function drawSteamedEnvironment() {
  brush.noStroke();

  // 1A. Deep Teal Tiles swallowed by wet-into-wet blooms (Upper-Left, Top, Right)
  brush.fillBleed(0.48, "out");
  brush.fillTexture(0.78, 0.22);

  let tileRows = [-20, 140, 300, 460, 620, 780, 940, 1080];
  let tileCols = [-20, 180, 380, 580, 780, 980];

  // Batch 1: Darker submerged teal tiles in upper-left and right
  brush.fill("#174e54", 68);
  for (let r = 0; r < tileRows.length; r++) {
    let y = tileRows[r];
    let xOff = (r % 2) * 95;
    for (let c = 0; c < tileCols.length; c++) {
      let x = tileCols[c] + xOff;
      // Skip tiles heavily covered by the man's silhouette or towel in lower-right
      if (x > 260 && x < 760 && y > 320 && y < 950) continue;
      if (x > 680 && y > 680) continue;
      if (random() < 0.65) {
        brush.rect(x + random(-8, 8), y + random(-8, 8), 165, 130, "corner");
      }
    }
  }

  // Batch 2: Lighter sea-glass teal blooms swallowing the tile edges
  brush.fillBleed(0.55, "out");
  brush.fill("#2b6e75", 52);
  for (let i = 0; i < 16; i++) {
    let x = random(40, 1140);
    let y = random(40, 720);
    if (isInsideWipe(x, y, 40)) continue;
    brush.circle(x, y, random(75, 160), 0.35);
  }

  // 1B. Blurred Towel draped in lower-right & mid-left behind the steam
  brush.fillBleed(0.45, "out");
