  drawShapePoly([
    [760, 640], [1180, 590], [1210, 1210], [640, 1210], [690, 860]
  ], 0.25);
  drawShapePoly([
    [20, 860], [210, 910], [260, 1210], [-20, 1210]
  ], 0.25);

  brush.fill("#8c7c6b", 62);
  drawShapePoly([
    [820, 720], [1160, 690], [1180, 1180], [740, 1180]
