  // Warm vertical towel folds dissolving into fog
  brush.fill("#dfd6c7", 80);
  for (let i = 0; i < 6; i++) {
    let tx = 790 + i * 68;
    drawShapePoly([
      [tx, 660 + i * 12], [tx + 36, 670 + i * 12],
