  drawShapePoly([
    [290, 120], [740, 110], [820, 420], [740, 890],
    [680, 1190], [140, 1190], [210, 740], [250, 360]
  ], 0.35);

  brush.fill("#3d2219", 55);
  drawShapePoly([
    [330, 180], [680, 190], [650, 1080], [230, 1080], [270, 520]
  ], 0.35);

  // 1D. Rolling Wet-into-Wet Watercolour Fog in Pearl Grey & Warm Breath-White
  // Batch 1: Pearl grey rolling clouds
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.82, 0.28);
  brush.fill("#b7c3c7", 82);
  for (let i = 0; i < 22; i++) {
    let x = random(50, 1150);
    let y = random(50, 1150);
    if (isInsideWipe(x, y, -30)) continue;
    brush.circle(x, y, random(95, 220), 0.4);
  }

  // Batch 2: Deeper cool slate-pearl condensation pockets
  brush.fill("#8c9ea3", 58);
  let slateClouds = [
    [140, 210, 150], [980, 150, 170], [1060, 560, 160],
    [130, 580, 130], [520, 960, 180], [840, 860, 165],
    [340, 1080, 155], [640, 140, 140], [1020, 1040, 175]
  ];
  for (let c of slateClouds) {
    brush.circle(c[0], c[1], c[2], 0.42);
  }

  // Batch 3: Warm breath-white blooms swallowing the background around the face
  brush.fillBleed(0.48, "in");
  brush.fillTexture(0.7, 0.32);
  brush.fill("#f4f0e6", 115);
  for (let i = 0; i < 26; i++) {
    let x = random(60, 1140);
    let y = random(60, 1140);
    if (isInsideWipe(x, y, -10)) continue;
    brush.circle(x, y, random(80, 195), 0.38);
  }

  // Batch 4: Luminous mist veil right near the wipe margins
  brush.fill("#faf8f2", 130);
  for (let i = 0; i < 24; i++) {
    let t = map(i, 0, 23, 0.02, 0.98);
    let side = (i % 2 === 0) ? 1 : -1;
    let dist = random(210, 340) * side;
    let cx = WIPE_AX + t * WIPE_DX + WIPE_NX * dist;
    let cy = WIPE_AY + t * WIPE_DY + WIPE_NY * dist;
    brush.circle(cx, cy, random(75, 145), 0.35);
  }

  // Subtle dissolved grout lines peeking through the upper-left and upper-right fog
  brush.set("2H", "#5d7a80", 0.35);
  for (let y of [140, 300, 460, 620, 780]) {
    for (let seg = 0; seg < 12; seg++) {
      let x1 = seg * 100 + random(-10, 10);
      let x2 = x1 + random(40, 85);
      if (isInsideWipe((x1 + x2) * 0.5, y, 50)) continue;
      if (random() < 0.45) {
        brush.line(x1, y + random(-2, 2), x2, y + random(-2, 2));
      }
    }
  }
  brush.noStroke();
}

// ---------------------------------------------------------------------------
// 2. SURGICAL WINDOW BASE PLANES (OPAQUE WASHES FOR HIGH CONTRAST)
// ---------------------------------------------------------------------------
function drawWipeBasePlanes() {
  brush.noStroke();
  brush.noFill();

  // Sample closed boundary polygon of the entire palm wipe
  let wipePoly = [];
  // Upper edge (t from 0 to 0.75)
  for (let i = 0; i <= 24; i++) {
    let t = map(i, 0, 24, 0.0, 0.74);
    let arcShift = -38 * Math.sin(t * Math.PI);
    let w = (t < 0.16) ? 192 * Math.sqrt(max(0.05, (t / 0.16) * (2 - t / 0.16))) : 192;
    let x = WIPE_AX + t * WIPE_DX + WIPE_NX * (arcShift - w);
    let y = WIPE_AY + t * WIPE_DY + WIPE_NY * (arcShift - w);
    wipePoly.push([x, y]);
  }
  // 4 Finger lobes at the top-right end
  let fingerTips = [
    [-168, 0.80], [-132, 0.96], [-88, 0.86],
    [-44, 1.04], [2, 0.88],
    [44, 0.99], [86, 0.85],
    [130, 0.89], [172, 0.76]
  ];
  for (let ft of fingerTips) {
    let s = ft[0], t = ft[1];
    let arcShift = -38 * Math.sin(constrain(t, 0, 1) * Math.PI);
    let x = WIPE_AX + t * WIPE_DX + WIPE_NX * (arcShift + s);
    let y = WIPE_AY + t * WIPE_DY + WIPE_NY * (arcShift + s);
    wipePoly.push([x, y]);
  }
  // Lower edge (t from 0.72 down to 0)
  for (let i = 24; i >= 0; i--) {
    let t = map(i, 0, 24, 0.0, 0.72);
    let arcShift = -38 * Math.sin(t * Math.PI);
    let w = (t < 0.16) ? 192 * Math.sqrt(max(0.05, (t / 0.16) * (2 - t / 0.16))) : 192;
    let x = WIPE_AX + t * WIPE_DX + WIPE_NX * (arcShift + w);
    let y = WIPE_AY + t * WIPE_DY + WIPE_NY * (arcShift + w);
    wipePoly.push([x, y]);
  }
  // Palm heel arc at t < 0
  for (let a = 70; a >= -70; a -= 28) {
    let rad = a * Math.PI / 180;
    let t = -0.095 * Math.cos(rad);
    let s = 135 * Math.sin(rad);
    let x = WIPE_AX + t * WIPE_DX + WIPE_NX * s;
    let y = WIPE_AY + t * WIPE_DY + WIPE_NY * s;
    wipePoly.push([x, y]);
  }

  // 2A. Deep obsidian-teal base wash across the entire clear window
  brush.wash("#071e22", 248);
  drawShapePoly(wipePoly, 0.12);

  // 2B. Warm underpainting wash for the face & neck area inside the wipe
  let facePoly = [
    clampPointToWipe(310, 410),
    clampPointToWipe(520, 350),
    clampPointToWipe(755, 340),
    clampPointToWipe(775, 520),
    clampPointToWipe(680, 690),
    clampPointToWipe(595, 810),
    clampPointToWipe(275, 960),
    clampPointToWipe(240, 740),
    clampPointToWipe(305, 575)
  ];
  brush.wash("#452118", 245);
  drawShapePoly(facePoly, 0.1);

  // 2C. Mid-value warm terracotta-bisque skin wash on the jaw & cheek
  let litJawPoly = [
    clampPointToWipe(335, 440),
    clampPointToWipe(550, 370),
    clampPointToWipe(745, 380),
    clampPointToWipe(735, 565),
    clampPointToWipe(575, 704),
    clampPointToWipe(425, 670),
    clampPointToWipe(315, 585)
  ];
  brush.wash("#a8644c", 235);
  drawShapePoly(litJawPoly, 0.15);

  // 2D. Bright warm highlight wash on the freshly shaved jaw corridor
  let shavedGlowPoly = [
    clampPointToWipe(425, 495),
    clampPointToWipe(565, 490),
    clampPointToWipe(580, 645),
    clampPointToWipe(430, 650)
  ];
  brush.wash("#d9987c", 225);
  drawShapePoly(shavedGlowPoly, 0.18);

  // 2E. Deep submandibular shadow wash directly beneath the jawline
  let neckShadowPoly = [
    clampPointToWipe(312, 588),
    clampPointToWipe(435, 672),
    clampPointToWipe(572, 706),
    clampPointToWipe(625, 675),
    clampPointToWipe(585, 795),
    clampPointToWipe(435, 845),
    clampPointToWipe(255, 920),
    clampPointToWipe(250, 745)
  ];
  brush.wash("#1f0c08", 240);
  drawShapePoly(neckShadowPoly, 0.12);

  brush.noWash();
}

// ---------------------------------------------------------------------------
// 3A. DEEP HIGH-CONTRAST TEAL TILES IN THE CLEAR WIPE BACKGROUND
// ---------------------------------------------------------------------------
function drawClearTilesInWipe() {
  // Left side of neck/jaw (x < 318) and right side of face/lather (x > 740)
  brush.set("cpencil", "#0d3840", 0.55);

  // Vertical colored-pencil shading strokes in the glossy dark tiles
  for (let x = 90; x <= 1090; x += 4) {
    // Only draw in the tile background zones (left of face/neck, or right of cheek)
    let isLeftTile = x < 312;
    let isRightTile = x > 748;
    if (!isLeftTile && !isRightTile) continue;

    for (let y = 180; y <= 980; y += 22) {
      if (!isInsideWipe(x, y, -6)) continue;
      // Avoid overlapping the lower neck on the left
      if (isLeftTile && x > 255 && y > 585) continue;

      let n = noise(x * 0.02, y * 0.02);
      let col = n > 0.58 ? "#164e57" : (n > 0.3 ? "#0c3138" : "#05161a");
      brush.set("cpencil", col, 0.48);
      brush.line(x, y, x + random(-2, 2), min(y + 20, 980));
    }
  }

  // Crisp recessed tile grout lines & razor-sharp ceramic bevel highlights inside the wipe
  let clearGroutY = [300, 460, 620, 780, 940];
  for (let gy of clearGroutY) {
    for (let x = 80; x < 1090; x += 6) {
      if (!isInsideWipe(x, gy, -5)) continue;
      if (x >= 258 && x <= 752 && gy > 360) continue;
      // Dark grout recess
      brush.set("rotring", "#020b0d", 0.55);
      brush.line(x, gy, x + 6, gy);
      // Glossy ceramic lower bevel catchlight
      brush.set("fine_cpencil", "#4b8e96", 0.35);
      brush.line(x, gy + 3, x + 6, gy + 3);
    }
  }

  // Vertical tile joints in the clear window
  let vJoints = [
    [180, 460, 620], [275, 620, 780], [180, 780, 940],
    [875, 180, 300], [780, 300, 460], [970, 300, 460], [875, 460, 620]
  ];
  for (let vj of vJoints) {
    let vx = vj[0], y1 = vj[1], y2 = vj[2];
    for (let y = y1; y < y2; y += 6) {
      if (!isInsideWipe(vx, y, -5)) continue;
      brush.set("rotring", "#020b0d", 0.5);
      brush.line(vx, y, vx, y + 6);
      brush.set("fine_cpencil", "#3e7d85", 0.32);
      brush.line(vx + 3, y, vx + 3, y + 6);
    }
  }
}

// ---------------------------------------------------------------------------
// 3B. NECK, STERNOCLEIDOMASTOID & SUBMANDIBULAR CHIAROSCURO SHADOW
// ---------------------------------------------------------------------------
function drawNeckAndSubmandibularShadow() {
  // Directional anatomical hatching on the neck (x: 245..620, y below jawline)
  for (let x = 245; x <= 620; x += 3.5) {
    let jawY = getJawY(x);
    for (let y = jawY + 2; y <= 965; y += 9) {
      if (!isInsideWipe(x, y, -4)) continue;

      let distFromJaw = y - jawY;
      // Sternocleidomastoid diagonal ridge runs from (315, 610) toward (465, 890)
      let scmCenter = 315 + (y - 610) * 0.54;
      let distSCM = Math.abs(x - scmCenter);
      // Laryngeal prominence (Adam's apple) around (495, 795)
      let distLarynx = Math.hypot(x - 495, (y - 795) * 1.2);

      let col = "#240e0a";
      let w = 0.42;

      if (distFromJaw < 34) {
        // Deep core cast shadow directly under the mandible
        col = distFromJaw < 16 ? "#140604" : "#260f0b";
        w = 0.48;
      } else if (distFromJaw < 58) {
        // Warm reflected bounce light & subsurface scatter border
        col = "#4a2016";
      } else if (distSCM < 32) {
        // Lit muscular ridge of the sternocleidomastoid
        col = distSCM < 14 ? "#995840" : "#733d2b";
      } else if (distLarynx < 38) {
        col = (x < 495) ? "#8c4e39" : "#381810";
      } else {
        col = (x < 380) ? "#3b1b14" : "#5c2d20";
      }

      // Cool teal ambient reflection on the far-left neck edge
      if (x < 292 && distFromJaw > 25) {
        col = "#2f383b";
      }

      brush.set("fine_cpencil", col, w);
      let ang = 68 + 14 * Math.sin((x - 300) * 0.015);
      let dx = Math.cos(ang * Math.PI / 180) * 12;
      let dy = Math.sin(ang * Math.PI / 180) * 12;
      brush.line(x, y, x + dx, y + dy);
    }
  }

  // Cross-contour skin crease lines across the neck
  for (let creaseY of [755, 815, 868]) {
    for (let x = 285; x <= 555; x += 8) {
      let cy = creaseY + 14 * Math.sin((x - 280) * 0.012);
      if (!isInsideWipe(x, cy, -6) || cy < getJawY(x) + 18) continue;
      brush.set("2B", "#1c0a07", 0.3);
      brush.line(x, cy, x + 9, cy + 2);
      brush.set("fine_cpencil", "#8a4d38", 0.25);
      brush.line(x, cy + 2.5, x + 9, cy + 4.5);
    }
  }
}

// ---------------------------------------------------------------------------
// 3C. COLOURED-PENCIL JAW, FRESHLY SHAVED CORRIDOR & LOWER LIP
// ---------------------------------------------------------------------------
function drawFreshlyShavedJawAndLip() {
  // 1. Coloured-pencil cross-contouring across the entire exposed jaw, chin & cheek
  for (let y = 340; y <= 706; y += 3.2) {
    for (let x = 310; x <= 755; x += 4.5) {
      if (!isInsideWipe(x, y, -4)) continue;
      let jawY = getJawY(x);
      if (y > jawY) continue;

      // Skip lower lip box (handled with specialized lip strokes right after)
      if (x > 485 && x < 685 && y > 405 && y < 495) continue;

      // Distance from jawline border
      let dJaw = jawY - y;
      // Labiomental shadow hollow below the lower lip (around x: 510..660, y: 495..535)
      let dHollow = Math.hypot((x - 580) * 0.65, y - 512);
      // Chin pad prominence around (565, 615)
      let dChin = Math.hypot((x - 565) * 0.8, (y - 615) * 0.9);
      // Freshly shaved wet highlight ridge around x: 455..520, y: 515..635
      let dWetRidge = Math.abs(x - (472 + (y - 500) * 0.18));

      let col = "#b87458";
      let weight = 0.38;

      if (dHollow < 34) {
        col = dHollow < 18 ? "#59281d" : "#7d3d2d";
      } else if (dJaw < 18) {
        // Reflected core shadow along the bottom curve of the mandible
        col = dJaw < 8 ? "#4a2118" : "#783c2c";
      } else if (x >= 420 && x <= 575 && y >= 490 && y <= 650) {
        // The freshly shaved corridor! Taut, warm, wet glowing skin
        if (dWetRidge < 16 && y > 515 && y < 630) {
          col = dWetRidge < 7 ? "#fae3d4" : "#ebbca3";
          weight = 0.42;
        } else if (dWetRidge < 36) {
          col = "#d99273";
        } else {
          col = "#be7458";
        }
      } else if (dChin < 55) {
        col = dChin < 26 ? "#e6af96" : "#c78166";
      } else if (x < 420) {
        // Left cheek / gonion plane turning away from main light
        col = x < 355 ? "#703929" : "#96533e";
      } else {
        col = "#b06c52";
      }

      // Add subtle subsurface carmine/rose warmth near the foam borders and cheek
      if (random() < 0.22 && dWetRidge >= 14) {
        col = (y < 560) ? "#ba5d50" : "#9e4b3b";
      }

      brush.set("fine_cpencil", col, weight);
      // Follow 3D facial contour angle
      let contourAng = 18 - (x - 480) * 0.14;
      let len = 9;
      let dx = Math.cos(contourAng * Math.PI / 180) * len;
      let dy = Math.sin(contourAng * Math.PI / 180) * len;
      brush.line(x, y, x + dx, y + dy);
    }
  }

  // 2. Burnished white colored-pencil wet skin speculars along the freshly shaved jaw
  for (let i = 0; i < 95; i++) {
    let sy = random(512, 632);
    let sx = 470 + (sy - 500) * 0.18 + random(-11, 11);
    if (!isInsideWipe(sx, sy, -6)) continue;
    brush.set("fine_cpencil", random() < 0.45 ? "#ffffff" : "#f7dfd0", 0.32);
    brush.line(sx, sy, sx + random(4, 9), sy + random(2, 6));
  }

  // Crisp jawline boundary definition where the mandible meets the deep neck shadow
  for (let x = 312; x <= 685; x += 4) {
    let jy = getJawY(x);
    if (!isInsideWipe(x, jy, -5)) continue;
    brush.set("2B", "#140503", 0.42);
    brush.line(x, jy, x + 5, getJawY(x + 5));
    // Subsurface crimson-ochre glow just above the shadow terminator
    brush.set("fine_cpencil", "#8a3324", 0.35);
    brush.line(x, jy - 3, x + 5, getJawY(x + 5) - 3);
  }

  // 3. THE LOWER LIP & MOUTH CORNER (Upper-center of the wipe: x 485..685, y 400..495)
  // Dark oral fissure (mouth opening line)
  for (let x = 488; x <= 680; x += 3) {
    let u = (x - 488) / 192;
    let mouthY = 442 - 8 * Math.sin(u * Math.PI) + (u - 0.5) * -10;
    if (!isInsideWipe(x, mouthY, -4)) continue;

    // Upper lip shadow margin just above the oral fissure
    for (let uy = mouthY - 28; uy < mouthY; uy += 3.5) {
      if (!isInsideWipe(x, uy, -4)) continue;
      brush.set("fine_cpencil", uy > mouthY - 10 ? "#3d1614" : "#6e332c", 0.38);
      brush.line(x, uy, x + 2, uy + 5);
    }

    // Deep umber-carmine oral fissure
    brush.set("rotring", "#1f0606", 0.65);
    brush.line(x, mouthY, x + 3.5, mouthY - 0.5);
    brush.set("fine_cpencil", "#541515", 0.45);
    brush.line(x, mouthY + 2, x + 3.5, mouthY + 2);

    // Plump lower lip vermilion body (from mouthY + 3 down to lipBottomY)
    let lipDepth = 46 * Math.sin(constrain(u, 0.04, 0.96) * Math.PI);
    let lipBottomY = mouthY + lipDepth;

    for (let ly = mouthY + 3; ly <= lipBottomY; ly += 2.8) {
      if (!isInsideWipe(x, ly, -4)) continue;
      let v = (ly - mouthY) / max(1, lipDepth);
      let lCol = "#9e423d";
      if (v < 0.22) lCol = "#692220";
      else if (v < 0.52) lCol = (random() < 0.45) ? "#e89b93" : "#c7645c";
      else if (v < 0.78) lCol = "#a84842";
      else lCol = "#6b2924";

      brush.set("fine_cpencil", lCol, 0.34);
      // Curved vertical anatomical lip sulci
      let curveX = (u - 0.45) * 4;
      brush.line(x, ly, x + curveX, ly + 4);
    }

    // Crisp vertical lip creases & moist white specular catchlights across the lower lip roll
    if (x % 9 === 0 && u > 0.12 && u < 0.88) {
      let creaseTop = mouthY + lipDepth * 0.18;
      let creaseBot = mouthY + lipDepth * 0.85;
      if (isInsideWipe(x, (creaseTop + creaseBot) * 0.5, -5)) {
        brush.set("rotring", "#4f1715", 0.28);
        brush.line(x, creaseTop, x + (u - 0.45) * 5, creaseBot);
        brush.set("fine_cpencil", "#ffffff", 0.35);
        brush.line(x + 1.5, mouthY + lipDepth * 0.32, x + 2, mouthY + lipDepth * 0.48);
      }
    }
  }
}

// ---------------------------------------------------------------------------
// 3D. SCULPTED SHAVING FOAM MASSES & HUNDREDS OF MICRO-BUBBLES
// ---------------------------------------------------------------------------
function drawShavingFoamMasses() {
  // We have 3 primary sculpted shaving lather zones:
  // Zone 1: Left Cheek & Jaw Angle lather bank (x: 312..428, y: 455..635)
  // Zone 2: Right Chin, Jaw & Cheek lather bank (x: 562..760, y: 440..700)
  // Zone 3: Lower Neck foam trail (x: 335..545, y: 695..775)

  brush.noStroke();
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.45, 0.15);

  // Base opaque washes for the thick white shaving cream banks
  let leftFoamPts = [
    clampPointToWipe(320, 465),
    clampPointToWipe(425, 482),
    clampPointToWipe(418, 555),
    clampPointToWipe(428, 632),
    clampPointToWipe(355, 628),
    clampPointToWipe(312, 582),
    clampPointToWipe(314, 515)
  ];
  brush.wash("#c8d4d9", 242);
  drawShapePoly(leftFoamPts, 0.22);

  let rightFoamPts = [
    clampPointToWipe(572, 495),
    clampPointToWipe(680, 435),
    clampPointToWipe(758, 430),
    clampPointToWipe(748, 560),
    clampPointToWipe(655, 655),
    clampPointToWipe(570, 702),
    clampPointToWipe(558, 610)
  ];
  brush.wash("#d6e0e4", 245);
  drawShapePoly(rightFoamPts, 0.22);

  let neckFoamPts = [
    clampPointToWipe(345, 698),
    clampPointToWipe(465, 712),
    clampPointToWipe(545, 725),
    clampPointToWipe(520, 768),
    clampPointToWipe(415, 758),
    clampPointToWipe(335, 735)
  ];
  brush.wash("#9eb0b8", 230);
  drawShapePoly(neckFoamPts, 0.25);

  // Bright pure-white highlight pillows on the upper-left faces of the foam banks
  brush.wash("#f7fafb", 245);
  drawShapePoly([
    clampPointToWipe(332, 475), clampPointToWipe(422, 488),
    clampPointToWipe(415, 585), clampPointToWipe(345, 565)
  ], 0.25);

  drawShapePoly([
    clampPointToWipe(575, 502), clampPointToWipe(695, 448),
    clampPointToWipe(725, 525), clampPointToWipe(635, 615),
    clampPointToWipe(564, 595)
  ], 0.25);
  brush.noWash();

  // Coloured-pencil 3D sculpting of the foam ridges, shadows, and clean razor-cut wall!
  // Along x ≈ 422 (left wall of shaved path) and x ≈ 565 (right wall of shaved path),
  // the razor has sliced a crisp cliff through the thick foam!
  for (let y = 482; y <= 632; y += 2.5) {
    let lx = 422 + 5 * Math.sin(y * 0.05);
    if (isInsideWipe(lx, y, -4)) {
      // Cast shadow of the left foam ridge onto the wet shaved skin
      brush.set("fine_cpencil", "#7a402e", 0.38);
      brush.line(lx + 1, y, lx + 8, y + 2);
      // Thick sunlit white ridge of cut foam
      brush.set("fine_cpencil", "#ffffff", 0.55);
      brush.line(lx - 10, y - 1, lx, y);
      // Cool blue-grey shadow trough inside the left foam bank
      brush.set("fine_cpencil", "#7f949e", 0.42);
      brush.line(lx - 38, y + 2, lx - 14, y);
    }
  }

  for (let y = 495; y <= 685; y += 2.5) {
    let rx = 566 + 6 * Math.cos(y * 0.045);
    if (isInsideWipe(rx, y, -4)) {
      // Shadow wall of the right cut foam cliff (facing away from upper-left light)
      brush.set("fine_cpencil", "#6b828c", 0.45);
      brush.line(rx, y, rx + 12, y + 1);
      // Bright titanium white crest just behind the shadow wall
      brush.set("fine_cpencil", "#ffffff", 0.58);
      brush.line(rx + 12, y, rx + 38, y - 3);
      // Sculpted mid-tone and deep teal-grey shadow on far right of cheek foam
      brush.set("fine_cpencil", "#8ea3ad", 0.42);
      brush.line(rx + 65, y - 2, rx + 115, y + 6);
    }
  }

  // Sculpt the lower neck foam trail
  for (let x = 338; x <= 540; x += 3.5) {
    let ny = 715 + 10 * Math.sin(x * 0.03);
    if (!isInsideWipe(x, ny, -5)) continue;
    brush.set("fine_cpencil", "#657a85", 0.45);
    brush.line(x, ny + 14, x + 8, ny + 28);
    brush.set("fine_cpencil", "#e8eff2", 0.45);
    brush.line(x, ny - 6, x + 8, ny + 8);
  }

  // Draw hundreds of hyperrealistic individual foam bubbles!
  let bubbleZones = [
    { x1: 318, x2: 425, y1: 468, y2: 630, count: 165 },
    { x1: 562, x2: 750, y1: 445, y2: 690, count: 240 },
    { x1: 340, x2: 538, y1: 702, y2: 762, count: 85 }
  ];

  for (let bz of bubbleZones) {
    for (let i = 0; i < bz.count; i++) {
      let bx = random(bz.x1, bz.x2);
      let by = random(bz.y1, bz.y2);
      if (!isInsideWipe(bx, by, -5)) continue;
      if (by > getJawY(bx) + 6 && bz.y2 < 700) continue;

      let r = random() < 0.18 ? random(3.8, 7.2) : random(1.4, 3.6);
      // Dark interior of the soap bubble
      brush.set("rotring", random() < 0.5 ? "#5a707a" : "#7d939e", 0.32);
      brush.circle(bx, by, r, 0.15);
      // Crisp white specular rim / catchlight on upper-left of bubble
      brush.set("fine_cpencil", "#ffffff", 0.38);
      brush.arc(bx, by, r, 195, 330);
    }
  }
}

// ---------------------------------------------------------------------------
// 3E. HYPERREALISTIC STUBBLE HAIRS & SHAVED FOLLICLE PORES
// ---------------------------------------------------------------------------
function drawStubbleAndPores() {
  // 1. Coarse unshaved dark beard stubble on upper-left cheek (above foam: y < 480),
  // around the mouth/chin cleft, peeking through thin foam edges, and on the lower neck!
  for (let y = 355; y <= 920; y += 5.5) {
    for (let x = 265; x <= 745; x += 5.5) {
      let hx = x + random(-2.2, 2.2);
      let hy = y + random(-2.2, 2.2);
      if (!isInsideWipe(hx, hy, -5)) continue;

      let jawY = getJawY(hx);
      // Skip tile background
      if (hx < 312 && hy < 590) continue;
      if (hx > 748) continue;
      // Skip lower lip vermilion
      if (hx > 488 && hx < 680 && hy > 432 && hy < 492) continue;
      // Skip razor head area
      if (hx > 418 && hx < 612 && hy > 628 && hy < 688) continue;

      // Determine if this point is in thick opaque foam, freshly shaved corridor, or unshaved stubble
      let inLeftFoam = (hx >= 322 && hx <= 418 && hy >= 475 && hy <= 625);
      let inRightFoam = (hx >= 572 && hx <= 740 && hy >= 455 && hy <= 685 && hy <= jawY);
      let inNeckFoam = (hx >= 342 && hx <= 535 && hy >= 702 && hy <= 760);
      let inShavedZone = (hx > 418 && hx < 568 && hy > 488 && hy < 645);

      if (inLeftFoam || inRightFoam || inNeckFoam) {
        // Occasional stubble hair poking right through the thin edge of the foam!
        let nearEdge = (Math.abs(hx - 418) < 12) || (Math.abs(hx - 572) < 12) || (hy < 488);
        if (!nearEdge || random() > 0.35) continue;
      }

      if (inShavedZone) {
        // Freshly shaved skin: microscopic cut follicle dots flush with the pores!
        brush.set("rotring", random() < 0.5 ? "#2e1812" : "#4a2c24", 0.32);
        brush.line(hx, hy, hx + 1.1, hy + 1.3);
        if (random() < 0.25) {
          brush.set("fine_cpencil", "#f5cbb8", 0.22);
          brush.line(hx - 1, hy - 1, hx, hy - 0.5);
        }
        continue;
      }

      // Unshaved coarse stubble hair!
      // Natural hair growth direction: downward and sweeping toward the chin / down the neck
      let ang = 75;
      if (hy < jawY) {
        ang = 52 + (hx - 450) * 0.12 + random(-8, 8);
      } else {
        // Neck whorl pattern
        ang = 82 - (hx - 420) * 0.18 + random(-10, 10);
      }

      let len = random(3.2, 6.2);
      let dx = Math.cos(ang * Math.PI / 180) * len;
      let dy = Math.sin(ang * Math.PI / 180) * len;

      // Follicle pore shadow at root
      brush.set("fine_cpencil", "#4a2016", 0.35);
      brush.line(hx - 0.8, hy - 0.8, hx + 0.5, hy + 0.5);

      // Crisp beard shaft (dark espresso/black with occasional copper/silver glint hair)
      let hairCol = "#120907";
      let rVal = random();
      if (rVal < 0.12) hairCol = "#b89f8d"; // Silver/blonde glint hair
      else if (rVal < 0.35) hairCol = "#38211a";

      brush.set("stubble_tip", hairCol, random(0.32, 0.48));
      brush.line(hx, hy, hx + dx, hy + dy);

      // Tiny wet skin highlight beside the emerging hair follicle
      if (hy < jawY && random() < 0.35) {
        brush.set("fine_cpencil", "#f2c6b0", 0.24);
        brush.line(hx - 1.2, hy, hx - 0.2, hy + 1.0);
      }
    }
  }
}

// ---------------------------------------------------------------------------
// 3F. THE NICK OF CARMINE & CAPILLARY FOAM BLEED
// ---------------------------------------------------------------------------
function drawCarmineNickAndBleed() {
  // Positioned on the freshly shaved curve of the jaw at (476, 558)
  const nx = 476, ny = 558;

  // 1. Subsurface erythematous flush around the nick
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fill("#c92236", 85);
  brush.circle(nx + 2, ny + 4, 18, 0.25);

  // Capillary pink-carmine bloom where the trickle touches the right/lower foam bank (around 490..568, 575..620)
  brush.fillBleed(0.35, "out");
  brush.fill("#e01b35", 110);
  brush.circle(555, 588, 22, 0.35);
  brush.fill("#ff5972", 95);
  brush.circle(564, 596, 30, 0.4);
  brush.noFill();

  // 2. The surgical skin incision line (tiny horizontal-diagonal nick)
  brush.set("rotring", "#380006", 0.68);
  brush.line(nx - 9, ny - 2, nx + 7, ny + 1);
  brush.set("fine_cpencil", "#8a0012", 0.55);
  brush.line(nx - 10, ny - 1, nx + 8, ny + 2.5);

  // 3. Plump jewel-like droplet of vivid carmine blood welling from the cut
  brush.noStroke();
  brush.wash("#7a0010", 250);
  brush.circle(nx + 1, ny + 4.5, 6.8, 0.12);
  brush.wash("#c90620", 250);
  brush.circle(nx + 0.5, ny + 3.5, 5.6, 0.1);
  brush.wash("#ff1e3a", 245);
  brush.circle(nx + 1.5, ny + 5.2, 3.6, 0.1);
  brush.noWash();

  // Deep shadow under the blood bead
  brush.set("rotring", "#2b0004", 0.45);
  brush.arc(nx + 1, ny + 4.5, 7.0, 20, 165);

  // Thin carmine rivulet running down the wet skin from (477, 564) to the blade foam roll & right foam edge
  brush.set("rotring", "#9e0219", 0.52);
  brush.spline([
    [nx + 1, ny + 6, 1.0],
    [nx + 4, ny + 22, 0.85],
    [nx + 9, ny + 40, 0.7],
    [nx + 12, ny + 66, 0.9]
  ], 0.35);

  brush.set("fine_cpencil", "#ff2e49", 0.38);
  brush.spline([
    [nx + 2, ny + 7, 0.9],
    [nx + 5, ny + 22, 0.75],
    [nx + 10, ny + 40, 0.6]
  ], 0.35);

  // Lateral capillary branching into the foam edge at (550..572, 578..608)
  for (let i = 0; i < 28; i++) {
    let bx = random(546, 578);
    let by = random(572, 614);
    let r = random(1.5, 4.2);
    let cCol = random() < 0.4 ? "#b8041c" : (random() < 0.6 ? "#e82742" : "#ff758a");
    brush.set("rotring", cCol, 0.34);
    brush.circle(bx, by, r, 0.2);
  }
  // Feeder thread along skin groove to the foam bank
  brush.set("rotring", "#b5061e", 0.35);
  brush.spline([
    [nx + 5, ny + 18, 0.8],
    [515, 582, 0.6],
    [556, 589, 0.8]
  ], 0.4);

  // Pinpoint pure-white wet specular catchlight on top of the carmine blood droplet
  brush.set("rotring", "#ffffff", 0.65);
  brush.line(nx - 2.2, ny + 1.5, nx - 0.5, ny + 2.2);
  brush.line(nx - 1.8, ny + 2.3, nx - 0.8, ny + 2.8);
}

// ---------------------------------------------------------------------------
// 3G. THE SAFETY RAZOR MID-STROKE, FOAM ROLL & KNURLED CHROME HANDLE
// ---------------------------------------------------------------------------
function drawSafetyRazorMidStroke() {
  // Razor head center at (515, 662), angled at -10 degrees
  // Spans from x = 420 to x = 610, y = 632 to y = 692
  // Handle extends from (518, 682) down-right to (605, 865)

  // 1. Cast shadow of the razor head and handle onto the jaw & neck
  brush.noStroke();
  brush.wash("#0d0403", 230);
  drawShapePoly([
    clampPointToWipe(425, 668),
    clampPointToWipe(605, 646),
    clampPointToWipe(612, 695),
    clampPointToWipe(565, 855),
    clampPointToWipe(495, 865),
    clampPointToWipe(485, 702),
    clampPointToWipe(422, 686)
  ], 0.15);

  // 2. Chrome Razor Head Base Planes
  // Top cap curved chrome body
  let capPts = [
    [420, 660], [435, 645], [515, 634], [595, 628],
    [612, 640], [608, 656], [424, 676]
  ];
  brush.wash("#1b2d33", 252);
  drawShapePoly(capPts, 0.18);

  // Scalloped safety bar / baseplate below the blade
  let guardPts = [
    [424, 674], [608, 654], [605, 672], [428, 690]
  ];
  brush.wash("#0a161a", 252);
  drawShapePoly(guardPts, 0.1);

  // 3. The Knurled Chrome Handle Base Plane (extending down to the wipe edge)
  let handlePts = [
    clampPointToWipe(498, 678),
    clampPointToWipe(538, 674),
    clampPointToWipe(608, 838),
    clampPointToWipe(564, 858)
  ];
  brush.wash("#18262b", 250);
  drawShapePoly(handlePts, 0.08);
  brush.noWash();

  // 4. High-Contrast Chrome Reflections on the Razor Head
  // Alternating obsidian, deep teal, silver-steel, and pure white specular bands
  let numHeadStripes = 22;
  for (let i = 0; i <= numHeadStripes; i++) {
    let v = i / numHeadStripes;
    let yLeft = lerp(647, 688, v);
    let yRight = lerp(630, 670, v);

    let col = "#22363d";
    let w = 0.52;
    if (v < 0.14) { col = "#c9d6dc"; }
    else if (v < 0.28) { col = "#061114"; w = 0.6; } // Dark obsidian reflection band
    else if (v < 0.45) { col = "#ffffff"; w = 0.65; } // Blinding chrome highlight band
    else if (v < 0.56) { col = "#133b42"; } // Reflected bathroom teal
    else if (v < 0.68) { col = "#eef4f7"; w = 0.58; } // Exposed surgical razor blade edge!
    else if (v < 0.82) { col = "#081317"; w = 0.58; } // Recessed gap under blade
    else { col = "#7f949c"; } // Lower safety bar rim

    brush.set("fine_cpencil", col, w);
    brush.line(424, yLeft, 608, yRight);
  }

  // Scalloped comb teeth along the safety guard bar (v around 0.72..0.95)
  for (let i = 0; i < 19; i++) {
    let u = i / 18;
    let tx = lerp(430, 602, u);
    let ty = lerp(675, 656, u);
    // Bright chrome tooth top
    brush.set("rotring", "#ffffff", 0.48);
    brush.line(tx, ty, tx + 3, ty + 11);
    brush.line(tx + 1.5, ty, tx + 4.5, ty + 11);
    // Deep black slot between guard teeth
    brush.set("rotring", "#03090b", 0.52);
    brush.line(tx + 5, ty, tx + 8, ty + 11);
  }

  // 5. PILE OF SCRAPED SHAVING FOAM, CUT STUBBLE & CARMINE STREAK ON THE BLADE!
  // Billowing cylinder of displaced foam along the leading upper edge of the razor (x: 422..604, y: 618..658)
  brush.noStroke();
  let bladeFoamPts = [
    [420, 646], [450, 628], [495, 622], [545, 616],
    [595, 614], [608, 632], [595, 644], [515, 652], [424, 662]
  ];
  brush.wash("#d0dce0", 248);
  drawShapePoly(bladeFoamPts, 0.28);

  // Pure white top billows of the scraped foam roll
  brush.wash("#ffffff", 248);
  drawShapePoly([
    [426, 642], [465, 625], [525, 618], [588, 616],
    [585, 632], [510, 640], [432, 650]
  ], 0.3);

  // Pink-carmine blood stain mixed into the scraped foam roll right below the nick (x: 472..508)
  brush.wash("#f0485e", 215);
  brush.circle(488, 634, 14, 0.3);
  brush.wash("#ff8fa0", 195);
  brush.circle(496, 638, 19, 0.35);
  brush.noWash();

  // Detailed colored-pencil sculpting & micro-bubbles on the blade's foam roll
  for (let i = 0; i < 95; i++) {
    let u = random(0, 1);
    let fx = lerp(424, 602, u);
    let fy = lerp(648, 626, u) + random(-14, 8);
    let r = random(1.4, 4.5);
    let isBloody = (fx > 474 && fx < 512);
    let bCol = isBloody ? "#c91830" : (random() < 0.5 ? "#69808a" : "#8ea2ab");
    brush.set("rotring", bCol, 0.32);
    brush.circle(fx, fy, r, 0.2);
    brush.set("fine_cpencil", isBloody ? "#ffd6dc" : "#ffffff", 0.36);
    brush.arc(fx, fy, r, 190, 340);
  }

  // Dozens of tiny black/brown cut stubble clippings trapped in the blade's foam roll!
  for (let i = 0; i < 75; i++) {
    let u = random(0.04, 0.94);
    let sx = lerp(428, 596, u);
    let sy = lerp(646, 626, u) + random(-11, 7);
    let ang = random(0, 180);
    let len = random(2.2, 4.8);
    brush.set("stubble_tip", random() < 0.7 ? "#120806" : "#361e17", 0.42);
    brush.line(sx, sy, sx + Math.cos(ang) * len, sy + Math.sin(ang) * len);
  }

  // 6. Precision Diamond Knurling & Cylindrical Chrome Reflections on the Handle
  let hSteps = 34;
  for (let i = 0; i <= hSteps; i++) {
    let t = i / hSteps;
    // Axis of handle from (518, 678) to (586, 848)
    let cx = lerp(518, 586, t);
    let cy = lerp(678, 848, t);
    if (!isInsideWipe(cx, cy, -5)) continue;

    // Perpendicular direction across handle width (radius ~ 21 px)
    let nx = 0.928, ny = -0.371;

    // Chrome neck collar rings near top of handle (t < 0.18)
    if (t < 0.18) {
      brush.set("rotring", (i % 2 === 0) ? "#ffffff" : "#071216", 0.55);
      brush.line(cx - nx * 16, cy - ny * 16, cx + nx * 16, cy + ny * 16);
      continue;
    }

    // Cylindrical specular highlight stripes & diamond knurling across the barrel
    for (let s = -20; s <= 20; s += 3.5) {
      let px = cx + nx * s;
      let py = cy + ny * s;
      if (!isInsideWipe(px, py, -4)) continue;

      let normS = s / 20; // -1 to 1 across cylinder
      let kCol = "#2e4047";
      if (normS < -0.65) kCol = "#5b747d"; // Left edge bounce light
      else if (normS < -0.25) kCol = "#ffffff"; // Main cylindrical specular strip
      else if (normS < 0.2) kCol = "#081317"; // Core dark metallic reflection
      else if (normS < 0.6) kCol = "#7d949c"; // Secondary steel highlight
      else kCol = "#050d10"; // Right shadow edge

      brush.set("rotring", kCol, 0.38);
      // Criss-cross diamond knurling strokes
      brush.line(px - 2.5, py + 1.5, px + 2.5, py + 3.5);
      if ((i + Math.round(s)) % 2 === 0 && Math.abs(normS + 0.42) < 0.25) {
        // Blinding white diamond facets along the highlight ridge
        brush.set("rotring", "#ffffff", 0.45);
        brush.line(px - 1.5, py - 1.5, px + 1.5, py + 1.5);
      }
    }
  }

  // Glimpse of the man's wet thumb gripping the lower-right of the handle inside the wipe (around 575, 765)
  let thumbPts = [
    clampPointToWipe(558, 742),
    clampPointToWipe(612, 732),
    clampPointToWipe(635, 775),
    clampPointToWipe(595, 818),
    clampPointToWipe(552, 788)
  ];
  brush.noStroke();
  brush.wash("#7a3e2c", 242);
  drawShapePoly(thumbPts, 0.28);
  brush.noWash();

  for (let y = 736; y <= 812; y += 3.2) {
    for (let x = 555; x <= 628; x += 4) {
      if (!isInsideWipe(x, y, -5)) continue;
      if (Math.hypot(x - 592, y - 775) > 38) continue;
      let dTop = y - 736;
      let tCol = dTop < 16 ? "#e0a287" : (dTop < 36 ? "#b0654b" : "#592619");
      brush.set("fine_cpencil", tCol, 0.38);
      brush.line(x, y, x + 6, y - 2);
    }
  }
  // Wet highlight on thumb knuckle
  brush.set("fine_cpencil", "#ffffff", 0.42);
  brush.arc(585, 756, 16, 200, 320);
}

// ---------------------------------------------------------------------------
// 4. WIPE BOUNDARY RIDGE & SHARP VERTICAL DRIP CHANNELS
// ---------------------------------------------------------------------------
function drawWipeBoundaryAndDripChannels() {
  // 4A. Pushed ridge of condensation, soap residue & palm streak arcs right along the wipe boundary
  for (let i = 0; i < 420; i++) {
    let t = random(-0.04, 1.02);
    let arcShift = -38 * Math.sin(constrain(t, 0, 1) * Math.PI);
    let side = random() < 0.55 ? 1 : -1;
    let sOffset = side * (188 + random(-14, 18));
    if (t > 0.72) sOffset = random(-165, 165);

    let bx = WIPE_AX + t * WIPE_DX + WIPE_NX * (arcShift + sOffset);
    let by = WIPE_AY + t * WIPE_DY + WIPE_NY * (arcShift + sOffset);
    let wd = getWipeData(bx, by);

    if (Math.abs(wd.d) < 22) {
      let streakLen = random(18, 58);
      let ang = WIPE_ANGLE + random(-6, 6);
      let dx = Math.cos(ang * Math.PI / 180) * streakLen;
      let dy = Math.sin(ang * Math.PI / 180) * streakLen;

      let col = wd.d > 0 ? "#ffffff" : (random() < 0.5 ? "#d0dde0" : "#6c858c");
      brush.set("fine_cpencil", col, random(0.3, 0.55));
      brush.line(bx, by, bx + dx, by + dy);
    }
  }

  // Interior palm-print / finger drag micro-streaks across the glass inside the wipe
  for (let i = 0; i < 55; i++) {
    let t = random(0.08, 0.92);
    let s = random(-165, 165);
    let arcShift = -38 * Math.sin(t * Math.PI);
    let sx = WIPE_AX + t * WIPE_DX + WIPE_NX * (arcShift + s);
    let sy = WIPE_AY + t * WIPE_DY + WIPE_NY * (arcShift + s);
    if (!isInsideWipe(sx, sy, -12)) continue;
    let len = random(35, 95);
    let dx = WIPE_UX * len;
    let dy = WIPE_UY * len;
    brush.set("fine_cpencil", "#e6f0f2", 0.2);
    brush.line(sx, sy, sx + dx, sy + dy);
  }

  // 4B. SHARP LITTLE DRIP CHANNELS RUNNING DOWN FROM THE WIPE'S EDGE
  // Define 21 gravity drip channels originating along the lower edge of the diagonal wipe
  // (plus 5 shorter drips from the upper edge trickling down into the clear window)
  let lowerDripT = [
    0.04, 0.09, 0.14, 0.19, 0.25, 0.30, 0.35, 0.41, 0.46, 0.52,
    0.57, 0.62, 0.68, 0.73, 0.78, 0.83, 0.87, 0.91, 0.95, 0.99, 1.02
  ];

  for (let idx = 0; idx < lowerDripT.length; idx++) {
    let t = lowerDripT[idx];
    // Find exact lower boundary point for this x/t
    let startX = WIPE_AX + t * WIPE_DX + WIPE_NX * 160;
    let startY = WIPE_AY + t * WIPE_DY + WIPE_NY * 160;

    // Refine startY so it sits right on the lower wipe boundary (d ≈ 0)
    for (let step = -80; step <= 120; step += 3) {
      let testY = startY + step;
      let wd = getWipeData(startX, testY);
      if (wd.d >= -2 && wd.d <= 6) {
        startY = testY;
        break;
      }
    }

    // Channel length varies naturally (some long dramatic runners, some short sharp channels)
    let dripLen = (idx % 3 === 0) ? random(220, 395) : ((idx % 2 === 0) ? random(115, 210) : random(55, 110));
    let endY = min(1165, startY + dripLen);
    if (endY <= startY + 25) continue;

    let chanW = random(4.8, 8.8);

    // Build meandering path points downward
    let pathLeft = [];
    let pathRight = [];
    let pathCenter = [];
    let curX = startX;

    for (let y = startY - 4; y <= endY; y += 8) {
      let progress = (y - startY) / max(1, endY - startY);
      let wobble = (noise(idx * 10, y * 0.025) - 0.5) * 7.5;
      curX += wobble * 0.42;
      // Taper slightly in the middle, swell slightly into the terminal droplet
      let wHere = chanW * (1.0 - 0.32 * Math.sin(progress * Math.PI));
      if (progress > 0.9) wHere = chanW * 0.95;

      pathCenter.push([curX, y]);
      pathLeft.push([curX - wHere * 0.5, y]);
      pathRight.push([curX + wHere * 0.5, y]);
    }

    let polyPts = pathLeft.concat(pathRight.slice().reverse());

    // What clear dark color is revealed behind the steam inside this sharp drip channel?
    let revealCol = "#0c353b"; // Deep teal tile
    if (startX > 250 && startX < 650) {
      revealCol = (startX < 460) ? "#2b130d" : "#4f261b"; // Dark warm neck/chest shadow
    } else if (startX >= 680 && startY > 620) {
      revealCol = "#6e6154"; // Unfogged darker towel tone
    }

    // Wash the clear channel interior so it slices sharply through the white/pearl watercolor fog!
    brush.noStroke();
    brush.wash(revealCol, 235);
    drawShapePoly(polyPts, 0.15);
    brush.noWash();

    // Crisp dark internal shadow along the left edge of the channel
    brush.set("rotring", "#06191c", 0.42);
    for (let k = 0; k < pathLeft.length - 1; k++) {
      brush.line(pathLeft[k][0], pathLeft[k][1], pathLeft[k + 1][0], pathLeft[k + 1][1]);
    }

    // Crisp bright condensation ridge pushed to the outer edges of the channel
    brush.set("fine_cpencil", "#ffffff", 0.48);
    for (let k = 0; k < pathRight.length - 1; k++) {
      brush.line(pathRight[k][0] + 1.2, pathRight[k][1], pathRight[k + 1][0] + 1.2, pathRight[k + 1][1]);
      brush.line(pathLeft[k][0] - 1.5, pathLeft[k][1], pathLeft[k + 1][0] - 1.5, pathLeft[k + 1][1]);
    }

    // Luminous internal refraction streak down the center of the wet channel
    brush.set("fine_cpencil", startX > 260 && startX < 640 ? "#b8745c" : "#5ca0a8", 0.32);
    for (let k = 1; k < pathCenter.length - 1; k += 2) {
      brush.line(pathCenter[k][0] + 0.8, pathCenter[k][1], pathCenter[k + 1][0] + 0.8, pathCenter[k + 1][1]);
    }

    // Plump high-contrast water droplet bead at the bottom tip of the channel!
    let tip = pathCenter[pathCenter.length - 1];
    drawWaterDroplet(tip[0], tip[1], chanW * 0.78, revealCol);
  }

  // 5 shorter drips starting from the UPPER edge of the wipe and trickling down across the clear glass!
  let upperDripT = [0.22, 0.38, 0.55, 0.71, 0.84];
  for (let idx = 0; idx < upperDripT.length; idx++) {
    let t = upperDripT[idx];
    let arcShift = -38 * Math.sin(t * Math.PI);
    let ux = WIPE_AX + t * WIPE_DX + WIPE_NX * (arcShift - 188);
    let uy = WIPE_AY + t * WIPE_DY + WIPE_NY * (arcShift - 188);
    let len = random(42, 95);

    brush.set("rotring", "#081c20", 0.34);
    brush.line(ux - 1.5, uy, ux - 1.0, uy + len);
    brush.set("fine_cpencil", "#ffffff", 0.42);
    brush.line(ux + 1.2, uy, ux + 1.5, uy + len);
    drawWaterDroplet(ux, uy + len, random(3.5, 5.2), "#163d42");
  }
}

// Helper to render a jewel-like 3D water droplet on the mirror
function drawWaterDroplet(x, y, r, baseCol) {
  brush.noStroke();
  // Dark upper refraction crescent
  brush.wash("#051417", 240);
  brush.circle(x, y, r, 0.12);
  // Luminous lower caustic crescent
  brush.wash(baseCol === "#0c353b" ? "#7dc2c9" : "#e6b8a1", 230);
  brush.circle(x + 0.4, y + r * 0.28, r * 0.68, 0.12);
  brush.noWash();

  // Crisp dark rim
  brush.set("rotring", "#041012", 0.38);
  brush.arc(x, y, r, 180, 360);

  // Pinpoint pure-white specular catchlight on upper-left dome + bottom caustic glint
  brush.set("rotring", "#ffffff", 0.62);
  brush.line(x - r * 0.38, y - r * 0.35, x - r * 0.08, y - r * 0.42);
  brush.set("fine_cpencil", "#ffffff", 0.45);
  brush.arc(x, y, r * 0.85, 25, 145);
}

// ---------------------------------------------------------------------------
// 5. FINAL ATMOSPHERIC BREATH MIST & CONDENSATION MICRO-BEADS
// ---------------------------------------------------------------------------
function drawFinalSteamMistAndDroplets() {
  // 1. Fine spray mist over the steamed mirror to unify the wet-into-wet blooms
  for (let i = 0; i < 85; i++) {
    let x = random(30, 1170);
    let y = random(30, 1170);
    let wd = getWipeData(x, y);
    if (wd.d < 16) continue;

    let col = random() < 0.6 ? "#f5f3ed" : "#b8c7cc";
    brush.set("pore_stipple", col, random(0.8, 1.6));
    let ang = random(0, 360);
    brush.line(x, y, x + Math.cos(ang) * 35, y + Math.sin(ang) * 35);
  }

  // 2. Condensation beads clustered heavily along the outer margin of the wipe (8 < d < 75)
  for (let i = 0; i < 320; i++) {
    let t = random(-0.05, 1.04);
    let arcShift = -38 * Math.sin(constrain(t, 0, 1) * Math.PI);
    let side = random() < 0.58 ? 1 : -1;
    let distFromEdge = random(4, 68);
    let s = side * (190 + distFromEdge);
    if (t > 0.72) s = random(-185, 185);

    let bx = WIPE_AX + t * WIPE_DX + WIPE_NX * (arcShift + s);
    let by = WIPE_AY + t * WIPE_DY + WIPE_NY * (arcShift + s);
    let wd = getWipeData(bx, by);
    if (wd.d < 2 || wd.d > 75) continue;

    let r = map(wd.d, 2, 75, 3.8, 1.4, true) * random(0.65, 1.35);
    // Tiny dark upper crescent & white lower highlight of each condensation bead
    brush.set("rotring", "#3b5259", 0.32);
    brush.arc(bx, by, r, 185, 355);
    brush.set("fine_cpencil", "#ffffff", 0.42);
    brush.arc(bx, by, r, 15, 165);
  }
}

