async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8419);
  noiseSeed(8419);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.paperBg);

  // 1. PALE GRAPH-PAPER BLUE GROUND & CAST SHADOW
  drawGraphPaperGround();
  drawSneakerCastShadow();

  // 2. MUD-CAKED RUNNING SHOE (CLOSE 3/4 OVERHEAD VIEW)
  drawOutsoleAndMidsole();
