  drawTopologyDiagramOverlay(laceSystem);

  noLoop();
}

// ============================================================================
// GEOMETRY & DRAWING HELPERS
// ============================================================================

function drawPoly(pts, curvature = 0, closeShape = true) {
  if (!pts || pts.length < 2) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closeShape ? CLOSE : undefined);
}

function drawDashedLine(x1, y1, x2, y2, dashLen, gapLen, brushName, col, w) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let distTotal = Math.hypot(dx, dy);
  if (distTotal < 1) return;
  let ux = dx / distTotal;
  let uy = dy / distTotal;
  brush.set(brushName, col, w);
  let d = 0;
  while (d < distTotal) {
    let dEnd = Math.min(distTotal, d + dashLen);
    brush.line(x1 + ux * d, y1 + uy * d, x1 + ux * dEnd, y1 + uy * dEnd);
    d += dashLen + gapLen;
  }
}

function drawDashedCurve(pts, dashStep, brushName, col, w) {
  brush.set(brushName, col, w);
  for (let i = 0; i < pts.length - 1; i += dashStep * 2) {
    let j = Math.min(pts.length - 1, i + dashStep);
    brush.line(pts[i][0], pts[i][1], pts[j][0], pts[j][1]);
  }
}

function drawArrowhead(x, y, ux, uy, size, brushName, col, w) {
  let nx = -uy;
  let ny = ux;
  let bx = x - ux * size;
  let by = y - uy * size;
  brush.set(brushName, col, w);
  brush.line(x, y, bx + nx * size * 0.48, by + ny * size * 0.48);
  brush.line(x, y, bx - nx * size * 0.48, by - ny * size * 0.48);
}

function drawGlyphText(str, x, y, h, col, weight = 0.35, spacing = 0.78) {
  let w = h * 0.62;
  let cx = x;
  brush.set("rotring", col, weight);
  for (let i = 0; i < str.length; i++) {
    let ch = str[i];
    if (ch === " ") {
      cx += w * 0.85;
      continue;
    }
    let segs = GLYPHS[ch] || GLYPHS[ch.toUpperCase()];
    if (segs) {
      for (let s of segs) {
        brush.line(
          cx + s[0] * w,
          y + s[1] * h,
          cx + s[2] * w,
          y + s[3] * h
        );
      }
    }
    cx += w + h * 0.22 * spacing;
  }
}

function evalCatmullRom(p0, p1, p2, p3, t) {
  let t2 = t * t;
  let t3 = t2 * t;
  let out = [];
  for (let k = 0; k < p0.length; k++) {
    let v0 = p0[k], v1 = p1[k], v2 = p2[k], v3 = p3[k];
    let val = 0.5 * (
      (2 * v1) +
      (-v0 + v2) * t +
      (2 * v0 - 5 * v1 + 4 * v2 - v3) * t2 +
      (-v0 + 3 * v1 - 3 * v2 + v3) * t3
    );
    out.push(val);
  }
  return out;
}

function sampleRibbonSpline(ctrlPts, stepPx = 2.2) {
  // ctrlPts: [[x, y, z, halfW, mud], ...]
  let raw = [];
  let n = ctrlPts.length;
  for (let i = 0; i < n - 1; i++) {
    let p0 = ctrlPts[Math.max(0, i - 1)];
    let p1 = ctrlPts[i];
    let p2 = ctrlPts[i + 1];
    let p3 = ctrlPts[Math.min(n - 1, i + 2)];
    let segDist = Math.hypot(p2[0] - p1[0], p2[1] - p1[1]);
    let steps = Math.max(8, Math.ceil(segDist / stepPx));
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      raw.push(evalCatmullRom(p0, p1, p2, p3, t));
    }
  }
  raw.push(ctrlPts[n - 1].slice());

  // Compute arc length, tangents, and normals
  let samples = [];
  let arc = 0;
  for (let i = 0; i < raw.length; i++) {
    if (i > 0) {
      arc += Math.hypot(raw[i][0] - raw[i - 1][0], raw[i][1] - raw[i - 1][1]);
    }
    let iPrev = Math.max(0, i - 1);
    let iNext = Math.min(raw.length - 1, i + 1);
    let dx = raw[iNext][0] - raw[iPrev][0];
    let dy = raw[iNext][1] - raw[iPrev][1];
    let len = Math.hypot(dx, dy) || 1;
    let tx = dx / len;
    let ty = dy / len;
    let nx = -ty;
    let ny = tx;
    samples.push({
      x: raw[i][0],
      y: raw[i][1],
      z: raw[i][2] !== undefined ? raw[i][2] : 1.0,
      w: raw[i][3] !== undefined ? raw[i][3] : 11.5,
      mud: raw[i][4] !== undefined ? raw[i][4] : 0.0,
      s: arc,
      tx, ty, nx, ny,
      cut: false
    });
  }
  return samples;
}

