function drawMeshVampAndTongue() {
  // Main upper body base silhouette
  const upperBase = [
    [185, 315], [242, 442], [355, 578], [515, 725],
    [685, 845], [835, 895], [970, 868], [1052, 810],
    [1048, 705], [965, 565], [815, 420], [645, 285],
    [475, 185], [315, 180], [210, 230]
  ];
  brush.noStroke();
  brush.wash(PAL.greyLight, 235);
  drawPoly(upperBase, 0.22);

  // Breathable Mesh Vamp Dome (forefoot diamond mesh region)
  const vampDome = [
    [545, 625], [645, 745], [775, 812], [915, 808],
    [972, 738], [928, 608], [805, 488], [675, 425],
    [595, 485]
  ];
  brush.wash(PAL.laceBase, 225);
  drawPoly(vampDome, 0.28);

  // Soft alcohol-marker shading on lateral & medial curves of the vamp dome
  const vampShade = [
    [545, 625], [645, 745], [775, 812], [915, 808],
    [885, 755], [755, 742], [635, 668], [585, 575]
  ];
  brush.wash(PAL.greyMid, 145);
  drawPoly(vampShade, 0.25);
  brush.noWash();

  // HYPERREAL 3D PERSPECTIVE MESH GRID & PORES ON THE VAMP
  // Map uv in [0,1]^2 onto the domed forefoot surface
  function vampUV(u, v) {
    // u: along shoe length (throat -> toe), v: across width (lateral -> medial)
    let xThroat = lerp(555, 705, v);
    let yThroat = lerp(635, 435, v);
    let xToe = lerp(795, 955, v);
    let yToe = lerp(810, 635, v);
    let x = lerp(xThroat, xToe, u);
    let y = lerp(yThroat, yToe, u);
    // Dome curvature bulge toward upper-right/down-right
    let bulge = Math.sin(u * Math.PI) * Math.sin(v * Math.PI) * 34;
    return [x + bulge * 0.65, y - bulge * 0.55];
  }

  // Draw intersecting curved mesh filaments
  let nu = 22, nv = 18;
  brush.set("2H", PAL.greyScuff, 0.32);
  for (let i = 0; i <= nu; i++) {
    let u = i / nu;
    let pts = [];
    for (let j = 0; j <= nv; j++) {
      pts.push(vampUV(u, j / nv));
    }
    brush.spline(pts, 0.25);
  }
  for (let j = 0; j <= nv; j++) {
    let v = j / nv;
    let pts = [];
    for (let i = 0; i <= nu; i++) {
      pts.push(vampUV(i / nu, v));
    }
    brush.spline(pts, 0.25);
  }

  // Diagonal honeycomb weave & individual recessed mesh pores + trapped grit
  for (let i = 0; i < nu; i++) {
    for (let j = 0; j < nv; j++) {
      let u = (i + 0.5) / nu;
      let v = (j + 0.5) / nv;
      // Keep inside elliptical dome mask
      let du = (u - 0.5) * 1.85;
      let dv = (v - 0.5) * 1.9;
      if (du * du + dv * dv > 0.92) continue;

      let [px, py] = vampUV(u, v);
      let nVal = noise(i * 0.35, j * 0.35);

      // Determine if this mesh cell is clogged with dried mud/grit
      let isMuddy = (v < 0.42 && u > 0.25) || (u > 0.62 && nVal > 0.42) || nVal > 0.66;
      if (isMuddy) {
        brush.set("2B", nVal > 0.62 ? PAL.mudDark : PAL.mudDeep, 0.72);
        brush.line(px - 2.2, py - 1.2, px + 2.2, py + 1.2);
        brush.line(px - 1.2, py + 2.0, px + 1.5, py - 1.8);
      } else {
        brush.set("rotring", PAL.greyDark, 0.42);
        brush.line(px - 1.6, py - 0.8, px + 1.6, py + 0.8);
      }
    }
  }

  // Padded Gusseted Tongue (running up the center of the throat under the laces)
  const tonguePoly = [
    [355, 295], [472, 205], [615, 345], [775, 535],
    [715, 625], [645, 655], [485, 495], [345, 355]
  ];
  brush.noStroke();
  brush.wash(PAL.laceWarm, 235);
  drawPoly(tonguePoly, 0.2);

  // Tongue lateral shadow & foam baffle ribs
  const tongueShade = [
    [345, 355], [485, 495], [645, 655], [680, 635],
    [525, 465], [385, 315]
  ];
  brush.wash(PAL.greyMid, 150);
  drawPoly(tongueShade, 0.2);

  // Woven Safety-Orange Tongue Crest Label near top of tongue
  const tongueTag = [
    [378, 285], [448, 222], [502, 272], [432, 338]
  ];
  brush.wash(PAL.orangeMid, 235);
  drawPoly(tongueTag, 0.05);
  brush.noWash();

  brush.set("rotring", PAL.inkBlack, 0.55);
  drawPoly(tonguePoly, 0.2);
  drawPoly(tongueTag, 0.04);

  // Technical spec stripes on woven tongue tag
  brush.set("rotring", PAL.pureWhite, 0.55);
  brush.line(398, 282, 444, 240);
  brush.line(410, 294, 456, 252);
  brush.set("rotring", PAL.inkBlack, 0.35);
  brush.line(422, 306, 468, 264);
  brush.line(432, 316, 478, 274);

  // Tongue mesh pores & horizontal stitch baffles
  for (let k = 1; k <= 6; k++) {
    let t = k / 7;
    let x1 = lerp(395, 655, t);
    let y1 = lerp(345, 615, t);
    let x2 = lerp(475, 745, t);
    let y2 = lerp(265, 535, t);
    drawDashedLine(x1, y1, x2, y2, 5, 4, "rotring", PAL.greyDark, 0.32);
  }
}

