      id: "TailFrayed",
      ctrl: [
        [492, 412, 3.4, 10.0, 0.2],
        [448, 535, 3.2, 11.5, 0.4], // OVER LoopL1 return stem
        [395, 648, 1.5, 11.6, 0.6], // UNDER LoopL1 lower arc
        [378, 765, 3.5, 11.6, 0.5], // Drapes over muddy midsole edge
        [355, 868, 3.5, 11.0, 0.2]  // Spills onto pale blue graph paper -> Frayed Aglet
      ]
    },

    // S17: CENTRAL DOUBLE-BOW COLLAR WRAP (High-z binding bridge locking the knot core)
    {
      id: "KnotCollar1",
      ctrl: [
        [458, 352, 4.1, 10.5, 0.1],
        [502, 378, 4.4, 11.8, 0.2],
        [545, 412, 4.1, 10.5, 0.2]
      ]
    },
    {
      id: "KnotCollar2",
      ctrl: [
        [475, 425, 4.2, 10.2, 0.2],
        [515, 385, 4.6, 11.5, 0.1],
        [548, 348, 4.2, 10.2, 0.1]
      ]
    }
  ];

  // Sample all strands
  const strands = strandDefs.map(def => ({
    id: def.id,
    ctrl: def.ctrl,
    samples: sampleRibbonSpline(def.ctrl, 2.0)
  }));

  // ==========================================================================
  // EXACT TOPOLOGICAL CROSSING & UNDER-CROSSING WHITE GAP DETECTOR
  // ==========================================================================
  const crossings = [];

  for (let a = 0; a < strands.length; a++) {
    let sA = strands[a].samples;
    for (let b = 0; b < strands.length; b++) {
      if (a === b) continue;
      let sB = strands[b].samples;

      // Mark sample points of sA as `cut = true` wherever sA passes UNDER sB
      for (let i = 0; i < sA.length; i++) {
        let pA = sA[i];
        // Left & right ribbon edge points of sA at sample i
        let lxA = pA.x + pA.nx * pA.w;
        let lyA = pA.y + pA.ny * pA.w;
        let rxA = pA.x - pA.nx * pA.w;
        let ryA = pA.y - pA.ny * pA.w;

        for (let j = 0; j < sB.length; j += 2) {
          let pB = sB[j];
          if (pB.z <= pA.z + 0.12) continue; // Only cut when sB is strictly OVER sA

          // Tidy white gap buffer outside the over-strand's black outline: 8.5 px
          let gapThreshold = pB.w + 8.5;
          let dCenter = Math.hypot(pA.x - pB.x, pA.y - pB.y);
          if (dCenter < gapThreshold + pA.w) {
            let dLeft = Math.hypot(lxA - pB.x, lyA - pB.y);
            let dRight = Math.hypot(rxA - pB.x, ryA - pB.y);
            if (dCenter < gapThreshold || dLeft < gapThreshold || dRight < gapThreshold) {
              pA.cut = true;
              break;
            }
          }
        }
      }

      // Record exact centerline crossings (for numbering c1..cN in the topology diagram)
      if (a < b) {
        for (let i = 0; i < sA.length - 2; i += 2) {
          for (let j = 0; j < sB.length - 2; j += 2) {
            let d = Math.hypot(sA[i].x - sB[j].x, sA[i].y - sB[j].y);
            if (d < 4.5) {
              let cx = 0.5 * (sA[i].x + sB[j].x);
              let cy = 0.5 * (sA[i].y + sB[j].y);
              let tooClose = crossings.some(c => Math.hypot(c.x - cx, c.y - cy) < 34);
              if (!tooClose) {
                let overS = sA[i].z > sB[j].z ? sA[i] : sB[j];
                let underS = sA[i].z > sB[j].z ? sB[j] : sA[i];
                let crossSign = (overS.tx * underS.ty - overS.ty * underS.tx) >= 0 ? "+" : "-";
                crossings.push({
                  x: cx,
                  y: cy,
                  sign: crossSign,
                  overStrand: sA[i].z > sB[j].z ? strands[a].id : strands[b].id,
                  underStrand: sA[i].z > sB[j].z ? strands[b].id : strands[a].id
                });
              }
            }
          }
        }
      }
    }
  }

  return {
    eyelets,
    hiddenPaths,
    strands,
    crossings,
    tailIntactEnd: strands.find(s => s.id === "TailIntact").samples.slice(-1)[0],
    tailFrayedEnd: strands.find(s => s.id === "TailFrayed").samples.slice(-1)[0]
  };
}

function drawSubterraneanLacePaths(laceSystem) {
  // Dashed topological trajectories showing where the lace travels underneath the suede eyestay
  for (let hp of laceSystem.hiddenPaths) {
    let pts = sampleRibbonSpline([
      [hp[0][0], hp[0][1], 0, 8, 0],
      [hp[1][0], hp[1][1], 0, 8, 0],
      [hp[2][0], hp[2][1], 0, 8, 0]
    ], 3.0);
    let xy = pts.map(p => [p.x, p.y]);
    drawDashedCurve(xy, 2, "rotring", PAL.inkBlue, 0.42);
  }
}

function drawEyeletGrommets(eyelets) {
  const allEyelets = [...eyelets.L, ...eyelets.M];
  for (let idx = 0; idx < allEyelets.length; idx++) {
    let [ex, ey] = allEyelets[idx];
    let isTopCollar = (idx === 5 || idx === 11);

    // Outer metallic / enamel grommet ring
    brush.noStroke();
    brush.wash(isTopCollar ? PAL.orangeLight : PAL.greyPale, 245);
    brush.circle(ex, ey, 14, 0.05);

    // Dark recessed eyelet hole
    brush.wash(PAL.inkBlack, 240);
    brush.circle(ex, ey, 7.5, 0.04);
    brush.noWash();

    // Crisp fine-liner grommet rings & white highlight glint
    brush.set("rotring", PAL.inkBlack, 0.6);
    brush.circle(ex, ey, 14, 0.04);
    brush.circle(ex, ey, 7.5, 0.04);
    brush.set("rotring", PAL.pureWhite, 0.65);
    brush.arc(ex, ey, 11, 200, 310);
  }
}

// ============================================================================
// 4. RENDERING TOPOLOGICAL LACE RIBBONS WITH WHITE UNDER-CROSSING GAPS
// ============================================================================

function renderTopologicalLaces(laceSystem) {
  const { strands } = laceSystem;

  // PASS 1: Paint crisp white topological gap reserves at all under-crossing cut intervals
  // This ensures that even over the dark/muddy shoe tongue, every under-crossing breaks with a tidy white gap!
  brush.noStroke();
  brush.wash(PAL.gapWhite, 250);
  for (let st of strands) {
    let s = st.samples;
    let i = 0;
    while (i < s.length) {
      if (!s[i].cut) { i++; continue; }
      let start = Math.max(0, i - 2);
      while (i < s.length && s[i].cut) i++;
      let end = Math.min(s.length - 1, i + 2);
      if (end - start >= 2) {
        let leftPts = [];
        let rightPts = [];
        for (let k = start; k <= end; k++) {
          let p = s[k];
          let padW = p.w + 3.5;
          leftPts.push([p.x + p.nx * padW, p.y + p.ny * padW]);
          rightPts.push([p.x - p.nx * padW, p.y - p.ny * padW]);
        }
        drawPoly([...leftPts, ...rightPts.reverse()], 0.05);
      }
    }
  }
  brush.noWash();

  // Collect all visible (uncut) contiguous sub-segments across all strands
  let visibleSegments = [];
  for (let st of strands) {
    let s = st.samples;
    let i = 0;
    while (i < s.length) {
      if (s[i].cut) { i++; continue; }
      let start = i;
      while (i < s.length && !s[i].cut) i++;
      let end = i - 1;
      if (end - start >= 3) {
        let sub = s.slice(start, end + 1);
        let zAvg = sub.reduce((acc, p) => acc + p.z, 0) / sub.length;
        visibleSegments.push({
          strandId: st.id,
          pts: sub,
          zAvg,
          cutStart: start > 0 && s[start - 1].cut,
          cutEnd: end < s.length - 1 && s[end + 1].cut
        });
      }
    }
  }

  // Sort visible segments by average z so any non-cut junctions layer naturally
  visibleSegments.sort((a, b) => a.zAvg - b.zAvg);

  // PASS 2: Render each visible ribbon segment
  for (let seg of visibleSegments) {
    drawSingleLaceRibbonSegment(seg);
  }
}

function drawSingleLaceRibbonSegment(seg) {
  const pts = seg.pts;
  const n = pts.length;
  if (n < 3) return;

  let leftEdge = [];
  let rightEdge = [];
  let centerLine = [];
  let shadowStrip = [];

  for (let i = 0; i < n; i++) {
    let p = pts[i];
    leftEdge.push([p.x + p.nx * p.w, p.y + p.ny * p.w]);
    rightEdge.push([p.x - p.nx * p.w, p.y - p.ny * p.w]);
    centerLine.push([p.x, p.y]);
    shadowStrip.push([p.x - p.nx * (p.w * 0.25), p.y - p.ny * (p.w * 0.25)]);
  }

  const fullRibbonPoly = [...leftEdge, ...rightEdge.slice().reverse()];
  const shadowRibbonPoly = [...shadowStrip, ...rightEdge.slice().reverse()];

  // 1. Flat alcohol-marker base fill (warm off-white / cream lace)
  brush.noStroke();
  brush.wash(PAL.laceBase, 250);
  drawPoly(fullRibbonPoly, 0.08);

  // 2. Scuffed grey marker bevel along the lower/right side of the lace ribbon
  brush.wash(PAL.laceShadow, 210);
  drawPoly(shadowRibbonPoly, 0.08);

  // 3. Mud staining along segments with high mud factor
  for (let i = 3; i < n - 3; i += 8) {
    let p = pts[i];
    if (p.mud > 0.35 && noise(p.x * 0.03, p.y * 0.03) > 0.32) {
      let p2 = pts[Math.min(n - 1, i + 6)];
      let mudPatch = [
        [p.x + p.nx * p.w * 0.9, p.y + p.ny * p.w * 0.9],
        [p2.x + p2.nx * p2.w * 0.85, p2.y + p2.ny * p2.w * 0.85],
        [p2.x - p2.nx * p2.w * 0.85, p2.y - p2.ny * p2.w * 0.85],
        [p.x - p.nx * p.w * 0.9, p.y - p.ny * p.w * 0.9]
      ];
      brush.wash(p.mud > 0.6 ? PAL.mudMid : PAL.mudLight, 185);
      drawPoly(mudPatch, 0.1);
    }
  }
  brush.noWash();

  // 4. Safety-orange woven center tracer stitches along the spine of the shoelace
  brush.set("marker", PAL.orangeMid, 0.65);
  for (let i = 3; i < n - 3; i += 6) {
    let p1 = pts[i];
    let p2 = pts[Math.min(n - 1, i + 3)];
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // 5. Braided tubular chevron weave texture inside the ribbon
  brush.set("2H", PAL.greyScuff, 0.32);
  for (let i = 2; i < n - 2; i += 4) {
    let p = pts[i];
    let pNext = pts[Math.min(n - 1, i + 2)];
    let lx = p.x + p.nx * (p.w * 0.82);
    let ly = p.y + p.ny * (p.w * 0.82);
    let rx = p.x - p.nx * (p.w * 0.82);
    let ry = p.y - p.ny * (p.w * 0.82);
    brush.line(lx, ly, pNext.x, pNext.y);
    brush.line(rx, ry, pNext.x, pNext.y);
  }

  // 6. Precise white pen highlight along the upper ridge of the lace
  brush.set("rotring", PAL.pureWhite, 0.55);
  for (let i = 3; i < n - 4; i += 5) {
    let p1 = pts[i];
    let p2 = pts[i + 3];
    brush.line(
      p1.x + p1.nx * (p1.w * 0.52),
      p1.y + p1.ny * (p1.w * 0.52),
      p2.x + p2.nx * (p2.w * 0.52),
      p2.y + p2.ny * (p2.w * 0.52)
    );
  }

  // 7. CRISP BLACK FINE-LINER OUTLINES along both edges of the lace strand
  brush.set("rotring", PAL.inkBlack, 0.78);
  brush.spline(leftEdge, 0.15);
  brush.spline(rightEdge, 0.15);

  // Subtle topological stop-ticks at under-crossing break ends
  brush.set("rotring", PAL.inkBlack, 0.45);
  if (seg.cutStart) {
    let p0 = pts[0];
    brush.line(
      p0.x + p0.nx * p0.w, p0.y + p0.ny * p0.w,
      p0.x + p0.nx * (p0.w * 0.55), p0.y + p0.ny * (p0.w * 0.55)
    );
    brush.line(
      p0.x - p0.nx * p0.w, p0.y - p0.ny * p0.w,
      p0.x - p0.nx * (p0.w * 0.55), p0.y - p0.ny * (p0.w * 0.55)
    );
  }
  if (seg.cutEnd) {
    let pE = pts[n - 1];
    brush.line(
      pE.x + pE.nx * pE.w, pE.y + pE.ny * pE.w,
      pE.x + pE.nx * (pE.w * 0.55), pE.y + pE.ny * (pE.w * 0.55)
    );
    brush.line(
      pE.x - pE.nx * pE.w, pE.y - pE.ny * pE.w,
      pE.x - pE.nx * (pE.w * 0.55), pE.y - pE.ny * (pE.w * 0.55)
    );
  }
}

// ============================================================================
// 5. AGLETS: INTACT SAFETY-ORANGE AGLET & HYPERREAL FRAYED AGLET
// ============================================================================

function drawIntactAglet(endPt) {
  let x = endPt.x, y = endPt.y;
  let ux = endPt.tx, uy = endPt.ty;
  let nx = endPt.nx, ny = endPt.ny;
  let len = 54;
  let w0 = 7.8, w1 = 6.4;

  let pTL = [x + nx * w0, y + ny * w0];
  let pTR = [x - nx * w0, y - ny * w0];
  let pBR = [x + ux * len - nx * w1, y + uy * len - ny * w1];
  let pBL = [x + ux * len + nx * w1, y + uy * len + ny * w1];

  // Safety-orange plastic aglet body
  brush.noStroke();
  brush.wash(PAL.orangeMid, 245);
  drawPoly([pTL, pTR, pBR, pBL], 0.04);

  // Shaded right edge of cylinder
  let pMidT = [x - nx * 1.2, y - ny * 1.2];
  let pMidB = [x + ux * len - nx * 1.0, y + uy * len - ny * 1.0];
  brush.wash(PAL.orangeDeep, 210);
  drawPoly([pMidT, pTR, pBR, pMidB], 0.04);
  brush.noWash();

  // Specular white pen highlight stripe along cylinder
  brush.set("rotring", PAL.pureWhite, 0.85);
  brush.line(
    x + nx * 3.8 + ux * 4, y + ny * 3.8 + uy * 4,
    x + nx * 3.2 + ux * (len - 5), y + ny * 3.2 + uy * (len - 5)
  );

  // Crimp rings & crisp black fine-liner outline
  brush.set("rotring", PAL.inkBlack, 0.72);
  drawPoly([pTL, pTR, pBR, pBL], 0.04);
  for (let d of [8, 14, len - 7]) {
    brush.line(
      x + ux * d + nx * w0 * 0.92, y + uy * d + ny * w0 * 0.92,
      x + ux * d - nx * w0 * 0.92, y + uy * d - ny * w0 * 0.92
    );
  }
}

function drawFrayedAglet(endPt) {
  let x = endPt.x, y = endPt.y;
  let ux = endPt.tx, uy = endPt.ty;
  let nx = endPt.nx, ny = endPt.ny;

  // 1. Cracked, peeled-back plastic aglet sheath (upper 34px before the burst)
  let sheathLen = 34;
  let w0 = 8.5;
  let sTL = [x + nx * w0, y + ny * w0];
  let sTR = [x - nx * w0, y - ny * w0];
  // Jagged split bottom edge of the fractured sheath
  let sSplit1 = [x + ux * sheathLen + nx * (w0 + 4.5), y + uy * sheathLen + ny * (w0 + 4.5)];
  let sSplit2 = [x + ux * (sheathLen - 11) + nx * 2.2, y + uy * (sheathLen - 11) + ny * 2.2];
  let sSplit3 = [x + ux * (sheathLen + 4) - nx * 1.5, y + uy * (sheathLen + 4) - ny * 1.5];
  let sSplit4 = [x + ux * (sheathLen - 14) - nx * 4.5, y + uy * (sheathLen - 14) - ny * 4.5];
  let sSplit5 = [x + ux * (sheathLen + 2) - nx * (w0 + 5.0), y + uy * (sheathLen + 2) - ny * (w0 + 5.0)];

  const sheathPoly = [sTL, sTR, sSplit5, sSplit4, sSplit3, sSplit2, sSplit1];

  brush.noStroke();
  brush.wash(PAL.orangeLight, 235);
  drawPoly(sheathPoly, 0.02);
  brush.noWash();

  // Peeled curl shard sticking out to the left
  const shardPoly = [
    [x + ux * 16 + nx * w0, y + uy * 16 + ny * w0],
    [x + ux * 36 + nx * (w0 + 13), y + uy * 36 + ny * (w0 + 13)],
    [x + ux * 39 + nx * (w0 + 6), y + uy * 39 + ny * (w0 + 6)],
    [x + ux * 24 + nx * (w0 - 1), y + uy * 24 + ny * (w0 - 1)]
  ];
  brush.noStroke();
  brush.wash(PAL.orangeMid, 230);
  drawPoly(shardPoly, 0.05);
  brush.noWash();

  // 2. Exploding plume of 26 frayed cotton/polyester micro-threads
  let bx = x + ux * (sheathLen - 4);
  let by = y + uy * (sheathLen - 4);

  // Soft cream/grey marker mass behind the dense core of the frayed tuft
  const tuftCore = [
    [bx + nx * 9, by + ny * 9],
    [bx + ux * 58 + nx * 36, by + uy * 58 + ny * 36],
    [bx + ux * 92 + nx * 8, by + uy * 92 + ny * 8],
    [bx + ux * 74 - nx * 38, by + uy * 74 - ny * 38],
    [bx - nx * 9, by - ny * 9]
  ];
  brush.noStroke();
  brush.wash(PAL.laceWarm, 180);
  drawPoly(tuftCore, 0.25);
  brush.noWash();

  // Individual hyperreal frayed fibers with crimped kinks, mud specks & orange tracer threads
  const numFibers = 26;
  let labeledFibers = [];
  for (let f = 0; f < numFibers; f++) {
    let frac = (f / (numFibers - 1)) * 2 - 1; // -1..1
    let startX = bx + nx * frac * 7.5;
    let startY = by + ny * frac * 7.5;
    let fiberLen = 58 + (1 - Math.abs(frac) * 0.45) * 48 + random(-14, 18);
    let spread = frac * 46 + random(-9, 9);

    let fPts = [[startX, startY]];
    let steps = 6;
    for (let s = 1; s <= steps; s++) {
      let t = s / steps;
      // Crimped wave from the unbraided weave
      let crimp = Math.sin(t * Math.PI * 3.5 + f * 1.3) * (3.2 + t * 4.5);
      let fx = startX + ux * (fiberLen * t) + nx * (spread * Math.pow(t, 1.25) + crimp);
      let fy = startY + uy * (fiberLen * t) + ny * (spread * Math.pow(t, 1.25) + crimp);
      fPts.push([fx, fy]);
    }

    let isOrangeTracer = (f === 7 || f === 12 || f === 18);
    let isMuddyFiber = (f % 5 === 0);

    // Fine white core & dark fine-liner casing on key strands
    if (isOrangeTracer) {
      brush.set("rotring", PAL.orangeDeep, 0.58);
      brush.spline(fPts, 0.35);
    } else if (isMuddyFiber) {
      brush.set("2B", PAL.mudDeep, 0.55);
      brush.spline(fPts, 0.35);
    } else {
      brush.set("rotring", PAL.inkBlack, 0.42);
      brush.spline(fPts, 0.35);
      brush.set("rotring", PAL.pureWhite, 0.3);
      brush.line(fPts[0][0], fPts[0][1], fPts[2][0], fPts[2][1]);
    }

    if (f === 2 || f === 8 || f === 14 || f === 20 || f === 24) {
      labeledFibers.push(fPts[fPts.length - 1]);
    }
  }

  // Re-stroke cracked sheath outlines on top of fiber roots for crispness
  brush.set("rotring", PAL.inkBlack, 0.72);
  drawPoly(sheathPoly, 0.02);
  drawPoly(shardPoly, 0.05);
  brush.set("rotring", PAL.pureWhite, 0.75);
  brush.line(x + nx * 4 + ux * 4, y + ny * 4 + uy * 4, x + nx * 4 + ux * 22, y + ny * 4 + uy * 22);

  // Tiny stray lint fragments & topological fiber labels (f1..f5) on the graph paper
  for (let k = 0; k < labeledFibers.length; k++) {
    let tip = labeledFibers[k];
    let lx = tip[0] - 28 + k * 8;
    let ly = tip[1] + 18;
    drawDashedLine(tip[0], tip[1], lx + 6, ly - 3, 3, 3, "rotring", PAL.inkBlue, 0.28);
    drawGlyphText("f" + (k + 1), lx, ly, 10, PAL.inkSlate, 0.32);
  }
}

// ============================================================================
// 6. TOPOLOGY DIAGRAM OVERLAY (CROSSING NUMBERS, ARROWS, MARGINAL PROOF)
// ============================================================================

function drawTopologyDiagramOverlay(laceSystem) {
  const { strands, crossings } = laceSystem;

  // A. NUMBERED CROSSING CALLOUTS (c1 .. c18) & WRITHE SIGNS (+ / -)
  // Sort crossings top-to-bottom / throat-to-bow for clean logical numbering
  const sortedCrossings = crossings.slice().sort((a, b) => (a.y + a.x * 0.3) - (b.y + b.x * 0.3));
  const maxCallouts = Math.min(18, sortedCrossings.length);

  for (let i = 0; i < maxCallouts; i++) {
    let c = sortedCrossings[i];
    let idx = i + 1;

    // Small dashed topological inspection circle right around the crossing
    brush.set("rotring", PAL.inkOrange, 0.38);
    brush.circle(c.x, c.y, 17, 0.04);

    // Offset badge position so it doesn't obscure the white under-crossing gap
    let angle = (i % 2 === 0 ? -42 : 138) + (i * 23) % 50;
    let dist = 34 + (i % 3) * 8;
    let bx = c.x + Math.cos(angle * Math.PI / 180) * dist;
    let by = c.y + Math.sin(angle * Math.PI / 180) * dist;

    // Crisp leader line from crossing ring to numbered badge
    let rEdgeX = c.x + Math.cos(angle * Math.PI / 180) * 16;
    let rEdgeY = c.y + Math.sin(angle * Math.PI / 180) * 16;
    brush.set("rotring", PAL.inkSlate, 0.34);
    brush.line(rEdgeX, rEdgeY, bx, by);

    // White circular badge with black fine-liner ring
    brush.noStroke();
    brush.wash(PAL.gapWhite, 240);
    brush.circle(bx, by, 13.5, 0.03);
    brush.noWash();

    brush.set("rotring", PAL.inkSlate, 0.48);
    brush.circle(bx, by, 13.5, 0.03);

    // Crossing index label (c1..c18) and writhe sign (+/-)
    let label = "c" + idx;
    drawGlyphText(label, bx - (idx >= 10 ? 9.5 : 6.8), by - 4.5, 9.5, PAL.inkBlack, 0.34, 0.65);
    drawGlyphText(c.sign, c.x + 14, c.y - 18, 10, PAL.inkOrange, 0.42);
  }

  // B. TOPOLOGICAL ORIENTATION ARROWS ALONG THE LACE STRANDS
  for (let st of strands) {
    let s = st.samples;
    if (s.length < 35) continue;
    let midIdx = Math.floor(s.length * 0.46);
    if (s[midIdx].cut) midIdx = Math.floor(s.length * 0.28);
    if (s[midIdx] && !s[midIdx].cut) {
      let p = s[midIdx];
      // Offset arrow slightly outside the ribbon edge
      let ax = p.x + p.nx * (p.w + 9);
      let ay = p.y + p.ny * (p.w + 9);
      brush.set("rotring", PAL.inkOrange, 0.48);
      brush.line(ax - p.tx * 18, ay - p.ty * 18, ax + p.tx * 12, ay + p.ty * 12);
      drawArrowhead(ax + p.tx * 12, ay + p.ty * 12, p.tx, p.ty, 8.5, "rotring", PAL.inkOrange, 0.48);
    }
  }

  // C. MARGINAL PROOF BLOCK 1 (TOP-LEFT): TITLE & ABSTRACT PLANAR KNOT PROJECTION
  drawPoly([[62, 62], [445, 62], [445, 162], [62, 162]], 0);
  brush.noStroke();
  brush.wash(PAL.gapWhite, 175);
  drawPoly([[62, 62], [445, 62], [445, 162], [62, 162]], 0);
  brush.noWash();

  brush.set("rotring", PAL.inkSlate, 0.5);
  drawPoly([[62, 62], [445, 62], [445, 162], [62, 162]], 0);
  brush.line(62, 92, 445, 92);
  brush.line(315, 62, 315, 162);

  drawGlyphText("FIG. 04 // DOUBLED BOW TOPOLOGY", 74, 72, 11.5, PAL.inkBlack, 0.38);
  drawGlyphText("KNOT: T(2,4) SLIP-TANGLE", 74, 104, 10, PAL.inkSlate, 0.32);
  drawGlyphText("CROSSINGS N = " + maxCallouts + "  WRITHE W = +6", 74, 122, 10, PAL.inkSlate, 0.32);
  drawGlyphText("GAP d = 2.4 MM   BRAID f = 24", 74, 140, 10, PAL.inkOrange, 0.32);

  // Miniature abstract Gauss / Clover-Bow diagram inside [315..445, 62..162]
  let gx = 380, gy = 112;
  brush.set("rotring", PAL.inkSlate, 0.45);
  brush.circle(gx, gy, 34, 0.03);
  // Chords of the Gauss diagram
  for (let a = 0; a < 6; a++) {
    let ang1 = (a * 60 + 15) * Math.PI / 180;
    let ang2 = ((a * 60 + 155) % 360) * Math.PI / 180;
    brush.set("rotring", a % 2 === 0 ? PAL.inkOrange : PAL.inkBlue, 0.35);
    brush.line(
      gx + Math.cos(ang1) * 34, gy + Math.sin(ang1) * 34,
      gx + Math.cos(ang2) * 34, gy + Math.sin(ang2) * 34
    );
  }

  // D. MARGINAL PROOF BLOCK 2 (TOP-RIGHT): UNDER-CROSSING GAP & REIDEMEISTER DETAIL
  const boxTR = [[855, 62], [1138, 62], [1138, 228], [855, 228]];
  brush.noStroke();
  brush.wash(PAL.gapWhite, 175);
  drawPoly(boxTR, 0);
  brush.noWash();

  brush.set("rotring", PAL.inkSlate, 0.5);
  drawPoly(boxTR, 0);
  brush.line(855, 90, 1138, 90);
  drawGlyphText("LEMMA 1: UNDER-CROSSING GAP", 868, 71, 10.5, PAL.inkBlack, 0.36);

  // Schematic diagram of an over/under crossing with dimensioned white gap delta
  let sx = 945, sy = 148;
  // Under-strand left & right pieces with tidy gap
  brush.set("rotring", PAL.inkBlack, 0.65);
  brush.line(sx - 55, sy - 6, sx - 16, sy - 6);
  brush.line(sx - 55, sy + 6, sx - 16, sy + 6);
  brush.line(sx + 16, sy - 6, sx + 55, sy - 6);
  brush.line(sx + 16, sy + 6, sx + 55, sy + 6);
  // Over-strand vertical
  brush.noStroke();
  brush.wash(PAL.orangePale, 220);
  drawPoly([[sx - 7, sy - 42], [sx + 7, sy - 42], [sx + 7, sy + 42], [sx - 7, sy + 42]], 0);
  brush.noWash();
  brush.set("rotring", PAL.inkBlack, 0.65);
  brush.line(sx - 7, sy - 42, sx - 7, sy + 42);
  brush.line(sx + 7, sy - 42, sx + 7, sy + 42);

  // Dimension ticks for the white gap
  brush.set("rotring", PAL.inkOrange, 0.38);
  brush.line(sx + 7, sy - 22, sx + 7, sy - 10);
  brush.line(sx + 16, sy - 22, sx + 16, sy - 10);
  brush.line(sx + 2, sy - 16, sx + 24, sy - 16);
  drawGlyphText("d=8PX", 1022, 128, 9.5, PAL.inkOrange, 0.32);
  drawGlyphText("OVER: Z+1", 1022, 148, 9.5, PAL.inkSlate, 0.32);
  drawGlyphText("UNDER: CUT", 1022, 168, 9.5, PAL.inkSlate, 0.32);
  drawGlyphText("Δ(t)=t-1+1/t", 872, 204, 10, PAL.inkBlack, 0.34);

  // Leader line from Upper-Right Bow Loop R2 apex to Top-Right Proof Box
  drawDashedLine(835, 165, 855, 148, 5, 4, "rotring", PAL.inkBlue, 0.35);

  // E. MARGINAL PROOF BLOCK 3 (BOTTOM-LEFT): FRAYED AGLET BRAID DECOMPOSITION
  const boxBL = [[62, 865], [272, 865], [272, 1135], [62, 1135]];
  brush.noStroke();
  brush.wash(PAL.gapWhite, 175);
  drawPoly(boxBL, 0);
  brush.noWash();

  brush.set("rotring", PAL.inkSlate, 0.5);
  drawPoly(boxBL, 0);
  brush.line(62, 892, 272, 892);
  drawGlyphText("DETAIL B: AGLET FRAY", 72, 874, 10.5, PAL.inkBlack, 0.36);
  drawGlyphText("SHEATH: FRACTURED ACETATE", 72, 906, 9, PAL.inkSlate, 0.3);
  drawGlyphText("PLUME: 26 UNLINKED FIBERS", 72, 924, 9, PAL.inkSlate, 0.3);
  drawGlyphText("∂A -> Σ fk (lk = 0)", 72, 944, 9.5, PAL.inkOrange, 0.32);

  // Topological tree diagram of tubular braid splitting into fibers inside [62..272, 965..1120]
  let tx = 165, ty = 980;
  brush.set("rotring", PAL.inkBlack, 0.65);
  brush.line(tx - 6, ty, tx - 6, ty + 35);
  brush.line(tx + 6, ty, tx + 6, ty + 35);
  for (let b = -4; b <= 4; b++) {
    let endX = tx + b * 18;
    let endY = ty + 112;
    brush.set("rotring", b === 0 ? PAL.inkOrange : PAL.inkSlate, 0.36);
    brush.spline([
      [tx + b * 1.2, ty + 35],
      [tx + b * 8, ty + 72],
      [endX, endY]
    ], 0.3);
  }
  drawGlyphText("f1       f13      f26", 86, 1105, 9, PAL.inkSlate, 0.3);

  // Dashed caliper line connecting Detail B box to the real frayed aglet
  drawDashedLine(272, 955, 345, 912, 6, 4, "rotring", PAL.inkOrange, 0.4);

  // F. MARGINAL SPEC & SCALE BAR (BOTTOM-RIGHT)
  const boxBR = [[865, 1045], [1138, 1045], [1138, 1138], [865, 1138]];
  brush.noStroke();
  brush.wash(PAL.gapWhite, 175);
  drawPoly(boxBR, 0);
  brush.noWash();

  brush.set("rotring", PAL.inkSlate, 0.5);
  drawPoly(boxBR, 0);
  drawGlyphText("ELEV: 54.7 DEG // GRIT MESH", 878, 1058, 9.5, PAL.inkBlack, 0.34);

  // Graduated scale bar
  brush.set("rotring", PAL.inkBlack, 0.55);
  brush.line(880, 1102, 1110, 1102);
  for (let s = 0; s <= 4; s++) {
    let sxBar = 880 + s * 57.5;
    brush.line(sxBar, 1094, sxBar, 1108);
  }
  drawGlyphText("0    10   20   30   40 MM", 878, 1115, 9, PAL.inkSlate, 0.3);
}

// Hyperrealism in p5.brush — Swimmer Turning to Breathe in an Outdoor Lido
// Cross-processed 90s film palette: cyan-teal shadows, blown-out chartreuse highlights,
// strange peach-magenta skin accent, brutal marker shadows, pen droplets & gritty spray grain.

const TILT = -19; // Tilted snapshot Dutch angle in degrees
const CX = 585;
const CY = 575;
let cosT, sinT;

// Transform swimmer-space (u, v) -> canvas-space (x, y)
// u: longitudinal axis along waterline (-650 left/crown to +650 right/shoulder)
// v: transverse axis (-650 above water/air to +650 below water/trough)
function pt(u, v) {
  return [
    CX + u * cosT - v * sinT,
    CY + u * sinT + v * cosT
  ];
}

function pts(arr) {
  return arr.map(p => pt(p[0], p[1]));
}

// Helper for drawing closed/open shapes safely via beginShape/vertex/endShape
function drawPoly(uvPoints, curvature = 0.22, closed = true) {
  if (!uvPoints || uvPoints.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < uvPoints.length; i++) {
    let [x, y] = pt(uvPoints[i][0], uvPoints[i][1]);
    brush.vertex(x, y);
  }
  brush.endShape(closed);
}

// Watercolor fill helper
function watercolorUV(uvPoints, col, opacity, bleed = 0.18, tex = 0.45, border = 0.3, curv = 0.25) {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.noWash();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  drawPoly(uvPoints, curv, true);
  brush.noFill();
}

// Fast opaque/semi-opaque wash helper
function washUV(uvPoints, col, opacity, curv = 0.18) {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.noFill();
  brush.wash(col, opacity);
  drawPoly(uvPoints, curv, true);
  brush.noWash();
}

// Hard-blocked marker shadow plane (combines wash + dense felt-marker hatching + edge)
function markerBlockUV(uvPoints, col, opacity, hatchDist = 9, localAngle = 15, weight = 1.15, curv = 0.14) {
  brush.noStroke();
  brush.noFill();
  brush.noMass();
  brush.wash(col, opacity);
  brush.hatchStyle("chisel_marker", col, weight);
  brush.hatch(hatchDist, localAngle + TILT, { rand: 0.04, continuous: true });
  drawPoly(uvPoints, curv, true);
  brush.noHatch();
  brush.noWash();

  brush.set("marker", col, weight * 0.85);
  drawPoly(uvPoints, curv, true);
  brush.noStroke();
}

// Directional hatching helper in (u, v) space
function hatchUV(uvPoints, brushName, col, weight, dist, localAngle, opts = { rand: 0.06 }, curv = 0.22) {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noMass();
  brush.hatchStyle(brushName, col, weight);
  brush.hatch(dist, localAngle + TILT, opts);
  drawPoly(uvPoints, curv, true);
  brush.noHatch();
}

// Spline helper in (u, v) space
function splineUV(uvPoints, brushName, col, weight = 1, curv = 0.5) {
  if (!uvPoints || uvPoints.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(brushName, col, weight);
  let cPts = uvPoints.map(p => {
    let [x, y] = pt(p[0], p[1]);
    return p.length > 2 ? [x, y, p[2]] : [x, y];
  });
  brush.spline(cPts, curv);
}

// Line helper in (u, v) space
function lineUV(u1, v1, u2, v2, brushName, col, weight = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(brushName, col, weight);
  let [x1, y1] = pt(u1, v1);
  let [x2, y2] = pt(u2, v2);
  brush.line(x1, y1, x2, y2);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(199807);
  noiseSeed(199807);

  cosT = cos(TILT);
  sinT = sin(TILT);

  // Register custom brushes before scaling so they scale proportionally with built-ins
  brush.add("chisel_marker", {
    type: "marker",
    weight: 4.2,
    scatter: 0.06,
    opacity: 165,
    spacing: 0.35,
    pressure: [0.85, 1.0, 0.85],
    markerTip: false,
    noise: 0.25
  });

  brush.add("micro_pen", {
    type: "default",
    weight: 0.38,
    scatter: 0.03,
    sharpness: 0.92,
    grain: 0.85,
    opacity: 235,
    spacing: 0.15,
    pressure: [0.6, 1.15, 0.5],
    noise: 0.35
  });

  brush.add("soft_glaze", {
    type: "default",
    weight: 14,
    scatter: 0.45,
    sharpness: 0.08,
    grain: 0.28,
    opacity: 28,
    spacing: 0.4,
    pressure: [0.4, 1.2, 0.4],
    noise: 0.4
  });

  brush.add("film_grain", {
    type: "spray",
    weight: 1.1,
    scatter: 6.5,
    opacity: 95,
    spacing: 0.65,
    pressure: [0.7, 1.2, 0.7],
    noise: 0.9
  });

  brush.scaleBrushes(3);
}

function draw() {
  translate(-width / 2, -height / 2);

  // Cross-processed Palette Constants
  const C_ABYSS      = "#011015"; // Brutal shadow cyan-black
  const C_DEEP_TEAL  = "#042630"; // Deep lido shadow teal
  const C_DARK_CYAN  = "#074252"; // Dark cyan-teal
  const C_MID_CYAN   = "#0e6b80"; // Cross-processed midtone cyan
  const C_BRIGHT_CYN = "#1ca3b8"; // Electric pool cyan
  const C_PALE_CYAN  = "#7fe3dc"; // Fog / caustic mint-cyan

  const C_CHART_DEEP = "#b8d916"; // Warm chartreuse transition
  const C_CHART      = "#e8ff38"; // Blown-out acid chartreuse highlight
  const C_CHART_BLOW = "#f9ff9e"; // Overexposed yellow-cream highlight
  const C_WHITE_HOT  = "#feffeb"; // Specular core

  const C_SKIN_DARK  = "#6b112f"; // Deep plum-crimson skin terminator
  const C_SKIN_MAG   = "#a81d46"; // Rich magenta-coral shadow skin
  const C_SKIN_MID   = "#d93b62"; // Strange cross-processed peach-magenta
  const C_SKIN_PEACH = "#f26b83"; // Sunlit wet peach-pink
  const C_SKIN_GLOW  = "#ff9eae"; // High peach transition into chartreuse

  // Base ground: vibrant cross-processed cyan-teal
  background(C_DEEP_TEAL);

  // =========================================================================
  // 1. OUTDOOR LIDO BACKGROUND & CAUSTIC WATER PLANES (Batched Fills/Washes)
  // =========================================================================
  renderLidoBackground({
    C_ABYSS, C_DEEP_TEAL, C_DARK_CYAN, C_MID_CYAN,
    C_BRIGHT_CYN, C_PALE_CYAN, C_CHART_DEEP, C_CHART, C_CHART_BLOW
  });

  // =========================================================================
  // 2. SWIMMER ANATOMY: SWIM CAP, NECK, EMERGING SHOULDER & FACE PLANES
  // =========================================================================
  renderSwimCap({
    C_ABYSS, C_DEEP_TEAL, C_DARK_CYAN, C_MID_CYAN,
    C_BRIGHT_CYN, C_PALE_CYAN, C_CHART, C_CHART_BLOW, C_SKIN_MID
  });

  renderNeckAndShoulder({
    C_ABYSS, C_DEEP_TEAL, C_DARK_CYAN, C_MID_CYAN,
    C_SKIN_DARK, C_SKIN_MAG, C_SKIN_MID, C_SKIN_PEACH, C_SKIN_GLOW,
    C_CHART_DEEP, C_CHART, C_CHART_BLOW, C_WHITE_HOT
  });

  renderFacePlanes({
    C_ABYSS, C_DEEP_TEAL, C_DARK_CYAN, C_MID_CYAN,
    C_SKIN_DARK, C_SKIN_MAG, C_SKIN_MID, C_SKIN_PEACH, C_SKIN_GLOW,
    C_CHART_DEEP, C_CHART, C_CHART_BLOW, C_WHITE_HOT
  });

  // =========================================================================
  // 3. HALF-OPEN BREATHING MOUTH & NOSE DETAIL
  // =========================================================================
  renderNoseAndMouth({
    C_ABYSS, C_DEEP_TEAL, C_DARK_CYAN, C_PALE_CYAN,
    C_SKIN_DARK, C_SKIN_MAG, C_SKIN_MID, C_SKIN_PEACH, C_SKIN_GLOW,
    C_CHART, C_CHART_BLOW, C_WHITE_HOT
  });

  // =========================================================================
  // 4. FOGGED GOGGLES & DOUBLE SILICONE STRAP
  // =========================================================================
  renderFoggedGoggles({
    C_ABYSS, C_DEEP_TEAL, C_DARK_CYAN, C_MID_CYAN, C_BRIGHT_CYN, C_PALE_CYAN,
    C_SKIN_DARK, C_SKIN_MID, C_SKIN_PEACH,
    C_CHART, C_CHART_BLOW, C_WHITE_HOT
  });

  // =========================================================================
  // 5. WATER SHEETING OFF SHOULDER & FOREGROUND BOW-WAVE TROUGH
  // =========================================================================
  renderSheetingWaterAndWaves({
    C_ABYSS, C_DEEP_TEAL, C_DARK_CYAN, C_MID_CYAN, C_BRIGHT_CYN, C_PALE_CYAN,
    C_SKIN_MAG, C_SKIN_MID, C_SKIN_PEACH,
    C_CHART_DEEP, C_CHART, C_CHART_BLOW, C_WHITE_HOT
  });

  // =========================================================================
  // 6. PEN-PICKED DROPLETS, CONDENSATION BEADS & FLYING SPRAY
  // =========================================================================
  renderPenDroplets({
    C_ABYSS, C_DEEP_TEAL, C_DARK_CYAN, C_BRIGHT_CYN, C_PALE_CYAN,
    C_SKIN_DARK, C_SKIN_MID, C_SKIN_PEACH,
    C_CHART, C_CHART_BLOW, C_WHITE_HOT
  });

  // =========================================================================
  // 7. SNAPSHOT EDGE BLUR, VIGNETTE & GRITTY CROSS-PROCESSED SPRAY GRAIN
  // =========================================================================
  renderSnapshotBlurAndGrain({
    C_ABYSS, C_DEEP_TEAL, C_DARK_CYAN, C_BRIGHT_CYN,
    C_SKIN_MID, C_SKIN_PEACH, C_CHART, C_CHART_BLOW
  });

  noLoop();
}

// ===========================================================================
// LAYER 1: OUTDOOR LIDO BACKGROUND & SUBMERGED WATER PLANES
// ===========================================================================
function renderLidoBackground(P) {
  // Deep cyan-teal base washes across upper lido water and lower wave trough
  washUV([[-850, -850], [850, -850], [850, -120], [-850, -80]], P.C_DARK_CYAN, 210, 0.05);
  washUV([[-850, 40], [850, 20], [850, 850], [-850, 850]], P.C_ABYSS, 235, 0.05);

  // Distorted outdoor lido lane line & pool wall tiles in upper-left background
  washUV([[-800, -680], [200, -720], [140, -520], [-800, -470]], P.C_DEEP_TEAL, 200, 0.15);
  washUV([[-780, -460], [650, -560], [620, -340], [-780, -290]], P.C_MID_CYAN, 175, 0.2);
  washUV([[-750, -320], [720, -380], [700, -180], [-750, -160]], P.C_BRIGHT_CYN, 145, 0.2);

  // Sunlit chartreuse caustic networks in background lido water (batched by color)
  const causticShapesChart = [
    [[-640, -490], [-420, -520], [-350, -440], [-560, -410]],
    [[-310, -560], [-40, -590], [40, -500], [-240, -470]],
    [[110, -530], [460, -570], [520, -460], [180, -430]],
    [[-590, -360], [-360, -395], [-290, -325], [-520, -295]],
    [[220, -410], [590, -450], [650, -360], [290, -335]]
  ];
  for (let s of causticShapesChart) {
    watercolorUV(s, P.C_CHART, 130, 0.28, 0.5, 0.25, 0.35);
  }

  const causticShapesBlow = [
    [[-540, -465], [-410, -485], [-380, -435], [-500, -420]],
    [[-210, -540], [-30, -555], [10, -505], [-180, -490]],
    [[260, -490], [480, -515], [510, -460], [310, -440]]
  ];
  for (let s of causticShapesBlow) {
    washUV(s, P.C_CHART_BLOW, 185, 0.35);
  }

  // Horizontal rippled water texture in background lido
  for (let i = 0; i < 42; i++) {
    let uStart = random(-720, 420);
    let uLen = random(110, 320);
    let vPos = random(-660, -190);
    let col = random() < 0.35 ? P.C_CHART : (random() < 0.5 ? P.C_PALE_CYAN : P.C_DEEP_TEAL);
    let w = random(0.7, 1.9);
    splineUV([
      [uStart, vPos, 0.4],
      [uStart + uLen * 0.35, vPos + random(-14, 14), 1.1],
      [uStart + uLen * 0.7, vPos + random(-14, 14), 0.9],
      [uStart + uLen, vPos + random(-8, 8), 0.3]
    ], "marker", col, w, 0.5);
  }

  // Hard marker-blocked dark water bands in upper background for brutal contrast
  markerBlockUV([[-740, -610], [-280, -635], [-220, -555], [-700, -530]], P.C_ABYSS, 210, 11, 4, 1.1, 0.2);
  markerBlockUV([[-120, -650], [420, -680], [460, -585], [-70, -565]], P.C_DEEP_TEAL, 200, 10, -3, 1.1, 0.2);
}

