    [[-165, 115], [-25, 95], [125, 98], [95, 148], [-55, 152]],
    [[145, 85], [345, 58], [465, 72], [395, 125], [185, 122]],
    [[-85, 195], [115, 175], [265, 192], [195, 235], [-35, 228]],
