    ], br, col, wt, 0.45);
  }
}

// ===========================================================================
// LAYER 6: PEN-PICKED WATER DROPLETS, MICRO-BEADS & FLYING SPRAY
// ===========================================================================
function drawDroplet(u, v, r, shadowCol, coreCol, hiCol) {
  // 1. Cast shadow crescent on down-light (+v, +u) side
  let sPts = [
    [u - r * 0.7, v + r * 0.2, 0.5],
    [u + r * 0.2, v + r * 1.15, 1.2],
    [u + r * 1.05, v + r * 0.3, 0.5]
  ];
  splineUV(sPts, "rotring", shadowCol, clampW(r * 0.22), 0.5);

  // 2. Refracted core touch
  if (r > 3.2) {
    let cPoly = [
      [u - r * 0.65, v - r * 0.35],
      [u + r * 0.55, v - r * 0.45],
      [u + r * 0.75, v + r * 0.45],
      [u - r * 0.45, v + r * 0.65]
    ];
    washUV(cPoly, coreCol, 185, 0.4);
  }

  // 3. Crisp pen contour around droplet
  let rimPts = [
    [u - r * 0.85, v, 0.7],
    [u, v - r * 0.85, 1.0],
    [u + r * 0.85, v, 1.1],
    [u, v + r * 0.85, 1.0],
    [u - r * 0.85, v, 0.7]
  ];
  splineUV(rimPts, "micro_pen", shadowCol, clampW(r * 0.2), 0.55);

  // 4. Pinpoint blown-out chartreuse/white highlight on upper-left (-v) side
  lineUV(u - r * 0.35, v - r * 0.45, u + r * 0.2, v - r * 0.5, "pen", hiCol, clampW(r * 0.28));
  if (r > 4.0) {
    // Secondary internal bounce reflection on bottom rim
    lineUV(u - r * 0.15, v + r * 0.55, u + r * 0.35, v + r * 0.45, "micro_pen", hiCol, clampW(r * 0.18));
  }
}

function clampW(w) {
  return constrain(w, 0.45, 1.85);
}

function renderPenDroplets(P) {
  // 1. Skin droplets across forehead, cheekbone, nose bridge, upper lip, chin & shoulder
  const skinRegions = [
    // Forehead & brow
    { uMin: -165, uMax: -95, vMin: -265, vMax: -135, count: 28, rMin: 2.2, rMax: 6.5 },
    // High cheekbone & mid-cheek (hero cluster!)
    { uMin: -95, uMax: 55, vMin: -165, vMax: -15, count: 58, rMin: 2.0, rMax: 8.0 },
    // Nose bridge & tip
    { uMin: -115, uMax: -22, vMin: -10, vMax: 42, count: 22, rMin: 1.8, rMax: 5.5 },
    // Chin & lower lip surround
    { uMin: 55, uMax: 148, vMin: 18, vMax: 85, count: 26, rMin: 2.2, rMax: 6.8 },
    // Neck & emerging deltoid shoulder
    { uMin: 25, uMax: 520, vMin: -295, vMax: -35, count: 75, rMin: 2.2, rMax: 8.5 }
  ];

  for (let reg of skinRegions) {
    for (let i = 0; i < reg.count; i++) {
      let u = random(reg.uMin, reg.uMax);
      let v = random(reg.vMin, reg.vMax);
      let r = random(reg.rMin, reg.rMax);
      let core = random() < 0.45 ? P.C_CHART : P.C_SKIN_PEACH;
      let hi = random() < 0.6 ? P.C_WHITE_HOT : P.C_CHART_BLOW;
      drawDroplet(u, v, r, P.C_ABYSS, core, hi);
    }
  }

  // 2. Droplets & condensation beads on the fogged goggle lenses and gaskets
  for (let i = 0; i < 38; i++) {
    let a = random(360);
    let radU = random(6, 44);
    let radV = random(6, 34);
    let u = -135 + cos(a) * radU;
    let v = -80 + sin(a) * radV;
    let r = random(1.6, 5.2);
    drawDroplet(u, v, r, P.C_DEEP_TEAL, P.C_BRIGHT_CYN, P.C_WHITE_HOT);
  }
  for (let i = 0; i < 22; i++) {
    let a = random(360);
    let u = -152 + cos(a) * random(5, 36);
    let v = 68 + sin(a) * random(5, 28);
    let r = random(1.6, 4.8);
    drawDroplet(u, v, r, P.C_ABYSS, P.C_PALE_CYAN, P.C_CHART_BLOW);
  }

  // 3. Droplets beaded on silicone swim cap & along goggle straps
  for (let i = 0; i < 45; i++) {
    let u = random(-410, -145);
    let v = random(-295, -20);
    let r = random(2.0, 6.2);
    drawDroplet(u, v, r, P.C_ABYSS, P.C_BRIGHT_CYN, P.C_CHART_BLOW);
  }

  // 4. Airborne flying droplets, liquid filaments & ligaments detaching from the sheeting water!
  for (let i = 0; i < 95; i++) {
    let t = random(0, 1);
    let baseU = lerp(-15, 620, t);
    let baseV = -180 - sin(t * 170) * 190 + random(-95, 55);
    let r = random(2.0, 7.5);

    if (random() < 0.4) {
      // Motion-streaked flying liquid filament picked out in pen
      let streakLen = random(14, 38);
      let ang = random(-35, 25);
      let du = cos(ang) * streakLen;
      let dv = sin(ang) * streakLen;
      lineUV(baseU, baseV + 2, baseU + du, baseV + dv + 2, "rotring", P.C_ABYSS, 1.05);
      lineUV(baseU, baseV, baseU + du, baseV + dv, "pen", P.C_CHART, 1.15);
      lineUV(baseU, baseV - 1, baseU + du * 0.6, baseV + dv * 0.6 - 1, "micro_pen", P.C_WHITE_HOT, 1.0);
    } else {
      drawDroplet(baseU, baseV, r, P.C_ABYSS, P.C_CHART, P.C_WHITE_HOT);
    }
  }
}

// ===========================================================================
// LAYER 7: SNAPSHOT EDGE BLUR, CHROMATIC BLEED & GRITTY SPRAY GRAIN
// ===========================================================================
function renderSnapshotBlurAndGrain(P) {
  // 1. Snapshot Edge Blur & Vignette (working directly in canvas coordinates 0..1200)
  // Soft lens-aberrated washes and out-of-focus bokeh streaks around outer border
  const edgeWashes = [
    // Top-left corner vignette
    { pts: [[0, 0], [420, 0], [240, 160], [0, 380]], col: P.C_ABYSS, op: 140 },
    // Top-right corner blur
    { pts: [[780, 0], [1200, 0], [1200, 360], [980, 170]], col: P.C_DEEP_TEAL, op: 135 },
    // Bottom-left corner vignette
    { pts: [[0, 820], [190, 990], [380, 1200], [0, 1200]], col: P.C_ABYSS, op: 165 },
    // Bottom-right corner vignette
    { pts: [[820, 1200], [1010, 1010], [1200, 820], [1200, 1200]], col: P.C_ABYSS, op: 170 }
  ];

  for (let ew of edgeWashes) {
    brush.noStroke();
    brush.noHatch();
    brush.noWash();
    brush.fill(ew.col, ew.op);
    brush.fillBleed(0.45, "out");
    brush.fillTexture(0.65, 0.15);
    brush.beginShape(0.3);
    for (let p of ew.pts) brush.vertex(p[0], p[1]);
    brush.endShape(true);
    brush.noFill();
  }

  // Peripheral snapshot motion/lens blur strokes along all 4 canvas edges
  for (let i = 0; i < 64; i++) {
    let side = i % 4;
    let x1, y1, x2, y2;
    if (side === 0) { // Top edge
      x1 = random(0, 1100); y1 = random(5, 95);
      x2 = x1 + random(80, 220); y2 = y1 + random(-25, 35);
    } else if (side === 1) { // Bottom edge
      x1 = random(0, 1100); y1 = random(1105, 1195);
      x2 = x1 + random(80, 220); y2 = y1 + random(-35, 25);
    } else if (side === 2) { // Left edge
      x1 = random(5, 95); y1 = random(0, 1100);
      x2 = x1 + random(-25, 45); y2 = y1 + random(80, 220);
    } else { // Right edge
      x1 = random(1105, 1195); y1 = random(0, 1100);
      x2 = x1 + random(-45, 25); y2 = y1 + random(80, 220);
    }
    let blurCol = random() < 0.3 ? P.C_SKIN_MID : (random() < 0.5 ? P.C_CHART : P.C_DARK_CYAN);
    brush.set("soft_glaze", blurCol, random(1.2, 2.6));
    brush.line(x1, y1, x2, y2);
  }

  // 2. Gritty Cross-Processed Film Grain covering the entire 1200x1200 canvas
  // Diagonal sweeps of "spray" and custom "film_grain" in cyan, chartreuse, and peach-magenta
  const grainPasses = [
    { col: P.C_DEEP_TEAL, count: 65, brushName: "film_grain", wMin: 0.8, wMax: 1.5 },
    { col: P.C_CHART,     count: 55, brushName: "film_grain", wMin: 0.7, wMax: 1.3 },
    { col: P.C_SKIN_PEACH,count: 42, brushName: "spray",      wMin: 0.7, wMax: 1.2 },
    { col: P.C_ABYSS,     count: 48, brushName: "spray",      wMin: 0.8, wMax: 1.4 },
    { col: P.C_CHART_BLOW,count: 35, brushName: "spray",      wMin: 0.6, wMax: 1.1 }
  ];

  for (let gp of grainPasses) {
    for (let i = 0; i < gp.count; i++) {
      let x1 = random(-40, 1240);
      let y1 = random(-40, 1240);
      let len = random(140, 420);
      let ang = TILT + random(-28, 28);
      let x2 = x1 + cos(ang) * len;
      let y2 = y1 + sin(ang) * len;
      brush.set(gp.brushName, gp.col, random(gp.wMin, gp.wMax));
      brush.line(x1, y1, x2, y2);
    }
  }
}

