function draw() {
  translate(-width / 2, -height / 2);

  // Warm backlit parchment ground (light radiating from within the glass)
  background("#fcf6e4");
  brush.set("HB", "#181416", 1);

  // Plate geometry parameters
  const plate = {
    cx: 605,
    cy: 685,
    rxOuter: 535,
    ryOuter: 385,
    rxMid: 430,
    ryMid: 305,
    rxWell: 398,
    ryWell: 280,
    tilt: -5.5
  };

  // Helper to get point on tilted plate ellipse
  function platePt(rNormX, rNormY, angDeg, cxOff = 0, cyOff = 0) {
    let rad = angDeg;
    let lx = cos(rad) * rNormX;
    let ly = sin(rad) * rNormY;
    let c = cos(plate.tilt);
    let s = sin(plate.tilt);
    return [
      plate.cx + cxOff + lx * c - ly * s,
      plate.cy + cyOff + lx * s + ly * c
    ];
  }

  // Helper to draw a closed polygon with brush.beginShape
  function drawPoly(pts, curvature = 0.08) {
    if (!pts || pts.length < 3) return;
    brush.beginShape(curvature);
    for (let i = 0; i < pts.length; i++) {
      brush.vertex(pts[i][0], pts[i][1]);
    }
    brush.endShape(true);
  }

  // Helper for linear interpolation between two 2D points
  function lerpPt(p1, p2, t) {
    return [lerp(p1[0], p2[0], t), lerp(p1[1], p2[1], t)];
  }

  // Helper for polygon centroid
  function polyCenter(pts) {
    let sx = 0, sy = 0;
    for (let p of pts) {
      sx += p[0];
      sy += p[1];
    }
    return [sx / pts.length, sy / pts.length];
  }

  // Shrink or expand polygon toward its center
  function scalePoly(pts, factor, customCenter = null) {
    let c = customCenter || polyCenter(pts);
    return pts.map(p => [
      lerp(c[0], p[0], factor),
      lerp(c[1], p[1], factor)
    ]);
  }

  // =========================================================================
  // 1. BUILD GEOMETRY FOR BACKGROUND SURROUND & GREEN GLASS PLATE
  // =========================================================================
  let bgTiles = [];
  let rimTiles = [];
  let jewelTiles = [];
  let wellTiles = [];
  let allSolderJoints = [];

  const nSectors = 32;
  const ringRadii = [
    [1.0, 1.0],       // 0: inner well edge
    [1.08, 1.08],     // 1: cabochon jewel band outer edge
    [1.345, 1.375],   // 2: outer plate rim edge
    [1.62, 1.72],     // 3: first background surround ring
    [2.15, 2.35]      // 4: outer canvas surround ring
  ];

  // Well concentric rings
  const wellRings = [0.16, 0.38, 0.66, 1.0];

  // Generate Background Surround Tiles (rings 2->3 and 3->4)
  for (let rIdx = 2; rIdx < 4; rIdx++) {
    let rA = ringRadii[rIdx];
    let rB = ringRadii[rIdx + 1];
    for (let i = 0; i < nSectors; i++) {
      let a1 = (i * 360) / nSectors;
      let a2 = ((i + 1) * 360) / nSectors;
      let shift = (rIdx % 2 === 1) ? (180 / nSectors) : 0;
      let p1 = platePt(plate.rxWell * rA[0], plate.ryWell * rA[1], a1 + shift);
      let p2 = platePt(plate.rxWell * rA[0], plate.ryWell * rA[1], a2 + shift);
      let p3 = platePt(plate.rxWell * rB[0], plate.ryWell * rB[1], a2 + shift);
      let p4 = platePt(plate.rxWell * rB[0], plate.ryWell * rB[1], a1 + shift);
      let pts = [p1, p2, p3, p4];
      let c = polyCenter(pts);
      // Only include tiles near or inside canvas bounds
      if (c[0] > -180 && c[0] < 1380 && c[1] > -180 && c[1] < 1380) {
        bgTiles.push({ pts, center: c, sector: i, ring: rIdx });
        allSolderJoints.push(p1, p2);
      }
    }
  }

  // Generate Plate Outer Rim Tiles & Cabochon Jewel Band
  for (let i = 0; i < nSectors; i++) {
    let a1 = (i * 360) / nSectors;
    let a2 = ((i + 1) * 360) / nSectors;
    let aMid = (a1 + a2) * 0.5;

    // Jewel band (between ring 0 and ring 1)
    let j1 = platePt(plate.rxWell * ringRadii[0][0], plate.ryWell * ringRadii[0][1], a1);
    let j2 = platePt(plate.rxWell * ringRadii[0][0], plate.ryWell * ringRadii[0][1], a2);
    let j3 = platePt(plate.rxWell * ringRadii[1][0], plate.ryWell * ringRadii[1][1], a2);
    let j4 = platePt(plate.rxWell * ringRadii[1][0], plate.ryWell * ringRadii[1][1], a1);
    jewelTiles.push({
      pts: [j1, j2, j3, j4],
      center: polyCenter([j1, j2, j3, j4]),
      sector: i,
      angle: aMid
    });
    allSolderJoints.push(j1, j4);

    // Scalloped Outer Rim Tile (between ring 1 and ring 2, with slightly arched outer lip)
    let r1 = j4;
    let r2 = j3;
    let r3 = platePt(plate.rxWell * ringRadii[2][0], plate.ryWell * ringRadii[2][1], a2);
    let rMid = platePt(plate.rxWell * (ringRadii[2][0] + 0.018), plate.ryWell * (ringRadii[2][1] + 0.018), aMid);
    let r4 = platePt(plate.rxWell * ringRadii[2][0], plate.ryWell * ringRadii[2][1], a1);
    rimTiles.push({
      pts: [r1, r2, r3, rMid, r4],
      center: polyCenter([r1, r2, r3, r4]),
      sector: i,
      angle: aMid
    });
    allSolderJoints.push(r3, r4);
  }

  // Generate Plate Inner Well Tiles (concentric rings of cooler green glass)
  const wellSectors = 16;
  for (let wIdx = 0; wIdx < wellRings.length - 1; wIdx++) {
    let f1 = wellRings[wIdx];
    let f2 = wellRings[wIdx + 1];
    let secCount = (wIdx === 0) ? 8 : wellSectors;
    for (let i = 0; i < secCount; i++) {
      let a1 = (i * 360) / secCount + wIdx * 11;
      let a2 = ((i + 1) * 360) / secCount + wIdx * 11;
      let aMid = (a1 + a2) * 0.5;
      let p1 = platePt(plate.rxWell * f1, plate.ryWell * f1, a1);
      let p1m = platePt(plate.rxWell * f1, plate.ryWell * f1, aMid);
      let p2 = platePt(plate.rxWell * f1, plate.ryWell * f1, a2);
      let p3 = platePt(plate.rxWell * f2, plate.ryWell * f2, a2);
      let p3m = platePt(plate.rxWell * f2, plate.ryWell * f2, aMid);
      let p4 = platePt(plate.rxWell * f2, plate.ryWell * f2, a1);
      let pts = [p1, p1m, p2, p3, p3m, p4];
      wellTiles.push({
        pts,
        center: polyCenter(pts),
        ring: wIdx,
        sector: i,
        angle: aMid
      });
      allSolderJoints.push(p1, p4);
    }
  }

  // Center medallion of the plate well
  let centerMedallion = [];
  for (let i = 0; i < 16; i++) {
    centerMedallion.push(platePt(plate.rxWell * wellRings[0], plate.ryWell * wellRings[0], (i * 360) / 16));
  }
  wellTiles.push({
    pts: centerMedallion,
    center: [plate.cx, plate.cy],
    ring: -1,
    sector: 0,
    angle: 0
  });

  // =========================================================================
  // 2. RENDER BACKGROUND SURROUND & GREEN GLASS PLATE (WATERCOLOR + STREAKS)
  // =========================================================================

  // Helper to paint opalescent streaks inside a tile
  function paintOpalStreaks(pts, baseAngle, streakColors, count = 6, weight = 1.1) {
    let c = polyCenter(pts);
    for (let k = 0; k < count; k++) {
      let t1 = (k + 0.5) / count;
      let idxA = floor(random(pts.length));
      let idxB = (idxA + 1) % pts.length;
      let idxC = (idxA + floor(pts.length / 2)) % pts.length;
      let idxD = (idxC + 1) % pts.length;
      let startP = lerpPt(pts[idxA], pts[idxB], t1);
      let endP = lerpPt(pts[idxC], pts[idxD], 1 - t1);
      startP = lerpPt(c, startP, 0.88);
      endP = lerpPt(c, endP, 0.88);
      let midP = [
        lerp(startP[0], endP[0], 0.5) + random(-10, 10),
        lerp(startP[1], endP[1], 0.5) + random(-10, 10)
      ];
      let col = random(streakColors);
      brush.set("opal_streak", col, weight * random(0.75, 1.3));
      brush.spline([
        [startP[0], startP[1], 0.4],
        [midP[0], midP[1], 1.2],
        [endP[0], endP[1], 0.4]
      ], 0.45);
    }
  }

  // 2A. Background Surround Tiles (Soft Edwardian muted pastel mauve, antique taupe, dusty plum-pearl)
  const bgPaletteDark = ["#584a52", "#6b5a63", "#4d4147", "#7c6a72"];
  const bgPaletteMid = ["#948188", "#ab989c", "#87777e", "#b8a6a4"];
  const bgPaletteLight = ["#d2c2bc", "#e3d6cc", "#c7b6b2", "#ebe0d5"];

  brush.noStroke();
  for (let tile of bgTiles) {
    // Distance to upper-left light source (380, 260)
    let dLight = dist(tile.center[0], tile.center[1], 420, 300);
    let pal = dLight < 520 ? bgPaletteLight : (dLight < 820 ? bgPaletteMid : bgPaletteDark);
    let col = pal[(tile.sector + tile.ring) % pal.length];
    brush.wash(col, 195);
    drawPoly(tile.pts, 0.04);
    brush.noWash();

    // Subtle opalescent streaks in background glass
    paintOpalStreaks(
      tile.pts,
      tile.sector * 11,
      ["#f5ece2", "#d8c7c8", "#8f7d85", "#52444c", "#e8d5e6"],
      5,
      1.3
    );
  }

  // 2B. Batched Watercolor Glazes on the Cooler Green Glass Plate
  // Group green tiles into color batches for authentic watercolor bleed & fast caching
  const plateGreenBatches = [
    { fill: "#cfeadd", wash: "#e5f6ee", bleed: 0.16 }, // Pastel milky mint
    { fill: "#a8d8c2", wash: "#c4e8d7", bleed: 0.18 }, // Soft seafoam opal
    { fill: "#84bfa6", wash: "#a5d4bf", bleed: 0.18 }, // Celadon Tiffany glass
    { fill: "#63a189", wash: "#80b8a1", bleed: 0.20 }, // Deeper sage-jade glass
    { fill: "#bed8a8", wash: "#d8ebC5", bleed: 0.17 }  // Warm amber-tinted green glass (under honey)
  ];

  let batchedGreenPolys = [[], [], [], [], []];

  for (let tile of rimTiles) {
    let dLight = dist(tile.center[0], tile.center[1], 450, 340);
    let bIdx = (tile.sector % 3 === 0) ? 0 : (dLight < 480 ? 1 : (dLight < 720 ? 2 : 3));
    batchedGreenPolys[bIdx].push(tile.pts);
  }

  for (let tile of wellTiles) {
    // Tiles under the lower-right honey drip zone get warm golden-green transmitted light
    let dHoney = dist(tile.center[0], tile.center[1], 685, 765);
    let dSlab = dist(tile.center[0], tile.center[1], 530, 560);
    let bIdx = 1;
    if (dHoney < 230) bIdx = 4;
    else if (dSlab < 260) bIdx = 3;
    else if ((tile.sector + tile.ring) % 3 === 0) bIdx = 0;
    else if ((tile.sector + tile.ring) % 2 === 0) bIdx = 2;
    batchedGreenPolys[bIdx].push(tile.pts);
  }

  // Execute batched washes & watercolor fills for the green plate
  brush.noStroke();
  for (let b = 0; b < batchedGreenPolys.length; b++) {
    let spec = plateGreenBatches[b];
    for (let pts of batchedGreenPolys[b]) {
      brush.wash(spec.wash, 185);
      drawPoly(pts, 0.06);
      brush.noWash();
    }
    brush.fill(spec.fill, 125);
    brush.fillBleed(spec.bleed, "in");
    brush.fillTexture(0.55, 0.42);
    for (let pts of batchedGreenPolys[b]) {
      drawPoly(pts, 0.06);
    }
    brush.noFill();
  }

  // 2C. Cabochon Jewel Band (Soft pastel aqua, pearl-mint, and lavender-opal jewels)
  const jewelColors = ["#d6f2ea", "#b8e3e8", "#e4d8ec", "#fff9e6", "#bce8d2"];
  for (let j of jewelTiles) {
    let jCol = jewelColors[j.sector % jewelColors.length];
    brush.noStroke();
    brush.wash(jCol, 225);
    drawPoly(j.pts, 0.12);
    brush.noWash();

    // Inner glowing cabochon highlight
    brush.set("glaze_soft", "#ffffff", 0.55);
    brush.circle(j.center[0] - 2, j.center[1] - 2, 4.5, 0.15);
  }

  // 2D. Streaky Opalescent Striations across every Plate Tile
  for (let tile of rimTiles) {
    paintOpalStreaks(
      tile.pts,
      tile.angle + 90,
      ["#f7fff9", "#d8f2e5", "#7ab89e", "#528e76", "#fff6df"],
      6,
      1.0
    );
  }

  for (let tile of wellTiles) {
    let dHoney = dist(tile.center[0], tile.center[1], 680, 760);
    let streakPal = dHoney < 250
      ? ["#fff8dc", "#f5d78e", "#a2d4b4", "#6ba68b", "#e3f2d5"]
      : ["#f4fff9", "#cbeadd", "#7bb89f", "#4d8770", "#e6f5ec"];
    paintOpalStreaks(tile.pts, tile.angle + 90, streakPal, 7, 1.05);
  }

  // Cast shadow & warm golden backlit caustic glow on the plate well beneath the slab & honey
  brush.noStroke();
  let causticZone = [];
  for (let a = 0; a < 360; a += 20) {
    causticZone.push([
      675 + cos(a) * 245 + sin(a * 2) * 18,
      775 + sin(a) * 155 + cos(a * 3) * 12
    ]);
  }
  brush.fill("#f7c868", 85);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.6, 0.3);
  drawPoly(causticZone, 0.25);
  brush.noFill();

  // Deep cool emerald-amber shadow directly under the overhanging slab cliff
  let underSlabShadow = [
    [290, 560], [510, 490], [820, 530], [855, 695],
    [680, 815], [440, 775], [275, 650]
  ];
  brush.fill("#2f5446", 95);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.5, 0.45);
  drawPoly(underSlabShadow, 0.2);
  brush.noFill();

  // =========================================================================
  // 3. GENERATE 3D TILTED HONEYCOMB SLAB GEOMETRY
  // =========================================================================
  // Axial hex grid (q, r) projected onto a tilted 3D slab with organic honey sag
  const hexSide = 25.5;
  const slabOriginX = 535;
  const slabOriginY = 485;

  // Transform axial (q, r) + local offsets (dx, dy) + height z into 2D screen space
  function projectSlabPoint(lx, ly, z = 0) {
    // Rotate slab slightly in plane
    let rot = -14;
    let rx = lx * cos(rot) - ly * sin(rot);
    let ry = lx * sin(rot) + ly * cos(rot);

    // 3D foreshortening & tilt toward lower-right
    let px = slabOriginX + rx * 1.04 - ry * 0.22;
    let py = slabOriginY + rx * 0.16 + ry * 0.68;

    // Organic softening/sagging near the lower-right cliff where honey pulls down
    let sagFactor = constrain(map(px + py * 1.15, 1020, 1520, 0, 1), 0, 1);
    sagFactor = pow(sagFactor, 1.7);
    let nWarp = (noise(lx * 0.008 + 10, ly * 0.008 + 10) - 0.5) * 14;

    px += sagFactor * 26 + nWarp * 0.5;
    py += sagFactor * 52 + nWarp * 0.4 - z;
    return [px, py];
  }

  // Determine which (q, r) cells belong to our thick cut slab of honeycomb
  function isCellInSlab(q, r) {
    // Irregular organic hexagonal-wedge slab shape
    let lx = hexSide * sqrt(3) * (q + r * 0.5);
    let ly = hexSide * 1.5 * r;
    let normDist = sqrt(pow(lx / 295, 2) + pow(ly / 235, 2));
    let edgeNoise = (noise(q * 0.35 + 5, r * 0.35 + 5) - 0.48) * 0.28;
    // Trim corners for an authentic cut comb slab
    if (q + r > 7) return false;
    if (q + r < -7) return false;
    if (q > 7 || q < -7 || r > 6 || r < -6) return false;
    return (normDist + edgeNoise) < 1.02;
  }

  let cellMap = new Map();
  let cells = [];

  for (let r = -6; r <= 6; r++) {
    for (let q = -7; q <= 7; q++) {
      if (!isCellInSlab(q, r)) continue;
      let cxLocal = hexSide * sqrt(3) * (q + r * 0.5);
      let cyLocal = hexSide * 1.5 * r;

      let topPts = [];
      let botPts = [];
      let innerPts = [];

      // Slab thickness varies slightly (thicker in front-center, slightly tapered at back)
      let thickness = map(r, -5, 5, 52, 84) + (noise(q * 0.3, r * 0.3) - 0.5) * 12;

      for (let v = 0; v < 6; v++) {
        let ang = 30 + v * 60; // Pointy-top hexagons
        let vx = cxLocal + hexSide * cos(ang);
        let vy = cyLocal + hexSide * sin(ang);
        topPts.push(projectSlabPoint(vx, vy, thickness));
        botPts.push(projectSlabPoint(vx, vy, 0));
        // Deeper point inside the cell tube for 3D uncapped cells
        innerPts.push(projectSlabPoint(
          lerp(cxLocal, vx, 0.62),
          lerp(cyLocal, vy, 0.62),
          thickness - 26
        ));
      }

      let centerTop = projectSlabPoint(cxLocal, cyLocal, thickness);
      let centerInner = projectSlabPoint(cxLocal, cyLocal, thickness - 28);

      // Classify cell state for hyperreal variety
      let nVal = noise(q * 0.32 + 20, r * 0.32 + 20);
      let dripProx = dist(centerTop[0], centerTop[1], 675, 595);
      let leftEdgeProx = dist(centerTop[0], centerTop[1], 315, 450);

      let state = "uncapped";
      if (dripProx < 145) {
        state = "overflow"; // Heavy sagging honey overflowing the hex walls
      } else if (leftEdgeProx < 135 || (r <= -4 && q <= 1)) {
        state = "green_translucent"; // Thinner comb where cooler green plate glass shows through
      } else if (nVal > 0.53 || (q <= -1 && r >= -2 && r <= 2 && nVal > 0.42)) {
        state = "capped"; // Milky-cream opalescent wax cap
      } else if (nVal > 0.44) {
        state = "partial_cap"; // Torn milky wax rim over glowing amber honey
      } else {
        state = "uncapped"; // Deep 3D hexagonal liquid honey well
      }

      let cellObj = {
        q, r,
        cxLocal, cyLocal,
        topPts,
        botPts,
        innerPts,
        centerTop,
        centerInner,
        thickness,
        state,
        nVal
      };
      cellMap.set(`${q},${r}`, cellObj);
      cells.push(cellObj);
    }
  }

  // Sort cells back-to-front by screen Y
  cells.sort((a, b) => a.centerTop[1] - b.centerTop[1]);

  // Neighbor directions for pointy-top axial hexes (matching edge v -> (v+1)%6)
  // v=0: 30 deg, v=1: 90 deg, v=2: 150 deg, v=3: 210 deg, v=4: 270 deg, v=5: 330 deg
  const neighborDirs = [
    [0, 1],   // edge 0 (between 30 and 90 deg): SE neighbor
    [-1, 1],  // edge 1 (between 90 and 150 deg): SW neighbor
    [-1, 0],  // edge 2 (between 150 and 210 deg): W neighbor
    [0, -1],  // edge 3 (between 210 and 270 deg): NW neighbor
    [1, -1],  // edge 4 (between 270 and 330 deg): NE neighbor
    [1, 0]    // edge 5 (between 330 and 30 deg): E neighbor
  ];

  // =========================================================================
  // 4. RENDER 3D SIDE WALLS OF THE HONEYCOMB SLAB (TUBULAR CROSS-SECTIONS)
  // =========================================================================
  let sideWallPolys = [];

  for (let cell of cells) {
    // Check front-facing edges (edges 0, 1, 2, 5 that face downward/outward in perspective)
    for (let e of [0, 1, 2, 5]) {
      let nd = neighborDirs[e];
      let nKey = `${cell.q + nd[0]},${cell.r + nd[1]}`;
      if (!cellMap.has(nKey)) {
        let v1 = e;
        let v2 = (e + 1) % 6;
        let pTop1 = cell.topPts[v1];
        let pTop2 = cell.topPts[v2];
        let pBot2 = cell.botPts[v2];
        let pBot1 = cell.botPts[v1];
        // Only draw visible front/side cliff walls
        if ((pBot1[1] + pBot2[1]) * 0.5 > (pTop1[1] + pTop2[1]) * 0.5 + 8) {
          sideWallPolys.push({
            pts: [pTop1, pTop2, pBot2, pBot1],
            center: polyCenter([pTop1, pTop2, pBot2, pBot1]),
            cell,
            edge: e
          });
          allSolderJoints.push(pBot1, pBot2);
        }
      }
    }
  }

  // Sort side walls back-to-front
  sideWallPolys.sort((a, b) => a.center[1] - b.center[1]);

  for (let wall of sideWallPolys) {
    let wPts = wall.pts;
    let isGreenEdge = wall.cell.state === "green_translucent";
    let isRightSide = wall.center[0] > 560;

    let baseCol = isGreenEdge
      ? "#b5d9be"
      : (isRightSide ? "#d67724" : "#f0b456");

    brush.noStroke();
    brush.wash(baseCol, 225);
    drawPoly(wPts, 0.04);
    brush.noWash();

    // Vertical opalescent tube striations inside each 3D comb wall
    for (let s = 1; s <= 3; s++) {
      let t = s / 4;
      let topM = lerpPt(wPts[0], wPts[1], t);
      let botM = lerpPt(wPts[3], wPts[2], t);
      let midM = [lerp(topM[0], botM[0], 0.5) + random(-3, 3), lerp(topM[1], botM[1], 0.5)];
      let sCol = isGreenEdge
        ? (s === 2 ? "#e8f7ec" : "#7eb89c")
        : (s === 2 ? "#fff6d6" : (isRightSide ? "#f5c26b" : "#c7621a"));
      brush.set("opal_streak", sCol, 1.05);
      brush.spline([[topM[0], topM[1], 0.5], [midM[0], midM[1], 1.2], [botM[0], botM[1], 0.5]], 0.3);
    }
  }

  // =========================================================================
  // 5. RENDER HONEYCOMB TOP FACE CELLS (WATERCOLOR + OPALESCENT GLAZES)
  // =========================================================================

  // Batch watercolor washes & bleeds by cell state first for rich internal glow
  let uncappedPolys = [];
  let cappedPolys = [];
  let greenCellPolys = [];
  let overflowPolys = [];

  for (let cell of cells) {
    if (cell.state === "capped" || cell.state === "partial_cap") cappedPolys.push(cell.topPts);
    else if (cell.state === "green_translucent") greenCellPolys.push(cell.topPts);
    else if (cell.state === "overflow") overflowPolys.push(cell.topPts);
    else uncappedPolys.push(cell.topPts);
  }

  brush.noStroke();
  // Batch 1: Milky-cream & pastel peach wax caps
  for (let pts of cappedPolys) {
    brush.wash("#fcf0d5", 220);
    drawPoly(pts, 0.05);
    brush.noWash();
  }
  brush.fill("#f7dfc2", 115);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.5, 0.35);
  for (let pts of cappedPolys) drawPoly(pts, 0.05);
  brush.noFill();

  // Batch 2: Cooler green translucent wax cells (plate showing through)
  for (let pts of greenCellPolys) {
    brush.wash("#d2ede0", 210);
    drawPoly(pts, 0.05);
    brush.noWash();
  }
  brush.fill("#96ccb4", 125);
  brush.fillBleed(0.16, "in");
  brush.fillTexture(0.5, 0.4);
  for (let pts of greenCellPolys) drawPoly(pts, 0.05);
  brush.noFill();

  // Batch 3: Deep uncapped topaz & butterscotch cells
  for (let pts of uncappedPolys) {
    brush.wash("#f5c26b", 220);
    drawPoly(pts, 0.05);
    brush.noWash();
  }
  brush.fill("#e38d32", 130);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.6, 0.45);
  for (let pts of uncappedPolys) drawPoly(pts, 0.05);
  brush.noFill();

  // Batch 4: Overflowing rich amber-butterscotch cells
  for (let pts of overflowPolys) {
    brush.wash("#f0a846", 225);
    drawPoly(pts, 0.05);
    brush.noWash();
  }
  brush.fill("#d16b1c", 140);
  brush.fillBleed(0.2, "in");
  brush.fillTexture(0.65, 0.5);
  for (let pts of overflowPolys) drawPoly(pts, 0.05);
  brush.noFill();

  // Now render detailed 3D internal cell structure and streaky glazes for each cell
  for (let cell of cells) {
    let tPts = cell.topPts;
    let iPts = cell.innerPts;
    let cTop = cell.centerTop;

    // Record hex vertices for solder joints
    for (let p of tPts) allSolderJoints.push(p);

    if (cell.state === "uncapped" || cell.state === "overflow") {
      // Draw 3 receding internal hex walls (upper-left edges 3, 4, 5 visible inside the cell)
      const wallColors = ["#b85416", "#d97824", "#f0a948"];
      brush.noStroke();
      for (let w = 0; w < 3; w++) {
        let e = (w + 3) % 6;
        let eNext = (e + 1) % 6;
        let wallQuad = [tPts[e], tPts[eNext], iPts[eNext], iPts[e]];
        brush.wash(wallColors[w], 195);
        drawPoly(wallQuad, 0.02);
        brush.noWash();
      }

      // Glowing backlit bottom floor of the cell (light coming from within the glass)
      let floorCol = cell.state === "overflow" ? "#ffe9a8" : "#fff9de";
      brush.wash(floorCol, 235);
      drawPoly(iPts, 0.08);
      brush.noWash();

      // Streaky opalescent glazes across the cell
      paintOpalStreaks(
        tPts,
        35,
        ["#fffbe8", "#f7cc7c", "#e68a2e", "#bd5214", "#fae4ad"],
        5,
        0.95
      );

      // Curved glossy meniscus highlight inside the liquid honey well
      brush.set("refract_strand", "#fffdf2", 1.15);
      brush.arc(cTop[0] - 2, cTop[1] - 2, hexSide * 0.48, 200, 330);

    } else if (cell.state === "capped") {
      // Milky-cream, pastel peach & buttercream opalescent wax cap
      let innerCap = scalePoly(tPts, 0.76, cTop);
      brush.noStroke();
      brush.wash(cell.nVal > 0.62 ? "#fffdf5" : "#fae8d2", 220);
      drawPoly(innerCap, 0.14);
      brush.noWash();

      // Streaky milky-cream and soft butterscotch swirls
      paintOpalStreaks(
        tPts,
        -25,
        ["#ffffff", "#fff6e0", "#f7d4b2", "#f2c47e", "#e8b068"],
        6,
        1.0
      );

      // Crystalline wax cap stipple & highlight rim
      brush.set("wax_stipple", "#fffef7", 0.9);
      brush.circle(cTop[0], cTop[1], hexSide * 0.35, 0.25);
      brush.set("refract_strand", "#ffffff", 0.95);
      brush.arc(cTop[0] - 3, cTop[1] - 3, hexSide * 0.52, 195, 315);

    } else if (cell.state === "partial_cap") {
      // Milky-cream wax cap with a torn central opening revealing dark golden honey
      paintOpalStreaks(
        tPts,
        15,
        ["#fffdf4", "#f7e0bc", "#f2bd6e", "#f9dcd0"],
        5,
        0.95
      );
      let holePts = scalePoly(tPts, 0.56, [cTop[0] + 2, cTop[1] + 2]);
      brush.noStroke();
      brush.wash("#c96018", 230);
      drawPoly(holePts, 0.22);
      brush.noWash();

      // Bright inner glow inside the torn opening
      let corePts = scalePoly(tPts, 0.32, [cTop[0] + 3, cTop[1] + 3]);
      brush.wash("#ffe699", 220);
      drawPoly(corePts, 0.25);
      brush.noWash();

      // Crisp white wax rim & liquid meniscus
      brush.set("refract_strand", "#fffef8", 1.25);
      drawPoly(holePts, 0.22);

    } else if (cell.state === "green_translucent") {
      // Cooler green glass showing through thinner translucent wax cells
      let innerGreen = scalePoly(tPts, 0.68, cTop);
      brush.noStroke();
      brush.wash("#e3f7ec", 210);
      drawPoly(innerGreen, 0.1);
      brush.noWash();

      paintOpalStreaks(
        tPts,
        45,
        ["#f5fff9", "#bce6d1", "#7ab89c", "#f7e5a6", "#d8f2e4"],
        5,
        0.95
      );
      brush.set("refract_strand", "#f7fffb", 0.9);
      brush.arc(cTop[0] - 2, cTop[1] - 2, hexSide * 0.45, 200, 320);
    }
  }

  // =========================================================================
  // 6. SAGGING HONEY DRAPES & POOL ON THE PLATE (TIFFANY LEADED LOBES + GLAZES)
  // =========================================================================
  // Construct interconnected leaded glass lobes for the honey pool and sagging curtains
  // Drawn from bottom pool ripples up to the sagging cliff curtains so overlaps stack naturally

  const honeyLobes = [
    // Outer lower-right pool ripple on the green plate (greenish-amber refractive edge)
    {
      pts: [
        [520, 865], [605, 915], [715, 938], [825, 922],
        [895, 875], [905, 815], [845, 785], [725, 825], [585, 820]
      ],
      wash: "#e6b85c",
      fill: "#c98b32",
      streaks: ["#fff7d6", "#d4e08e", "#9ec488", "#f2b85c", "#c76b1e"],
      isPool: true
    },
    // Outer front-left pool lobe on the green plate
    {
      pts: [
        [435, 795], [470, 858], [545, 882], [625, 862],
        [615, 795], [525, 760], [455, 758]
      ],
      wash: "#f0be62",
      fill: "#d98829",
