function draw() {
  translate(-width / 2, -height / 2);
  background("#c6ccd2");

  // 1. Cool grey granite ground: mineral washes, crystalline quartz/biotite grain, rock fissures
  drawGraniteGround();

  // 2. Medieval manuscript crag frame: scribe drypoint layout lines, corner arcs & chiselled border
  drawManuscriptCragFrame();

  // 3. Crustose map lichen (Rhizocarpon geographicum) colonies on the granite slab
  drawGraniteLichenColonies(false);

  // 4. Deep multi-layered graphite cast shadows of the 3D knot onto the granite slab
  drawKnotCastShadows();

  // 5. Strict over-under 3D braided climbing ropes (z-sorted sub-segments)
  drawBraidedClimbingRopes();

  // 6. Final atmospheric chalk dust, rope frays catching sunlight, and border lichen details
  drawGraniteLichenColonies(true);
  drawFinalChalkAndMicroFray();

  noLoop();
}

