// CELTIC KNOT TOPOLOGY & STRICT OVER-UNDER SOLVER
// ============================================================================

function buildCelticRopeSystem() {
  const cx = 600;
  const cy = 600;
  const sc = 0.96;

  // Rope 0: Vibrant Magenta Lead Rope (Corner loops & inner octagonal ring)
  const qRope0 = [
    [-46, -136],
    [-278, -154],
    [-408, -282],
    [-424, -398],
    [-398, -424],
    [-282, -408],
    [-154, -278],
    [-136, -46]
  ];

  // Rope 1: Electric Blue Rope (45-degree rotated cardinal border arches & central star)
  const qRope1Base = [
    [-38, -112],
    [-242, -128],
    [-368, -238],
    [-312, -296],
    [-296, -312],
    [-238, -368],
    [-128, -242],
    [-112, -38]
  ];
  const cos45 = Math.SQRT1_2;
  const qRope1 = qRope1Base.map(([x, y]) => {
    let rx = (x - y) * cos45;
    let ry = (x + y) * cos45;
    // Gently square-fit outer cardinal arches to the manuscript border
    let r = Math.hypot(rx, ry);
    let boost = r > 320 ? 0.965 : 0.92;
    return [rx * boost, ry * boost];
  });

  // Rope 2: Mineral Lichen-Lime Rope (Outer perimeter & mid-court interlocking wreath)
  const qRope2 = [
    [-226, -86],
    [-366, -138],
    [-416, -232],
    [-324, -324],
    [-232, -416],
    [-138, -366],
    [-86, -226]
  ];

  const paletteDefs = [
    {
      // Accent Rope: Vibrant Magenta (Primary focal accent)
      name: "magenta",
      radius: 23.5,
      wash: "#8c1449",
      deepShadow: "#240815",
      midShadow: "#590d30",
      coreColor: "#b8145d",
      brightColor: "#e6227a",
      burnishLight: "#ff66ab",
      chalkTint: "#ffd9ea",
      fleckDark: "#1a1f29",
      fleckLight: "#f0f4f8",
      patternPeriod: 4
    },
    {
      // Electric Blue Rope (Toned with cool graphite & crag chalk)
      name: "electric_blue",
      radius: 22.5,
      wash: "#235380",
      deepShadow: "#101b29",
      midShadow: "#1b3959",
      coreColor: "#2467a6",
      brightColor: "#3895eb",
      burnishLight: "#7ec4ff",
