      name: "lime",
      radius: 21.5,
      wash: "#56701e",
      deepShadow: "#182110",
      midShadow: "#354714",
      coreColor: "#6c911f",
      brightColor: "#98c92a",
      burnishLight: "#c7f056",
      chalkTint: "#eefad2",
      fleckDark: "#1f261b",
      fleckLight: "#ebede6",
      patternPeriod: 4
    }
  ];

  const quadTemplates = [qRope0, qRope1, qRope2];

  for (let r = 0; r < 3; r++) {
    const qPts = quadTemplates[r];
    const ctrlPts = [];
    for (let q = 0; q < 4; q++) {
      for (let i = 0; i < qPts.length; i++) {
        let [x, y] = qPts[i];
        x *= sc;
        y *= sc;
        let rx, ry;
        if (q === 0) { rx = x; ry = y; }
        else if (q === 1) { rx = -y; ry = x; }
        else if (q === 2) { rx = -x; ry = -y; }
        else { rx = y; ry = -x; }
        ctrlPts.push({ x: cx + rx, y: cy + ry });
      }
    }

    // Resample closed Catmull-Rom spline to uniform arc-length steps (ds = 4.5 px)
    const densePts = sampleClosedSpline(ctrlPts, 28);
    const uniformPts = resampleUniformClosed(densePts, 4.5);

    ropes.push({
      id: r,
      palette: paletteDefs[r],
      points: uniformPts,
      crossings: []
    });
  }

  // Find all transverse 2-strand intersections across all 3 ropes
  findAndAssignStrictOverUnder();

  // Build z-sorted sub-segments for painter's algorithm rendering
  buildSortedSubSegments();
}

function sampleClosedSpline(ctrl, stepsPerSeg) {
  const n = ctrl.length;
  const out = [];
  for (let i = 0; i < n; i++) {
    const p0 = ctrl[(i - 1 + n) % n];
    const p1 = ctrl[i];
    const p2 = ctrl[(i + 1) % n];
    const p3 = ctrl[(i + 2) % n];
    for (let s = 0; s < stepsPerSeg; s++) {
      const t = s / stepsPerSeg;
      const t2 = t * t;
      const t3 = t2 * t;
      const x = 0.5 * (
        (2 * p1.x) +
        (-p0.x + p2.x) * t +
        (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * t2 +
        (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * t3
      );
      const y = 0.5 * (
        (2 * p1.y) +
        (-p0.y + p2.y) * t +
        (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * t2 +
        (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * t3
      );
      out.push({ x, y });
    }
  }
  return out;
}

function resampleUniformClosed(pts, targetDs) {
  const n = pts.length;
  const cumLen = [0];
  let total = 0;
  for (let i = 0; i < n; i++) {
    const a = pts[i];
    const b = pts[(i + 1) % n];
    total += Math.hypot(b.x - a.x, b.y - a.y);
    cumLen.push(total);
  }

  const count = Math.round(total / targetDs);
  const actualDs = total / count;
  const res = [];
  let segIdx = 0;

  for (let k = 0; k < count; k++) {
    const s = k * actualDs;
    while (segIdx < n - 1 && cumLen[segIdx + 1] < s) {
      segIdx++;
    }
    const l0 = cumLen[segIdx];
    const l1 = cumLen[segIdx + 1];
    const frac = l1 > l0 ? (s - l0) / (l1 - l0) : 0;
    const p0 = pts[segIdx];
    const p1 = pts[(segIdx + 1) % n];
    res.push({
      x: p0.x + (p1.x - p0.x) * frac,
      y: p0.y + (p1.y - p0.y) * frac,
      s: s,
      idx: k,
      z: 0,
      tx: 0,
      ty: 0,
      nx: 0,
      ny: 0
    });
  }

  // Compute smooth tangents and normals
  for (let k = 0; k < count; k++) {
    const prev = res[(k - 1 + count) % count];
    const next = res[(k + 1) % count];
    let dx = next.x - prev.x;
    let dy = next.y - prev.y;
    let len = Math.hypot(dx, dy) || 1;
    res[k].tx = dx / len;
    res[k].ty = dy / len;
    res[k].nx = -res[k].ty;
    res[k].ny = res[k].tx;
  }

  return res;
}

function findAndAssignStrictOverUnder() {
  const rawCrossings = [];

  for (let r1 = 0; r1 < ropes.length; r1++) {
    const pts1 = ropes[r1].points;
    const n1 = pts1.length;

    for (let r2 = r1; r2 < ropes.length; r2++) {
      const pts2 = ropes[r2].points;
      const n2 = pts2.length;

      for (let i = 0; i < n1; i++) {
        const a1 = pts1[i];
        const a2 = pts1[(i + 1) % n1];

        const jStart = (r1 === r2) ? i + 8 : 0;
        for (let j = jStart; j < n2; j++) {
          if (r1 === r2) {
            const cycDist = Math.min(Math.abs(i - j), n1 - Math.abs(i - j));
            if (cycDist < 12) continue;
          }

          const b1 = pts2[j];
          const b2 = pts2[(j + 1) % n2];

          // Fast bounding-box reject
          if (Math.max(a1.x, a2.x) < Math.min(b1.x, b2.x) - 1) continue;
          if (Math.min(a1.x, a2.x) > Math.max(b1.x, b2.x) + 1) continue;
          if (Math.max(a1.y, a2.y) < Math.min(b1.y, b2.y) - 1) continue;
          if (Math.min(a1.y, a2.y) > Math.max(b1.y, b2.y) + 1) continue;

          const hit = segmentIntersection(a1, a2, b1, b2);
          if (hit) {
            // Avoid duplicate detections of the same crossing
            let isDup = false;
            for (let c of rawCrossings) {
              if (Math.hypot(c.x - hit.x, c.y - hit.y) < 18) {
                isDup = true;
                break;
              }
            }
            if (!isDup) {
              rawCrossings.push({
                id: rawCrossings.length,
                x: hit.x,
                y: hit.y,
                r1,
                idx1: i + hit.t,
                r2,
                idx2: j + hit.u
              });
            }
          }
        }
      }
    }
  }

  crossings = rawCrossings;

  // Register crossing visits on each rope and sort along arc length
  for (let c of crossings) {
    ropes[c.r1].crossings.push({ crossingId: c.id, side: 1, pos: c.idx1, sign: 0 });
    ropes[c.r2].crossings.push({ crossingId: c.id, side: 2, pos: c.idx2, sign: 0 });
  }

  for (let r = 0; r < ropes.length; r++) {
    ropes[r].crossings.sort((a, b) => a.pos - b.pos);
    ropes[r].crossings.forEach((v, k) => { v.order = k; });
  }

  // Test the 4 global rope polarity combinations (sigma_0 = +1, sigma_1 = +-1, sigma_2 = +-1)
  // to find the exact topological alternating solution where every rope alternates (+1, -1, +1, -1)
  // and every crossing has opposite signs on its two strands.
  let bestSigmas = [1, 1, 1];
  let bestScore = -1;

  for (let s1 of [1, -1]) {
    for (let s2 of [1, -1]) {
      const sigmas = [1, s1, s2];
      let score = 0;
      for (let c of crossings) {
        const v1 = ropes[c.r1].crossings.find(v => v.crossingId === c.id && v.side === 1);
        const v2 = ropes[c.r2].crossings.find(v => v.crossingId === c.id && v.side === 2);
        const z1 = sigmas[c.r1] * ((v1.order % 2 === 0) ? 1 : -1);
        const z2 = sigmas[c.r2] * ((v2.order % 2 === 0) ? 1 : -1);
        if (z1 === -z2) score++;
      }
      if (score > bestScore) {
        bestScore = score;
        bestSigmas = sigmas;
      }
    }
  }

  // Apply strict alternating signs to every crossing visit
  for (let r = 0; r < ropes.length; r++) {
    for (let v of ropes[r].crossings) {
      v.sign = bestSigmas[r] * ((v.order % 2 === 0) ? 1 : -1);
    }
  }

  // Ensure every crossing has strictly opposite signs on its two strands
  for (let c of crossings) {
    const v1 = ropes[c.r1].crossings.find(v => v.crossingId === c.id && v.side === 1);
    const v2 = ropes[c.r2].crossings.find(v => v.crossingId === c.id && v.side === 2);
    if (v1.sign === v2.sign) {
      v2.sign = -v1.sign;
    }
    c.overRope = v1.sign > 0 ? c.r1 : c.r2;
    c.underRope = v1.sign > 0 ? c.r2 : c.r1;
    c.overIdx = v1.sign > 0 ? Math.round(c.idx1) : Math.round(c.idx2);
    c.underIdx = v1.sign > 0 ? Math.round(c.idx2) : Math.round(c.idx1);
  }

  // Smoothly interpolate 3D height z(s) in [-1, +1] along each closed rope between consecutive crossings
  for (let r = 0; r < ropes.length; r++) {
    const pts = ropes[r].points;
    const n = pts.length;
    const visits = ropes[r].crossings;
    const m = visits.length;
    if (m === 0) continue;

    for (let i = 0; i < n; i++) {
      // Find surrounding crossing visits along the closed loop
      let kNext = 0;
      while (kNext < m && visits[kNext].pos <= i) {
        kNext++;
      }
      const vPrev = visits[(kNext - 1 + m) % m];
      const vNext = visits[kNext % m];

      let p0 = vPrev.pos;
      let p1 = vNext.pos;
      let idx = i;
      if (p1 <= p0) {
        p1 += n;
        if (idx < p0) idx += n;
      }

      const span = Math.max(1, p1 - p0);
      const t = constrain((idx - p0) / span, 0, 1);
      // Cosine bridge keeps the strand plateaued near +1 or -1 through the crossing zone
      const shapedT = 0.5 - 0.5 * Math.cos(Math.PI * constrain((t - 0.12) / 0.76, 0, 1));
      pts[i].z = lerp(vPrev.sign, vNext.sign, shapedT);
    }
  }
}

function segmentIntersection(a1, a2, b1, b2) {
  const dax = a2.x - a1.x;
  const day = a2.y - a1.y;
  const dbx = b2.x - b1.x;
  const dby = b2.y - b1.y;
  const denom = dax * dby - day * dbx;
  if (Math.abs(denom) < 1e-6) return null;

  const s0x = a1.x - b1.x;
  const s0y = a1.y - b1.y;
  const t = (dbx * s0y - dby * s0x) / denom;
  const u = (dax * s0y - day * s0x) / denom;

  if (t >= 0 && t <= 1 && u >= 0 && u <= 1) {
    return {
      x: a1.x + t * dax,
      y: a1.y + t * day,
      t,
      u
    };
  }
  return null;
}

function buildSortedSubSegments() {
  // Slice each rope into short chunks of 7 points (~31px long, smaller than rope diameter)
  // and sort all chunks by average z height for crisp painter's algorithm interlace
  const chunkLen = 7;
  for (let r = 0; r < ropes.length; r++) {
    const pts = ropes[r].points;
    const n = pts.length;
    for (let start = 0; start < n; start += chunkLen) {
      const end = Math.min(n, start + chunkLen);
      let zSum = 0;
      for (let i = start; i < end; i++) {
        zSum += pts[i].z;
      }
      const avgZ = zSum / (end - start);
      subSegments.push({
        ropeId: r,
        startIdx: start,
        endIdx: end,
        z: avgZ
      });
    }
  }

  subSegments.sort((a, b) => a.z - b.z);
}

