function drawGraniteGround() {
  // Subtle mineral slab watercolor washes batched by tone
  const slabTones = [
    { col: "#b4bcc4", alpha: 52, count: 8 },
    { col: "#9ea7b0", alpha: 42, count: 8 },
    { col: "#d5dce2", alpha: 55, count: 7 },
    { col: "#858f99", alpha: 35, count: 6 }
  ];

  brush.noStroke();
  for (let batch of slabTones) {
    brush.fill(batch.col, batch.alpha);
    brush.fillBleed(0.42, "out");
    brush.fillTexture(0.82, 0.32);
    for (let i = 0; i < batch.count; i++) {
      const cx = random(80, 1120);
      const cy = random(80, 1120);
      const rx = random(140, 340);
      const ry = random(110, 290);
      brush.beginShape(0.65);
      for (let a = 0; a < 360; a += 45) {
        const rad = 0.75 + 0.45 * noise(cx * 0.01 + cos(a), cy * 0.01 + sin(a));
        brush.vertex(cx + cos(a) * rx * rad, cy + sin(a) * ry * rad);
      }
      brush.endShape(CLOSE);
    }
  }
  brush.noFill();

  // Granite directional cleavage planes hatched in fine 2H & HB graphite
  brush.hatchStyle("2H", "#7c858f", 0.75);
  brush.hatch(14, 28, { rand: 0.14, gradient: 0.35 });
  brush.noStroke();
  brush.rect(40, 40, 1120, 1120, "corner");
  brush.noHatch();

  brush.hatchStyle("HB", "#626b75", 0.65);
  brush.hatch(22, -52, { rand: 0.18, gradient: 0.45 });
  brush.noStroke();
  brush.rect(40, 40, 1120, 1120, "corner");
  brush.noHatch();

  // Fine spray stipple for granite mineral grain (feldspar, smoky quartz, biotite mica)
  brush.set("spray", "#464e57", 0.95);
  for (let i = 0; i < 95; i++) {
    const x1 = random(30, 1170);
    const y1 = random(30, 1170);
    const ang = random(360);
    const len = random(45, 160);
    brush.line(x1, y1, x1 + cos(ang) * len, y1 + sin(ang) * len);
  }

  brush.set("spray", "#eef3f7", 0.85);
  for (let i = 0; i < 75; i++) {
    const x1 = random(30, 1170);
    const y1 = random(30, 1170);
    const ang = random(360);
    const len = random(35, 130);
    brush.line(x1, y1, x1 + cos(ang) * len, y1 + sin(ang) * len);
  }

  // Individual crystalline biotite mica flecks & quartz glints in sharp graphite
  const micaColors = ["#22272e", "#38404a", "#525b66"];
  for (let c of micaColors) {
    brush.set("2B", c, 0.85);
    for (let i = 0; i < 380; i++) {
      const x = random(24, 1176);
      const y = random(24, 1176);
      const l = random(2.5, 7.5);
      const a = random(360);
      brush.line(x, y, x + cos(a) * l, y + sin(a) * l);
    }
  }

  // Bright feldspar & quartz crystal facets
  brush.set("cpencil", "#f2f6fa", 0.9);
  for (let i = 0; i < 320; i++) {
    const x = random(24, 1176);
    const y = random(24, 1176);
    const l = random(2.5, 6.5);
    const a = random(-45, 45);
    brush.line(x, y, x + cos(a) * l, y + sin(a) * l);
  }

  // Natural granite fissures / crag cracks with shadow lip and sunlit bevel
  const fissures = [
    [[65, 210], [230, 290], [420, 340], [640, 465], [890, 520], [1145, 630]],
    [[190, 1135], [340, 960], [510, 830], [720, 610], [960, 310], [1110, 95]],
    [[85, 810], [265, 755], [445, 770], [590, 710]]
  ];

  for (let fis of fissures) {
    const jittered = [];
    for (let s = 0; s < fis.length - 1; s++) {
      const p0 = fis[s];
      const p1 = fis[s + 1];
      const steps = 8;
      for (let k = 0; k < steps; k++) {
        const t = k / steps;
        const bx = lerp(p0[0], p1[0], t);
        const by = lerp(p0[1], p1[1], t);
        const nOff = (noise(bx * 0.015, by * 0.015) - 0.5) * 26;
        jittered.push([bx + nOff, by - nOff * 0.7, 0.5 + 0.7 * noise(bx * 0.05)]);
      }
    }
    jittered.push([fis[fis.length - 1][0], fis[fis.length - 1][1], 0.4]);

    // Soft graphite bevel shadow along crack
    brush.set("charcoal", "#4a525c", 1.15);
    const shadowPts = jittered.map(p => [p[0] + 3.5, p[1] + 4.5, p[2] * 0.7]);
    brush.spline(shadowPts, 0.35);

    // Sunlit lower lip of granite fissure
    brush.set("cpencil", "#ebeff4", 0.9);
    const lightPts = jittered.map(p => [p[0] - 2.2, p[1] - 2.2, p[2] * 0.8]);
    brush.spline(lightPts, 0.35);

    // Razor-sharp fissure core in 2B & rotring
    brush.set("2B", "#1e2329", 0.95);
    brush.spline(jittered, 0.35);
  }
}

