function drawManuscriptCragFrame() {
  // Scribe's drypoint & graphite construction lines extending to slab margins
  const frameOuter = 112;
  const frameInner = 142;
  const spanOuter = 1200 - frameOuter * 2;
  const spanInner = 1200 - frameInner * 2;

  // Faint architectural construction grid & diagonal scribe lines
  brush.set("2H", "#6c7580", 0.65);
  brush.line(60, frameOuter, 1140, frameOuter);
  brush.line(60, 1200 - frameOuter, 1140, 1200 - frameOuter);
  brush.line(frameOuter, 60, frameOuter, 1140);
  brush.line(1200 - frameOuter, 60, 1200 - frameOuter, 1140);

  brush.line(60, frameInner, 1140, frameInner);
  brush.line(60, 1200 - frameInner, 1140, 1200 - frameInner);
  brush.line(frameInner, 60, frameInner, 1140);
  brush.line(1200 - frameInner, 60, 1200 - frameInner, 1140);

  // Subtle compass construction arcs at the four corners & cardinal midpoints
  const corners = [
    [frameInner, frameInner, 0, 90],
    [1200 - frameInner, frameInner, 90, 180],
    [1200 - frameInner, 1200 - frameInner, 180, 270],
    [frameInner, 1200 - frameInner, 270, 360]
  ];
  for (let [cx, cy, a0, a1] of corners) {
    brush.set("2H", "#5d6670", 0.6);
    brush.arc(cx, cy, 44, a0 - 15, a1 + 15);
    brush.arc(cx, cy, 56, a0 - 10, a1 + 10);
    // Corner cross-hairs
    brush.set("HB", "#3f4750", 0.75);
    brush.line(cx - 14, cy, cx + 14, cy);
    brush.line(cx, cy - 14, cx, cy + 14);
  }

  // Shaded border channel between outer and inner manuscript frame lines
  brush.hatchStyle("HB", "#555e68", 0.7);
  brush.hatch(7, 45, { rand: 0.08 });
  brush.noStroke();
  brush.rect(frameOuter, frameOuter, spanOuter, frameInner - frameOuter, "corner");
  brush.rect(frameOuter, 1200 - frameInner, spanOuter, frameInner - frameOuter, "corner");
  brush.rect(frameOuter, frameInner, frameInner - frameOuter, spanInner, "corner");
  brush.rect(1200 - frameInner, frameInner, frameInner - frameOuter, spanInner, "corner");
  brush.noHatch();

  // Chiselled graphite double-border outlines with sunlit chalk bevel
  brush.set("cpencil", "#eef2f6", 1.1);
  brush.noFill();
  brush.rect(frameOuter - 2, frameOuter - 2, spanOuter + 4, spanOuter + 4, "corner");
  brush.rect(frameInner + 2, frameInner + 2, spanInner - 4, spanInner - 4, "corner");

  brush.set("2B", "#262c33", 1.15);
  brush.rect(frameOuter, frameOuter, spanOuter, spanOuter, "corner");
  brush.rect(frameInner, frameInner, spanInner, spanInner, "corner");
}

