      const dist = random(0, site.r * 0.8);
      const lx = site.x + cos(ang) * dist;
      const ly = site.y + sin(ang) * dist;
      brush.line(lx, ly, lx + 1.8, ly + 1.8);
    }
  }
}

// ============================================================================
// STAGE 4: DEEP GRAPHITE CAST SHADOWS ON GRANITE
// ============================================================================

function drawKnotCastShadows() {
  // Soft outer penumbra in charcoal & HB graphite
  for (let r = 0; r < ropes.length; r++) {
    const pts = ropes[r].points;
    const rad = ropes[r].palette.radius;
    const n = pts.length;

    // Layer 1: Wide diffused shadow on granite
    brush.set("charcoal", "#636c77", 1.35);
    for (let i = 0; i < n; i += 2) {
      const p = pts[i];
      // Higher z strands arch further off the rock and cast a further shadow
      const heightFactor = 1.0 + (p.z + 1) * 0.48;
      const offX = 11 * heightFactor;
      const offY = 14 * heightFactor;
      const sx = p.x + offX;
      const sy = p.y + offY;
      const w = rad * 1.08;
      brush.line(
        sx - p.nx * w,
        sy - p.ny * w,
        sx + p.nx * w,
        sy + p.ny * w
      );
    }

    // Layer 2: Mid-dark graphite umbra
    brush.set("2B", "#3c434c", 1.25);
    for (let i = 0; i < n; i++) {
      const p = pts[i];
      const heightFactor = 1.0 + (p.z + 1) * 0.42;
      const offX = 8.5 * heightFactor;
      const offY = 10.5 * heightFactor;
      const sx = p.x + offX;
      const sy = p.y + offY;
      const w = rad * 0.88;
      brush.line(
        sx - p.nx * w,
        sy - p.ny * w,
        sx + p.nx * w,
        sy + p.ny * w
      );
    }

    // Layer 3: Deep ambient occlusion crevice directly beneath low-z strands
    brush.set("2B", "#1d2228", 1.15);
    for (let i = 0; i < n; i++) {
      const p = pts[i];
      const heightFactor = 1.0 + (p.z + 1) * 0.28;
      const offX = 4.5 * heightFactor;
      const offY = 6.0 * heightFactor;
      const sx = p.x + offX;
      const sy = p.y + offY;
      const w = rad * 0.72;
      brush.line(
        sx - p.nx * w * 0.4,
        sy - p.ny * w * 0.4,
        sx + p.nx * w * 1.05,
        sy + p.ny * w * 1.05
      );
    }
  }
}

// ============================================================================
// STAGE 5: Z-SORTED 3D BRAIDED KERNMANTLE CLIMBING ROPES
// ============================================================================

function drawBraidedClimbingRopes() {
  // Light direction from top-left (-0.68, -0.73)
  const lightX = -0.68;
  const lightY = -0.73;

  for (let seg of subSegments) {
    const rope = ropes[seg.ropeId];
    const pal = rope.palette;
    const pts = rope.points;
    const n = pts.length;
    const R = pal.radius;

    // 1. If this sub-segment is bridging OVER a crossing (z > 0.15),
    // first cast a crisp dark graphite bridge shadow onto the UNDER rope below it!
    if (seg.z > 0.15) {
      const bridgeStrength = map(seg.z, 0.15, 1.0, 0.3, 1.0, true);
      brush.set("charcoal", "#161a20", 1.2 * bridgeStrength);
      for (let i = seg.startIdx; i < seg.endIdx; i++) {
        const p = pts[i];
        const nextP = pts[(i + 1) % n];
        const off = 4.5 * bridgeStrength;
        // Shadow alongside both flanks and leading shadow edge of the over-bridge
        brush.line(
          p.x + p.nx * (R + 2.5) + off * 0.7,
          p.y + p.ny * (R + 2.5) + off * 0.9,
          nextP.x + nextP.nx * (R + 2.5) + off * 0.7,
          nextP.y + nextP.ny * (R + 2.5) + off * 0.9
        );
        brush.line(
          p.x - p.nx * (R + 1.5) + off * 0.4,
          p.y - p.ny * (R + 1.5) + off * 0.5,
          nextP.x - nextP.nx * (R + 1.5) + off * 0.4,
          nextP.y - nextP.ny * (R + 1.5) + off * 0.5
        );
      }
    }

    // 2. Base opaque pigment bed across the cylindrical width of the sub-segment
    for (let i = seg.startIdx; i < seg.endIdx; i++) {
      const p = pts[i];
      // Cross-sectional base strokes to seal the rope body over underlying strands
      brush.set("burnish_heavy", pal.midShadow, 1.35);
      brush.line(
        p.x - p.nx * (R * 0.96),
        p.y - p.ny * (R * 0.96),
        p.x + p.nx * (R * 0.96),
        p.y + p.ny * (R * 0.96)
      );

      // Sunlit side base burnish
      const nDotL = p.nx * lightX + p.ny * lightY;
      const litSide = nDotL >= 0 ? 1 : -1;
      brush.set("burnish_heavy", pal.coreColor, 1.2);
      brush.line(
        p.x - p.nx * (R * 0.15 * litSide),
        p.y - p.ny * (R * 0.15 * litSide),
        p.x + p.nx * (R * 0.88 * litSide),
        p.y + p.ny * (R * 0.88 * litSide)
      );
    }

    // 3. Braided Kernmantle Sheath Carriers (2-over-2 herringbone / diamond plait)
    // Every axial station i draws interlocking diagonal carrier bundles across u in [-R, +R]
    const numCarriers = 5;
    for (let i = seg.startIdx; i < seg.endIdx; i++) {
      const p = pts[i];
      const nextP = pts[(i + 1) % n];

      // Determine how strongly this normal side faces the top-left crag light
      const normalLight = p.nx * lightX + p.ny * lightY;
      // Height z also modulates brightness (strands depressed into under-crossings are deeper in shadow)
      const zLight = map(p.z, -1, 1, -0.32, 0.28);

      for (let c = 0; c < numCarriers; c++) {
        // Transverse position u across cylinder [-0.84*R, +0.84*R]
        const uFrac = map(c + 0.5, 0, numCarriers, -0.86, 0.86);
        const u0 = map(c, 0, numCarriers, -0.92, 0.92) * R;
        const u1 = map(c + 1, 0, numCarriers, -0.92, 0.92) * R;
        const uMid = 0.5 * (u0 + u1);

        // Cylindrical surface illumination at transverse position uFrac
        const cylAngle = uFrac * 1.35;
        const surfNx = p.nx * Math.cos(cylAngle);
        const surfNy = p.ny * Math.cos(cylAngle);
        const surfNz = Math.sin(Math.acos(constrain(uFrac, -0.98, 0.98)));
        const localLight = (surfNx * lightX + surfNy * lightY) * 0.72 + surfNz * 0.45 + zLight;

        // Herringbone weave direction alternates by (i + c) % 2
        const parity = (i + c) % 2 === 0 ? 1 : -1;
        const axialShift = 4.6 * parity;

        const sx0 = p.x + p.nx * u0 - p.tx * (axialShift * 0.45);
        const sy0 = p.y + p.ny * u0 - p.ty * (axialShift * 0.45);
        const sx1 = nextP.x + nextP.nx * u1 + p.tx * (axialShift * 0.45);
        const sy1 = nextP.y + nextP.ny * u1 + p.ty * (axialShift * 0.45);

        // Graphite twist shadow groove in the valley between braided carrier bundles
        brush.set("graphite_fine", pal.deepShadow, 0.85);
        brush.line(
          sx0 - p.tx * 1.1,
          sy0 - p.ty * 1.1,
          sx1 - p.tx * 1.1,
          sy1 - p.ty * 1.1
        );

        // Technical climbing rope bi-pattern tracer flecks woven into the sheath
        const isDarkTracer = ((i + c * 2) % (pal.patternPeriod * 3) === 0) && (c === 1 || c === 3);
        const isLightTracer = ((i + c * 2 + 2) % (pal.patternPeriod * 3) === 0) && (c === 2);

        let fiberCol;
        if (isDarkTracer) {
          fiberCol = pal.fleckDark;
        } else if (isLightTracer && localLight > -0.1) {
          fiberCol = pal.fleckLight;
        } else if (localLight < -0.18) {
          fiberCol = pal.deepShadow;
        } else if (localLight < 0.08) {
          fiberCol = pal.midShadow;
        } else if (localLight < 0.36) {
          fiberCol = pal.coreColor;
        } else if (localLight < 0.62) {
          fiberCol = pal.brightColor;
        } else {
          fiberCol = pal.burnishLight;
        }

        // Draw primary coloured-pencil burnished carrier bundle (2 parallel filaments per bundle)
        brush.set("sheath_cp", fiberCol, 1.05);
        brush.line(sx0, sy0, sx1, sy1);
        brush.line(
          sx0 + p.tx * 1.3,
          sy0 + p.ty * 1.3,
          sx1 + p.tx * 1.3,
          sy1 + p.ty * 1.3
        );

        // Specular nylon sheen & chalk highlight on high-light carrier crowns
        if (localLight > 0.52 && !isDarkTracer) {
          brush.set("cpencil", pal.chalkTint, 0.85);
          const mx = 0.5 * (sx0 + sx1);
          const my = 0.5 * (sy0 + sy1);
          brush.line(
            mx - p.tx * 1.8,
            my - p.ty * 1.8,
            mx + p.tx * 1.8,
            my + p.ty * 1.8
          );
        }

        // Deep graphite shading in the under-crossing troughs and shadow side of cylinder
        if (localLight < -0.05 || p.z < -0.35) {
          const gWeight = map(localLight, -0.6, 0.0, 0.95, 0.45, true);
          brush.set("graphite_fine", "#1b2026", gWeight);
          brush.line(
            p.x + p.nx * uMid - p.tx * 2.2,
            p.y + p.ny * uMid - p.ty * 2.2,
            nextP.x + nextP.nx * uMid + p.tx * 2.2,
            nextP.y + nextP.ny * uMid + p.ty * 2.2
          );
        }
      }

      // 4. Scalloped outer braided sheath edges & graphite contour twist shadows
      const wobble = 1.3 * Math.sin(i * 1.55);
      const leftEdgeX = p.x - p.nx * (R + wobble * 0.4);
      const leftEdgeY = p.y - p.ny * (R + wobble * 0.4);
      const rightEdgeX = p.x + p.nx * (R - wobble * 0.4);
      const rightEdgeY = p.y + p.ny * (R - wobble * 0.4);

      const nextLeftX = nextP.x - nextP.nx * (R - wobble * 0.4);
      const nextLeftY = nextP.y - nextP.ny * (R - wobble * 0.4);
      const nextRightX = nextP.x + nextP.nx * (R + wobble * 0.4);
      const nextRightY = nextP.y + nextP.ny * (R + wobble * 0.4);

      // Left contour edge
      const leftLit = (-p.nx * lightX - p.ny * lightY) > 0;
      brush.set("2B", leftLit ? "#2c333b" : "#14181d", leftLit ? 0.85 : 1.15);
      brush.line(leftEdgeX, leftEdgeY, nextLeftX, nextLeftY);

      // Right contour edge
      const rightLit = (p.nx * lightX + p.ny * lightY) > 0;
      brush.set("2B", rightLit ? "#2c333b" : "#14181d", rightLit ? 0.85 : 1.15);
      brush.line(rightEdgeX, rightEdgeY, nextRightX, nextRightY);

      // Subtle reflected granite bounce-light along the shadow rim of the rope cylinder
      if (!leftLit && i % 2 === 0) {
        brush.set("cpencil", "#9aa4b0", 0.65);
        brush.line(
          leftEdgeX + p.nx * 2.2,
          leftEdgeY + p.ny * 2.2,
          nextLeftX + nextP.nx * 2.2,
          nextLeftY + nextP.ny * 2.2
        );
      }
      if (!rightLit && i % 2 === 0) {
        brush.set("cpencil", "#9aa4b0", 0.65);
        brush.line(
          rightEdgeX - p.nx * 2.2,
          rightEdgeY - p.ny * 2.2,
          nextRightX - nextP.nx * 2.2,
          nextRightY - nextP.ny * 2.2
        );
      }
    }
  }
}

// ============================================================================
// STAGE 6: CLIMBING CHALK SMUDGES & MICRO-FRAYED SHEATH FILAMENTS
// ============================================================================

function drawFinalChalkAndMicroFray() {
  const lightX = -0.68;
  const lightY = -0.73;

  // 1. Magnesium carbonate climbing chalk smudges on high-z over-bridges & bend crests
  for (let r = 0; r < ropes.length; r++) {
    const pts = ropes[r].points;
    const pal = ropes[r].palette;
    const R = pal.radius;
    const n = pts.length;

    for (let i = 0; i < n; i++) {
      const p = pts[i];
      const chalkNoise = noise(p.x * 0.018, p.y * 0.018, r * 10);

      // Chalk accumulates heavily where the climber's hands grip high over-crossings and sharp bends
      if (p.z > 0.25 && chalkNoise > 0.44) {
        const litDir = (p.nx * lightX + p.ny * lightY) >= 0 ? 1 : -1;
        const cx = p.x + p.nx * (R * 0.32 * litDir);
        const cy = p.y + p.ny * (R * 0.32 * litDir);

        brush.set("chalk_smudge", "#f2f6fa", 0.9);
        brush.line(cx - p.tx * 5, cy - p.ty * 5, cx + p.tx * 5, cy + p.ty * 5);

        // Burnished white coloured pencil chalk streaks catching the crag texture
        if (i % 2 === 0) {
          brush.set("cpencil", "#ffffff", 0.95);
          const uOff = random(-0.45, 0.55) * R;
          const sx = p.x + p.nx * uOff;
          const sy = p.y + p.ny * uOff;
          brush.line(
            sx - p.tx * 3.5 + p.nx * 2.0,
            sy - p.ty * 3.5 + p.ny * 2.0,
            sx + p.tx * 3.5 - p.nx * 2.0,
            sy + p.ty * 3.5 - p.ny * 2.0
          );
        }
      }

      // 2. Hyperrealistic frayed nylon sheath filaments along the rope silhouette
      if (p.z > -0.25 && random() < 0.34) {
        const side = random() < 0.58 ? 1 : -1;
        const isSunlit = (p.nx * side * lightX + p.ny * side * lightY) > -0.1;
        const ex = p.x + p.nx * side * (R - 0.5);
        const ey = p.y + p.ny * side * (R - 0.5);
        const frayLen = random(4.0, 11.5);
        const flare = random(0.25, 0.75);

        const fx = ex + (p.nx * side * flare + p.tx * random(-0.9, 0.9)) * frayLen;
        const fy = ey + (p.ny * side * flare + p.ty * random(-0.9, 0.9)) * frayLen;

        brush.set(
          "graphite_fine",
          isSunlit ? pal.chalkTint : pal.brightColor,
          isSunlit ? 0.72 : 0.55
        );
        brush.line(ex, ey, fx, fy);
      }
    }
  }

  // 3. Loose climbing chalk smudges & fingerprints on the granite slab around the knot
  const chalkDustZones = [
    [220, 220], [980, 220], [220, 980], [980, 980],
    [600, 195], [600, 1005], [195, 600], [1005, 600],
    [455, 455], [745, 455], [455, 745], [745, 745]
  ];
  for (let [zx, zy] of chalkDustZones) {
    brush.set("chalk_smudge", "#eef3f8", 1.15);
    for (let k = 0; k < 5; k++) {
      const ox = zx + random(-28, 28);
      const oy = zy + random(-28, 28);
      const ang = random(360);
      brush.line(ox, oy, ox + cos(ang) * 24, oy + sin(ang) * 24);
    }
  }
}

// Hyperrealistic Sancai Shaved Ice in a Footed Cream Bowl
// Wet-in-wet watercolor, hard tide-lines, speckled granulation, dry-brush & crystalline pencil facets

const CX = 600;
const RIM_Y = 645;
const RIM_RX = 346;
const RIM_RY = 152;
const PEAK_X = 594;
const PEAK_Y = 208;
const WAIST_Y = 892;
const FOOT_Y = 962;

async function setup() {
