// ============================================================================
// 3D SURFACE GEOMETRY HELPERS (Mound, Rim, Bowl Body, Foot)
// ============================================================================

// Relief function for the craggy shaved-ice mountain
function iceRelief(s, ang) {
  let rad = ang * Math.PI / 180;
  let nx = Math.cos(rad) * (0.8 + s * 1.9) + 2.5;
  let ny = Math.sin(rad) * (0.8 + s * 1.9) + 2.5;
  let n1 = noise(nx * 1.1, ny * 1.1, s * 2.2) - 0.48;
  let n2 = noise(nx * 2.7 + 10, ny * 2.7 + 10, s * 4.5) - 0.48;
  let n3 = noise(nx * 6.0 + 25, ny * 6.0 + 25, s * 8.0) - 0.48;

  // Terraced horizontal ledges where shaved ice packs and syrups pool
  let terrace = Math.sin(s * 540 + n1 * 140) * 0.18;
  let env = Math.pow(Math.sin(constrain(s, 0, 1) * 180), 0.65);
  return (n1 * 48 + n2 * 22 + n3 * 9 + terrace * 14) * env;
}

// Returns 2D canvas point for (s, ang) on the ice mound (0 <= s <= 1)
// or spilling over the rim onto the bowl exterior (s > 1)
function moundPt(s, ang, extraLift = 0) {
  if (s <= 1.0) {
    let sc = constrain(s, 0, 1);
    let baseCx = lerp(PEAK_X, CX, Math.pow(sc, 0.85)) + 10 * Math.sin(sc * 220) * (1 - sc);
    let baseCy = lerp(PEAK_Y, RIM_Y - 6, Math.pow(sc, 0.91));

    // Plump shaved-ice dome profile with slight mid-slope shoulders
    let shoulder = 1.0 + 0.08 * Math.sin(sc * 360) * (1 - sc * 0.4);
    let rx = (RIM_RX - 10) * Math.pow(sc, 0.74) * shoulder;
    let ry = (RIM_RY - 8) * Math.pow(sc, 0.84) * shoulder;

    let rel = iceRelief(sc, ang);
    let rad = ang * Math.PI / 180;

    // Peak crag offset
    let peakCragY = (1 - sc) * (noise(ang * 0.04, 1.7) - 0.5) * 26;

    let x = baseCx + (rx + rel * 0.85) * Math.cos(rad);
    let y = baseCy + (ry + rel * 0.42) * Math.sin(rad) - Math.abs(rel) * 0.55 + peakCragY - extraLift;
    return [x, y];
  } else {
    // s > 1: cresting the ceramic lip (1.0..1.07) and running down the bowl exterior (s > 1.07)
    let rad = ang * Math.PI / 180;
    if (s <= 1.07) {
      let t = (s - 1.0) / 0.07;
      let rx = lerp(RIM_RX - 10, RIM_RX + 7, t);
      let ry = lerp(RIM_RY - 8, RIM_RY + 4, t);
      let lipArch = Math.sin(t * 180) * 7;
      return [
        CX + rx * Math.cos(rad),
        RIM_Y + ry * Math.sin(rad) - lipArch - extraLift
      ];
    } else {
      let u = constrain((s - 1.07) * 1.65, 0, 0.96);
      return bowlBodyPt(u, ang, extraLift);
    }
  }
}

// Point on the exterior ceramic bowl belly (u: 0 at rim, 1 at waist)
function bowlBodyPt(u, ang, radialOut = 0) {
  let uc = constrain(u, 0, 1);
  // Classic Tang/Song full-bellied bowl profile
  let curve = Math.pow(1 - uc, 0.54);
  let rx = lerp(130, RIM_RX + 7, curve) + radialOut;
  let ry = rx * 0.44;
  let cy = lerp(RIM_Y, WAIST_Y, Math.pow(uc, 0.92));
  let rad = ang * Math.PI / 180;
  return [CX + rx * Math.cos(rad), cy + ry * Math.sin(rad)];
}

// Point on the footed pedestal (v: 0 at waist, 1 at foot ring base)
function bowlFootPt(v, ang, radialOut = 0) {
  let vc = constrain(v, 0, 1);
  let rx = lerp(128, 154, Math.pow(vc, 0.75)) + radialOut;
  let ry = rx * 0.45;
  let cy = lerp(WAIST_Y - 4, FOOT_Y, vc);
  let rad = ang * Math.PI / 180;
  return [CX + rx * Math.cos(rad), cy + ry * Math.sin(rad)];
}

// Helper to draw a closed watercolor shape from an array of [x, y] points
function drawPolyShape(pts, curv = 0.35) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Generates a natural organic syrup lobe polygon on the mound surface
function buildSyrupLobe(sStart, sEnd, angCenter, halfWidFn, noiseSeedVal, stepCount = 24, lift = 0) {
  let leftSide = [];
  let rightSide = [];
  for (let i = 0; i <= stepCount; i++) {
    let t = i / stepCount;
    let s = lerp(sStart, sEnd, t);
    let hw = halfWidFn(t, s);
    let nL = (noise(noiseSeedVal + t * 4.5, 1.3) - 0.5) * hw * 0.52;
    let nR = (noise(noiseSeedVal + t * 4.5, 7.9) - 0.5) * hw * 0.52;
    let drift = (noise(noiseSeedVal * 0.7 + s * 3.2, 4.1) - 0.5) * 9;

    // Capillary jaggedness along ice crystals when on the mound
    let crystalJagL = s < 1.0 ? (noise(noiseSeedVal + i * 1.9, 11.2) - 0.5) * 4.2 : 0;
    let crystalJagR = s < 1.0 ? (noise(noiseSeedVal + i * 1.9, 23.4) - 0.5) * 4.2 : 0;

    let aL = angCenter + drift - hw + nL + crystalJagL;
    let aR = angCenter + drift + hw + nR + crystalJagR;

    leftSide.push(moundPt(s, aL, lift));
    rightSide.push(moundPt(s, aR, lift));
  }
  let poly = [];
  for (let i = 0; i < leftSide.length; i++) poly.push(leftSide[i]);
  for (let i = rightSide.length - 1; i >= 0; i--) poly.push(rightSide[i]);
  return poly;
}

// ============================================================================
// MAIN RENDER PIPELINE
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);

  // Warm oatmeal paper base
  background("#dfd5c5");

  // 1. Warm Oatmeal Ground & Dusky Twilight Atmospheric Washes
  renderOatmealGround();

  // 2. Cast Shadows on the Tabletop
  renderTableCastShadow();

  // 3. Back Rim of the Footed Cream Bowl
  renderBowlBackRim();

  // 4. Shaved Ice Mound Base, Twilight Crevices & Initial Crystalline Structure
  renderIceMoundBase();

  // 5. Three Sancai Syrups on the Mound (Wet-in-Wet Watercolor, Bleeds, Granulation, Tide-Lines)
