// Helper to trace crisp, broken watercolor tide-lines along a polygon perimeter
function traceTideLine(poly, col, weight, coverage = 0.6) {
  if (!poly || poly.length < 4) return;
  brush.set("cpencil", col, weight);
  let chunk = [];
  for (let i = 0; i < poly.length; i++) {
    if (noise(i * 0.35, poly[i][0] * 0.01) < coverage) {
      chunk.push([poly[i][0], poly[i][1], random(0.5, 1.3)]);
      if (chunk.length >= 6) {
        brush.spline(chunk, 0.4);
        chunk = [chunk[chunk.length - 1]];
      }
    } else {
      if (chunk.length >= 2) brush.spline(chunk, 0.4);
      chunk = [];
    }
  }
  if (chunk.length >= 2) brush.spline(chunk, 0.4);
}

