  let footShadowPts = [];
  for (let a = -5; a <= 105; a += 6) footShadowPts.push(bowlFootPt(0.0, a));
  for (let a = 105; a >= -5; a -= 6) footShadowPts.push(bowlFootPt(0.95, a));
  brush.fillBleed(0.22, "out");
  brush.fill("#877974", 125);
  drawPolyShape(footShadowPts, 0.3);

  // Deepest core shadow on the right side of the foot + under-belly collar shadow
  let footCorePts = [];
  for (let a = 5; a <= 68; a += 6) footCorePts.push(bowlFootPt(0.0, a));
  for (let a = 68; a >= 5; a -= 6) footCorePts.push(bowlFootPt(0.92, a));
  brush.fillBleed(0.15, "in");
  brush.fill("#5e5254", 135);
  drawPolyShape(footCorePts, 0.3);

  // Collar shadow directly under the bowl belly overhang
  let collarPts = [];
  for (let a = -5; a <= 185; a += 6) collarPts.push(bowlFootPt(0.0, a));
  for (let a = 185; a >= -5; a -= 6) collarPts.push(bowlFootPt(0.26, a));
  brush.fill("#665a5b", 130);
  drawPolyShape(collarPts, 0.25);

  // --------------------------------------------------------------------------
  // B. MAIN CREAM BOWL BODY (Rounded Kiln-Fired Stoneware Belly)
  // --------------------------------------------------------------------------
  let bodyPts = [];
  for (let a = -12; a <= 192; a += 5) bodyPts.push(bowlBodyPt(0.0, a));
  for (let a = 192; a >= -12; a -= 6) bodyPts.push(bowlBodyPt(1.0, a));

  // Opaque warm cream base so the bowl cleanly occludes the lower ice mound
  brush.wash("#efe6d5", 252);
  drawPolyShape(bodyPts, 0.28);
  brush.noWash();

  // Left-side warm key-light glow on the cream glaze (#faf5ea)
  let bodyLitPts = [];
  for (let a = 95; a <= 186; a += 6) bodyLitPts.push(bowlBodyPt(0.02, a));
  for (let a = 186; a >= 95; a -= 6) bodyLitPts.push(bowlBodyPt(0.85, a));
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.55, 0.4);
  brush.fill("#fcf8ef", 140);
  drawPolyShape(bodyLitPts, 0.35);

  // Warm stoneware mid-tone gradation across the center and lower curve (#d4c4ac)
  let bodyMidPts = [];
  for (let a = -10; a <= 135; a += 6) bodyMidPts.push(bowlBodyPt(0.02, a));
  for (let a = 135; a >= 165; a += 10) bodyMidPts.push(bowlBodyPt(0.65, a));
  for (let a = 165; a >= -10; a -= 6) bodyMidPts.push(bowlBodyPt(1.0, a));
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.72, 0.55);
  brush.fill("#d1c0a8", 125);
  drawPolyShape(bodyMidPts, 0.35);

  // Dusky twilight shadow on the right flank & lower belly of the bowl (#9c8d85)
  let bodyShadPts = [];
  for (let a = -10; a <= 88; a += 6) bodyShadPts.push(bowlBodyPt(0.02, a));
  for (let a = 88; a <= 145; a += 10) bodyShadPts.push(bowlBodyPt(0.72, a));
  for (let a = 145; a >= -10; a -= 6) bodyShadPts.push(bowlBodyPt(1.0, a));
  brush.fillBleed(0.28, "out");
  brush.fill("#9c8d85", 130);
  drawPolyShape(bodyShadPts, 0.35);

  // Deepest twilight form shadow on the right belly curve (#6e6063)
  let bodyCoreShad = [];
  for (let a = 4; a <= 64; a += 6) bodyCoreShad.push(bowlBodyPt(0.06, a));
  for (let a = 64; a <= 105; a += 10) bodyCoreShad.push(bowlBodyPt(0.75, a));
  for (let a = 105; a >= 4; a -= 6) bodyCoreShad.push(bowlBodyPt(0.96, a));
  brush.fillBleed(0.2, "in");
  brush.fill("#6e6063", 125);
  drawPolyShape(bodyCoreShad, 0.35);

  // Rolled Front Lip of the Cream Bowl
  let frontLipPts = [];
  for (let a = -14; a <= 194; a += 5) {
    let rad = a * Math.PI / 180;
    frontLipPts.push([
      CX + (RIM_RX + 8) * Math.cos(rad),
      RIM_Y + (RIM_RY + 5) * Math.sin(rad)
    ]);
  }
  for (let a = 194; a >= -14; a -= 5) {
    let rad = a * Math.PI / 180;
    frontLipPts.push([
      CX + (RIM_RX - 10) * Math.cos(rad),
      RIM_Y + (RIM_RY - 6) * Math.sin(rad) - 4
    ]);
  }
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.5, 0.65);
  brush.fill("#f5eee0", 210);
  drawPolyShape(frontLipPts, 0.3);

  brush.noFill();

  // --------------------------------------------------------------------------
  // C. CERAMIC GLAZE CRACKLE (CRAZING), IRON FLECKS & CONTOUR SHADING
  // --------------------------------------------------------------------------
  // Subtle stoneware wheel-throwing rings following the bowl's latitude ellipses
  for (let u = 0.12; u <= 0.88; u += 0.11) {
    let ringPts = [];
    let aStart = random(-4, 25);
    let aEnd = aStart + random(45, 110);
    for (let a = aStart; a <= aEnd; a += 7) {
      ringPts.push(bowlBodyPt(u, a));
    }
    brush.set("2H", u > 0.5 ? "#8c7d75" : "#bfb09b", 0.42);
    brush.spline(ringPts, 0.5);
  }

  // Fine ceramic glaze crackle (crazing network) on the cream bowl
  brush.set("2H", "#b5a48e", 0.32);
  for (let i = 0; i < 28; i++) {
    let u = random(0.08, 0.82);
    let a = random(8, 172);
    let crackPts = [];
    for (let j = 0; j < 4; j++) {
      crackPts.push(bowlBodyPt(constrain(u, 0.04, 0.94), a));
      u += random(-0.14, 0.18);
      a += random(-12, 12);
    }
    brush.spline(crackPts, 0.2);
  }

  // Kiln-fired iron speckles on the stoneware body and foot
  brush.set("granulation_stipple", "#6e5849", 0.55);
  for (let i = 0; i < 38; i++) {
    let u = random(0.05, 0.92);
    let a = random(0, 180);
    let p = bowlBodyPt(u, a);
    brush.line(p[0], p[1], p[0] + random(6, 16), p[1] + random(-4, 4));
  }

  // Crisp structural pencil/pen contours on the bowl rim, waist, and foot ring
  let outerRimLine = [];
  for (let a = -12; a <= 192; a += 5) outerRimLine.push(bowlBodyPt(0.0, a));
  brush.set("HB", "#7d6d61", 0.65);
  brush.spline(outerRimLine, 0.45);

  // Subtle kiln-flushed russet line along the rim edge
  brush.set("cpencil", "#9c7556", 0.55);
  brush.spline(outerRimLine, 0.45);

  // Left and right silhouette contours of the bowl belly and foot
  let leftSil = [];
  let rightSil = [];
  for (let u = 0; u <= 1.0; u += 0.1) {
    leftSil.push(bowlBodyPt(u, 180));
    rightSil.push(bowlBodyPt(u, 0));
  }
  brush.set("HB", "#8a7b6d", 0.6);
  brush.spline(leftSil, 0.45);
  brush.set("HB", "#4d4247", 0.75);
  brush.spline(rightSil, 0.45);

  let footBotLine = [];
  for (let a = -4; a <= 184; a += 6) footBotLine.push(bowlFootPt(1.0, a));
  brush.set("HB", "#42363b", 0.8);
  brush.spline(footBotLine, 0.45);
}

// ============================================================================
// 7. POOLED RIM MOAT & SANCAI GLAZE DRIPS RUNNING DOWN THE CERAMIC EXTERIOR
// ============================================================================
function renderRimPoolsAndExteriorDrips() {
  brush.noStroke();
  brush.noHatch();

  // --------------------------------------------------------------------------
  // A. LIQUID SYRUP MOAT POOLING INSIDE THE FRONT RIM OF THE BOWL
  // --------------------------------------------------------------------------
  // Amber Caramel rim pool (left-front inner rim: ang 98..176)
  let amberMoat = [];
  for (let a = 96; a <= 176; a += 5) amberMoat.push(moundPt(0.95 + 0.02 * sin(a * 5), a));
  for (let a = 176; a >= 96; a -= 5) amberMoat.push(moundPt(1.02, a));
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.85, 0.9);
  brush.fill("#9e3806", 175);
  drawPolyShape(amberMoat, 0.35);

  // Jade Matcha rim pool (right-front inner rim: ang 6..88)
  let matchaMoat = [];
  for (let a = 6; a <= 88; a += 5) matchaMoat.push(moundPt(0.95 + 0.02 * cos(a * 5), a));
  for (let a = 88; a >= 6; a -= 5) matchaMoat.push(moundPt(1.02, a));
  brush.fill("#144729", 180);
  drawPolyShape(matchaMoat, 0.35);

  // Ivory Condensed Milk rim pool (bridging the center moat: ang 62..126)
  let milkMoat = [];
  for (let a = 62; a <= 126; a += 5) milkMoat.push(moundPt(0.96 + 0.02 * sin(a * 6), a, 1.5));
  for (let a = 126; a >= 62; a -= 5) milkMoat.push(moundPt(1.02, a, 1.5));
  brush.wash("#efe5cf", 215);
  drawPolyShape(milkMoat, 0.35);
  brush.noWash();

  // --------------------------------------------------------------------------
  // B. SANCAI GLAZE DRIPS SPILLING OVER THE RIM DOWN THE CREAM BOWL EXTERIOR
  // --------------------------------------------------------------------------
  // Define the thick kiln-glaze-like drips:
  // [sEnd, angCenter, baseWidth, bulbWidth, type]
  let exteriorDrips = [
    // Amber Caramel drips on the left/front-left
    { sEnd: 1.52, ang: 148, w0: 5.5, wBulb: 4.8, type: "amber", seed: 1101 },
    { sEnd: 1.68, ang: 131, w0: 7.2, wBulb: 6.2, type: "amber", seed: 1117 },
    { sEnd: 1.38, ang: 115, w0: 4.8, wBulb: 4.2, type: "amber", seed: 1133 },
    // Jade Matcha drips on the right/front-right
    { sEnd: 1.62, ang: 44,  w0: 6.8, wBulb: 5.8, type: "matcha", seed: 1201 },
    { sEnd: 1.41, ang: 62,  w0: 5.0, wBulb: 4.4, type: "matcha", seed: 1219 },
    { sEnd: 1.33, ang: 25,  w0: 4.2, wBulb: 3.8, type: "matcha", seed: 1237 },
    // Ivory Condensed Milk drips in the center & overlapping amber/matcha
    { sEnd: 1.58, ang: 91,  w0: 6.6, wBulb: 5.8, type: "milk", seed: 1301 },
    { sEnd: 1.34, ang: 76,  w0: 4.6, wBulb: 4.0, type: "milk", seed: 1319 },
    { sEnd: 1.29, ang: 124, w0: 4.2, wBulb: 3.7, type: "milk", seed: 1337 }
  ];

  // Helper to construct a bulbous pendant drip polygon from s = 0.96 to sEnd
  function makeDripPoly(drip, widthScale = 1.0, angOffset = 0, sOffset = 0) {
    return buildSyrupLobe(
      0.96,
      drip.sEnd + sOffset,
      drip.ang + angOffset,
      (t) => {
        // Narrows slightly below the rim neck, then swells into a heavy teardrop bulb at t = 0.85..0.95
        let neck = lerp(drip.w0, drip.w0 * 0.55, constrain(t * 1.8, 0, 1));
        let bulb = drip.wBulb * Math.pow(Math.sin(constrain((t - 0.45) / 0.55, 0, 1) * 180), 0.75);
        let tipRound = t > 0.92 ? Math.cos(((t - 0.92) / 0.08) * 90) : 1.0;
        return (neck * (1 - t * 0.4) + bulb * 0.75) * tipRound * widthScale;
      },
      drip.seed,
      20
    );
  }

  // 1. Cast drop-shadows of the thick drips onto the cream ceramic bowl (shifted slightly right/down)
  brush.fillBleed(0.08, "out");
  brush.fillTexture(0.6, 0.5);
  brush.fill("#73635c", 115);
  for (let d of exteriorDrips) {
    drawPolyShape(makeDripPoly(d, 0.95, -1.6, 0.015), 0.35);
  }

  // 2. Render Amber Caramel Exterior Drips
  for (let d of exteriorDrips.filter(x => x.type === "amber")) {
    let outerPoly = makeDripPoly(d, 1.0, 0, 0);
    let innerPoly = makeDripPoly(d, 0.65, 0.3, -0.01);

    brush.fillBleed(0.12, "in");
    brush.fillTexture(0.85, 0.92);
    brush.fill("#b84e09", 185);
    drawPolyShape(outerPoly, 0.35);

    brush.fillBleed(0.06, "in");
    brush.fill("#591802", 205);
    drawPolyShape(innerPoly, 0.35);

    traceTideLine(outerPoly, "#3d0e01", 0.55, 0.8);
  }

  // 3. Render Jade Matcha Exterior Drips
  for (let d of exteriorDrips.filter(x => x.type === "matcha")) {
    let outerPoly = makeDripPoly(d, 1.0, 0, 0);
    let innerPoly = makeDripPoly(d, 0.65, -0.3, -0.01);

    brush.fillBleed(0.12, "in");
    brush.fillTexture(0.85, 0.92);
    brush.fill("#225c34", 190);
    drawPolyShape(outerPoly, 0.35);

    brush.fillBleed(0.06, "in");
    brush.fill("#092917", 210);
    drawPolyShape(innerPoly, 0.35);

    traceTideLine(outerPoly, "#051a0e", 0.55, 0.8);
  }

  // 4. Render Ivory Condensed Milk Exterior Drips
  for (let d of exteriorDrips.filter(x => x.type === "milk")) {
    let outerPoly = makeDripPoly(d, 1.0, 0, 0);
    let shadePoly = makeDripPoly(d, 0.6, -0.5, -0.01);

    brush.wash("#f5eedc", 235);
    drawPolyShape(outerPoly, 0.35);
    brush.noWash();

    brush.fillBleed(0.1, "in");
    brush.fillTexture(0.75, 0.8);
    brush.fill("#c7b088", 145);
    drawPolyShape(shadePoly, 0.35);

    traceTideLine(outerPoly, "#9e865f", 0.5, 0.75);
  }

  brush.noFill();

  // Save drip metadata on window for the specular gloss pass
  window._exteriorDrips = exteriorDrips;
  window._makeDripPoly = makeDripPoly;
}

// ============================================================================
// 8. HYPERREALISTIC ICE CRYSTAL FACETS, DRY-BRUSH & SPECULAR LIQUID GLOSS
// ============================================================================
function renderCrystallineFacetsAndHighlights() {
  brush.noFill();
  brush.noHatch();

  // --------------------------------------------------------------------------
  // A. DRY-BRUSH SKIMMING HIGHLIGHTS ACROSS CRAGGY ICE RIDGES
  // --------------------------------------------------------------------------
  brush.set("dry_skim", "#ffffff", 0.85);
  let ridgeZones = [
    [0.06, 0.88, 174],
    [0.08, 0.85, 148],
    [0.10, 0.92, 102],
    [0.05, 0.90, 80],
    [0.12, 0.86, 30],
    [0.15, 0.88, 6]
  ];
  for (let rz of ridgeZones) {
    let [s0, s1, baseAng] = rz;
    for (let s = s0; s <= s1; s += 0.08) {
      let a = baseAng + (noise(s * 8, baseAng) - 0.5) * 14;
      let p1 = moundPt(s, a, 1.5);
      let p2 = moundPt(s + 0.045, a + random(-5, 5), 1.5);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // --------------------------------------------------------------------------
  // B. SHARP GEOMETRIC PENCIL FACETS PICKING OUT INDIVIDUAL ICE CRYSTALS
  // --------------------------------------------------------------------------
  // Draw hundreds of tiny polyhedral crystal facets across exposed ice & thin syrup edges
  for (let i = 0; i < 340; i++) {
    let s = Math.pow(random(0.02, 0.97), 0.85);
    let ang = random(-8, 188);

    // Determine whether this crystal is in exposed ice, amber bleed, or matcha bleed
    let inAmber = (ang > 106 && ang < 166 && noise(s * 4, ang * 0.05) > 0.38);
    let inMatcha = (ang > 14 && ang < 74 && noise(s * 4, ang * 0.05) > 0.38);
    let inMilk = (ang > 78 && ang < 104 && s < 0.75);

    if (inMilk && random() < 0.7) continue; // Thick condensed milk hides most facets

    let center = moundPt(s, ang, 1.0);
    let sz = random(4.5, 12.5) * (0.65 + 0.5 * s);
    let rot = random(0, 360);

    // 3 or 4 vertices of a sharp crystalline shard
    let v1 = [center[0] + sz * cos(rot), center[1] + sz * 0.65 * sin(rot)];
    let v2 = [center[0] + sz * 0.85 * cos(rot + 115), center[1] + sz * 0.65 * sin(rot + 115)];
    let v3 = [center[0] + sz * 0.9 * cos(rot + 235), center[1] + sz * 0.65 * sin(rot + 235)];

    // Shadow facet edge
    if (inAmber) {
      brush.set("2H", "#8f3908", 0.42);
    } else if (inMatcha) {
      brush.set("2H", "#194d2c", 0.42);
    } else {
      brush.set("2H", ang < 85 ? "#69788c" : "#8b99ab", 0.42);
    }
    brush.line(v1[0], v1[1], v2[0], v2[1]);
    brush.line(v2[0], v2[1], v3[0], v3[1]);

    // Bright frozen highlight edge catching the upper-left light
    if (inAmber) {
      brush.set("crystal_needle", "#ffebb3", 0.52);
    } else if (inMatcha) {
      brush.set("crystal_needle", "#dbf2d5", 0.52);
    } else {
      brush.set("crystal_needle", "#ffffff", 0.62);
    }
    brush.line(v3[0], v3[1], v1[0], v1[1]);

    // Internal dihedral ridge line inside larger ice crystals
    if (sz > 8.0) {
      brush.line(center[0], center[1], v1[0], v1[1]);
    }
  }

  // --------------------------------------------------------------------------
  // C. FROZEN NEEDLE SPICULES ALONG THE OUTER SILHOUETTE OF THE MOUND
  // --------------------------------------------------------------------------
  // Left slope, summit crown, and right slope crystalline silhouette shards
  for (let s = 0.02; s <= 0.96; s += 0.018) {
    // Left silhouette edge
    let pL = moundPt(s, 184 + (1 - s) * 14);
    let angL = random(155, 225);
    let lenL = random(5, 15);
    brush.set("crystal_needle", "#ffffff", 0.65);
    brush.line(pL[0], pL[1], pL[0] + lenL * cos(angL), pL[1] + lenL * sin(angL));
    brush.set("2H", "#8c99ab", 0.38);
    brush.line(pL[0] + lenL * cos(angL), pL[1] + lenL * sin(angL), pL[0] + 4, pL[1] + 5);

    // Right silhouette edge
    let pR = moundPt(s, -4 - (1 - s) * 12);
    let angR = random(-45, 25);
    let lenR = random(5, 14);
    brush.set("crystal_needle", "#eef4fa", 0.58);
    brush.line(pR[0], pR[1], pR[0] + lenR * cos(angR), pR[1] + lenR * sin(angR));
    brush.set("2H", "#647285", 0.42);
    brush.line(pR[0] + lenR * cos(angR), pR[1] + lenR * sin(angR), pR[0] - 4, pR[1] + 5);
  }

  // Crown summit icy crags
  for (let a = 195; a <= 345; a += 8) {
    let pC = moundPt(0.03, a);
    let lenC = random(6, 16);
    let angC = random(-125, -55);
    brush.set("crystal_needle", "#ffffff", 0.72);
    brush.line(pC[0], pC[1], pC[0] + lenC * cos(angC), pC[1] + lenC * sin(angC));
  }
}

function renderLiquidSpecularGloss() {
  brush.noFill();
  brush.noHatch();

  // --------------------------------------------------------------------------
  // A. STICKY GLOSSY SPECULAR STREAKS ON MOUND SYRUP LOBES
  // --------------------------------------------------------------------------
  // Helper to draw curved specular meniscus reflections along a syrup flow path
  function drawSyrupMeniscusGloss(sStart, sEnd, ang, col, weight, seedOffset) {
    let pts = [];
    let steps = 10;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let s = lerp(sStart, sEnd, t);
      let wiggle = (noise(seedOffset + t * 3.5, 2.1) - 0.5) * 6;
      let p = moundPt(s, ang + wiggle, 2.5);
      let press = Math.sin(t * 180) * 1.3 + 0.15;
      pts.push([p[0], p[1], press]);
    }
    brush.set("syrup_gloss", col, weight);
    brush.spline(pts, 0.45);
  }

  // Gleaming warm highlights on Amber Caramel rivers
  let amberGlossTracks = [
    [0.04, 0.26, 141, 0.95],
    [0.31, 0.58, 144, 1.10],
    [0.63, 0.92, 140, 1.15],
    [0.08, 0.35, 115, 0.85],
    [0.44, 0.78, 116, 0.95],
    [0.24, 0.56, 162, 0.80],
    [0.64, 0.93, 161, 0.90]
  ];
  for (let i = 0; i < amberGlossTracks.length; i++) {
    let [s0, s1, ang, w] = amberGlossTracks[i];
    drawSyrupMeniscusGloss(s0, s1, ang, "#fff3cc", w, 2000 + i * 31);
    drawSyrupMeniscusGloss(s0 + 0.03, s1 - 0.04, ang + 1.2, "#ffffff", w * 0.65, 2000 + i * 31);
  }

  // Gleaming celadon-white highlights on Jade Matcha rivers
  let matchaGlossTracks = [
    [0.04, 0.25, 46, 0.95],
    [0.30, 0.56, 44, 1.10],
    [0.61, 0.91, 46, 1.15],
    [0.10, 0.38, 70, 0.85],
    [0.45, 0.82, 69, 0.95],
    [0.22, 0.54, 21, 0.80],
    [0.62, 0.92, 20, 0.90]
  ];
  for (let i = 0; i < matchaGlossTracks.length; i++) {
    let [s0, s1, ang, w] = matchaGlossTracks[i];
    drawSyrupMeniscusGloss(s0, s1, ang, "#e6faea", w, 2200 + i * 29);
    drawSyrupMeniscusGloss(s0 + 0.03, s1 - 0.04, ang + 1.2, "#ffffff", w * 0.65, 2200 + i * 29);
  }

  // Pure luminous white gloss along the Ivory Condensed Milk ribbons
  let milkGlossTracks = [
    [0.02, 0.32, 93, 1.15],
    [0.38, 0.68, 92, 1.20],
    [0.72, 0.96, 93, 1.15],
    [0.07, 0.44, 125, 0.85],
    [0.50, 0.82, 124, 0.85],
    [0.08, 0.46, 59, 0.85],
    [0.52, 0.86, 58, 0.85]
  ];
  for (let i = 0; i < milkGlossTracks.length; i++) {
    let [s0, s1, ang, w] = milkGlossTracks[i];
    drawSyrupMeniscusGloss(s0, s1, ang, "#ffffff", w, 2400 + i * 37);
  }

  // --------------------------------------------------------------------------
  // B. HIGH-GLOSS SPECULAR REFLECTIONS ON THE EXTERIOR SANCAI DRIPS & RIM
  // --------------------------------------------------------------------------
  if (window._exteriorDrips) {
    for (let d of window._exteriorDrips) {
      // Long vertical liquid reflection running down the left-lit ridge of each drip
      let dripHilite = [];
      for (let t = 0.08; t <= 0.82; t += 0.12) {
        let s = lerp(1.01, d.sEnd, t);
        let p = moundPt(s, d.ang + d.w0 * 0.25, 1.5);
        dripHilite.push([p[0], p[1], Math.sin(t * 180) * 1.2 + 0.2]);
      }
      brush.set("syrup_gloss", "#ffffff", 0.95);
      brush.spline(dripHilite, 0.4);

      // Bright crescent window-catchlight on the swollen pendant bulb at the bottom of each drip
      let pBulb1 = moundPt(d.sEnd - 0.07, d.ang + d.wBulb * 0.38, 2.0);
      let pBulb2 = moundPt(d.sEnd - 0.025, d.ang + d.wBulb * 0.18, 2.0);
