// Local coordinates inside main walnut (Piece A)
function toWalnutA(x, y) {
  let dx = x - WALNUT_A.cx;
  let dy = y - WALNUT_A.cy;
  let c = cos(-WALNUT_A.angle);
  let s = sin(-WALNUT_A.angle);
  return { u: dx * c - dy * s, v: dx * s + dy * c };
}

function fromWalnutA(u, v) {
  let c = cos(WALNUT_A.angle);
  let s = sin(WALNUT_A.angle);
  return {
    x: WALNUT_A.cx + u * c - v * s,
    y: WALNUT_A.cy + u * s + v * c
  };
}

// Boundary radius of main walnut shell at local coordinate (u, v)
function walnutARadiusFactor(u, v) {
  // Slight apical point at u < 0 (top-left apex), fuller base at u > 0
  let asym = u < 0 ? 1.0 - 0.16 * Math.pow(-u / WALNUT_A.a, 1.6) : 1.0 + 0.04 * (u / WALNUT_A.a);
  let ang = atan2(v, u);
  let jag = 0.025 * sin(ang * 7 + 20) + 0.015 * cos(ang * 13 - 40);
  let bEff = WALNUT_A.b * asym * (1 + jag);
  let aEff = WALNUT_A.a * (1 + 0.02 * cos(ang * 5));
  return Math.sqrt((u * u) / (aEff * aEff) + (v * v) / (bEff * bEff));
}

function inWalnutA(x, y, pad = 0) {
  let p = toWalnutA(x, y);
  let f = walnutARadiusFactor(p.u, p.v);
  return f <= 1.0 + pad / 130.0;
}

// Local coordinates inside secondary shell cap (Piece B)
function toWalnutB(x, y) {
  let dx = x - WALNUT_B.cx;
  let dy = y - WALNUT_B.cy;
  let c = cos(-WALNUT_B.angle);
  let s = sin(-WALNUT_B.angle);
  return { u: dx * c - dy * s, v: dx * s + dy * c };
}

function fromWalnutB(u, v) {
  let c = cos(WALNUT_B.angle);
  let s = sin(WALNUT_B.angle);
  return {
    x: WALNUT_B.cx + u * c - v * s,
    y: WALNUT_B.cy + u * s + v * c
  };
}

function walnutBRadiusFactor(u, v) {
  let asym = u < 0 ? 1.0 - 0.12 * Math.pow(-u / WALNUT_B.a, 1.5) : 1.0 + 0.03 * (u / WALNUT_B.a);
  let ang = atan2(v, u);
  let flange = Math.exp(-Math.pow(v / 14, 2)) * 0.045; // Apical carpel suture flange
  let ripple = 0.02 * sin(ang * 9) + flange;
  let aEff = WALNUT_B.a * (1 + ripple);
  let bEff = WALNUT_B.b * asym * (1 + 0.02 * cos(ang * 7));
  return Math.sqrt((u * u) / (aEff * aEff) + (v * v) / (bEff * bEff));
}

function inWalnutB(x, y, pad = 0) {
  let p = toWalnutB(x, y);
  return walnutBRadiusFactor(p.u, p.v) <= 1.0 + pad / 95.0;
}

// Distance to polyline spine with interpolated radius
function distToSpine(x, y, spine) {
  let minD = 1e9;
  for (let i = 0; i < spine.length - 1; i++) {
    let A = spine[i];
    let B = spine[i + 1];
    let vx = B.x - A.x;
    let vy = B.y - A.y;
    let len2 = vx * vx + vy * vy;
    let t = len2 > 0 ? constrain(((x - A.x) * vx + (y - A.y) * vy) / len2, 0, 1) : 0;
    let px = A.x + t * vx;
    let py = A.y + t * vy;
    let r = lerp(A.r, B.r, t);
    let d = dist(x, y, px, py) - r;
    if (d < minD) minD = d;
  }
  return minD;
}

function inNutcracker(x, y, pad = 0) {
  // Quick bounding box reject
  if (x < 420 - pad || x > 1020 + pad || y < 245 - pad || y > 835 + pad) return false;

  // Pivot boss
  if (dist(x, y, nutcracker.pivot.x, nutcracker.pivot.y) <= nutcracker.pivot.rOuter + pad) return true;

  // Jaws & handles
  if (distToSpine(x, y, nutcracker.upperJaw) <= pad) return true;
  if (distToSpine(x, y, nutcracker.lowerJaw) <= pad) return true;
  if (distToSpine(x, y, nutcracker.upperHandle) <= pad) return true;
  if (distToSpine(x, y, nutcracker.lowerHandle) <= pad) return true;

  // Bolsters
  let bu = distToSpine(x, y, [
    { x: nutcracker.upperBolster.x1, y: nutcracker.upperBolster.y1, r: nutcracker.upperBolster.r },
    { x: nutcracker.upperBolster.x2, y: nutcracker.upperBolster.y2, r: nutcracker.upperBolster.r }
  ]);
  if (bu <= pad) return true;

  let bl = distToSpine(x, y, [
    { x: nutcracker.lowerBolster.x1, y: nutcracker.lowerBolster.y1, r: nutcracker.lowerBolster.r },
    { x: nutcracker.lowerBolster.x2, y: nutcracker.lowerBolster.y2, r: nutcracker.lowerBolster.r }
  ]);
  if (bl <= pad) return true;

  // Ring finials (annulus check so linen shows inside the open finger loops!)
  let du = dist(x, y, nutcracker.upperRing.cx, nutcracker.upperRing.cy);
  if (du <= nutcracker.upperRing.rOuter + pad && du >= nutcracker.upperRing.rInner - pad) return true;

  let dl = dist(x, y, nutcracker.lowerRing.cx, nutcracker.lowerRing.cy);
  if (dl <= nutcracker.lowerRing.rOuter + pad && dl >= nutcracker.lowerRing.rInner - pad) return true;

  return false;
}

function inAnyShard(x, y, pad = 0) {
  for (let s of shards) {
    let dx = x - s.cx;
    let dy = y - s.cy;
    if (dx * dx + dy * dy > (s.rx + 12 + pad) * (s.rx + 12 + pad)) continue;
    let c = cos(-s.angle);
    let sn = sin(-s.angle);
    let u = dx * c - dy * sn;
    let v = dx * sn + dy * c;
    if (pointInPoly(u, v, s.pts, pad)) return true;
  }
  return false;
}

function pointInPoly(u, v, pts, pad = 0) {
  let inside = false;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
    let xi = pts[i][0], yi = pts[i][1];
    let xj = pts[j][0], yj = pts[j][1];
    let intersect = ((yi > v) !== (yj > v)) && (u < (xj - xi) * (v - yi) / ((yj - yi) || 1e-6) + xi);
    if (intersect) inside = !inside;
  }
  if (inside || pad <= 0) return inside;
  for (let i = 0; i < pts.length; i++) {
    let A = pts[i];
    let B = pts[(i + 1) % pts.length];
    let vx = B[0] - A[0], vy = B[1] - A[1];
    let l2 = vx * vx + vy * vy;
    let t = l2 > 0 ? constrain(((u - A[0]) * vx + (v - A[1]) * vy) / l2, 0, 1) : 0;
    if (dist(u, v, A[0] + t * vx, A[1] + t * vy) <= pad) return true;
  }
  return false;
}

function inForegroundObject(x, y, pad = 0) {
  return (
    inWalnutA(x, y, pad) ||
    inWalnutB(x, y, pad) ||
    inNutcracker(x, y, pad) ||
    inAnyShard(x, y, pad)
  );
}

// ============================================================================
// RUMPLED LINEN HEIGHTFIELD & CAST SHADOWS
// ============================================================================

function linenHeight(x, y) {
  // Primary sweeping diagonal drapery folds across the table
  let u1 = (x - 600) * 0.72 + (y - 600) * 0.69;
  let v1 = -(x - 600) * 0.69 + (y - 600) * 0.72;

  // Major fold ridges
  let fold1 = 18 * Math.sin(v1 * 0.011 + 0.55 * Math.sin(u1 * 0.005));
  let fold2 = 11 * Math.cos((x * 0.45 - y * 0.89) * 0.013 + 0.8 * Math.sin(x * 0.004));

  // Crisp linen pinch-creases (rumpled cloth ridges)
  let creaseArg1 = (x * 0.62 + y * 0.78) * 0.017 + 1.4 * noise(x * 0.0022, y * 0.0022);
  let crease1 = -9 * Math.pow(Math.abs(Math.sin(creaseArg1)), 0.55);

  let creaseArg2 = (x * 0.82 - y * 0.57) * 0.021 + 1.2 * noise(x * 0.0028 + 30, y * 0.0028 + 30);
  let crease2 = 7.5 * Math.pow(Math.abs(Math.cos(creaseArg2)), 0.65);

  // Depression under the heavy walnut and iron nutcracker
  let dWalnut = dist(x, y, WALNUT_A.cx, WALNUT_A.cy);
  let ringWave = 6.5 * Math.exp(-Math.pow((dWalnut - 175) / 58, 2)) * Math.cos((dWalnut - 175) * 0.05);

  // Fine rumple micro-topography
  let micro = 5.5 * (noise(x * 0.0065, y * 0.0065) - 0.5);

  return fold1 + fold2 + crease1 + crease2 + ringWave + micro;
}

// Analytical soft cast shadow onto the linen from upper-left raking light
function computeCastShadow(x, y) {
  let shadow = 0;

  // 1. Cast shadow from Main Cracked Walnut (Piece A, height ~ 130px)
  // Shadow extends toward (+0.68, +0.56)
  let pA = toWalnutA(x - 58, y - 48);
  let fA = walnutARadiusFactor(pA.u * 0.86, pA.v * 0.94);
  if (fA < 1.25) {
    let sA = constrain(map(fA, 0.72, 1.22, 0.92, 0), 0, 0.92);
    shadow = Math.max(shadow, sA);
  }
  // Tight dark contact occlusion directly under Main Walnut base
  let pA0 = toWalnutA(x - 14, y - 12);
  let fA0 = walnutARadiusFactor(pA0.u, pA0.v);
  if (fA0 < 1.12) {
    shadow = Math.max(shadow, constrain(map(fA0, 0.9, 1.12, 1.0, 0), 0, 1.0));
  }

  // 2. Cast shadow from Secondary Shell Cap (Piece B, height ~ 85px)
  let pB = toWalnutB(x - 42, y - 35);
  let fB = walnutBRadiusFactor(pB.u * 0.88, pB.v * 0.95);
  if (fB < 1.25) {
    let sB = constrain(map(fB, 0.75, 1.22, 0.86, 0), 0, 0.86);
    shadow = Math.max(shadow, sB);
  }
  let pB0 = toWalnutB(x - 10, y - 9);
  let fB0 = walnutBRadiusFactor(pB0.u, pB0.v);
  if (fB0 < 1.12) {
    shadow = Math.max(shadow, constrain(map(fB0, 0.92, 1.12, 0.98, 0), 0, 0.98));
  }

  // 3. Cast shadow from Cast-Iron Nutcracker (offset along light ray)
  if (inNutcracker(x - 24, y - 20, 8)) {
    shadow = Math.max(shadow, 0.78);
  } else if (inNutcracker(x - 32, y - 27, 16)) {
    shadow = Math.max(shadow, 0.45);
  }
  if (inNutcracker(x - 8, y - 7, 4)) {
    shadow = Math.max(shadow, 0.92);
  }

  // 4. Cast shadow from scattered shards
  for (let s of shards) {
    let ox = s.h * 0.72;
    let oy = s.h * 0.6;
    let dx = (x - ox) - s.cx;
    let dy = (y - oy) - s.cy;
    if (dx * dx + dy * dy < (s.rx + 22) * (s.rx + 22)) {
      let c = cos(-s.angle), sn = sin(-s.angle);
      let u = dx * c - dy * sn;
      let v = dx * sn + dy * c;
      if (pointInPoly(u, v, s.pts, 5)) {
        shadow = Math.max(shadow, 0.82);
      } else if (pointInPoly(u, v, s.pts, 12)) {
        shadow = Math.max(shadow, 0.42);
      }
    }
  }

  return constrain(shadow, 0, 1);
}

// Total darkness on the linen at (x, y) in [0, 1]
function linenDarkness(x, y) {
  let eps = 2.5;
  let h0 = linenHeight(x, y);
  let hx = (linenHeight(x + eps, y) - h0) / eps;
  let hy = (linenHeight(x, y + eps) - h0) / eps;

  // Surface normal (-hx, -hy, 1) normalized
  let invLen = 1.0 / Math.sqrt(hx * hx + hy * hy + 1.0);
  let nx = -hx * invLen;
  let ny = -hy * invLen;
  let nz = invLen;

  // Lambertian + dramatic printmaker contrast
  let dotL = nx * (-LIGHT.x) + ny * (-LIGHT.y) + nz * LIGHT.z;
  let foldDark = constrain(map(dotL, -0.35, 0.82, 0.76, 0.03), 0.02, 0.82);

  // Diagonal lighting gradient across the copperplate (upper-left bright, lower-right deep)
  let plateGrad = constrain(map((x - 150) * 0.55 + (y - 150) * 0.45, 0, 920, 0.0, 0.24), 0, 0.26);

  // Cast shadow contribution
  let cShadow = computeCastShadow(x, y);

  return constrain(foldDark + plateGrad + cShadow * 0.74, 0.02, 0.98);
}

// ============================================================================
// 1. PAPER FIBERS, WIPED PLATE-TONE WASH & BEVELLED PLATE-MARK
// ============================================================================

function drawPaperAndPlateTone() {
  brush.noField();
  brush.noStroke();

  // Faint wiped raw-umber plate-tone wash inside the copperplate boundary
  let px = PLATE.x1;
  let py = PLATE.y1;
  let pw = PLATE.x2 - PLATE.x1;
  let ph = PLATE.y2 - PLATE.y1;

  // Base wiped raw umber veil across the plate
  brush.wash(PALETTE.plateUmber, 18);
  brush.rect(px, py, pw, ph, "corner");
  brush.noWash();

  // Subtle retroussage (ink left by the printer's palm/tarlatan in shadow zones)
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.55, 0.25);

  // Cool slate-umber shadow veil in lower-right & around the objects
  brush.fill(PALETTE.plateSlate, 15);
  drawSoftBlob(640, 680, 390, 320, 12);
  drawSoftBlob(780, 820, 260, 220, 10);

  // Warm raw-umber retroussage veil behind the walnut & nutcracker jaws
  brush.fill(PALETTE.plateUmber, 14);
  drawSoftBlob(460, 560, 310, 260, 12);

  // Hand-wiped bright aura in upper-left light entry zone
  brush.fill(PALETTE.paperLight, 20);
  drawSoftBlob(290, 280, 220, 180, 10);

  brush.noFill();

  // Delicate laid paper fibers in outer margins and faint plate wiping scratches
  brush.set("needle", PALETTE.paperFibers, 0.55);
  for (let i = 0; i < 180; i++) {
    let x = random(25, 1175);
    let y = random(25, 1175);
    let len = random(18, 55);
    let ang = random(-4, 4);
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // Subtle diagonal plate-wiping tarlatan drags inside the plate
  brush.set("needle", PALETTE.inkFaint, 0.35);
  for (let i = 0; i < 65; i++) {
    let x = random(PLATE.x1 + 20, PLATE.x2 - 60);
    let y = random(PLATE.y1 + 20, PLATE.y2 - 60);
    if (inForegroundObject(x, y, 25)) continue;
    let len = random(25, 85);
    brush.line(x, y, x + len * 0.72, y + len * 0.68);
  }
}

function drawSoftBlob(cx, cy, rx, ry, steps) {
  brush.beginShape(0.45);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let rMod = 0.88 + 0.24 * noise(cx * 0.01 + cos(a), cy * 0.01 + sin(a));
    brush.vertex(cx + cos(a) * rx * rMod, cy + sin(a) * ry * rMod);
  }
  brush.endShape(true);
}

function drawPlateMarkBorder() {
  let x1 = PLATE.x1, y1 = PLATE.y1, x2 = PLATE.x2, y2 = PLATE.y2;
  let b = PLATE.bevel;
  let ox1 = x1 - b, oy1 = y1 - b, ox2 = x2 + b, oy2 = y2 + b;

  // Top & Left bevels slope AWAY from upper-left light -> soft deboss shadow
  brush.set("drypoint", PALETTE.bevelShadow, 0.65);
  for (let t = 0; t <= b; t += 2.2) {
    // Top bevel lines
    brush.line(ox1 + t, oy1 + t, ox2 - t, oy1 + t);
    // Left bevel lines
    brush.line(ox1 + t, oy1 + t, ox1 + t, oy2 - t);
  }

  // Bottom & Right bevels slope TOWARD upper-left light -> bright paper highlight
  brush.set("drypoint", PALETTE.paperLight, 0.9);
  for (let t = 2; t <= b - 2; t += 2.0) {
    brush.line(ox1 + t, oy2 - t, ox2 - t, oy2 - t);
    brush.line(ox2 - t, oy1 + t, ox2 - t, oy2 - t);
  }

  // Outer deboss crease on bottom & right
  brush.set("needle", PALETTE.bevelShadow, 0.6);
  brush.line(ox1, oy2, ox2, oy2);
  brush.line(ox2, oy1, ox2, oy2);
  brush.line(ox1, oy1, ox1 + b, y1);
  brush.line(ox2, oy1, x2, y1);
  brush.line(ox1, oy2, x1, y2);
  brush.line(ox2, oy2, x2, y2);

  // Inner plate edge (where residual ink clings to the bevelled copper rim)
  brush.set("burin", PALETTE.inkLight, 0.75);
  brush.line(x1, y1, x2, y1);
  brush.line(x1, y1, x1, y2);
  brush.set("drypoint", PALETTE.inkFaint, 0.55);
  brush.line(x1, y2, x2, y2);
  brush.line(x2, y1, x2, y2);

  // Classical double engraved framing rule inside the copperplate
  let fx1 = x1 + 18, fy1 = y1 + 18, fx2 = x2 - 18, fy2 = y2 - 18;
  brush.set("burin", PALETTE.inkMid, 0.65);
  brush.line(fx1, fy1, fx2, fy1);
  brush.line(fx2, fy1, fx2, fy2);
  brush.line(fx2, fy2, fx1, fy2);
  brush.line(fx1, fy2, fx1, fy1);

  let gx1 = fx1 + 5, gy1 = fy1 + 5, gx2 = fx2 - 5, gy2 = fy2 - 5;
  brush.set("drypoint", PALETTE.inkLight, 0.48);
  brush.line(gx1, gy1, gx2, gy1);
  brush.line(gx2, gy1, gx2, gy2);
  brush.line(gx2, gy2, gx1, gy2);
  brush.line(gx1, gy2, gx1, gy1);

  // Tiny scientific engraving corner rosette ticks & plate registration marks
  brush.set("needle", PALETTE.inkMid, 0.5);
  let corners = [[fx1, fy1, 1, 1], [fx2, fy1, -1, 1], [fx2, fy2, -1, -1], [fx1, fy2, 1, -1]];
  for (let c of corners) {
    brush.line(c[0], c[1], c[0] - c[2] * 8, c[1] - c[3] * 8);
  }
}

// ============================================================================
// 2. RUMPLED LINEN WEAVE HATCHING SYSTEM
// ============================================================================

function drawRumpledLinen() {
  let xMin = PLATE.x1 + 25;
  let xMax = PLATE.x2 - 25;
  let yMin = PLATE.y1 + 25;
  let yMax = PLATE.y2 - 25;

  // PASS 1: Warp threads (nearly horizontal, curving over the 3D linen folds)
  let warpSpacing = 4.6;
  let step = 8.0;

  for (let yBase = yMin; yBase <= yMax; yBase += warpSpacing) {
    let segLight = [];
    let segDark = [];
    let segDeep = [];

    for (let x = xMin; x <= xMax; x += step) {
      // Slight diagonal warp tilt + 3D vertical displacement from linen folds
      let yRaw = yBase + (x - 600) * 0.045;
      let h = linenHeight(x, yRaw);
      let y = yRaw - h * 0.58;

      if (y < yMin || y > yMax || inForegroundObject(x, y, 1.5)) {
        flushLinenSegments(segLight, segDark, segDeep);
        segLight = [];
        segDark = [];
        segDeep = [];
        continue;
      }

      let d = linenDarkness(x, y);
      // Periodic over-under thread weave modulation
      let weave = 0.09 * Math.sin(x * 0.68 + yBase * 0.72);
      let dEff = constrain(d + weave, 0, 1);

      // In the brightest upper-left linen crests, skip occasional stitches for crisp weave sparkle
      if (dEff < 0.08 && Math.sin(x * 0.45 + yBase) > 0.25) {
        flushLinenSegments(segLight, segDark, segDeep);
        segLight = [];
        segDark = [];
        segDeep = [];
        continue;
      }

      let pLight = constrain(map(dEff, 0.04, 0.55, 0.16, 1.15), 0.14, 1.2);
      segLight.push([x, y, pLight]);

      if (dEff > 0.34) {
        let pDark = constrain(map(dEff, 0.34, 0.92, 0.22, 1.38), 0.2, 1.42);
        segDark.push([x, y + 0.45, pDark]);
      } else if (segDark.length > 0) {
        drawSplineSegment(segDark, "burin", PALETTE.inkMid, 0.62);
        segDark = [];
      }

      if (dEff > 0.64) {
        let pDeep = constrain(map(dEff, 0.64, 0.98, 0.35, 1.48), 0.3, 1.5);
        segDeep.push([x, y - 0.45, pDeep]);
      } else if (segDeep.length > 0) {
        drawSplineSegment(segDeep, "burin", PALETTE.inkDark, 0.78);
        segDeep = [];
      }
    }
    flushLinenSegments(segLight, segDark, segDeep);
  }

  // PASS 2: Weft threads (nearly vertical, curving over the 3D linen folds)
  let weftSpacing = 4.8;
  for (let xBase = xMin; xBase <= xMax; xBase += weftSpacing) {
    let segLight = [];
    let segDark = [];

    for (let y = yMin; y <= yMax; y += step) {
      let xRaw = xBase - (y - 600) * 0.045;
      let h = linenHeight(xRaw, y);
      let x = xRaw - h * 0.52;

      if (x < xMin || x > xMax || inForegroundObject(x, y, 1.5)) {
        if (segLight.length > 0) {
          drawSplineSegment(segLight, "drypoint", PALETTE.inkLight, 0.52);
          segLight = [];
        }
        if (segDark.length > 0) {
          drawSplineSegment(segDark, "burin", PALETTE.inkMid, 0.62);
          segDark = [];
        }
        continue;
      }

      let d = linenDarkness(x, y);
      let weave = 0.09 * Math.cos(y * 0.68 + xBase * 0.72);
      let dEff = constrain(d + weave, 0, 1);

      if (dEff < 0.11 && Math.cos(y * 0.42 + xBase) > 0.1) {
        if (segLight.length > 0) {
          drawSplineSegment(segLight, "drypoint", PALETTE.inkLight, 0.52);
          segLight = [];
        }
        if (segDark.length > 0) {
          drawSplineSegment(segDark, "burin", PALETTE.inkMid, 0.62);
          segDark = [];
        }
        continue;
      }

      let pLight = constrain(map(dEff, 0.06, 0.65, 0.15, 1.1), 0.14, 1.15);
      segLight.push([x, y, pLight]);

      if (dEff > 0.42) {
        let pDark = constrain(map(dEff, 0.42, 0.95, 0.22, 1.35), 0.2, 1.4);
        segDark.push([x + 0.45, y, pDark]);
      } else if (segDark.length > 0) {
        drawSplineSegment(segDark, "burin", PALETTE.inkMid, 0.62);
        segDark = [];
      }
    }
    if (segLight.length > 0) drawSplineSegment(segLight, "drypoint", PALETTE.inkLight, 0.52);
    if (segDark.length > 0) drawSplineSegment(segDark, "burin", PALETTE.inkMid, 0.62);
  }

  // PASS 3: Diagonal burin cross-hatching (-34 deg) in deep cloth troughs & cast shadows
  let diagSpacing = 4.2;
  for (let offset = -900; offset <= 900; offset += diagSpacing) {
    let seg = [];
    let segCore = [];
    for (let s = -650; s <= 650; s += 7.5) {
      let x = 600 + s * 0.83 - offset * 0.56;
      let yRaw = 600 + s * 0.56 + offset * 0.83;
      if (x < xMin || x > xMax || yRaw < yMin || yRaw > yMax) {
        if (seg.length > 0) { drawSplineSegment(seg, "burin", PALETTE.inkDark, 0.68); seg = []; }
        if (segCore.length > 0) { drawSplineSegment(segCore, "burin_heavy", PALETTE.inkBlack, 0.75); segCore = []; }
        continue;
      }
      let h = linenHeight(x, yRaw);
      let y = yRaw - h * 0.42;

      if (y < yMin || y > yMax || inForegroundObject(x, y, 1.2)) {
        if (seg.length > 0) { drawSplineSegment(seg, "burin", PALETTE.inkDark, 0.68); seg = []; }
        if (segCore.length > 0) { drawSplineSegment(segCore, "burin_heavy", PALETTE.inkBlack, 0.75); segCore = []; }
        continue;
      }

      let d = linenDarkness(x, y);
      if (d > 0.46) {
        let p = constrain(map(d, 0.46, 0.95, 0.18, 1.38), 0.16, 1.42);
        seg.push([x, y, p]);
      } else if (seg.length > 0) {
        drawSplineSegment(seg, "burin", PALETTE.inkDark, 0.68);
        seg = [];
      }

      if (d > 0.72) {
        let pCore = constrain(map(d, 0.72, 0.98, 0.25, 1.45), 0.22, 1.48);
        segCore.push([x + 0.5, y + 0.5, pCore]);
      } else if (segCore.length > 0) {
        drawSplineSegment(segCore, "burin_heavy", PALETTE.inkBlack, 0.75);
        segCore = [];
      }
    }
    if (seg.length > 0) drawSplineSegment(seg, "burin", PALETTE.inkDark, 0.68);
    if (segCore.length > 0) drawSplineSegment(segCore, "burin_heavy", PALETTE.inkBlack, 0.75);
  }

  // PASS 4: Characteristic linen slubs (thickened raw flax threads along the weave)
  brush.set("burin", PALETTE.inkMid, 0.58);
  for (let i = 0; i < 95; i++) {
    let sx = random(xMin + 20, xMax - 40);
    let sy = random(yMin + 20, yMax - 40);
    if (inForegroundObject(sx, sy, 14)) continue;
    let d = linenDarkness(sx, sy);
    let len = random(12, 34);
    let horiz = random() < 0.55;
    let pts = [];
    for (let t = 0; t <= 1; t += 0.25) {
      let px = horiz ? sx + (t - 0.5) * len : sx - (t - 0.5) * len * 0.05;
      let pyRaw = horiz ? sy + (t - 0.5) * len * 0.05 : sy + (t - 0.5) * len;
      let py = pyRaw - linenHeight(px, pyRaw) * 0.55;
      if (!inForegroundObject(px, py, 2)) {
        let p = (0.3 + d * 0.85) * Math.sin(t * Math.PI);
        pts.push([px, py, constrain(p, 0.18, 1.25)]);
      }
    }
    if (pts.length >= 3) brush.spline(pts, 0.25);
  }
}

function flushLinenSegments(segLight, segDark, segDeep) {
  if (segLight.length > 0) drawSplineSegment(segLight, "drypoint", PALETTE.inkLight, 0.54);
  if (segDark.length > 0) drawSplineSegment(segDark, "burin", PALETTE.inkMid, 0.62);
  if (segDeep.length > 0) drawSplineSegment(segDeep, "burin", PALETTE.inkDark, 0.78);
}

function drawSplineSegment(pts, brushName, col, weight) {
  if (pts.length < 2) return;
  brush.set(brushName, col, weight);
  if (pts.length === 2) {
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
  } else {
    brush.spline(pts, 0.3);
  }
}

// ============================================================================
// 3. SCATTERED SHELL SHARDS & SEPTUM FRAGMENTS
// ============================================================================

function drawShellShards() {
  for (let s of shards) {
    let c = cos(s.angle), sn = sin(s.angle);
    let worldPts = s.pts.map(p => [
      s.cx + p[0] * c - p[1] * sn,
      s.cy + p[0] * sn + p[1] * c
    ]);

    // 1. Subtle paper knock-out / pale raw-umber interior tone so linen doesn't bleed through
    brush.noStroke();
    brush.wash(PALETTE.paper, 230);
    brush.beginShape(0.12);
    for (let wp of worldPts) brush.vertex(wp[0], wp[1]);
    brush.endShape(true);
    brush.noWash();

    // 2. Internal hatching based on fragment anatomy
    let step = s.type === "septum_flake" ? 2.1 : 2.5;
    for (let v = -s.ry - 4; v <= s.ry + 4; v += step) {
      let linePts = [];
      for (let u = -s.rx - 4; u <= s.rx + 4; u += 2.5) {
        if (pointInPoly(u, v, s.pts, -0.5)) {
          // Local 3D curvature & fracture facets
          let curveZ = s.type === "septum_flake"
            ? 2.2 * Math.sin(u * 0.14)
            : 5.5 * (1 - (u * u) / (s.rx * s.rx + 1)) * (s.type === "shell_inner" ? -1 : 1);
          let shade = constrain(0.28 + 0.38 * (u / s.rx) + 0.32 * (v / s.ry) + 0.15 * sin(u * 0.35 + v * 0.25), 0.12, 0.95);
          let wx = s.cx + u * c - (v - curveZ * 0.35) * sn;
          let wy = s.cy + u * sn + (v - curveZ * 0.35) * c;
          linePts.push([wx, wy, map(shade, 0.1, 0.95, 0.2, 1.35)]);
        } else if (linePts.length > 0) {
          drawSplineSegment(linePts, s.type === "septum_flake" ? "drypoint" : "burin", PALETTE.inkMid, 0.58);
          linePts = [];
        }
      }
      if (linePts.length > 0) {
        drawSplineSegment(linePts, s.type === "septum_flake" ? "drypoint" : "burin", PALETTE.inkMid, 0.58);
      }
    }

    // Cross-hatching on the lower-right shadow bevel of each shard
    for (let u = -s.rx; u <= s.rx; u += 2.8) {
      let crossPts = [];
      for (let v = -s.ry; v <= s.ry; v += 2.5) {
        if (pointInPoly(u, v, s.pts, -0.5) && (u * 0.5 + v * 0.7 > -2)) {
          let wx = s.cx + u * c - v * sn;
          let wy = s.cy + u * sn + v * c;
          crossPts.push([wx, wy, 0.85]);
        } else if (crossPts.length > 0) {
          drawSplineSegment(crossPts, "burin", PALETTE.inkDark, 0.65);
          crossPts = [];
        }
      }
      if (crossPts.length > 0) drawSplineSegment(crossPts, "burin", PALETTE.inkDark, 0.65);
    }

    // Crisp angular fracture outline & thickness rim on lower-right edges
    brush.set("burin", PALETTE.inkDark, 0.75);
    for (let i = 0; i < worldPts.length; i++) {
      let A = worldPts[i];
      let B = worldPts[(i + 1) % worldPts.length];
      brush.line(A[0], A[1], B[0], B[1]);
      // Thick shell wall step on shadow-facing edges
      let nx = -(B[1] - A[1]), ny = B[0] - A[0];
      if (nx * 0.68 + ny * 0.56 > 0 && s.type !== "septum_flake") {
        let wall = 4.2;
        brush.set("burin_heavy", PALETTE.inkBlack, 0.82);
        brush.line(A[0] + 2.5, A[1] + 2.2, B[0] + 2.5, B[1] + 2.2);
        for (let t = 0; t <= 1; t += 0.25) {
          let px = lerp(A[0], B[0], t);
          let py = lerp(A[1], B[1], t);
          brush.line(px, py, px + wall * 0.7, py + wall * 0.65);
        }
        brush.set("burin", PALETTE.inkDark, 0.75);
      }
    }
  }
}

// ============================================================================
// 4. SECONDARY WALNUT SHELL CAP (PIECE B: VERMICULATED EXTERIOR SHELL)
// ============================================================================

function walnutBShellRelief(u, v) {
  let r2 = (u * u) / (WALNUT_B.a * WALNUT_B.a) + (v * v) / (WALNUT_B.b * WALNUT_B.b);
  if (r2 >= 1.05) return 0;
  let dome = Math.sqrt(Math.max(0, 1.0 - r2 * 0.92)) * 78;

  // Raised longitudinal suture keel along v ≈ 0 with flanged groove
  let sutureKeel = 9.5 * Math.exp(-Math.pow(v / 9.5, 2)) - 4.0 * Math.exp(-Math.pow(v / 2.8, 2));

  // Deep vermiculated shell pits and sinuous ridges
  let warpU = u * 0.055 + 2.2 * noise(u * 0.025 + 10, v * 0.025 + 10);
  let warpV = v * 0.065 + 2.2 * noise(u * 0.025 + 50, v * 0.025 + 50);
  let pits = -8.5 * Math.pow(Math.abs(Math.sin(warpU * 2.4) * Math.cos(warpV * 2.4)), 1.6);
  let ribs = 4.5 * Math.sin(u * 0.14 + Math.abs(v) * 0.08);

  return dome + sutureKeel + pits + ribs;
}

function drawWalnutShellCap() {
  // 1. Clean paper base inside shell silhouette
  brush.noStroke();
  brush.wash(PALETTE.paper, 240);
  brush.beginShape(0.25);
  for (let a = 0; a < 360; a += 5) {
    let u = cos(a) * WALNUT_B.a;
    let v = sin(a) * WALNUT_B.b;
    let f = walnutBRadiusFactor(u, v);
    let p = fromWalnutB(u / f, v / f);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(true);
  brush.noWash();

  // Subtle raw-umber shadow glaze on lower-right hemisphere of shell cap
  brush.fillBleed(0.18, "in");
  brush.fill(PALETTE.plateUmber, 22);
  brush.beginShape(0.3);
  for (let a = -35; a <= 165; a += 10) {
    let u = cos(a) * WALNUT_B.a * 0.92;
    let v = sin(a) * WALNUT_B.b * 0.92;
    let p = fromWalnutB(u, v);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(true);
  brush.noFill();

  // 2. Primary form-following meridian engraving lines (wrapping over craters and suture ridge)
  let vSpacing = 2.6;
  for (let vBase = -WALNUT_B.b; vBase <= WALNUT_B.b; vBase += vSpacing) {
    let segLight = [];
    let segDark = [];
    let segPit = [];

    for (let u = -WALNUT_B.a; u <= WALNUT_B.a; u += 3.2) {
      let vCurve = vBase * (1.0 - 0.22 * (u * u) / (WALNUT_B.a * WALNUT_B.a));
      if (walnutBRadiusFactor(u, vCurve) > 0.985) {
        flushLinenSegments(segLight, segDark, segPit);
        segLight = []; segDark = []; segPit = [];
        continue;
      }

      let eps = 2.0;
      let z0 = walnutBShellRelief(u, vCurve);
      let zx = (walnutBShellRelief(u + eps, vCurve) - z0) / eps;
      let zy = (walnutBShellRelief(u, vCurve + eps) - z0) / eps;

      // Normal in world space
      let c = cos(WALNUT_B.angle), s = sin(WALNUT_B.angle);
      let gx = zx * c - zy * s;
      let gy = zx * s + zy * c;
      let inv = 1.0 / Math.sqrt(gx * gx + gy * gy + 1.0);
      let dotL = (-gx * LIGHT.x * (-1) - gy * LIGHT.y * (-1) + LIGHT.z) * inv;

      // Crater pit darkness + overall dome lighting
      let domeShade = constrain(map(u * 0.55 + vCurve * 0.72, -75, 75, 0.08, 0.85), 0.05, 0.92);
      let slopeShade = constrain(map(dotL, -0.4, 0.85, 0.88, 0.04), 0.04, 0.92);
      let dark = constrain(domeShade * 0.52 + slopeShade * 0.58, 0.04, 0.98);

      // Deflect line position by 3D relief height for genuine sculptural engraving
      let wp = fromWalnutB(u, vCurve - (z0 - 45) * 0.16);

      if (dark < 0.1 && random() < 0.35) {
        flushLinenSegments(segLight, segDark, segPit);
        segLight = []; segDark = []; segPit = [];
        continue;
      }

      segLight.push([wp.x, wp.y, constrain(map(dark, 0.05, 0.65, 0.18, 1.25), 0.16, 1.3)]);

      if (dark > 0.42) {
        segDark.push([wp.x, wp.y + 0.45, constrain(map(dark, 0.42, 0.95, 0.25, 1.42), 0.22, 1.45)]);
      } else if (segDark.length > 0) {
        drawSplineSegment(segDark, "burin", PALETTE.inkMid, 0.65);
        segDark = [];
      }

      if (dark > 0.68) {
        segPit.push([wp.x, wp.y - 0.45, constrain(map(dark, 0.68, 0.98, 0.35, 1.48), 0.3, 1.5)]);
      } else if (segPit.length > 0) {
        drawSplineSegment(segPit, "burin_heavy", PALETTE.inkBlack, 0.75);
        segPit = [];
      }
    }
    flushLinenSegments(segLight, segDark, segPit);
  }

  // 3. Transverse cross-hatching ribs across the shell dome & deep vermiculated pits
  let uSpacing = 3.2;
  for (let uBase = -WALNUT_B.a + 6; uBase <= WALNUT_B.a - 6; uBase += uSpacing) {
    let seg = [];
    for (let v = -WALNUT_B.b; v <= WALNUT_B.b; v += 3.2) {
      let uCurve = uBase + 9 * Math.sin((v / WALNUT_B.b) * Math.PI * 0.5);
      if (walnutBRadiusFactor(uCurve, v) > 0.975) {
        if (seg.length > 0) { drawSplineSegment(seg, "burin", PALETTE.inkDark, 0.64); seg = []; }
        continue;
      }
      let z0 = walnutBShellRelief(uCurve, v);
      let domeShade = constrain(map(uCurve * 0.5 + v * 0.75, -75, 75, 0.05, 0.92), 0, 1);
      // Cross-hatch inside the shadow side OR inside deep vermiculated craters
      let warpU = uCurve * 0.055 + 2.2 * noise(uCurve * 0.025 + 10, v * 0.025 + 10);
      let warpV = v * 0.065 + 2.2 * noise(uCurve * 0.025 + 50, v * 0.025 + 50);
      let inPit = Math.pow(Math.abs(Math.sin(warpU * 2.4) * Math.cos(warpV * 2.4)), 1.6) > 0.48;

      if (domeShade > 0.38 || inPit) {
        let wp = fromWalnutB(uCurve - (z0 - 45) * 0.12, v);
        let p = constrain(map(domeShade + (inPit ? 0.32 : 0), 0.35, 1.1, 0.22, 1.38), 0.2, 1.42);
        seg.push([wp.x, wp.y, p]);
      } else if (seg.length > 0) {
        drawSplineSegment(seg, "burin", PALETTE.inkDark, 0.64);
        seg = [];
      }
    }
    if (seg.length > 0) drawSplineSegment(seg, "burin", PALETTE.inkDark, 0.64);
  }

  // 4. Engraved contour rim & shadowed base undercut of Piece B
  let rimPts = [];
  for (let a = 0; a <= 360; a += 4) {
    let u = cos(a) * WALNUT_B.a;
    let v = sin(a) * WALNUT_B.b;
    let f = walnutBRadiusFactor(u, v);
    let wp = fromWalnutB(u / f, v / f);
    let shade = constrain(map(cos(a - 45), -1, 1, 0.28, 1.45), 0.25, 1.48);
    rimPts.push([wp.x, wp.y, shade]);
  }
  drawSplineSegment(rimPts, "burin_heavy", PALETTE.inkDark, 0.78);
}

// ============================================================================
// 5. ANTIQUE CAST-IRON NUTCRACKER (METALLIC BURIN ENGRAVING)
// ============================================================================

function drawCastIronNutcracker() {
  // 1. Knock out linen behind the solid iron components
  knockOutNutcrackerSilhouette();

  // 2. Engrave Lower & Upper Handles (cylindrical cuff arcs + longitudinal lozenge lines)
  engraveIronSpine(nutcracker.lowerHandle, 18, false);
  engraveIronSpine(nutcracker.upperHandle, 18, false);

  // 3. Engrave Turned Molded Bolsters / Collars
  engraveIronBolster(nutcracker.lowerBolster);
  engraveIronBolster(nutcracker.upperBolster);

  // 4. Engrave Forged Open Loop Ring Finials at handle ends
  engraveIronRingFinial(nutcracker.lowerRing);
  engraveIronRingFinial(nutcracker.upperRing);

  // 5. Engrave Heavy Crushing Jaws & Interlocking Sawtooth Teeth
  engraveCrushingJaws();

  // 6. Engrave Slotted Hinge Knuckle & Domed Rivet Pin
  engravePivotKnuckle();

  // 7. Cast-iron granular stipple & oxidized surface pitting
  engraveIronPitting();
}

function knockOutNutcrackerSilhouette() {
  brush.noStroke();
  brush.wash(PALETTE.paper, 242);

  // Helper to wash a spine polygon
  let washSpine = (spine) => {
    let left = [], right = [];
    for (let i = 0; i < spine.length; i++) {
      let cur = spine[i];
      let next = spine[Math.min(i + 1, spine.length - 1)];
      let prev = spine[Math.max(i - 1, 0)];
      let tx = next.x - prev.x, ty = next.y - prev.y;
      let l = Math.sqrt(tx * tx + ty * ty) || 1;
      let nx = -ty / l, ny = tx / l;
      left.push([cur.x + nx * cur.r, cur.y + ny * cur.r]);
      right.unshift([cur.x - nx * cur.r, cur.y - ny * cur.r]);
    }
    let poly = left.concat(right);
    brush.beginShape(0.2);
    for (let p of poly) brush.vertex(p[0], p[1]);
    brush.endShape(true);
  };

  washSpine(nutcracker.upperJaw);
  washSpine(nutcracker.lowerJaw);
  washSpine(nutcracker.upperHandle);
  washSpine(nutcracker.lowerHandle);

  // Pivot boss
  brush.circle(nutcracker.pivot.x, nutcracker.pivot.y, nutcracker.pivot.rOuter, 0.05);
  brush.noWash();
}

// Evaluates point, tangent, normal, and radius along a spine for t in [0, 1]
function evalSpine(spine, t) {
  let segs = spine.length - 1;
  let ft = constrain(t * segs, 0, segs - 1e-6);
  let idx = Math.floor(ft);
  let lt = ft - idx;
  let A = spine[idx], B = spine[idx + 1];
  let x = lerp(A.x, B.x, lt);
  let y = lerp(A.y, B.y, lt);
  let r = lerp(A.r, B.r, lt);
  let tx = B.x - A.x, ty = B.y - A.y;
  let len = Math.sqrt(tx * tx + ty * ty) || 1;
  tx /= len; ty /= len;
  // Normal pointing toward upper-left / upper-right
  let nx = -ty, ny = tx;
  if (nx * LIGHT.x + ny * LIGHT.y < 0) {
    // Ensure v = -1 is the upper-left lit edge and v = +1 is the lower-right shadow edge
    nx = -nx; ny = -ny;
  }
  return { x, y, r, tx, ty, nx, ny };
}

// Metallic cylinder reflectance curve for antique cast iron:
// v in [-1 (upper-left lit edge), +1 (lower-right shadow edge)]
function ironCylinderDarkness(v, tAlong) {
  // Crisp narrow specular ridge around v = -0.46
  let spec = Math.exp(-Math.pow((v + 0.46) / 0.16, 2));
  // Dark metallic core reflection at v = +0.28 and edge dark at v = -0.92 & +0.92
  let core = 0.42 * Math.exp(-Math.pow((v - 0.30) / 0.38, 2));
  // Subtle reflected light from linen at v = +0.68
  let refl = -0.16 * Math.exp(-Math.pow((v - 0.68) / 0.18, 2));
  let base = 0.54 + 0.28 * v + core + refl - 0.52 * spec;
  // Slight forged hammer ripple along the length
  let ripple = 0.05 * Math.sin(tAlong * 38) + 0.04 * (noise(v * 3 + tAlong * 8) - 0.5);
  return constrain(base + ripple, 0.04, 0.98);
}

function engraveIronSpine(spine, numLong, isJaw) {
  // 1. Subtle cool-slate wash under the dark iron core
  brush.noStroke();
  brush.fillBleed(0.1, "in");
  brush.fill(PALETTE.plateSlate, 26);
  brush.beginShape(0.2);
  for (let t = 0; t <= 1; t += 0.1) {
    let s = evalSpine(spine, t);
    brush.vertex(s.x - s.nx * s.r * 0.05, s.y - s.ny * s.r * 0.05);
  }
  for (let t = 1; t >= 0; t -= 0.1) {
    let s = evalSpine(spine, t);
    brush.vertex(s.x - s.nx * s.r * 0.95, s.y - s.ny * s.r * 0.95);
  }
  brush.endShape(true);
  brush.noFill();

  // 2. Longitudinal burin lines along the length of the iron bar
  for (let i = 0; i <= numLong; i++) {
    let v = map(i, 0, numLong, -0.96, 0.96);
    let segMain = [];
    let segDeep = [];

    for (let t = 0; t <= 1.001; t += 0.035) {
      let st = evalSpine(spine, t);
      // Decorative mid-handle grip swell on handles
      let rMod = (!isJaw && t > 0.45 && t < 0.85) ? 1.0 + 0.12 * Math.sin(((t - 0.45) / 0.4) * Math.PI) : 1.0;
      let px = st.x - st.nx * (v * st.r * rMod);
      let py = st.y - st.ny * (v * st.r * rMod);
      let d = ironCylinderDarkness(v, t);

      // Break longitudinal lines across the bright specular highlight ridge
      if (d < 0.14 && t > 0.12 && t < 0.88) {
        if (segMain.length > 0) { drawSplineSegment(segMain, "burin", PALETTE.inkDark, 0.68); segMain = []; }
        if (segDeep.length > 0) { drawSplineSegment(segDeep, "burin_heavy", PALETTE.inkBlack, 0.82); segDeep = []; }
        continue;
      }

      segMain.push([px, py, constrain(map(d, 0.12, 0.95, 0.18, 1.4), 0.16, 1.45)]);
      if (d > 0.62) {
        segDeep.push([px + 0.4, py + 0.4, constrain(map(d, 0.62, 0.98, 0.3, 1.48), 0.25, 1.5)]);
      } else if (segDeep.length > 0) {
        drawSplineSegment(segDeep, "burin_heavy", PALETTE.inkBlack, 0.82);
        segDeep = [];
      }
    }
    if (segMain.length > 0) drawSplineSegment(segMain, "burin", PALETTE.inkDark, 0.68);
    if (segDeep.length > 0) drawSplineSegment(segDeep, "burin_heavy", PALETTE.inkBlack, 0.82);
  }

  // 3. Transverse / Annular cuff contours wrapping around the cylinder
  let numCuffs = isJaw ? 38 : 68;
  for (let j = 0; j <= numCuffs; j++) {
    let t = j / numCuffs;
    let st = evalSpine(spine, t);
    let rMod = (!isJaw && t > 0.45 && t < 0.85) ? 1.0 + 0.12 * Math.sin(((t - 0.45) / 0.4) * Math.PI) : 1.0;
    let rEff = st.r * rMod;

    let cuffPts = [];
    for (let k = 0; k <= 12; k++) {
      let v = map(k, 0, 12, -0.98, 0.98);
      // 3D elliptical curvature around the cylindrical cross-section
      let arch = Math.sqrt(Math.max(0, 1 - v * v)) * rEff * 0.32;
      let px = st.x - st.nx * (v * rEff) + st.tx * arch;
      let py = st.y - st.ny * (v * rEff) + st.ty * arch;
      let d = ironCylinderDarkness(v, t);

      if (d < 0.13 && k > 1 && k < 11) {
        if (cuffPts.length > 0) {
          drawSplineSegment(cuffPts, "burin", PALETTE.inkDark, 0.66);
          cuffPts = [];
        }
        continue;
      }
      cuffPts.push([px, py, constrain(map(d, 0.12, 0.96, 0.18, 1.42), 0.16, 1.45)]);
    }
    if (cuffPts.length > 0) drawSplineSegment(cuffPts, "burin", PALETTE.inkDark, 0.66);
  }

  // 4. Crisp upper-left boundary & heavy lower-right shadow contour
  let litEdge = [], shadEdge = [];
  for (let t = 0; t <= 1.001; t += 0.04) {
    let st = evalSpine(spine, t);
    let rMod = (!isJaw && t > 0.45 && t < 0.85) ? 1.0 + 0.12 * Math.sin(((t - 0.45) / 0.4) * Math.PI) : 1.0;
    litEdge.push([st.x + st.nx * st.r * rMod, st.y + st.ny * st.r * rMod, 0.65]);
    shadEdge.push([st.x - st.nx * st.r * rMod, st.y - st.ny * st.r * rMod, 1.38]);
  }
  drawSplineSegment(litEdge, "burin", PALETTE.inkMid, 0.68);
  drawSplineSegment(shadEdge, "burin_heavy", PALETTE.inkBlack, 0.88);
}

function engraveIronBolster(b) {
  // Turned double-bead iron collar between jaw and handle
  let spine = [{ x: b.x1, y: b.y1, r: b.r }, { x: b.x2, y: b.y2, r: b.r }];
  for (let t = 0; t <= 1.001; t += 0.07) {
    let st = evalSpine(spine, t);
    // Double bead molding profile
    let bead = 1.0 + 0.18 * Math.sin(t * Math.PI * 2);
    let rEff = st.r * bead;
    let pts = [];
    for (let k = 0; k <= 10; k++) {
      let v = map(k, 0, 10, -1, 1);
      let arch = Math.sqrt(Math.max(0, 1 - v * v)) * rEff * 0.28;
      let px = st.x - st.nx * (v * rEff) + st.tx * arch;
      let py = st.y - st.ny * (v * rEff) + st.ty * arch;
      let d = ironCylinderDarkness(v, t);
      pts.push([px, py, constrain(map(d, 0.08, 0.95, 0.2, 1.45), 0.18, 1.48)]);
    }
    drawSplineSegment(pts, "burin_heavy", PALETTE.inkDark, 0.75);
  }
}

function engraveIronRingFinial(ring) {
  let rMid = (ring.rOuter + ring.rInner) * 0.5;
  let rTube = (ring.rOuter - ring.rInner) * 0.5;

  // Knock out ring body (keeping inner hole untouched so linen weave remains visible inside!)
  brush.noStroke();
  brush.wash(PALETTE.paper, 240);
  for (let a = 0; a < 360; a += 8) {
    let a1 = a, a2 = a + 9;
    brush.beginShape(0);
    brush.vertex(ring.cx + cos(a1) * ring.rInner, ring.cy + sin(a1) * ring.rInner);
    brush.vertex(ring.cx + cos(a1) * ring.rOuter, ring.cy + sin(a1) * ring.rOuter);
    brush.vertex(ring.cx + cos(a2) * ring.rOuter, ring.cy + sin(a2) * ring.rOuter);
    brush.vertex(ring.cx + cos(a2) * ring.rInner, ring.cy + sin(a2) * ring.rInner);
    brush.endShape(true);
  }
  brush.noWash();

  // 1. Concentric torus rings around the loop finial
  for (let u = -0.92; u <= 0.92; u += 0.22) {
    let rCur = rMid + u * rTube;
    let ringPts = [];
    for (let a = 0; a <= 360; a += 8) {
      let nx = cos(a) * u;
      let ny = sin(a) * u;
      let dotL = nx * (-LIGHT.x) + ny * (-LIGHT.y) + Math.sqrt(Math.max(0, 1 - u * u)) * 0.45;
      let d = constrain(map(dotL, -0.5, 0.85, 0.95, 0.12), 0.1, 0.98);
      if (d < 0.18 && cos(a + 135) > 0.5) {
        if (ringPts.length > 0) { drawSplineSegment(ringPts, "burin", PALETTE.inkDark, 0.65); ringPts = []; }
        continue;
      }
      ringPts.push([
        ring.cx + cos(a) * rCur,
        ring.cy + sin(a) * rCur,
        constrain(map(d, 0.12, 0.95, 0.22, 1.42), 0.2, 1.45)
      ]);
    }
    if (ringPts.length > 0) drawSplineSegment(ringPts, "burin", PALETTE.inkDark, 0.65);
  }

  // 2. Radial cross-sectional torus cuff lines
  for (let a = 0; a < 360; a += 7.5) {
    let cuff = [];
    for (let u = -1; u <= 1; u += 0.25) {
      let rCur = rMid + u * rTube;
      let arch = Math.sqrt(Math.max(0, 1 - u * u)) * rTube * 0.25;
      let px = ring.cx + cos(a) * rCur - sin(a) * arch;
      let py = ring.cy + sin(a) * rCur + cos(a) * arch;
      let shade = constrain(0.55 + 0.35 * cos(a - 45) + 0.25 * u, 0.18, 0.98);
      cuff.push([px, py, map(shade, 0.18, 0.98, 0.2, 1.42)]);
    }
    drawSplineSegment(cuff, "burin", PALETTE.inkBlack, 0.68);
  }

  // Outer & inner rim outlines
  brush.set("burin_heavy", PALETTE.inkBlack, 0.8);
  brush.circle(ring.cx, ring.cy, ring.rOuter, 0.02);
  brush.circle(ring.cx, ring.cy, ring.rInner, 0.02);
}

function engraveCrushingJaws() {
  // Engrave the main bodies of both jaws
  engraveIronSpine(nutcracker.upperJaw, 16, true);
  engraveIronSpine(nutcracker.lowerJaw, 16, true);

  // Recessed central fuller groove along each jaw face
  for (let jaw of [nutcracker.upperJaw, nutcracker.lowerJaw]) {
    let fullerPts = [];
    for (let t = 0.18; t <= 0.88; t += 0.04) {
      let st = evalSpine(jaw, t);
      fullerPts.push([st.x - st.nx * 2.5, st.y - st.ny * 2.5, 1.25]);
    }
    drawSplineSegment(fullerPts, "burin_heavy", PALETTE.inkBlack, 0.78);
  }

  // Interlocking pyramidal crushing teeth along the inner faces of both jaws
  let numTeeth = 7;
  for (let i = 0; i < numTeeth; i++) {
    let t = map(i, 0, numTeeth - 1, 0.24, 0.84);
    let tNext = map(i + 0.88, 0, numTeeth - 1, 0.24, 0.84);

    // Upper jaw tooth (pointing down-left toward lower jaw)
    let uA = evalSpine(nutcracker.upperJaw, t);
    let uB = evalSpine(nutcracker.upperJaw, tNext);
    let uMid = evalSpine(nutcracker.upperJaw, (t + tNext) * 0.5);
    let toothH = 8.5;
    let base1 = [uA.x - uA.nx * (uA.r - 2), uA.y - uA.ny * (uA.r - 2)];
    let base2 = [uB.x - uB.nx * (uB.r - 2), uB.y - uB.ny * (uB.r - 2)];
    let tip = [uMid.x - uMid.nx * (uMid.r + toothH), uMid.y - uMid.ny * (uMid.r + toothH)];
    drawIronTooth(base1, base2, tip, true);

    // Lower jaw tooth (pointing up-right toward upper jaw)
    let lA = evalSpine(nutcracker.lowerJaw, t);
    let lB = evalSpine(nutcracker.lowerJaw, tNext);
    let lMid = evalSpine(nutcracker.lowerJaw, (t + tNext) * 0.5);
    let lBase1 = [lA.x + lA.nx * (lA.r - 2), lA.y + lA.ny * (lA.r - 2)];
    let lBase2 = [lB.x + lB.nx * (lB.r - 2), lB.y + lB.ny * (lB.r - 2)];
    let lTip = [lMid.x + lMid.nx * (lMid.r + toothH), lMid.y + lMid.ny * (lMid.r + toothH)];
    drawIronTooth(lBase1, lBase2, lTip, false);
  }
}

function drawIronTooth(b1, b2, tip, isUpper) {
  let midBase = [(b1[0] + b2[0]) * 0.5, (b1[1] + b2[1]) * 0.5];

  // Knock out tooth triangle
  brush.noStroke();
  brush.wash(PALETTE.paper, 240);
  brush.beginShape(0);
  brush.vertex(b1[0], b1[1]);
  brush.vertex(tip[0], tip[1]);
  brush.vertex(b2[0], b2[1]);
  brush.endShape(true);
  brush.noWash();

  // Lit upper-left bevel facet (2 fine hairlines)
  brush.set("drypoint", PALETTE.inkMid, 0.58);
  for (let f = 0.25; f <= 0.75; f += 0.25) {
    let p1 = [lerp(b1[0], midBase[0], f), lerp(b1[1], midBase[1], f)];
    brush.line(p1[0], p1[1], tip[0], tip[1]);
  }

  // Shadowed lower-right bevel facet (dense dark burin lines)
  brush.set("burin_heavy", PALETTE.inkBlack, 0.78);
  for (let f = 0.1; f <= 1.0; f += 0.18) {
    let p2 = [lerp(midBase[0], b2[0], f), lerp(midBase[1], b2[1], f)];
    brush.line(p2[0], p2[1], tip[0], tip[1]);
  }

  // Sharp pyramid ridge & tooth outline
  brush.set("burin", PALETTE.inkBlack, 0.8);
  brush.line(b1[0], b1[1], tip[0], tip[1]);
  brush.line(tip[0], tip[1], b2[0], b2[1]);
  brush.line(midBase[0], midBase[1], tip[0], tip[1]);
}

function engravePivotKnuckle() {
  let px = nutcracker.pivot.x;
  let py = nutcracker.pivot.y;
  let rOut = nutcracker.pivot.rOuter;
  let rPin = nutcracker.pivot.rPin;

  // Knock out circular pivot boss
  brush.noStroke();
  brush.wash(PALETTE.paper, 245);
  brush.circle(px, py, rOut, 0.02);
  brush.noWash();

  // 1. Concentric turned iron rings on the boss face
  for (let r = rPin + 2.5; r <= rOut - 1.5; r += 2.2) {
    let pts = [];
    for (let a = 0; a <= 360; a += 8) {
      // Metallic sheen break at upper-left (-135 deg) and opposite (+45 deg)
      let sheen = Math.exp(-Math.pow(sin(a + 45), 2) * 8);
      let shadow = constrain(0.48 + 0.38 * cos(a - 45) - 0.42 * sheen, 0.08, 0.96);
      if (shadow < 0.15) {
        if (pts.length > 0) { drawSplineSegment(pts, "burin", PALETTE.inkDark, 0.65); pts = []; }
        continue;
      }
      pts.push([px + cos(a) * r, py + sin(a) * r, map(shadow, 0.14, 0.96, 0.2, 1.42)]);
    }
    if (pts.length > 0) drawSplineSegment(pts, "burin", PALETTE.inkDark, 0.65);
  }

  // 2. Radial burin cross-hatching on the shadow side of the knuckle boss
  brush.set("burin", PALETTE.inkBlack, 0.7);
  for (let a = -25; a <= 155; a += 6) {
    let r1 = rPin + 2;
    let r2 = rOut - 1;
    brush.line(px + cos(a) * r1, py + sin(a) * r1, px + cos(a) * r2, py + sin(a) * r2);
  }

  // 3. Domed central rivet pin (spherical dome with upper-left specular highlight)
  for (let r = 2.0; r <= rPin; r += 1.8) {
    let pinPts = [];
    for (let a = -45; a <= 195; a += 12) {
      let p = constrain(map(cos(a - 45), -0.6, 1, 0.25, 1.45), 0.22, 1.48);
      pinPts.push([px + cos(a) * r, py + sin(a) * r, p]);
    }
    drawSplineSegment(pinPts, "burin_heavy", PALETTE.inkBlack, 0.78);
  }

  // Rivet pin collar shadow & outer boss bevel
  brush.set("burin_heavy", PALETTE.inkBlack, 0.88);
  brush.circle(px, py, rPin + 0.8, 0.02);
  brush.circle(px, py, rOut, 0.02);
}

function engraveIronPitting() {
  // Fine stipple & burin nicks across the cast iron to capture antique sand-cast grain
  brush.set("stipple_graver", PALETTE.inkDark, 0.65);
  for (let spine of [nutcracker.upperJaw, nutcracker.lowerJaw, nutcracker.upperHandle, nutcracker.lowerHandle]) {
    for (let i = 0; i < 65; i++) {
      let t = random(0.05, 0.95);
      let v = random(-0.85, 0.85);
      let st = evalSpine(spine, t);
      let px = st.x - st.nx * (v * st.r * 0.88);
      let py = st.y - st.ny * (v * st.r * 0.88);
      brush.line(px, py, px + 1.2, py + 1.0);
    }
  }
}

// ============================================================================
// 6. MAIN CRACKED WALNUT (PIECE A: SHELL CRADLE, SEPTUM & BRAIN-LIKE KERNEL)
// ============================================================================

function getKernelGyri() {
  // 14 anatomical brain-like convolutions (gyri) arranged symmetrically in the two cotyledon hemispheres
  // u in [-115 (apex), +110 (base)], v in [-96 (upper-right hemisphere), +96 (lower-left hemisphere)]
  return [
    // Upper/Right Hemisphere (v < 0)
    { u1: -95, v1: -22, u2: -45, v2: -56, r: 22, h: 38 }, // Apical anterior lobe
    { u1: -45, v1: -56, u2: 18,  v2: -74, r: 25, h: 44 }, // Outer marginal gyrus 1
    { u1: 18,  v1: -74, u2: 78,  v2: -54, r: 24, h: 42 }, // Outer marginal gyrus 2
    { u1: 78,  v1: -54, u2: 96,  v2: -20, r: 21, h: 36 }, // Basal posterior lobe
    { u1: -58, v1: -24, u2: -8,  v2: -42, r: 21, h: 41 }, // Inner convoluted fold 1
    { u1: -8,  v1: -42, u2: 45,  v2: -34, r: 22, h: 43 }, // Central S-gyrus
    { u1: 35,  v1: -22, u2: 75,  v2: -32, r: 19, h: 37 }, // Inner basal fold

    // Lower/Left Hemisphere (v > 0)
    { u1: -95, v1: 22,  u2: -42, v2: 58,  r: 22, h: 37 }, // Apical anterior lobe
    { u1: -42, v1: 58,  u2: 20,  v2: 76,  r: 25, h: 43 }, // Outer marginal gyrus 1
    { u1: 20,  v1: 76,  u2: 80,  v2: 52,  r: 24, h: 40 }, // Outer marginal gyrus 2
    { u1: 80,  v1: 52,  u2: 96,  v2: 20,  r: 21, h: 35 }, // Basal posterior lobe
    { u1: -56, v1: 24,  u2: -5,  v2: 44,  r: 21, h: 40 }, // Inner convoluted fold 1
    { u1: -5,  v1: 44,  u2: 48,  v2: 35,  r: 22, h: 42 }, // Central S-gyrus
    { u1: 36,  v1: 22,  u2: 76,  v2: 32,  r: 19, h: 36 }  // Inner basal fold
  ];
}

// Evaluates 3D height, sulcus crevice depth, and local gyrus frame at kernel coords (u, v)
function evaluateKernelSurface(u, v, gyri) {
  let bestH = 0;
  let secondH = 0;
  let bestG = null;
  let bestT = 0;
  let bestDist = 1e9;

  // Secondary brain-like wriggling warps
  let wu = u + 4.8 * Math.sin(v * 0.095 + u * 0.045);
  let wv = v + 4.8 * Math.cos(u * 0.085 - v * 0.055);

  for (let g of gyri) {
    let vx = g.u2 - g.u1, vy = g.v2 - g.v1;
    let l2 = vx * vx + vy * vy;
    let t = l2 > 0 ? constrain(((wu - g.u1) * vx + (wv - g.v1) * vy) / l2, 0, 1) : 0;
    let px = g.u1 + t * vx;
    let py = g.v1 + t * vy;
    let d = dist(wu, wv, px, py);
    let rEff = g.r * (1.0 - 0.14 * Math.pow(2 * t - 1, 2));
    if (d < rEff * 1.35) {
      let normD = d / rEff;
      // Plump pillowy dome for each gyrus lobe
      let h = g.h * Math.max(0, 1.0 - normD * normD * 0.85) * Math.exp(-normD * normD * 0.35);
      // Secondary transverse dimples across each gyrus (like cerebral sulci)
      h += 3.2 * Math.sin(t * Math.PI * 4.5 + g.u1 * 0.1) * Math.max(0, 1 - normD);
      if (h > bestH) {
        secondH = bestH;
        bestH = h;
        bestG = g;
        bestT = t;
        bestDist = d;
      } else if (h > secondH) {
        secondH = h;
      }
    }
  }

  // Sulcus crevice indicator: spikes where two lobes meet or where height drops into a fold
  let sulcus = 0;
  if (bestH > 2 && secondH > 2) {
    sulcus = constrain(1.0 - Math.abs(bestH - secondH) / 11.5, 0, 1);
  }
  if (bestH < 14) {
    sulcus = Math.max(sulcus, constrain(map(bestH, 2, 14, 0.9, 0), 0, 0.9));
  }

  return { h: bestH, sulcus, bestG, bestT, bestDist };
}

// Septum half-width along central longitudinal axis u
function septumHalfWidth(u) {
  // Narrow papery partition at apex & base, swelling into the heart-shaped woody core at center
  let coreSwell = 21.0 * Math.exp(-Math.pow((u + 4) / 36, 2));
  let baseLine = 6.5 * Math.exp(-Math.pow(u / 118, 4));
  let jag = 1.8 * Math.sin(u * 0.22) + 1.2 * Math.cos(u * 0.37);
  return coreSwell + baseLine + jag;
}

function drawMainCrackedWalnut() {
  let gyri = getKernelGyri();

  // 1. Knock out main walnut footprint with clean rag paper
  brush.noStroke();
  brush.wash(PALETTE.paper, 246);
  brush.beginShape(0.25);
  for (let a = 0; a < 360; a += 4) {
    let u = cos(a) * WALNUT_A.a;
    let v = sin(a) * WALNUT_A.b;
    let f = walnutARadiusFactor(u, v);
    let wp = fromWalnutA(u / f, v / f);
    brush.vertex(wp.x, wp.y);
  }
  brush.endShape(true);
  brush.noWash();

  // Faint plate-tone shadow glaze inside the deep recess between shell rim and kernel
  brush.fillBleed(0.18, "in");
  brush.fill(PALETTE.plateUmber, 18);
  brush.beginShape(0.3);
  for (let a = 0; a < 360; a += 10) {
    let u = cos(a) * WALNUT_A.a * 0.84;
    let v = sin(a) * WALNUT_A.b * 0.84;
    let wp = fromWalnutA(u, v);
    brush.vertex(wp.x, wp.y);
  }
  brush.endShape(true);
  brush.noFill();

  // 2. SYSTEM A: Outer Shell Cradle & Fractured Woody Endocarp Rim
  drawMainWalnutShellRim();

  // 3. SYSTEM B: Brain-Like Kernel Lobes (Curvilinear Topography & Sulcus Engraving)
  drawBrainLikeKernelLobes(gyri);

  // 4. SYSTEM C: The Woody Septum (Fibrous Radiator Engraving & Torn Papery Core)
  drawWoodySeptum();
}

function drawMainWalnutShellRim() {
  // The shell rim surrounds the kernel cavity (f in [0.78, 1.0])
  // Additionally, on the lower-left / outer cradle side (v > 0), the curved exterior shell cradle is visible!

  // 1. Radial cross-grain lines across the thick fractured shell wall (f in [0.77, 0.96])
  for (let a = 0; a < 360; a += 1.4) {
    let dirU = cos(a) * WALNUT_A.a;
    let dirV = sin(a) * WALNUT_A.b;
    let fEdge = walnutARadiusFactor(dirU, dirV);
    let uOuter = dirU / fEdge;
    let vOuter = dirV / fEdge;

    // Inner cavity boundary has jagged conchoidal fracture steps
    let innerRatio = 0.79 + 0.028 * sin(a * 8 + 15) + 0.018 * cos(a * 15 - 30);
    // Thicker apical point at u < 0 (a near 180 deg) and basal pad at a near 0 deg
    if (Math.abs(sin(a)) < 0.38) innerRatio -= 0.045 * (1 - Math.abs(sin(a)) / 0.38);

    // On the lower-left side (a in [20, 160]), extend outer boundary to show the curved outer shell cradle
    let outerMult = (a > 15 && a < 165) ? 1.0 + 0.08 * Math.sin(((a - 15) / 150) * Math.PI) : 1.0;

    let wallPts = [];
    for (let s = innerRatio; s <= 0.96; s += 0.045) {
      let u = uOuter * s;
      let v = vOuter * s;
      let wp = fromWalnutA(u, v);
      // Fracture wall shading: brighter on upper-left rim, darker on lower-right rim & inner edge
      let rimLight = constrain(0.32 + 0.38 * cos(a - 45) + 0.16 * sin(a * 11 + s * 40), 0.12, 0.95);
      wallPts.push([wp.x, wp.y, map(rimLight, 0.12, 0.95, 0.18, 1.32)]);
    }
    drawSplineSegment(wallPts, "drypoint", PALETTE.inkMid, 0.56);

    // If outer cradle is visible (lower-left curve), engrave vermiculated shell cradle lines
    if (outerMult > 1.005) {
      let cradlePts = [];
      for (let s = 0.95; s <= outerMult; s += 0.025) {
        let wp = fromWalnutA(uOuter * s, vOuter * s);
        cradlePts.push([wp.x, wp.y, 1.25]);
      }
      drawSplineSegment(cradlePts, "burin", PALETTE.inkDark, 0.72);
    }
  }

  // 2. Concentric growth-lamella rings along the fractured shell wall
  for (let ring = 0; ring < 5; ring++) {
    let sBase = map(ring, 0, 4, 0.80, 0.955);
    let ringPts = [];
    for (let a = 0; a <= 360; a += 3) {
      let dirU = cos(a) * WALNUT_A.a;
      let dirV = sin(a) * WALNUT_A.b;
      let fEdge = walnutARadiusFactor(dirU, dirV);
      let s = sBase + 0.018 * sin(a * 8 + ring * 25);
      let wp = fromWalnutA((dirU / fEdge) * s, (dirV / fEdge) * s);
      let d = constrain(0.35 + 0.42 * cos(a - 45), 0.14, 0.96);
      if (d < 0.22 && ring > 0 && ring < 4 && random() < 0.35) {
        if (ringPts.length > 0) { drawSplineSegment(ringPts, "burin", PALETTE.inkMid, 0.62); ringPts = []; }
        continue;
      }
      ringPts.push([wp.x, wp.y, map(d, 0.14, 0.96, 0.2, 1.38)]);
    }
    if (ringPts.length > 0) drawSplineSegment(ringPts, "burin", PALETTE.inkMid, 0.62);
  }

  // 3. Deep dark undercut shadow inside the shell cavity rim (where the kernel tucks under the shell wall)
  for (let pass = 0; pass < 3; pass++) {
    let cavityPts = [];
    for (let a = 0; a <= 360; a += 3) {
      let dirU = cos(a) * WALNUT_A.a;
      let dirV = sin(a) * WALNUT_A.b;
      let fEdge = walnutARadiusFactor(dirU, dirV);
      let innerRatio = 0.785 - pass * 0.014 + 0.028 * sin(a * 8 + 15) + 0.018 * cos(a * 15 - 30);
      if (Math.abs(sin(a)) < 0.38) innerRatio -= 0.045 * (1 - Math.abs(sin(a)) / 0.38);
      let wp = fromWalnutA((dirU / fEdge) * innerRatio, (dirV / fEdge) * innerRatio);
      cavityPts.push([wp.x, wp.y, 1.35 - pass * 0.25]);
    }
    drawSplineSegment(cavityPts, pass === 0 ? "burin_heavy" : "burin", PALETTE.inkBlack, 0.78 - pass * 0.1);
  }

  // 4. Outer jagged shell perimeter contour
  let outerPts = [];
  for (let a = 0; a <= 360; a += 3) {
    let dirU = cos(a) * WALNUT_A.a;
    let dirV = sin(a) * WALNUT_A.b;
    let fEdge = walnutARadiusFactor(dirU, dirV);
    let outerMult = (a > 15 && a < 165) ? 1.0 + 0.08 * Math.sin(((a - 15) / 150) * Math.PI) : 1.0;
    let wp = fromWalnutA((dirU / fEdge) * outerMult, (dirV / fEdge) * outerMult);
    let shade = constrain(0.45 + 0.48 * cos(a - 45), 0.25, 1.45);
    outerPts.push([wp.x, wp.y, shade]);
  }
  drawSplineSegment(outerPts, "burin_heavy", PALETTE.inkBlack, 0.84);
}

function drawBrainLikeKernelLobes(gyri) {
  // The kernel occupies walnutARadiusFactor(u, v) < 0.78 and |v| > septumHalfWidth(u)

  // PASS 1: Individual Gyrus Cuff Contours (Curvilinear parallel rings wrapping over each brain-like lobe!)
  for (let g of gyri) {
    let vx = g.u2 - g.u1, vy = g.v2 - g.v1;
    let len = Math.sqrt(vx * vx + vy * vy) || 1;
    let tx = vx / len, ty = vy / len;
    let nx = -ty, ny = tx;

    // A) Transverse contour rings wrapping across the convex pillow of each gyrus
    let numRings = Math.floor(len / 2.2);
    for (let i = 0; i <= numRings; i++) {
      let t = i / numRings;
      let cu = lerp(g.u1, g.u2, t);
      let cv = lerp(g.v1, g.v2, t);
      let rEff = g.r * (1.0 - 0.14 * Math.pow(2 * t - 1, 2));

      let ringLight = [];
      let ringDark = [];

      for (let k = -10; k <= 10; k++) {
        let s = k / 10; // across the lobe width [-1, 1]
        let u = cu + nx * s * rEff;
        let v = cv + ny * s * rEff;

        // Clip to kernel cavity and outside the central woody septum
        if (walnutARadiusFactor(u, v) > 0.775 || Math.abs(v) < septumHalfWidth(u) - 1.0) {
          if (ringLight.length > 0) { drawSplineSegment(ringLight, "drypoint", PALETTE.inkMid, 0.56); ringLight = []; }
          if (ringDark.length > 0) { drawSplineSegment(ringDark, "burin", PALETTE.inkDark, 0.68); ringDark = []; }
          continue;
        }

        let surf = evaluateKernelSurface(u, v, gyri);
        // 3D normal & lighting on the gyrus
        let eps = 1.6;
        let hu = (evaluateKernelSurface(u + eps, v, gyri).h - surf.h) / eps;
        let hv = (evaluateKernelSurface(u, v + eps, gyri).h - surf.h) / eps;

        let c = cos(WALNUT_A.angle), sn = sin(WALNUT_A.angle);
        let gx = hu * c - hv * sn;
        let gy = hu * sn + hv * c;
        let inv = 1.0 / Math.sqrt(gx * gx + gy * gy + 1.0);
        let dotL = (gx * LIGHT.x + gy * LIGHT.y + LIGHT.z) * inv;

        // Sulcus occlusion + slope shading + cavity rim shadow
        let rimProx = constrain(map(walnutARadiusFactor(u, v), 0.66, 0.78, 0, 0.48), 0, 0.5);
        let septProx = constrain(map(Math.abs(v) - septumHalfWidth(u), 0, 9, 0.42, 0), 0, 0.45);
        let dark = constrain(
          map(dotL, -0.45, 0.88, 0.85, 0.02) + surf.sulcus * 0.58 + rimProx + septProx,
          0.02,
          0.98
        );

        // Curvilinear 3D arch displacement so the line visibly wraps over the rounded gyrus
        let arch = Math.sqrt(Math.max(0, 1 - s * s)) * rEff * 0.26;
        let wp = fromWalnutA(u - tx * arch * 0.6, v - ty * arch * 0.6 - surf.h * 0.14);

        // Leave waxy specular highlights open on upper-left gyrus crests!
        if (dark < 0.13) {
          if (ringLight.length > 0) { drawSplineSegment(ringLight, "drypoint", PALETTE.inkMid, 0.56); ringLight = []; }
          if (ringDark.length > 0) { drawSplineSegment(ringDark, "burin", PALETTE.inkDark, 0.68); ringDark = []; }
          continue;
        }

        ringLight.push([wp.x, wp.y, constrain(map(dark, 0.12, 0.75, 0.16, 1.25), 0.15, 1.3)]);

        if (dark > 0.46) {
          ringDark.push([wp.x + 0.35, wp.y + 0.35, constrain(map(dark, 0.46, 0.96, 0.25, 1.42), 0.22, 1.46)]);
        } else if (ringDark.length > 0) {
          drawSplineSegment(ringDark, "burin", PALETTE.inkDark, 0.68);
          ringDark = [];
        }
      }
      if (ringLight.length > 0) drawSplineSegment(ringLight, "drypoint", PALETTE.inkMid, 0.56);
      if (ringDark.length > 0) drawSplineSegment(ringDark, "burin", PALETTE.inkDark, 0.68);
    }

    // B) Longitudinal contour lines flowing along the spine of each gyrus (creating lozenge cross-hatching)
    for (let k = -6; k <= 6; k++) {
      let s = k / 6.5;
      let longPts = [];
      for (let t = 0; t <= 1.001; t += 0.06) {
        let cu = lerp(g.u1, g.u2, t);
        let cv = lerp(g.v1, g.v2, t);
        let rEff = g.r * (1.0 - 0.14 * Math.pow(2 * t - 1, 2));
        let u = cu + nx * s * rEff;
        let v = cv + ny * s * rEff;

        if (walnutARadiusFactor(u, v) > 0.775 || Math.abs(v) < septumHalfWidth(u) - 1.0) {
          if (longPts.length > 0) { drawSplineSegment(longPts, "burin", PALETTE.inkDark, 0.62); longPts = []; }
          continue;
        }

        let surf = evaluateKernelSurface(u, v, gyri);
        let shade = constrain(0.32 + 0.35 * s + surf.sulcus * 0.55 + (u + v) * 0.0025, 0.05, 0.98);
        if (shade < 0.36) {
          if (longPts.length > 0) { drawSplineSegment(longPts, "burin", PALETTE.inkDark, 0.62); longPts = []; }
          continue;
        }
        let wp = fromWalnutA(u, v - surf.h * 0.14);
        longPts.push([wp.x, wp.y, map(shade, 0.35, 0.98, 0.18, 1.38)]);
      }
      if (longPts.length > 0) drawSplineSegment(longPts, "burin", PALETTE.inkDark, 0.62);
    }
  }

  // PASS 2: Deep Sinuous Sulcus Trenches (Cerebral fissures between the kernel lobes)
  for (let v = -92; v <= 92; v += 2.2) {
    let sulcusPts = [];
    for (let u = -112; u <= 110; u += 2.4) {
      if (walnutARadiusFactor(u, v) > 0.77 || Math.abs(v) < septumHalfWidth(u)) {
        if (sulcusPts.length > 0) { drawSplineSegment(sulcusPts, "burin_heavy", PALETTE.inkBlack, 0.78); sulcusPts = []; }
        continue;
      }
      let surf = evaluateKernelSurface(u, v, gyri);
      if (surf.sulcus > 0.52) {
        let wp = fromWalnutA(u, v - surf.h * 0.12);
        sulcusPts.push([wp.x, wp.y, map(surf.sulcus, 0.52, 1.0, 0.35, 1.48)]);
      } else if (sulcusPts.length > 0) {
        drawSplineSegment(sulcusPts, "burin_heavy", PALETTE.inkBlack, 0.78);
        sulcusPts = [];
      }
    }
    if (sulcusPts.length > 0) drawSplineSegment(sulcusPts, "burin_heavy", PALETTE.inkBlack, 0.78);
  }

  // PASS 3: Delicate pellicle veins & stipple dots on the glistening kernel lobes
  brush.set("stipple_graver", PALETTE.inkMid, 0.55);
  for (let i = 0; i < 320; i++) {
    let u = random(-105, 102);
    let v = random(-88, 88);
    if (walnutARadiusFactor(u, v) > 0.75 || Math.abs(v) < septumHalfWidth(u) + 2) continue;
    let surf = evaluateKernelSurface(u, v, gyri);
    if (surf.h > 18) {
      let wp = fromWalnutA(u, v - surf.h * 0.14);
      brush.line(wp.x, wp.y, wp.x + 0.9, wp.y + 0.8);
    }
  }
}

function drawWoodySeptum() {
  // The woody septum runs along u in [-112, 108], v in [-septumHalfWidth(u), +septumHalfWidth(u)]
  // 1. Knock out septum ribbon with crisp rag paper so it separates cleanly from the two kernel hemispheres
  brush.noStroke();
  brush.wash(PALETTE.paper, 245);
  brush.beginShape(0.2);
  for (let u = -112; u <= 108; u += 4) {
    let w = septumHalfWidth(u);
    let wp = fromWalnutA(u, -w);
    brush.vertex(wp.x, wp.y);
  }
  for (let u = 108; u >= -112; u -= 4) {
    let w = septumHalfWidth(u);
    let wp = fromWalnutA(u, w);
    brush.vertex(wp.x, wp.y);
  }
  brush.endShape(true);
  brush.noWash();

  // 2. SEPTUM HATCHING SYSTEM: Fine radiating fibrous hairlines fanning outward from the central core
  let numFibers = 115;
  for (let i = 0; i <= numFibers; i++) {
    let u = map(i, 0, numFibers, -110, 106);
    let w = septumHalfWidth(u);

    // Fibrous radiator strokes fanning from the central ridge (v = 0) to the torn septum margins (v = +-w)
    for (let side of [-1, 1]) {
      let fiberPts = [];
      for (let s = 0; s <= 1.001; s += 0.2) {
        let uCur = u + side * s * (u * 0.08 + 4.5 * Math.sin(u * 0.05));
        let vCur = side * s * w;
        // 3D arch of the thin vertical septum plate
        let zSept = (1.0 - s * 0.45) * 28;
        let wp = fromWalnutA(uCur, vCur - zSept * 0.14);
        // Shading: bright papery crest along the top-left edge, shadowed along the base where it meets the kernel
        let shade = constrain(0.22 + 0.48 * s + (side > 0 ? 0.18 : -0.05) + 0.12 * sin(u * 0.35), 0.12, 0.94);
        fiberPts.push([wp.x, wp.y, map(shade, 0.12, 0.94, 0.16, 1.28)]);
      }
      drawSplineSegment(fiberPts, "needle", PALETTE.inkMid, 0.55);
    }
  }

  // 3. Longitudinal vascular bundle striations & central split fissure along v ≈ 0
  for (let frac of [-0.65, -0.35, -0.12, 0.12, 0.38, 0.68]) {
    let longPts = [];
    for (let u = -108; u <= 104; u += 3.5) {
      let w = septumHalfWidth(u);
      let v = frac * w;
      let zSept = (1.0 - Math.abs(frac) * 0.45) * 28;
      let wp = fromWalnutA(u, v - zSept * 0.14);
      let p = Math.abs(frac) < 0.2 ? 1.15 : 0.55;
      longPts.push([wp.x, wp.y, p]);
    }
    drawSplineSegment(
      longPts,
      Math.abs(frac) < 0.2 ? "burin" : "drypoint",
      Math.abs(frac) < 0.2 ? PALETTE.inkDark : PALETTE.inkMid,
      0.62
    );
  }

  // 4. Deckle-edged torn septum border & deep occlusion shadow where septum meets the kernel hemispheres
  for (let side of [-1, 1]) {
    let edgePts = [];
    let shadowPts = [];
    for (let u = -110; u <= 106; u += 3) {
      let w = septumHalfWidth(u);
      let wpEdge = fromWalnutA(u, side * w - 3.5);
      let wpShad = fromWalnutA(u, side * (w + 1.8));
      edgePts.push([wpEdge.x, wpEdge.y, side > 0 ? 1.25 : 0.72]);
      shadowPts.push([wpShad.x, wpShad.y, 1.38]);
    }
    drawSplineSegment(edgePts, "burin", PALETTE.inkDark, 0.68);
    drawSplineSegment(shadowPts, "burin_heavy", PALETTE.inkBlack, 0.8);
  }
}

// ============================================================================
// 7. FINAL INTAGLIO ACCENTS & DEEP OCCLUSION BURIN CUTS
// ============================================================================

function drawFinalEngravingAccents() {
  // 1. Deep contact shadow cuts directly under the main walnut, secondary shell cap, and nutcracker
  brush.set("burin_heavy", PALETTE.inkBlack, 0.9);

  // Contact shadow crescent under Main Walnut (Piece A)
  for (let pass = 0; pass < 4; pass++) {
    let cPts = [];
    for (let a = -35; a <= 145; a += 4) {
      let dirU = cos(a) * WALNUT_A.a;
      let dirV = sin(a) * WALNUT_A.b;
      let fEdge = walnutARadiusFactor(dirU, dirV);
      let outerMult = (a > 15 && a < 165) ? 1.0 + 0.08 * Math.sin(((a - 15) / 150) * Math.PI) : 1.0;
      let wp = fromWalnutA((dirU / fEdge) * outerMult, (dirV / fEdge) * outerMult);
      cPts.push([wp.x + pass * 1.4, wp.y + pass * 1.2, 1.45 - pass * 0.22]);
    }
    drawSplineSegment(cPts, "burin_heavy", PALETTE.inkBlack, 0.88 - pass * 0.12);
  }

  // Contact shadow crescent under Secondary Shell Cap (Piece B)
  for (let pass = 0; pass < 3; pass++) {
    let bPts = [];
    for (let a = -25; a <= 155; a += 5) {
      let dirU = cos(a) * WALNUT_B.a;
      let dirV = sin(a) * WALNUT_B.b;
      let fEdge = walnutBRadiusFactor(dirU, dirV);
      let wp = fromWalnutB(dirU / fEdge, dirV / fEdge);
      bPts.push([wp.x + pass * 1.3, wp.y + pass * 1.1, 1.42 - pass * 0.25]);
    }
    drawSplineSegment(bPts, "burin_heavy", PALETTE.inkBlack, 0.85 - pass * 0.12);
  }

  // 2. Printmaker stipple & flick work in the cast shadow penumbras on the linen
  brush.set("stipple_graver", PALETTE.inkDark, 0.68);
  for (let i = 0; i < 420; i++) {
    let x = random(220, 980);
    let y = random(280, 960);
    if (inForegroundObject(x, y, 2)) continue;
    let s = computeCastShadow(x, y);
    if (s > 0.25) {
      brush.line(x, y, x + 1.4, y + 1.1);
    }
  }

  // 3. Delicate engraved plate inscription in the lower plate margin (nineteenth-century natural history style)
  drawPlateInscriptions();
}

