function setStroke(name, col, w = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(name, col, w);
}

function setWash(col, op = 255) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, op);
}

function setWatercolor(col, op = 80, bleed = 0.25, tex = 0.35, border = 0.2) {
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.fill(col, op);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
}

