function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.casingDark);

  // 1. Junction box outer rim & clean off-white enamel plate
  drawBoxAndEnamelPlate();

  // 2. Printed schematic / transit-map markings on the enamel plate
  drawEnamelDiagramMarkings();

  // 3. Cable entry glands (knockouts) on the perimeter walls
  drawCableGlands();

  // 4. Terminal block bases (shadows & housings before wires dock)
  drawTerminalHousingsBase();

  // 5. Build and render all octilinear wires + scuffed PVC sheen + copper strands
  const wires = getWireDefinitions();
  drawAllWiresAndCopper(wires);

  // 6. Cable tie-down P-clips anchoring parallel wire trunks to the backplate
  drawCableClips();

  // 7. Brass screw terminals ("station stops") & dusty screw heads clamping the copper
  drawAllBrassTerminals();

  // 8. Corner box mounting lugs with heavy dusty screw heads & final surface patina
  drawCornerMountingScrews();
  drawFinalSurfaceRealism();

  noLoop();
}

