}

function drawMicroGlyphs(x, y, w, h) {
  setStroke("rotring", PAL.inkSoft, 0.42);
  let cx = x;
  while (cx < x + w) {
    let gw = random(3, 6);
    if (random() < 0.8) {
      brush.line(cx, y, cx + gw * 0.7, y);
      brush.line(cx, y + h, cx + gw, y + h);
      brush.line(cx, y, cx, y + h);
      if (random() < 0.5) brush.line(cx + gw * 0.7, y, cx + gw * 0.7, y + h);
    }
    cx += gw + 3;
  }
}

