// =============================================================================
// WIRE GEOMETRY HELPERS & MULTI-PASS RENDERER
// =============================================================================
function trimPolyline(pts, trimStart, trimEnd) {
  let out = pts.map(p => [p[0], p[1]]);
  if (trimStart > 0 && out.length >= 2) {
    let dx = out[1][0] - out[0][0];
    let dy = out[1][1] - out[0][1];
    let d = Math.hypot(dx, dy);
    if (d > trimStart + 4) {
      out[0] = [out[0][0] + (dx / d) * trimStart, out[0][1] + (dy / d) * trimStart];
    }
  }
  if (trimEnd > 0 && out.length >= 2) {
    let n = out.length - 1;
    let dx = out[n - 1][0] - out[n][0];
    let dy = out[n - 1][1] - out[n][1];
    let d = Math.hypot(dx, dy);
    if (d > trimEnd + 4) {
      out[n] = [out[n][0] + (dx / d) * trimEnd, out[n][1] + (dy / d) * trimEnd];
    }
  }
  return out;
}

// Bevels vertices with a tight radius while keeping straight segments 100% octilinear
function roundOctilinearCorners(pts, radius = 10) {
  if (pts.length <= 2) return pts;
  let res = [pts[0]];
  for (let i = 1; i < pts.length - 1; i++) {
    let p0 = pts[i - 1];
    let p1 = pts[i];
    let p2 = pts[i + 1];
    let v1x = p0[0] - p1[0], v1y = p0[1] - p1[1];
    let v2x = p2[0] - p1[0], v2y = p2[1] - p1[1];
    let len1 = Math.hypot(v1x, v1y);
    let len2 = Math.hypot(v2x, v2y);
    let r = Math.min(radius, len1 * 0.35, len2 * 0.35);
    if (r < 2) {
      res.push(p1);
      continue;
    }
    let a = [p1[0] + (v1x / len1) * r, p1[1] + (v1y / len1) * r];
    let b = [p1[0] + (v2x / len2) * r, p1[1] + (v2y / len2) * r];
    let m = [
      p1[0] + ((v1x / len1 + v2x / len2) * r) * 0.36,
      p1[1] + ((v1y / len1 + v2y / len2) * r) * 0.36
    ];
    res.push(a, m, b);
  }
  res.push(pts[pts.length - 1]);
  return res;
}

function offsetPolyline(pts, offsetDist) {
  let out = [];
  for (let i = 0; i < pts.length; i++) {
    let nx = 0, ny = 0;
    if (i < pts.length - 1) {
      let dx = pts[i + 1][0] - pts[i][0];
      let dy = pts[i + 1][1] - pts[i][1];
      let d = Math.hypot(dx, dy) || 1;
      nx += -dy / d;
      ny += dx / d;
    }
    if (i > 0) {
      let dx = pts[i][0] - pts[i - 1][0];
      let dy = pts[i][1] - pts[i - 1][1];
      let d = Math.hypot(dx, dy) || 1;
      nx += -dy / d;
      ny += dx / d;
    }
    let nd = Math.hypot(nx, ny) || 1;
    out.push([pts[i][0] + (nx / nd) * offsetDist, pts[i][1] + (ny / nd) * offsetDist]);
  }
  return out;
}

function drawPolylineSegments(pts) {
  for (let i = 0; i < pts.length - 1; i++) {
    brush.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
  }
}

function drawAllWiresAndCopper(wires) {
  const stripLen = 23;

  // First draw all exposed copper strand bundles at stripped wire ends
  for (let w of wires) {
    let pts = w.pts;
    if (w.stripStart && pts.length >= 2) {
      let pTerm = pts[0];
      let pNext = pts[1];
      let dx = pNext[0] - pTerm[0], dy = pNext[1] - pTerm[1];
      let d = Math.hypot(dx, dy) || 1;
      let pCut = [pTerm[0] + (dx / d) * stripLen, pTerm[1] + (dy / d) * stripLen];
      drawExposedCopperStrands(pCut[0], pCut[1], pTerm[0], pTerm[1]);
    }
    if (w.stripEnd && pts.length >= 2) {
      let n = pts.length - 1;
      let pTerm = pts[n];
      let pPrev = pts[n - 1];
      let dx = pPrev[0] - pTerm[0], dy = pPrev[1] - pTerm[1];
      let d = Math.hypot(dx, dy) || 1;
      let pCut = [pTerm[0] + (dx / d) * stripLen, pTerm[1] + (dy / d) * stripLen];
      drawExposedCopperStrands(pCut[0], pCut[1], pTerm[0], pTerm[1]);
    }
  }

  // Next draw each insulated PVC wire with shadow, marker body, shading, scuffs, sheen & rotring edges
  for (let w of wires) {
    let trimmed = trimPolyline(w.pts, w.stripStart ? stripLen : 0, w.stripEnd ? stripLen : 0);
    let smoothPts = roundOctilinearCorners(trimmed, 11);
    drawSingleInsulatedWire(smoothPts, w.col, w.stripStart, w.stripEnd);
  }
}

// =============================================================================
// HYPERREAL EXPOSED TWISTED COPPER STRANDS
// =============================================================================
function drawExposedCopperStrands(xCut, yCut, xTerm, yTerm) {
  let dx = xTerm - xCut;
  let dy = yTerm - yCut;
  let len = Math.hypot(dx, dy) || 1;
  let ux = dx / len, uy = dy / len;
  let nx = -uy, ny = ux;

  // Cast shadow of bare copper bundle onto terminal channel / backplate
  setStroke("wire_marker", PAL.enamelDeepShadow, 0.7);
  brush.line(xCut + 2.5, yCut + 3, xTerm + 2.5, yTerm + 3);

  // Dark oxidized copper core mass
  setStroke("rotring", PAL.copperDark, 2.2);
  brush.line(xCut, yCut, xTerm + ux * 3, yTerm + uy * 3);

  // Individual twisted fine copper strands fanning out & clamping under screw washer
  const numStrands = 11;
  for (let i = 0; i < numStrands; i++) {
    let t = (i / (numStrands - 1)) - 0.5; // -0.5 .. 0.5
    let startSpread = t * 7.2;
    let midSpread = t * 9.5 + sin(i * 68) * 1.6;
    let endSpread = t * 11.5 + cos(i * 53) * 2.0;

    // Slight overshoot past screw center (protruding twisted tips)
    let over = 2.5 + (i % 3) * 1.4;
    let sx = xCut + nx * startSpread;
    let sy = yCut + ny * startSpread;
    let mx = xCut + ux * (len * 0.52) + nx * midSpread;
    let my = yCut + uy * (len * 0.52) + ny * midSpread;
    let ex = xTerm + ux * over + nx * endSpread;
    let ey = yTerm + uy * over + ny * endSpread;

    let col = (i % 3 === 0) ? PAL.copperBright : (i % 2 === 0 ? PAL.copperMid : PAL.copperDark);
    setStroke("copper_filament", col, 0.85);
    brush.line(sx, sy, mx, my);
    brush.line(mx, my, ex, ey);

    // Helical twist cross-strands & fiery orange-gold reflections
    if (i % 2 === 0) {
      setStroke("rotring", PAL.copperGlint, 0.45);
      brush.line(
        xCut + ux * (len * 0.2) + nx * (startSpread * 0.9),
        yCut + uy * (len * 0.2) + ny * (startSpread * 0.9),
        xCut + ux * (len * 0.68) + nx * (midSpread * 0.65),
        yCut + uy * (len * 0.68) + ny * (midSpread * 0.65)
      );
    }
  }

  // Razor-sharp white-gold metallic specular pinpoints on top copper filaments & cut tips
  setStroke("rotring", PAL.copperSpec, 0.42);
  for (let k = -2; k <= 2; k++) {
    let sp = k * 2.1;
    brush.line(
      xCut + ux * 3 + nx * (sp - 0.7),
      yCut + uy * 3 + ny * (sp - 0.7),
      xCut + ux * 10 + nx * (sp + 0.8),
      yCut + uy * 10 + ny * (sp + 0.8)
    );
    // Glint at protruding wire tip
    let tipX = xTerm + ux * 3.5 + nx * (sp * 1.3);
    let tipY = yTerm + uy * 3.5 + ny * (sp * 1.3);
    brush.line(tipX - ux * 2, tipY - uy * 2, tipX, tipY);
  }
}

// =============================================================================
// HYPERREAL INSULATED PVC WIRE (MARKER BASE + SCUFFED SHEEN + ROTRING PEN)
// =============================================================================
function drawSingleInsulatedWire(pts, colKey, stripStart, stripEnd) {
  let c = PAL.wires[colKey];

  // 1. Cast shadow on enamel plate (offset +4.2, +5.0)
  let shadowPts = pts.map(p => [p[0] + 4.2, p[1] + 5.0]);
  setStroke("wire_marker", PAL.enamelShadow, 1.35);
  drawPolylineSegments(shadowPts);
  setStroke("wire_marker", PAL.enamelDeepShadow, 0.85);
  let tightShadowPts = pts.map(p => [p[0] + 2.2, p[1] + 2.8]);
  drawPolylineSegments(tightShadowPts);

  // 2. Flat marker PVC base cylinder
  setStroke("wire_marker", c.base, 1.45);
  drawPolylineSegments(pts);

  // 3. Cylindrical core shade along bottom-right edge
  let shadePts = offsetPolyline(pts, 2.5);
  setStroke("wire_marker", c.shade, 0.62);
  drawPolylineSegments(shadePts);

  // Mid-tone crown along center-top
  let midPts = offsetPolyline(pts, -0.9);
  setStroke("wire_marker", c.mid, 0.82);
  drawPolylineSegments(midPts);

  // 4. Special Green-Yellow protective earth stripes
  if (colKey === "GY") {
    drawGreenYellowStripes(pts, c);
  }

  // 5. Scuffed PVC sheen & bend stress highlights along upper-left ridge
  let sheenPts = offsetPolyline(pts, -2.3);
  setStroke("pvc_sheen", c.sheen, 0.95);
  drawPolylineSegments(sheenPts);

  // Intermittent high-gloss specular glints & scuffed abrasion marks along straight segments
  for (let i = 0; i < pts.length - 1; i++) {
    let x1 = pts[i][0], y1 = pts[i][1];
    let x2 = pts[i + 1][0], y2 = pts[i + 1][1];
    let dx = x2 - x1, dy = y2 - y1;
    let segLen = Math.hypot(dx, dy);
    if (segLen < 8) continue;
    let ux = dx / segLen, uy = dy / segLen;
    let nx = -uy, ny = ux;

    // Bright specular highlight at bend knuckles (stretched PVC sheen)
    setStroke("rotring", c.spec, 0.55);
    let bLen = Math.min(14, segLen * 0.35);
    brush.line(
      x1 + ux * 2 - nx * 2.3,
      y1 + uy * 2 - ny * 2.3,
      x1 + ux * bLen - nx * 2.3,
      y1 + uy * bLen - ny * 2.3
    );

    // Broken waxy specular ribbons along long straight runs
    if (segLen > 45) {
      for (let d = 18; d < segLen - 18; d += 28) {
        let gl = random(9, 18);
        setStroke("cpencil", c.spec, 0.75);
        brush.line(
          x1 + ux * d - nx * 2.2,
          y1 + uy * d - ny * 2.2,
          x1 + ux * Math.min(segLen - 8, d + gl) - nx * 2.2,
          y1 + uy * Math.min(segLen - 8, d + gl) - ny * 2.2
        );

        // Transverse PVC scuffs & plier/conduit rub marks
        if (random() < 0.65) {
          let sd = d + random(-6, 12);
          let sx = x1 + ux * sd;
          let sy = y1 + uy * sd;
          setStroke("2H", "#b8aa96", 0.55);
          brush.line(sx - nx * 4.2 - ux * 2, sy - ny * 4.2 - uy * 2, sx + nx * 3.5 + ux * 2, sy + ny * 3.5 + uy * 2);
          setStroke("rotring", "#3d342d", 0.32);
          brush.line(sx - nx * 2.5 + ux * 1, sy - ny * 2.5 + uy * 1, sx + nx * 3.8 - ux * 1, sy + ny * 3.8 - uy * 1);
        }

        // Tiny stamped factory spec dashes along wire center (e.g. H07V-U 2.5mm²)
        if (d % 56 === 18 && segLen > 95) {
          setStroke("rotring", colKey === "BK" || colKey === "BL" ? "#b8b0a4" : "#38302a", 0.3);
          for (let m = 0; m < 14; m += 3.5) {
            brush.line(
              x1 + ux * (d + m) + nx * 0.6,
              y1 + uy * (d + m) + ny * 0.6,
              x1 + ux * (d + m + 1.8) + nx * 0.6,
              y1 + uy * (d + m + 1.8) + ny * 0.6
            );
          }
        }
      }
    }
  }

  // 6. Crisp technical pen (Rotring) outer contours on both sides of the PVC jacket
  let edgeLeft = offsetPolyline(pts, -5.8);
  let edgeRight = offsetPolyline(pts, 5.8);
  setStroke("rotring", PAL.ink, 0.58);
  drawPolylineSegments(edgeLeft);
  drawPolylineSegments(edgeRight);

  // 7. Stripped PVC cut collars at ends (showing thickness of insulation jacket around copper)
  if (stripStart && pts.length >= 2) {
    drawStrippedPvcCollar(pts[0], pts[1], c);
  }
  if (stripEnd && pts.length >= 2) {
    let n = pts.length - 1;
    drawStrippedPvcCollar(pts[n], pts[n - 1], c);
  }
}

function drawGreenYellowStripes(pts, c) {
  // Longitudinal + diagonal helical green stripes along the yellow earth conductor
  let stripeCenter = offsetPolyline(pts, 0.8);
  setStroke("wire_marker", c.stripe, 0.62);
  drawPolylineSegments(stripeCenter);

  for (let i = 0; i < pts.length - 1; i++) {
    let x1 = pts[i][0], y1 = pts[i][1];
    let x2 = pts[i + 1][0], y2 = pts[i + 1][1];
    let dx = x2 - x1, dy = y2 - y1;
    let segLen = Math.hypot(dx, dy);
    if (segLen < 12) continue;
    let ux = dx / segLen, uy = dy / segLen;
    let nx = -uy, ny = ux;

    setStroke("rotring", c.stripeDark, 1.35);
    for (let d = 6; d < segLen - 6; d += 14) {
      brush.line(
        x1 + ux * (d - 3) - nx * 4.6,
        y1 + uy * (d - 3) - ny * 4.6,
        x1 + ux * (d + 4) + nx * 4.8,
        y1 + uy * (d + 4) + ny * 4.8
      );
    }
  }
}

function drawStrippedPvcCollar(pCut, pInside, c) {
  let dx = pInside[0] - pCut[0];
  let dy = pInside[1] - pCut[1];
  let d = Math.hypot(dx, dy) || 1;
  let ux = dx / d, uy = dy / d;
  let nx = -uy, ny = ux;

  // Beveled cut face of PVC insulation
  setStroke("rotring", c.sheen, 1.1);
  brush.line(pCut[0] - nx * 5.6, pCut[1] - ny * 5.6, pCut[0] + nx * 5.6, pCut[1] + ny * 5.6);
  setStroke("rotring", PAL.ink, 0.72);
  brush.line(
    pCut[0] - nx * 6.0, pCut[1] - ny * 6.0,
    pCut[0] + nx * 6.0, pCut[1] + ny * 6.0
  );
  // Slight shadow ring where copper exits the plastic sleeve
  setStroke("rotring", PAL.copperDark, 0.8);
  brush.line(
    pCut[0] - ux * 1.2 - nx * 3.8, pCut[1] - uy * 1.2 - ny * 3.8,
    pCut[0] - ux * 1.2 + nx * 3.8, pCut[1] - uy * 1.2 + ny * 3.8
  );
}

// =============================================================================
// 6. CABLE CLAMPS / P-CLIPS ANCHORING TRUNK BUNDLES TO ENAMEL PLATE
// =============================================================================
function drawCableClips() {
  const clips = [
    // [x1, y1, x2, y2] across major parallel wire trunks
    [172, 690, 228, 690],  // West vertical bundle (B1, B2, B3)
    [352, 210, 428, 210],  // North vertical bundle (C1, C2, C3, C4)
    [970, 402, 970, 498],  // East horizontal bundle (E3, E4, E5)
    [480, 192, 480, 288],  // North-West horizontal trunk (A1, A2, C4)
    [340, 812, 340, 888]   // South-West horizontal trunk
  ];

  for (let [x1, y1, x2, y2] of clips) {
    let dx = x2 - x1, dy = y2 - y1;
    let len = Math.hypot(dx, dy);
    let ux = dx / len, uy = dy / len;
    let nx = -uy, ny = ux;

    // Extending mounting tab for the clip screw
    let tabX = x1 - ux * 14;
    let tabY = y1 - uy * 14;

    // Shadow of clip bridge
    setStroke("wire_marker", PAL.enamelDeepShadow, 1.2);
    brush.line(tabX + 3, tabY + 4, x2 + ux * 6 + 3, y2 + uy * 6 + 4);

    // Cream nylon / zinc strap body
    setStroke("wire_marker", "#dfd6c5", 1.15);
    brush.line(tabX, tabY, x2 + ux * 6, y2 + uy * 6);
    setStroke("pvc_sheen", "#ffffff", 0.7);
    brush.line(tabX - nx * 2, tabY - ny * 2, x2 + ux * 6 - nx * 2, y2 + uy * 6 - ny * 2);

    // Crisp technical pen outline of strap
    setStroke("rotring", PAL.ink, 0.55);
    brush.line(tabX - nx * 5, tabY - ny * 5, x2 + ux * 6 - nx * 5, y2 + uy * 6 - ny * 5);
    brush.line(tabX + nx * 5, tabY + ny * 5, x2 + ux * 6 + nx * 5, y2 + uy * 6 + ny * 5);
    brush.line(x2 + ux * 6 - nx * 5, y2 + uy * 6 - ny * 5, x2 + ux * 6 + nx * 5, y2 + uy * 6 + ny * 5);

    // Small dusty retaining screw on the clip tab
    drawBrassScrewHead(tabX, tabY, 7.5, random(20, 160), true);
  }
}

