function drawStationNumberGlyph(cx, cy, num) {
  setStroke("rotring", PAL.ink, 0.48);
  if (num === 1) {
    brush.line(cx, cy - 4, cx, cy + 4);
  } else if (num === 2) {
    brush.line(cx - 2.5, cy - 3.5, cx + 2.5, cy - 3.5);
    brush.line(cx + 2.5, cy - 3.5, cx - 2.5, cy + 3.5);
    brush.line(cx - 2.5, cy + 3.5, cx + 2.5, cy + 3.5);
  } else if (num === 3) {
    brush.line(cx - 2.5, cy - 3.5, cx + 2.5, cy - 3.5);
    brush.line(cx - 1, cy, cx + 2.5, cy);
    brush.line(cx - 2.5, cy + 3.5, cx + 2.5, cy + 3.5);
    brush.line(cx + 2.5, cy - 3.5, cx + 2.5, cy + 3.5);
  } else if (num === 4) {
    brush.line(cx - 2.5, cy - 3.5, cx - 2.5, cy + 0.5);
    brush.line(cx - 2.5, cy + 0.5, cx + 2.5, cy + 0.5);
    brush.line(cx + 1.5, cy - 3.5, cx + 1.5, cy + 3.5);
  } else {
    brush.line(cx - 2.5, cy - 3.5, cx + 2.5, cy - 3.5);
    brush.line(cx - 2.5, cy, cx + 2.5, cy);
    brush.line(cx - 2.5, cy + 3.5, cx + 2.5, cy + 3.5);
  }
}

// =============================================================================
// HYPERREAL BRASS SCREW HEAD WITH MACHINED SHEEN, BURRS & SETTLED DUST
// =============================================================================
function drawBrassScrewHead(cx, cy, r, slotAngle, isBrass = true, extraDusty = false) {
  // 1. Cast shadow under washer/head
  setWash("#17110b", 200);
  brush.circle(cx + 2.2, cy + 2.8, r + 2.2, 0.03);

  // 2. Clamping washer rim
  setWash(isBrass ? PAL.brassDark : "#3d3a36", 255);
  brush.circle(cx, cy, r + 2.0, 0.03);
  setStroke("rotring", PAL.ink, 0.55);
  brush.circle(cx, cy, r + 2.0, 0.02);

  // 3. Screw head base body
  setWash(isBrass ? PAL.brassMid : "#6e6962", 255);
  brush.circle(cx, cy, r, 0.02);

  // 4. Conical machined metallic sheen sectors (upper-left & lower-right reflections)
  setStroke("rotring", isBrass ? PAL.brassBright : "#9e988e", 1.2);
  brush.arc(cx, cy, r * 0.72, 195, 265);
  brush.arc(cx, cy, r * 0.52, 200, 260);
  brush.arc(cx, cy, r * 0.68, 15, 75);

  setStroke("rotring", isBrass ? PAL.brassGlint : "#d6cfc3", 0.85);
  brush.arc(cx, cy, r * 0.62, 210, 248);
  brush.arc(cx, cy, r * 0.42, 25, 60);

  // Dark bronze shadow arcs on perpendicular quadrants
  setStroke("rotring", isBrass ? PAL.brassDark : "#383430", 0.9);
  brush.arc(cx, cy, r * 0.78, 105, 170);
  brush.arc(cx, cy, r * 0.78, 285, 350);

  // 5. Deep recessed screwdriver slot
  let ux = cos(slotAngle), uy = sin(slotAngle);
  let nx = -uy, ny = ux;
  let sLen = r * 0.92;

  // Lit bevel edge of slot
  setStroke("rotring", isBrass ? PAL.brassSpec : "#fffaf0", 0.75);
  brush.line(
    cx - ux * sLen + nx * 1.9, cy - uy * sLen + ny * 1.9,
    cx + ux * sLen + nx * 1.9, cy + uy * sLen + ny * 1.9
  );
  // Shadow bevel edge of slot
  setStroke("rotring", isBrass ? PAL.brassDark : "#2e2a27", 0.75);
  brush.line(
    cx - ux * sLen - nx * 1.9, cy - uy * sLen - ny * 1.9,
    cx + ux * sLen - nx * 1.9, cy + uy * sLen - ny * 1.9
  );

  // Dark recessed slot trench
  setStroke("rotring", "#1a120b", 1.45);
  brush.line(cx - ux * sLen, cy - uy * sLen, cx + ux * sLen, cy + uy * sLen);

  // Screwdriver torque burrs (bright gold nicks where screwdriver bit chewed the slot)
  setStroke("rotring", PAL.brassSpec, 0.55);
  brush.line(cx - ux * (r * 0.4) + nx * 2.4, cy - uy * (r * 0.4) + ny * 2.4, cx - ux * (r * 0.15) + nx * 1.6, cy - uy * (r * 0.15) + ny * 1.6);
  brush.line(cx + ux * (r * 0.2) - nx * 2.3, cy + uy * (r * 0.2) - ny * 2.3, cx + ux * (r * 0.45) - nx * 1.5, cy + uy * (r * 0.45) - ny * 1.5);

  // Crisp outer technical pen ring
  setStroke("rotring", PAL.ink, 0.65);
  brush.circle(cx, cy, r, 0.02);

  // 6. Settled workshop dust inside the screw slot & around the washer collar
  setStroke("cpencil", PAL.dustLight, extraDusty ? 1.15 : 0.75);
  brush.line(
    cx - ux * (sLen * 0.75) + nx * 0.5, cy - uy * (sLen * 0.75) + ny * 0.5,
    cx + ux * (sLen * 0.65) + nx * 0.5, cy + uy * (sLen * 0.65) + ny * 0.5
  );
  // Dust pooled along the lower-inner rim of the washer
  setStroke("cpencil", PAL.dustMid, extraDusty ? 1.1 : 0.7);
  brush.arc(cx, cy, r + 0.8, 30, 150);

  if (extraDusty || r >= 12) {
    setStroke("dust_grain", PAL.dustLight, 0.9);
    brush.line(cx - r * 0.6, cy - r * 0.3, cx + r * 0.6, cy + r * 0.4);
    setStroke("dust_grain", PAL.dustMid, 0.8);
    brush.line(cx - r * 0.4, cy + r * 0.5, cx + r * 0.5, cy - r * 0.4);
  }
}

