function draw() {
  translate(-width / 2, -height / 2);

  // 1. ARCHIVAL MUNSELL N6.75 NEUTRAL GREY CARD GROUND
  background("#b3b1ab");
  drawArchivalCardGround();

  // 2. GRID GEOMETRY & MUNSELL CHART CONFIGURATION
  const cols = 6;
  const rows = 5;
  const gridLeft = 148;
  const gridTop = 166;
  const cellW = 158;
  const cellH = 178;
  const gridW = cols * cellW; // 948
  const gridH = rows * cellH; // 890

  const colSpecs = [
    { hueCode: "5GY",   stage: "I. HARD JADE",     sub: "CHLOROPHYLL DOM.", chromaBase: 6 },
    { hueCode: "2.5GY", stage: "II. BREAKER",      sub: "APICAL BLUSH",     chromaBase: 8 },
    { hueCode: "10YR",  stage: "III. AMBER GOLD",  sub: "CAROTENE PEAK",    chromaBase: 10 },
    { hueCode: "5YR",   stage: "IV. PERSIMMON",    sub: "LYCOPENE ONSET",   chromaBase: 12 },
    { hueCode: "10R",   stage: "V. VERMILION",     sub: "FULL CHROMA",      chromaBase: 14 },
    { hueCode: "5R",    stage: "VI. OXBLOOD",      sub: "ANTHOCYANIN DEEP", chromaBase: 10 }
  ];

  const rowSpecs = [
    { valCode: "8/", valNum: 8, desc: "HIGH VALUE",   lumShift: 0.22, darkShift: 0.0 },
    { valCode: "7/", valNum: 7, desc: "LIGHT MID",    lumShift: 0.10, darkShift: 0.04 },
    { valCode: "6/", valNum: 6, desc: "STD CHROMA",   lumShift: 0.00, darkShift: 0.12 },
    { valCode: "5/", valNum: 5, desc: "DEEP VALUE",   lumShift: -0.08, darkShift: 0.25 },
    { valCode: "4/", valNum: 4, desc: "LOW VALUE",    lumShift: -0.16, darkShift: 0.40 }
  ];

  // Deliberately empty cells (systematic missing slots in the Munsell chart)
  const emptyCells = new Set(["1,0", "4,1", "2,3", "0,4"]);

  // 3. DRAW CHART RULED LINES, HEADERS, AND MARGINALIA
  drawChartFramework(gridLeft, gridTop, cellW, cellH, cols, rows, colSpecs, rowSpecs);

  // 4. PRE-COMPUTE CELL DATA & PALETTES
  const cells = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const isEmpty = emptyCells.has(`${c},${r}`);
      const x0 = gridLeft + c * cellW;
      const y0 = gridTop + r * cellH;
      const palette = computeMunsellTomatoPalette(c, r);
      const chroma = Math.max(4, colSpecs[c].chromaBase - Math.abs(r - 2) * 2);
      const munsellLabel = `${colSpecs[c].hueCode} ${rowSpecs[r].valNum}/${chroma}`;
      cells.push({
        c, r, x0, y0,
        cx: x0 + cellW * 0.5,
        cy: y0 + cellH * 0.53,
        isEmpty,
        palette,
        chroma,
        munsellLabel,
        colSpec: colSpecs[c],
        rowSpec: rowSpecs[r],
        seed: (r * 100 + c * 17 + 13) * 97
      });
    }
  }

  // 5. PASS 1: CELL BACKGROUNDS, CHIP SWATCHES, AND EMPTY CELL APPARATUS
  for (const cell of cells) {
    drawCellUnderlayAndSwatch(cell, cellW, cellH);
  }

  // 6. PASS 2: RENDER EACH HYPERREAL TOMATO SPECIMEN
  for (const cell of cells) {
    if (!cell.isEmpty) {
      drawHyperrealTomato(cell, cellW, cellH);
    } else {
      drawEmptyCellSpecimenSlot(cell, cellW, cellH);
    }
  }

  // 7. PASS 3: FINE GRAPHITE CELL NOTATION & CALIBRATION FOOTER
  for (const cell of cells) {
    drawCellPencilNotations(cell, cellW, cellH);
  }

  drawBottomCalibrationFooter(gridLeft, gridTop + gridH, gridW);

  noLoop();
}

// ============================================================================
// ARCHIVAL CARD & FRAMEWORK
// ============================================================================

function drawArchivalCardGround() {
  brush.noStroke();

  // Subtle uneven museum board toning using large low-opacity washes
  brush.wash("#bab8b2", 45);
  brush.rect(30, 30, 1140, 1140, "corner");

  brush.wash("#a8a6a0", 30);
  brush.rect(0, 820, 1200, 380, "corner");
  brush.noWash();

  // Fine paper tooth across the grey card
  brush.field("hand");
  brush.wiggle(1.5);
  for (let i = 0; i < 220; i++) {
    const px = random(20, 1180);
    const py = random(20, 1180);
    const len = random(40, 180);
    const col = i % 2 === 0 ? "#bfbdb7" : "#a3a19b";
    brush.set("2H", col, random(0.2, 0.45));
    brush.flowLine(px, py, len, random(360));
  }
  brush.noField();

  // Subtle dust / fibre flecks on the grey card
  for (let i = 0; i < 320; i++) {
    const x = random(25, 1175);
    const y = random(25, 1175);
    const col = random() > 0.45 ? "#9c9a94" : "#c7c5bf";
    brush.set("2H", col, random(0.25, 0.55));
    brush.line(x, y, x + random(-1.8, 1.8), y + random(-1.8, 1.8));
  }

  // Outer museum plate border rules
  brush.set("2H", "#6e6c66", 0.55);
  brush.noFill();
  brush.rect(36, 36, 1128, 1128, "corner");

  brush.set("2H", "#8a8882", 0.35);
  brush.rect(42, 42, 1116, 1116, "corner");

  // Corner registration hairlines
  const corners = [[36, 36, -1, -1], [1164, 36, 1, -1], [36, 1164, -1, 1], [1164, 1164, 1, 1]];
  brush.set("HB", "#4d4b46", 0.5);
  for (const [cx, cy, dx, dy] of corners) {
    brush.line(cx + dx * 4, cy, cx + dx * 18, cy);
    brush.line(cx, cy + dy * 4, cx, cy + dy * 18);
  }
}

function drawChartFramework(gridLeft, gridTop, cellW, cellH, cols, rows, colSpecs, rowSpecs) {
  const gridW = cols * cellW;
  const gridH = rows * cellH;

  // Main Header Block
  drawPencilText("MUNSELL POMOLOGICAL CHROMATICITY ATLAS  -  SOLANUM LYCOPERSICUM L.", gridLeft, 66, 8.5, "#3f3d39", 0.52, 1.35);
  drawPencilText("SYSTEMATIC RIPENING SERIES: CHLOROPHYLL JADE (5GY) TO ANTHOCYANIN OXBLOOD (5R)  |  ILLUMINANT C  |  N6.75 ARCHIVAL CARD", gridLeft, 84, 5.2, "#5e5c57", 0.38, 1.25);
  drawPencilText("PLATE VII-B", gridLeft + gridW - 76, 66, 7.2, "#45433f", 0.48, 1.3);
  drawPencilText("REF: USDA / MUNSELL 1975", gridLeft + gridW - 126, 84, 4.8, "#66645e", 0.36, 1.2);

  // Horizontal divider under title
  brush.set("HB", "#5b5954", 0.5);
  brush.line(gridLeft, 98, gridLeft + gridW, 98);
  brush.set("2H", "#82807a", 0.35);
  brush.line(gridLeft, 102, gridLeft + gridW, 102);

  // Column Hue Headers
  for (let c = 0; c < cols; c++) {
    const cx = gridLeft + c * cellW;
    // Small bracket & tick
    brush.set("2H", "#686660", 0.42);
    brush.line(cx + 8, 148, cx + cellW - 8, 148);
    brush.line(cx + 8, 148, cx + 8, 154);
    brush.line(cx + cellW - 8, 148, cx + cellW - 8, 154);

    drawPencilText(`HUE ${colSpecs[c].hueCode}`, cx + 10, 114, 6.8, "#3e3c38", 0.48, 1.25);
    drawPencilText(colSpecs[c].stage, cx + 10, 127, 5.0, "#575550", 0.38, 1.2);
    drawPencilText(colSpecs[c].sub, cx + 10, 138, 4.2, "#706e68", 0.32, 1.15);
  }

  // Row Value Headers (Left Margin)
  drawPencilText("MUNSELL", 56, gridTop - 26, 5.2, "#575550", 0.38, 1.2);
  drawPencilText("VALUE", 56, gridTop - 15, 5.8, "#3f3d39", 0.44, 1.25);

  for (let r = 0; r < rows; r++) {
    const ry = gridTop + r * cellH;
    const midY = ry + cellH * 0.5;

    // Neutral value reference patch in the left margin corresponding to row Value
    const vGray = [212, 184, 152, 118, 86][r];
    const vHex = rgbToHex(vGray, vGray - 1, vGray - 4);
    brush.noStroke();
    brush.wash(vHex, 235);
    brush.rect(56, midY - 22, 18, 44, "corner");
    brush.noWash();

    brush.set("2H", "#5d5b56", 0.4);
    brush.noFill();
    brush.rect(56, midY - 22, 18, 44, "corner");

    drawPencilText(`V ${rowSpecs[r].valCode}`, 82, midY - 14, 7.2, "#3d3b37", 0.48, 1.2);
    drawPencilText(rowSpecs[r].desc, 82, midY - 1, 4.3, "#63615b", 0.34, 1.12);
    drawPencilText(`REFL ${(rowSpecs[r].valNum * 10.2 - 12).toFixed(1)}%`, 82, midY + 10, 4.0, "#75736d", 0.32, 1.1);

    // Tick connecting row label to grid
    brush.set("2H", "#6d6b65", 0.4);
    brush.line(136, midY, gridLeft, midY);
  }

  // Ruled Grid Lines
  brush.set("HB", "#5e5c57", 0.52);
  brush.noFill();
  brush.rect(gridLeft, gridTop, gridW, gridH, "corner");

  // Internal vertical & horizontal grid lines
  for (let c = 1; c < cols; c++) {
    const x = gridLeft + c * cellW;
    brush.set("2H", "#72706a", 0.42);
    brush.line(x, gridTop, x, gridTop + gridH);
  }
  for (let r = 1; r < rows; r++) {
    const y = gridTop + r * cellH;
    brush.set("2H", "#72706a", 0.42);
    brush.line(gridLeft, y, gridLeft + gridW, y);
  }

  // Precision crosshair ticks at every grid intersection
  brush.set("HB", "#484641", 0.48);
  for (let r = 0; r <= rows; r++) {
    for (let c = 0; c <= cols; c++) {
      const ix = gridLeft + c * cellW;
      const iy = gridTop + r * cellH;
      brush.line(ix - 4.5, iy, ix + 4.5, iy);
      brush.line(ix, iy - 4.5, ix, iy + 4.5);
    }
  }

  // Right-side Chroma & Spectrophotometric scale ticks
  const rightX = gridLeft + gridW;
  for (let i = 0; i <= 40; i++) {
    const ty = gridTop + (gridH / 40) * i;
    const tickLen = i % 8 === 0 ? 12 : (i % 4 === 0 ? 8 : 4);
    brush.set("2H", "#6a6862", i % 8 === 0 ? 0.45 : 0.32);
    brush.line(rightX, ty, rightX + tickLen, ty);
    if (i % 8 === 0) {
      const nm = 520 + i * 4.5;
      drawPencilText(`${Math.round(nm)}NM`, rightX + 16, ty - 2.5, 4.2, "#63615b", 0.33, 1.1);
    }
  }
}

// ============================================================================
// COLORIMETRY: MUNSELL TOMATO PALETTE GENERATOR
// ============================================================================

function computeMunsellTomatoPalette(col, row) {
  // Value factor: row 0 is brightest (Value 8/), row 4 is darkest (Value 4/)
  const valNorm = 1.0 - row / 4.0; // 1.0 -> 0.0
  // Value multiplier that preserves vivid chroma while stepping down value systematically
  const vScale = [1.14, 1.02, 0.89, 0.74, 0.58][row];
  const shadowScale = [0.68, 0.60, 0.50, 0.40, 0.30][row];

  // Anchor RGBs for the 6 ripening columns at standard mid-value (Value 6/ - 7/):
  // Col 0: Hard Jade Green (5GY)
  // Col 1: Breaker Blush (2.5GY chartreuse-jade with warm coral-apricot blush)
  // Col 2: Amber Gold / Tangelo (10YR vivid cadmium orange-gold)
  // Col 3: Persimmon / Flame Scarlet-Orange (5YR intense red-orange)
  // Col 4: True Carmine / Vermilion Red (10R peak saturated tomato red)
  // Col 5: Deep Oxblood / Heirloom Garnet (5R rich dark crimson-claret with dusky olive-bronze shoulder)
  const bodyAnchors = [
    [94, 168, 66],    // Col 0: Vivid Jade Green
    [172, 178, 56],   // Col 1: Breaker Chartreuse-Lime base
    [244, 152, 24],   // Col 2: Vivid Sungold Amber-Orange
    [242, 82, 22],    // Col 3: Fiery Persimmon Scarlet
    [216, 26, 28],    // Col 4: Rich Carmine-Vermilion
    [136, 18, 28]     // Col 5: Deep Oxblood Garnet
  ];

  // Secondary blush / lower hemisphere ripening tone
  const blushAnchors = [
    [118, 184, 78],   // Col 0: Pale celadon-jade apex
    [234, 118, 68],   // Col 1: Warm rose-coral breaker blush on blossom end!
    [248, 114, 18],   // Col 2: Deep tangerine-persimmon blush
    [228, 44, 20],    // Col 3: Crimson-orange lower swell
    [186, 14, 24],    // Col 4: Deep arterial carmine
    [98, 10, 22]      // Col 5: Velvet claret-black
  ];

  // Shoulder tone around the stem cavity (chlorophyll persistence)
  const shoulderAnchors = [
    [62, 128, 44],    // Col 0: Deep forest jade shoulder
    [106, 154, 52],   // Col 1: Leaf-green shoulder
    [168, 162, 42],   // Col 2: Olive-gold shoulder hint
    [196, 122, 30],   // Col 3: Amber-bronze shoulder
    [175, 58, 26],    // Col 4: Warm russet-scarlet shoulder
    [96, 56, 32]      // Col 5: Heirloom dusky olive-mahogany shoulder
  ];

  // Deep core shadow tone (cooler/richer Munsell shadow)
  const shadowAnchors = [
    [38, 86, 34],
    [82, 76, 30],
    [138, 58, 14],
    [132, 24, 16],
    [108, 8, 18],
    [58, 6, 14]
  ];

  // Luminous upper-left midtone swell (around highlight)
  const lightAnchors = [
    [156, 216, 108],
    [218, 212, 92],
    [255, 198, 64],
    [255, 134, 58],
    [246, 76, 66],
    [188, 48, 56]
  ];

  const scaleColor = (rgb, mult, lift = 0) => [
    constrain(Math.round(rgb[0] * mult + lift), 8, 254),
    constrain(Math.round(rgb[1] * mult + lift), 6, 254),
    constrain(Math.round(rgb[2] * mult + lift), 6, 254)
  ];

  const lift = row === 0 ? 18 : (row === 1 ? 6 : 0);
  const bodyRGB = scaleColor(bodyAnchors[col], vScale, lift);
  const blushRGB = scaleColor(blushAnchors[col], vScale, lift * 0.7);
  const shoulderRGB = scaleColor(shoulderAnchors[col], vScale * 0.96, lift * 0.4);
  const shadowRGB = scaleColor(shadowAnchors[col], shadowScale * 1.35, 0);
  const lightRGB = scaleColor(lightAnchors[col], Math.min(1.22, vScale * 1.08), lift * 1.1);

  // Reflected light from the neutral grey card onto the bottom-right rim
  const reflRGB = [
    constrain(Math.round(shadowRGB[0] * 0.55 + 168 * 0.45), 30, 210),
    constrain(Math.round(shadowRGB[1] * 0.55 + 166 * 0.45), 30, 210),
    constrain(Math.round(shadowRGB[2] * 0.55 + 160 * 0.45), 30, 210)
  ];

  return {
    bodyRGB,
    blushRGB,
    shoulderRGB,
    shadowRGB,
    lightRGB,
    reflRGB,
    bodyHex: rgbToHex(...bodyRGB),
    blushHex: rgbToHex(...blushRGB),
    shoulderHex: rgbToHex(...shoulderRGB),
    shadowHex: rgbToHex(...shadowRGB),
    lightHex: rgbToHex(...lightRGB),
    reflHex: rgbToHex(...reflRGB)
  };
}

function rgbToHex(r, g, b) {
  const toH = (n) => constrain(Math.round(n), 0, 255).toString(16).padStart(2, '0');
  return `#${toH(r)}${toH(g)}${toH(b)}`;
}

function lerpRGB(c1, c2, t) {
  return [
    c1[0] + (c2[0] - c1[0]) * t,
    c1[1] + (c2[1] - c1[1]) * t,
    c1[2] + (c2[2] - c1[2]) * t
  ];
}

// ============================================================================
// CELL UNDERLAY, FLAT MUNSELL REFERENCE CHIP & EMPTY SLOT
// ============================================================================

function drawCellUnderlayAndSwatch(cell, cellW, cellH) {
  const { x0, y0, palette, isEmpty } = cell;

  // Faint inset specimen card boundary inside cell
  brush.set("2H", "#8f8d86", 0.28);
  brush.noFill();
  brush.rect(x0 + 6, y0 + 6, cellW - 12, cellH - 12, "corner");

  // Flat Munsell reference colour-chip swatch in the top-right corner of the cell
  const swX = x0 + cellW - 34;
  const swY = y0 + 11;
  const swW = 22;
  const swH = 14;

  // Chip shadow
  brush.noStroke();
  brush.wash("#87857f", 140);
  brush.rect(swX + 1.2, swY + 1.2, swW, swH, "corner");

  // Opaque matte gouache chip fill
  brush.wash(palette.bodyHex, 245);
  brush.rect(swX, swY, swW, swH, "corner");

  // Split diagonal showing secondary breaker/blush tone on Col 1
  if (cell.c === 1) {
    brush.wash(palette.blushHex, 210);
    brush.rect(swX + swW * 0.5, swY, swW * 0.5, swH, "corner");
  }
  brush.noWash();

  // Crisp ruled border around the reference swatch
  brush.set("2H", "#55534e", 0.35);
  brush.noFill();
  brush.rect(swX, swY, swW, swH, "corner");

  if (!isEmpty) {
    // Tiny registration crosshair under the tomato position
    brush.set("2H", "#82807a", 0.3);
    brush.line(cell.cx - 52, cell.cy, cell.cx - 44, cell.cy);
    brush.line(cell.cx + 44, cell.cy, cell.cx + 52, cell.cy);
    brush.line(cell.cx, cell.cy - 50, cell.cx, cell.cy - 42);
    brush.line(cell.cx, cell.cy + 42, cell.cx, cell.cy + 50);
  }
}

function drawEmptyCellSpecimenSlot(cell, cellW, cellH) {
  const { cx, cy, palette } = cell;
  const r = 42;

  // Faint ghost ring stain on the grey card where a specimen was lifted or omitted
  brush.noStroke();
  brush.wash("#a4a29c", 75);
  brush.circle(cx, cy, r * 0.92, 0.08);
  brush.wash("#b3b1ab", 180);
  brush.circle(cx, cy, r * 0.76, 0.06);
  brush.noWash();

  // Dashed mechanical-pencil circle indicating missing specimen locus
  brush.set("2H", "#686660", 0.38);
  for (let a = 0; a < 360; a += 15) {
    brush.arc(cx, cy, r, a, a + 8);
  }
  for (let a = 0; a < 360; a += 30) {
    brush.arc(cx, cy, r * 0.62, a, a + 12);
  }

  // Center calibration crosshairs
  brush.set("HB", "#575550", 0.42);
  brush.line(cx - 14, cy, cx + 14, cy);
  brush.line(cx, cy - 14, cx, cy + 14);

  // Diagonal hatch in small central square
  brush.set("2H", "#7a7872", 0.3);
  brush.noFill();
  brush.rect(cx - 18, cy - 18, 36, 36, "corner");

  // Painted mini colour test strip on left of empty slot
  brush.noStroke();
  brush.wash(palette.shoulderHex, 230);
  brush.rect(cx - 28, cy + 24, 18, 7, "corner");
  brush.wash(palette.bodyHex, 235);
  brush.rect(cx - 9, cy + 24, 18, 7, "corner");
  brush.wash(palette.shadowHex, 235);
  brush.rect(cx + 10, cy + 24, 18, 7, "corner");
  brush.noWash();

  brush.set("2H", "#5c5a55", 0.32);
  brush.rect(cx - 28, cy + 24, 56, 7, "corner");

  drawPencilText("SPECIMEN OMITTED", cx - 32, cy - 28, 4.2, "#595752", 0.35, 1.15);
  drawPencilText("STANDARD CHIP ONLY", cx - 35, cy + 35, 3.8, "#6e6c66", 0.32, 1.12);
}

// ============================================================================
// HYPERREAL TOMATO RENDERER (OPAQUE MATTE WATERCOLOUR / GOUACHE)
// ============================================================================

function getTomatoRadiusAtAngle(angleDeg, rx, ry, lobes, lobeDepth, phase, seedOffset) {
  const rad = angleDeg * Math.PI / 180;
  // Base elliptical radius
  const cosA = Math.cos(rad);
  const sinA = Math.sin(rad);
  const baseR = (rx * ry) / Math.sqrt((ry * cosA) ** 2 + (rx * sinA) ** 2);

  // Organic locule rib modulation (5 to 8 subtle swells around equator)
  const lobeWave = Math.cos(rad * lobes + phase) * lobeDepth;
  const secondaryWave = Math.sin(rad * (lobes + 2) - phase * 1.7 + seedOffset) * (lobeDepth * 0.35);

  // Slight flatten at top shoulder (around -90 deg)
  const topFlatten = Math.exp(-Math.pow(((angleDeg + 90 + 360) % 360 - 180) / 55, 2)) * 0.025;

  return baseR * (1 + lobeWave + secondaryWave - topFlatten);
}

function drawHyperrealTomato(cell, cellW, cellH) {
  const { c, r, cx, cy, palette, seed } = cell;
  randomSeed(seed);
  noiseSeed(seed + 31);

  // Specimen dimensions & morphological traits
  const rx = random(43, 48.5);
  const ry = rx * random(0.89, 0.97); // Slightly oblate spheroid from angled top view
  const lobes = [5, 6, 6, 7, 6, 8][c] + (r % 2 === 0 ? 0 : 1);
  const lobeDepth = random(0.022, 0.048) * (c === 5 ? 1.35 : 1.0); // Heirloom oxblood slightly more ribbed
  const phase = random(0, Math.PI * 2);

  // Stem cavity center (viewed from ~28–38 deg above, so slightly upper-left or upper-center)
  const tiltAngle = random(-110, -70);
  const cavityDist = ry * random(0.18, 0.30);
  const cavX = cx + cos(tiltAngle) * cavityDist * 0.45 + random(-3, 3);
  const cavY = cy - ry * random(0.20, 0.32);

  // Decide whether this specimen displays a full curling calyx with trichome hairs
  // or an exposed corky stem scar with remnant sepal collar and fine periderm hairs
  const hasFullCalyx = ((c + r * 2) % 3 !== 1);

  // --------------------------------------------------------------------------
  // STEP 1: GROUNDED CAST SHADOW & CHROMATIC BOUNCE ON GREY CARD
  // --------------------------------------------------------------------------
  const shOffX = 11 + r * 0.8;
  const shOffY = 13 + r * 0.8;

  brush.noStroke();
  // Soft outer penumbra
  brush.wash("#94928c", 95);
  drawOrganicBlob(cx + shOffX * 1.15, cy + shOffY * 1.15, rx * 0.98, ry * 0.92, lobes, lobeDepth * 0.4, phase, 16);

  // Mid umbra
  brush.wash("#75736d", 145);
  drawOrganicBlob(cx + shOffX * 0.82, cy + shOffY * 0.85, rx * 0.88, ry * 0.82, lobes, lobeDepth * 0.4, phase, 16);

  // Subtle chromatic bounce light inside the cast shadow edge
  brush.wash(palette.bodyHex, 38);
  drawOrganicBlob(cx + shOffX * 0.95, cy + shOffY * 0.95, rx * 0.82, ry * 0.76, lobes, 0.01, phase, 14);

  // Deep contact occlusion shadow right under the lower-right rim
  brush.wash("#45433f", 190);
  drawOrganicBlob(cx + shOffX * 0.42, cy + shOffY * 0.46, rx * 0.78, ry * 0.72, lobes, lobeDepth * 0.3, phase, 14);
  brush.noWash();

  // Soft graphite feathering on shadow edge
  for (let i = 0; i < 14; i++) {
    const ang = random(15, 135);
    const rad = getTomatoRadiusAtAngle(ang, rx, ry, lobes, lobeDepth, phase, seed);
    const sx = cx + shOffX * 0.7 + cos(ang) * rad * random(0.85, 1.08);
    const sy = cy + shOffY * 0.7 + sin(ang) * rad * random(0.82, 1.05);
    brush.set("2B", "#5e5c56", random(0.3, 0.55));
    brush.arc(cx + shOffX * 0.65, cy + shOffY * 0.68, rad * random(0.92, 1.04), ang - 12, ang + 12);
  }

  // --------------------------------------------------------------------------
  // STEP 2: OPAQUE MATTE WATERCOLOUR (GOUACHE) BASE SILHOUETTE
  // --------------------------------------------------------------------------
  brush.noStroke();
  // Solid opaque gouache underpainting
  brush.wash(palette.bodyHex, 250);
  drawOrganicBlob(cx, cy, rx, ry, lobes, lobeDepth, phase, 24);
  brush.noWash();

  // Matte watercolour texture layer over the whole fruit
  brush.fill(palette.bodyHex, 155);
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.48, 0.22);
  drawOrganicBlob(cx, cy, rx * 0.99, ry * 0.99, lobes, lobeDepth, phase, 18);
  brush.noFill();

  // --------------------------------------------------------------------------
  // STEP 3: RIPENING GRADIENT, BREAKER BLUSH & SHOULDER CHLOROPHYLL
  // --------------------------------------------------------------------------
  // 3A. Lower blossom-end blush (especially dramatic on Breaker Col 1 & Amber Col 2)
  brush.noStroke();
  brush.wash(palette.blushHex, c === 1 ? 185 : 130);
  drawHemisphereCrescent(cx, cy, rx * 0.96, ry * 0.96, 15, 165, 0.45);
  brush.noWash();

  // 3B. Upper shoulder tone around stem cavity (cooler jade/olive/bronze shoulder)
  brush.wash(palette.shoulderHex, c >= 3 ? 115 : 165);
  drawOrganicBlob(cavX, cavY + ry * 0.08, rx * 0.72, ry * 0.52, lobes, lobeDepth * 1.4, phase, 16);
  brush.noWash();

  // 3C. Form shadow crescent on bottom-right hemisphere
  brush.fill(palette.shadowHex, 165);
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.42, 0.18);
  drawHemisphereCrescent(cx, cy, rx * 0.98, ry * 0.98, -25, 145, 0.52);
  brush.noFill();

  // --------------------------------------------------------------------------
  // STEP 4: SPHERICAL MERIDIAN & LOCULE RIB MODELLING (MATTE GOUACHE STROKES)
  // --------------------------------------------------------------------------
  // Paint curved meridian strokes radiating from the stem cavity around the 3D volume
  const numMeridians = lobes * 4;
  for (let m = 0; m < numMeridians; m++) {
    const baseAng = (360 / numMeridians) * m + random(-3, 3);
    const radAngle = baseAng * Math.PI / 180;
    const ribFactor = Math.cos(radAngle * lobes + phase); // +1 on lobe crown, -1 in rib valley
    const outerR = getTomatoRadiusAtAngle(baseAng, rx, ry, lobes, lobeDepth, phase, seed) * 0.96;

    // Determine meridian color based on light direction (-125 deg) and rib valley vs crown
    const lightAlignment = Math.cos((baseAng - (-125)) * Math.PI / 180); // +1 toward light, -1 toward shadow

    let strokeRGB;
    if (ribFactor < -0.25) {
      // Furrow / valley between locules retains slightly more shoulder/shadow pigment
      strokeRGB = lerpRGB(palette.shoulderRGB, palette.shadowRGB, map(lightAlignment, 1, -1, 0.15, 0.78));
    } else if (lightAlignment > 0.2) {
      // Lit upper-left lobe swell
      strokeRGB = lerpRGB(palette.bodyRGB, palette.lightRGB, map(lightAlignment, 0.2, 1, 0.1, 0.85));
    } else if (c === 1 && sin(baseAng) > 0) {
      // Breaker tomato warm coral-orange streaks rising from bottom
      strokeRGB = lerpRGB(palette.bodyRGB, palette.blushRGB, random(0.45, 0.95));
    } else {
      // Midtone to form shadow
      strokeRGB = lerpRGB(palette.bodyRGB, palette.shadowRGB, map(lightAlignment, 0.2, -1, 0.05, 0.85));
    }

    const strokeHex = rgbToHex(...strokeRGB);

    // Construct 4-point curved meridian spline from near stem cavity to outer rim
    const p0x = cavX + cos(baseAng) * 7;
    const p0y = cavY + sin(baseAng) * 6;

    const midBulgeAngle = baseAng + (ribFactor * 4);
    const p1x = lerp(cavX, cx, 0.45) + cos(midBulgeAngle) * (outerR * 0.48);
    const p1y = lerp(cavY, cy, 0.45) + sin(midBulgeAngle) * (outerR * 0.46);

    const p2x = lerp(cavX, cx, 0.82) + cos(midBulgeAngle) * (outerR * 0.82);
    const p2y = lerp(cavY, cy, 0.82) + sin(midBulgeAngle) * (outerR * 0.80);

    const p3x = cx + cos(baseAng) * outerR;
    const p3y = cy + sin(baseAng) * outerR * (ry / rx);

    brush.set("gouache_broad", strokeHex, random(0.55, 0.95));
    brush.spline([[p0x, p0y, 0.3], [p1x, p1y, 0.9], [p2x, p2y, 1.0], [p3x, p3y, 0.3]], 0.55);

    // Extra fine rib crease line in the valleys near the shoulder
    if (ribFactor < -0.55) {
      const creaseHex = rgbToHex(...lerpRGB(palette.shoulderRGB, palette.shadowRGB, 0.65));
      brush.set("sable_fine", creaseHex, random(0.45, 0.72));
      brush.spline([[p0x, p0y, 0.8], [p1x, p1y, 0.65], [p2x, p2y, 0.2]], 0.5);
    }
  }

  // Equatorial concentric glazing strokes for smooth matte gouache volume
  for (let i = 0; i < 16; i++) {
    const startA = random(-180, 160);
    const span = random(35, 85);
    const ringFrac = random(0.42, 0.93);
    const midA = startA + span * 0.5;
    const lightAlign = Math.cos((midA - (-125)) * Math.PI / 180);

    let glazeRGB;
    if (lightAlign > 0.35) {
      glazeRGB = lerpRGB(palette.bodyRGB, palette.lightRGB, 0.55);
    } else if (lightAlign < -0.25) {
      glazeRGB = lerpRGB(palette.blushRGB, palette.shadowRGB, 0.7);
    } else {
      glazeRGB = lerpRGB(palette.bodyRGB, palette.blushRGB, 0.5);
    }

    brush.set("gouache_blend", rgbToHex(...glazeRGB), random(0.6, 1.05));
    brush.arc(cx, cy, rx * ringFrac, startA, startA + span);
  }

  // --------------------------------------------------------------------------
  // STEP 5: GREY-CARD REFLECTED BOUNCE LIGHT ON BOTTOM-RIGHT RIM
  // --------------------------------------------------------------------------
  for (let i = 0; i < 6; i++) {
    const a1 = random(18, 62);
    const a2 = a1 + random(24, 48);
    const rimR = getTomatoRadiusAtAngle((a1 + a2) * 0.5, rx, ry, lobes, lobeDepth, phase, seed) * random(0.91, 0.96);
    brush.set("gouache_blend", palette.reflHex, random(0.45, 0.75));
    brush.arc(cx, cy * 0.998, rimR * 0.96, a1, a2);
  }

  // Crisp outer contour cleanup with fine sable brush so edge against grey card is razor-sharp
  for (let a = 0; a < 360; a += 30) {
    const pts = [];
    for (let step = 0; step <= 30; step += 10) {
      const ang = a + step;
      const rr = getTomatoRadiusAtAngle(ang, rx, ry, lobes, lobeDepth, phase, seed);
      pts.push([cx + cos(ang) * rr * 0.985, cy + sin(ang) * rr * 0.985, 0.7]);
    }
    const midAng = a + 15;
    const lightAlign = Math.cos((midAng - (-125)) * Math.PI / 180);
    const edgeRGB = lightAlign > 0
      ? lerpRGB(palette.bodyRGB, palette.lightRGB, 0.35)
      : lerpRGB(palette.bodyRGB, palette.shadowRGB, 0.72);
    brush.set("sable_fine", rgbToHex(...edgeRGB), 0.58);
    brush.spline(pts, 0.5);
  }

  // --------------------------------------------------------------------------
  // STEP 6: SUBSURFACE CUTICLE SPECKLING (EPIDERMAL LENTICELS)
  // --------------------------------------------------------------------------
  const speckRGB = lerpRGB(palette.lightRGB, [252, 240, 185], 0.45);
  const speckHex = rgbToHex(...speckRGB);
  for (let i = 0; i < 24; i++) {
    const ang = random(360);
    const dist = random(0.28, 0.88) * rx;
    const sx = cx + cos(ang) * dist;
    const sy = cy + sin(ang) * dist * (ry / rx);
    brush.set("trichome_needle", speckHex, random(0.35, 0.65));
    brush.line(sx, sy, sx + random(-0.6, 0.6), sy + random(-0.6, 0.6));
  }

  // --------------------------------------------------------------------------
  // STEP 7: SINGLE SOFT HIGHLIGHT (UPPER-LEFT SWELL)
  // --------------------------------------------------------------------------
  drawSingleSoftHighlight(cx, cy, cavX, cavY, rx, ry, lobes, phase, palette);

  // --------------------------------------------------------------------------
  // STEP 8: STEM CAVITY, STEM SCAR & HYPERREAL CALYX WITH TRICHOME HAIRS
  // --------------------------------------------------------------------------
  drawStemScarAndCalyx(cavX, cavY, cx, cy, rx, ry, lobes, phase, palette, hasFullCalyx, c, r);
}

function drawOrganicBlob(cx, cy, rx, ry, lobes, lobeDepth, phase, steps) {
  brush.beginShape(0.45);
  for (let i = 0; i < steps; i++) {
    const ang = (360 / steps) * i;
    const r = getTomatoRadiusAtAngle(ang, rx, ry, lobes, lobeDepth, phase, 0);
    brush.vertex(cx + cos(ang) * r, cy + sin(ang) * r);
  }
  brush.endShape(true);
}

function drawHemisphereCrescent(cx, cy, rx, ry, startAngle, endAngle, innerInset) {
  brush.beginShape(0.45);
  const steps = 10;
  for (let i = 0; i <= steps; i++) {
    const a = lerp(startAngle, endAngle, i / steps);
    brush.vertex(cx + cos(a) * rx, cy + sin(a) * ry);
  }
  for (let i = steps; i >= 0; i--) {
    const a = lerp(startAngle, endAngle, i / steps);
    const bulge = Math.sin((i / steps) * Math.PI) * innerInset;
    brush.vertex(cx + cos(a) * rx * (1 - bulge), cy + sin(a) * ry * (1 - bulge));
  }
  brush.endShape(true);
}

function drawSingleSoftHighlight(cx, cy, cavX, cavY, rx, ry, lobes, phase, palette) {
  // Position on the upper-left / front-left shoulder swell (-132 deg from center)
  const hlAngle = -132;
  const hlDist = rx * 0.54;
  const hx = cx + cos(hlAngle) * hlDist;
  const hy = cy + sin(hlAngle) * hlDist * (ry / rx);

  // Broad luminous halo in warm pale tint of the fruit
  const haloHex = rgbToHex(...lerpRGB(palette.lightRGB, [255, 250, 238], 0.45));
  const midGlowHex = rgbToHex(...lerpRGB(palette.lightRGB, [255, 252, 244], 0.76));
  const coreHex = "#fffdf8";

  // Soft outer diffused glow following the curvature of the fruit
  for (let i = 0; i < 6; i++) {
    const a1 = hlAngle - 24 + i * 2;
    const a2 = hlAngle + 24 - i * 2;
    const rArc = hlDist + (i - 2.5) * 2.2;
    brush.set("gouache_broad", haloHex, 0.72 - i * 0.06);
    brush.arc(cx, cy, rArc, a1, a2);
  }

  // Mid soft satin highlight window
  for (let i = 0; i < 5; i++) {
    const a1 = hlAngle - 14 + i * 1.5;
    const a2 = hlAngle + 14 - i * 1.5;
    const rArc = hlDist + (i - 2) * 1.3;
    brush.set("gouache_blend", midGlowHex, 0.78 - i * 0.07);
    brush.arc(cx, cy, rArc, a1, a2);
  }

  // Bright, soft-edged matte-satin core broken subtly by a locule rib
  brush.set("sable_fine", coreHex, 0.92);
  brush.arc(cx, cy, hlDist - 0.8, hlAngle - 9, hlAngle - 1);
  brush.set("sable_fine", coreHex, 0.75);
  brush.arc(cx, cy, hlDist + 0.8, hlAngle + 1.5, hlAngle + 7.5);

  // Soft dry-brush pencil bloom around highlight edge for hyperreal skin texture
  brush.set("cpencil", midGlowHex, 0.45);
  brush.arc(cx, cy, hlDist - 2.2, hlAngle - 12, hlAngle + 10);
}

function drawStemScarAndCalyx(cavX, cavY, cx, cy, rx, ry, lobes, phase, palette, hasFullCalyx, col, row) {
  // 1. Deep sunken stem cavity shadow around pedicel attachment
  const cavShadHex = rgbToHex(...lerpRGB(palette.shoulderRGB, [22, 26, 18], 0.72));
  brush.noStroke();
  brush.wash(cavShadHex, 195);
  brush.circle(cavX, cavY, rx * 0.19, 0.15);
  brush.noWash();

  // Radial rib creases tucking tightly into the stem cavity
  for (let i = 0; i < lobes; i++) {
    const ribA = (360 / lobes) * i + (phase * 180 / Math.PI);
    const p1x = cavX + cos(ribA) * 3.5;
    const p1y = cavY + sin(ribA) * 3.0;
    const p2x = cavX + cos(ribA + 6) * (rx * 0.24);
    const p2y = cavY + sin(ribA + 6) * (ry * 0.22);
    const p3x = cavX + cos(ribA) * (rx * 0.42);
    const p3y = cavY + sin(ribA) * (ry * 0.36);

    brush.set("sable_fine", cavShadHex, 0.58);
    brush.spline([[p1x, p1y, 0.95], [p2x, p2y, 0.65], [p3x, p3y, 0.15]], 0.5);
  }

  // 2. Corky woody stem scar (pedicel abscission ring) — always present at the center,
  // either fully exposed or forming the basal collar around the calyx!
  const scarR = hasFullCalyx ? rx * 0.125 : rx * 0.155;

  // Dark recess ring around scar
  brush.set("sable_fine", "#2d2820", 0.65);
  brush.circle(cavX, cavY, scarR * 1.08, 0.12);

  // Corky russet-ochre periderm fill
  brush.noStroke();
  brush.wash("#8e795b", 235);
  brush.circle(cavX, cavY, scarR, 0.12);
  brush.wash("#b8a484", 190);
  brush.circle(cavX - 0.8, cavY - 0.6, scarR * 0.72, 0.1);
  brush. wash("#574936", 210);
  brush.circle(cavX + 0.5, cavY + 0.5, scarR * 0.34, 0.1);
  brush.noWash();

  // Vascular bundle dots & radial corky striations inside the stem scar
  for (let i = 0; i < 12; i++) {
    const a = i * 30 + random(-8, 8);
    const sx1 = cavX + cos(a) * (scarR * 0.32);
    const sy1 = cavY + sin(a) * (scarR * 0.28);
    const sx2 = cavX + cos(a) * (scarR * 0.98);
    const sy2 = cavY + sin(a) * (scarR * 0.88);
    brush.set("trichome_needle", i % 2 === 0 ? "#4a3d2c" : "#dfd2ba", 0.48);
    brush.line(sx1, sy1, sx2, sy2);
  }

  if (!hasFullCalyx) {
    // EXPOSED STEM SCAR SPECIMEN:
    // Add a raised corky rim highlight and a halo of fine silver-buff epidermal trichome hairs
    // plus 1 or 2 tiny dried sepal stubs clinging to the scar rim
    brush.set("sable_fine", "#ded0b8", 0.5);
    brush.arc(cavX, cavY, scarR * 0.92, -165, -35);

    // Remnant sepal stub
    const stubA = random(-70, 40);
    const stX = cavX + cos(stubA) * scarR * 1.75;
    const stY = cavY + sin(stubA) * scarR * 1.55;
    brush.set("sable_fine", "#556b38", 0.85);
    brush.spline([
      [cavX + cos(stubA) * scarR * 0.8, cavY + sin(stubA) * scarR * 0.8, 0.9],
      [stX, stY, 0.6],
      [stX + cos(stubA + 25) * 4, stY + sin(stubA + 25) * 4, 0.15]
    ], 0.5);

    // Fine microscopic calyx-collar hairs around the stem scar rim
    for (let h = 0; h < 28; h++) {
      const ha = random(360);
      const hr = scarR * random(0.78, 1.18);
      const hx1 = cavX + cos(ha) * hr;
      const hy1 = cavY + sin(ha) * hr * 0.9;
      const hLen = random(2.5, 5.8);
      const hCurl = ha + random(-28, 28);
      const hx2 = hx1 + cos(hCurl) * hLen;
      const hy2 = hy1 + sin(hCurl) * hLen;
      const hairCol = h % 3 === 0 ? "#f4f2e6" : "#c5ccb0";
      brush.set("trichome_needle", hairCol, random(0.32, 0.52));
      brush.line(hx1, hy1, hx2, hy2);
    }
    return;
  }

  // 3. FULL HYPERREAL CALYX (SEPALS + PEDICEL STUB + GLISTENING TRICHOME HAIRS)
  const numSepals = [5, 6, 6, 5, 6, 7][col];
  const sepalVFactor = [1.08, 1.02, 0.95, 0.88, 0.78][row];

  const sepalDark = rgbToHex(
    Math.round(28 * sepalVFactor),
    Math.round(58 * sepalVFactor),
    Math.round(22 * sepalVFactor)
  );
  const sepalMid = rgbToHex(
    Math.round(58 * sepalVFactor),
    Math.round(108 * sepalVFactor),
    Math.round(38 * sepalVFactor)
  );
  const sepalLight = rgbToHex(
    Math.round(112 * sepalVFactor),
    Math.round(162 * sepalVFactor),
    Math.round(68 * sepalVFactor)
  );
  const sepalTip = rgbToHex(
    Math.round(158 * sepalVFactor),
    Math.round(188 * sepalVFactor),
    Math.round(104 * sepalVFactor)
  );

  const sepals = [];
  for (let s = 0; s < numSepals; s++) {
    const baseA = (360 / numSepals) * s + random(-14, 14) + phase * 30;
    const len = rx * random(0.46, 0.74);
    const curlDir = (s % 2 === 0 ? 1 : -1) * random(14, 34);

    const p0 = [cavX + cos(baseA) * 3.5, cavY + sin(baseA) * 3.0];
    const p1 = [
      cavX + cos(baseA + curlDir * 0.25) * (len * 0.38),
      cavY + sin(baseA + curlDir * 0.25) * (len * 0.34)
    ];
    const p2 = [
      cavX + cos(baseA + curlDir * 0.65) * (len * 0.74),
      cavY + sin(baseA + curlDir * 0.65) * (len * 0.68)
    ];
    const p3 = [
      cavX + cos(baseA + curlDir) * len,
      cavY + sin(baseA + curlDir) * (len * 0.92) - random(1.5, 4.5) // Upward lifted tip!
    ];
    sepals.push({ baseA, len, curlDir, p0, p1, p2, p3 });
  }

  // 3A. Cast shadows of the lifted curling sepals onto the tomato skin
  const sepalShadowHex = rgbToHex(...lerpRGB(palette.shoulderRGB, [14, 16, 12], 0.76));
  for (const sep of sepals) {
    const shOffX = 3.2;
    const shOffY = 4.6;
    brush.set("sable_fine", sepalShadowHex, 1.05);
    brush.spline([
      [sep.p0[0] + 1, sep.p0[1] + 1.5, 0.8],
      [sep.p1[0] + shOffX * 0.6, sep.p1[1] + shOffY * 0.6, 0.95],
      [sep.p2[0] + shOffX, sep.p2[1] + shOffY, 0.7],
      [sep.p3[0] + shOffX * 1.25, sep.p3[1] + shOffY * 1.25, 0.2]
    ], 0.5);
  }

  // 3B. Paint the fleshy green sepal blades (dark underside, mid body, bright upper ridge)
  for (const sep of sepals) {
    const perpA = sep.baseA + 90;
    const wX = cos(perpA) * 2.1;
    const wY = sin(perpA) * 2.1;

    // Dark underside edge
    brush.set("sable_fine", sepalDark, 1.15);
    brush.spline([
      [sep.p0[0] + wX * 0.6, sep.p0[1] + wY * 0.6, 0.9],
      [sep.p1[0] + wX, sep.p1[1] + wY, 1.1],
      [sep.p2[0] + wX * 0.6, sep.p2[1] + wY * 0.6, 0.75],
      [sep.p3[0], sep.p3[1], 0.15]
    ], 0.5);

    // Mid green blade
    brush.set("sable_fine", sepalMid, 1.25);
    brush.spline([
      [sep.p0[0], sep.p0[1], 0.95],
      [sep.p1[0], sep.p1[1], 1.15],
      [sep.p2[0], sep.p2[1], 0.8],
      [sep.p3[0], sep.p3[1], 0.18]
    ], 0.5);

    // Sunlit upper vein & curling tip
    brush.set("trichome_needle", sepalLight, 0.95);
    brush.spline([
      [sep.p0[0] - wX * 0.4, sep.p0[1] - wY * 0.4, 0.7],
      [sep.p1[0] - wX * 0.5, sep.p1[1] - wY * 0.5, 0.95],
      [sep.p2[0] - wX * 0.3, sep.p2[1] - wY * 0.3, 0.75],
      [sep.p3[0], sep.p3[1], 0.3]
    ], 0.5);

    // Pale dry tip
    brush.set("trichome_needle", sepalTip, 0.65);
    brush.line(sep.p2[0], sep.p2[1], sep.p3[0], sep.p3[1]);
  }

  // 3C. Central cut pedicel stem stub rising from the calyx whorl, crowned with a circular stem scar!
  const stemDX = random(-4, 5);
  const stemDY = random(-9, -5);
  const stemTopX = cavX + stemDX;
  const stemTopY = cavY + stemDY;

  // Pedicel stalk shadow & body
  brush.set("sable_fine", sepalDark, 1.6);
  brush.line(cavX + 1.2, cavY + 1, stemTopX + 1.2, stemTopY + 1);
  brush.set("sable_fine", sepalMid, 1.45);
  brush.line(cavX, cavY, stemTopX, stemTopY);
  brush.set("trichome_needle", sepalLight, 0.85);
  brush.line(cavX - 1.2, cavY, stemTopX - 1.2, stemTopY);

  // Cut woody stem scar at the top of the pedicel stub
  brush.noStroke();
  brush.wash("#6e644a", 240);
  brush.circle(stemTopX, stemTopY, 4.2, 0.1);
  brush.wash("#c9bfa2", 220);
  brush.circle(stemTopX, stemTopY, 2.8, 0.08);
  brush.wash("#4f4734", 220);
  brush.circle(stemTopX, stemTopY, 1.1, 0.05);
  brush.noWash();

  brush.set("trichome_needle", "#3b3526", 0.45);
  brush.circle(stemTopX, stemTopY, 4.1, 0.1);

  // 3D. HYPERREAL CALYX HAIRS (GLISTENING GLANDULAR TRICHOMES)
  // Dozens of razor-sharp silvery-white and pale-celadon hairs radiating off the sepals and pedicel!
  for (const sep of sepals) {
    const numHairs = 7;
    for (let h = 1; h <= numHairs; h++) {
      const t = h / (numHairs + 1);
      // Interpolate along sepal spine
      const bx = lerp(lerp(sep.p0[0], sep.p1[0], t * 1.4), lerp(sep.p1[0], sep.p3[0], t), t);
      const by = lerp(lerp(sep.p0[1], sep.p1[1], t * 1.4), lerp(sep.p1[1], sep.p3[1], t), t);

      for (const side of [-1, 1]) {
        const hairAngle = sep.baseA + sep.curlDir * t + side * random(48, 82);
        const hairLen = random(3.2, 7.2) * (1 - t * 0.45);
        const hxMid = bx + cos(hairAngle) * (hairLen * 0.55);
        const hyMid = by + sin(hairAngle) * (hairLen * 0.55);
        const hxTip = bx + cos(hairAngle + side * 14) * hairLen;
        const hyTip = by + sin(hairAngle + side * 14) * hairLen;

        const hairColor = random() > 0.35 ? "#f7f8ef" : "#d6e2c1";
        brush.set("trichome_needle", hairColor, random(0.32, 0.56));
        brush.spline([[bx, by, 0.95], [hxMid, hyMid, 0.6], [hxTip, hyTip, 0.1]], 0.4);
      }
    }
  }

  // Trichome hairs bristling along the central pedicel stem
  for (let h = 0; h < 14; h++) {
    const t = random(0.15, 0.92);
    const sx = lerp(cavX, stemTopX, t) + random(-2, 2);
    const sy = lerp(cavY, stemTopY, t);
    const ha = (h % 2 === 0 ? -155 : -25) + random(-25, 25);
    const hLen = random(3.5, 6.8);
    brush.set("trichome_needle", "#f7f9f0", random(0.36, 0.58));
    brush.line(sx, sy, sx + cos(ha) * hLen, sy + sin(ha) * hLen);
  }
}

