function drawCellPencilNotations(cell, cellW, cellH) {
  const { c, r, x0, y0, munsellLabel, isEmpty, seed } = cell;
  randomSeed(seed + 500);

  const rowChar = String.fromCharCode(65 + r); // A..E
  const cellCode = `${rowChar}${c + 1}`;

  // Top-left cell coordinate & Munsell notation
  drawPencilText(`${cellCode}  ${munsellLabel}`, x0 + 10, y0 + 11, 5.2, "#3d3b37", 0.42, 1.18);

  // Sub-label under Munsell code
  const dE = (0.4 + ((c * 3 + r * 7) % 14) * 0.12).toFixed(2);
  drawPencilText(`DE:${dE}`, x0 + 10, y0 + 20, 3.9, "#6a6862", 0.32, 1.12);

  // Bottom-left & bottom-right clinical metrics
  const brix = (3.8 + c * 0.55 + (4 - r) * 0.12).toFixed(1);
  const lyc = [0.2, 1.4, 3.8, 7.6, 12.4, 14.8][c];
  const mass = (44.0 + ((c * 11 + r * 19) % 18) + (c === 5 ? 6.4 : 0)).toFixed(1);

  if (!isEmpty) {
    drawPencilText(`LYC ${lyc}MG  BRIX ${brix}`, x0 + 10, y0 + cellH - 19, 3.9, "#5e5c57", 0.33, 1.12);
    drawPencilText(`WT ${mass}G`, x0 + 10, y0 + cellH - 11, 3.8, "#73716b", 0.31, 1.12);
    drawPencilText(`LOT.${204 + r * 6 + c}`, x0 + cellW - 44, y0 + cellH - 11, 3.8, "#6e6c66", 0.31, 1.12);
  } else {
    drawPencilText(`CHIP REF ONLY`, x0 + 10, y0 + cellH - 19, 3.9, "#686660", 0.33, 1.12);
    drawPencilText(`[VOID SLOT]`, x0 + 10, y0 + cellH - 11, 3.8, "#75736d", 0.31, 1.12);
    drawPencilText(`N/A`, x0 + cellW - 26, y0 + cellH - 11, 3.8, "#75736d", 0.31, 1.12);
  }
}

function drawBottomCalibrationFooter(gridLeft, gridBottom, gridW) {
  const yTop = gridBottom + 18;

  // 10-step Munsell Neutral Value Grayscale Step Wedge (N1.5 to N9.0)
  drawPencilText("MUNSELL NEUTRAL VALUE CALIBRATION SCALE (N1.5 TO N9.0)", gridLeft, yTop, 4.5, "#4d4b46", 0.36, 1.18);

  const stepW = 34;
  const stepH = 16;
  const wedgeY = yTop + 9;

  for (let i = 0; i < 10; i++) {
    const vLevel = 1.5 + i * 0.833;
    const gray = Math.round(map(i, 0, 9, 32, 236));
    const hex = rgbToHex(gray, gray - 1, gray - 3);
    const sx = gridLeft + i * (stepW + 3);

    brush.noStroke();
    brush.wash(hex, 245);
    brush.rect(sx, wedgeY, stepW, stepH, "corner");
    brush.noWash();

    brush.set("2H", "#575550", 0.35);
    brush.noFill();
    brush.rect(sx, wedgeY, stepW, stepH, "corner");

    drawPencilText(`N${vLevel.toFixed(1)}`, sx + 5, wedgeY + stepH + 4, 3.6, "#63615b", 0.3, 1.1);
  }

  // Right-side clinical legend, scale bar, and colourist verification
  const scaleX = gridLeft + 415;
  drawPencilText("LINEAR SCALE  1:1.15  (METRIC MM)", scaleX, yTop, 4.5, "#4d4b46", 0.36, 1.18);

  // Ruled 50mm scale bar
  const barY = wedgeY + 8;
  const barW = 180;
  brush.set("HB", "#45433f", 0.48);
  brush.line(scaleX, barY, scaleX + barW, barY);
  brush.line(scaleX, barY + 4, scaleX + barW, barY + 4);

  for (let m = 0; m <= 50; m += 5) {
    const mx = scaleX + (m / 50) * barW;
    const h = m % 10 === 0 ? 9 : 5;
    brush.set("HB", "#45433f", m % 10 === 0 ? 0.48 : 0.34);
    brush.line(mx, barY - (h - 4), mx, barY + 4);
    if (m % 10 === 0) {
      drawPencilText(`${m}`, mx - 3, barY + 8, 3.8, "#5c5a55", 0.32, 1.1);
    }
  }

  // Verification stamp block on far right
  const rightBoxX = gridLeft + gridW - 265;
  brush.set("2H", "#6e6c66", 0.38);
  brush.noFill();
  brush.rect(rightBoxX, yTop - 2, 265, 38, "corner");

  drawPencilText("MEDIUM: OPAQUE MATTE WATERCOLOUR & GRAPHITE", rightBoxX + 8, yTop + 4, 4.2, "#4a4843", 0.35, 1.15);
  drawPencilText("SPECIMENS: 26 RENDERED  /  4 OMITTED CONTROLS", rightBoxX + 8, yTop + 14, 4.0, "#5e5c57", 0.33, 1.15);
  drawPencilText("ASSAYED & PAINTED BY LAB. COLORIMETRY DIV.", rightBoxX + 8, yTop + 24, 3.9, "#6e6c66", 0.32, 1.15);
}

// ============================================================================
// SINGLE-STROKE MECHANICAL PENCIL LETTERING ENGINE (100% p5.brush)
// ============================================================================

function drawPencilText(text, x, y, size, colorHex, weight, tracking = 1.15) {
  const str = String(text).toUpperCase();
  const charW = size * 0.62;
  const charH = size;
  const stepX = charW * tracking;

  brush.set("2H", colorHex, weight);

  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    if (ch === ' ') continue;

    const glyph = FONT_GLYPHS[ch];
    if (!glyph) continue;

    const cx = x + i * stepX;
    const cy = y;

    for (const poly of glyph) {
      if (poly.length === 2) {
        const x1 = cx + poly[0][0] * charW;
        const y1 = cy + poly[0][1] * charH;
        const x2 = cx + poly[1][0] * charW;
        const y2 = cy + poly[1][1] * charH;
        brush.line(x1, y1, x2, y2);
      } else if (poly.length > 2) {
        for (let j = 0; j < poly.length - 1; j++) {
          const x1 = cx + poly[j][0] * charW;
          const y1 = cy + poly[j][1] * charH;
          const x2 = cx + poly[j + 1][0] * charW;
          const y2 = cy + poly[j + 1][1] * charH;
          brush.line(x1, y1, x2, y2);
        }
      }
    }
  }
}

