// =============================================================================
// GEOMETRY & TESSELLATION ENGINE
// =============================================================================

function cleanPoly(pts, minDist = 1.2) {
  if (!pts || pts.length < 3) return [];
  let out = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (!p || isNaN(p[0]) || isNaN(p[1])) continue;
    if (out.length === 0) {
      out.push([p[0], p[1]]);
    } else {
      let prev = out[out.length - 1];
      if ( hypot(p[0] - prev[0], p[1] - prev[1]) >= minDist ) {
        out.push([p[0], p[1]]);
      }
    }
  }
  if (out.length >= 3) {
    let first = out[0], last = out[out.length - 1];
    if (hypot(first[0] - last[0], first[1] - last[1]) < minDist) {
      out.pop();
    }
  }
  return out.length >= 3 ? out : [];
}

function hypot(dx, dy) {
  return Math.sqrt(dx * dx + dy * dy);
}

function polyCentroid(pts) {
  let sx = 0, sy = 0;
  for (let p of pts) { sx += p[0]; sy += p[1]; }
  return [sx / pts.length, sy / pts.length];
}

function polyBounds(pts) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (let p of pts) {
    if (p[0] < minX) minX = p[0];
    if (p[1] < minY) minY = p[1];
    if (p[0] > maxX) maxX = p[0];
    if (p[1] > maxY) maxY = p[1];
  }
  return { minX, minY, maxX, maxY, w: maxX - minX, h: maxY - minY };
}

function pointInPoly(x, y, vs) {
  let inside = false;
  for (let i = 0, j = vs.length - 1; i < vs.length; j = i++) {
    let xi = vs[i][0], yi = vs[i][1];
    let xj = vs[j][0], yj = vs[j][1];
    let intersect = ((yi > y) !== (yj > y)) &&
                    (x < (xj - xi) * (y - yi) / ((yj - yi) || 0.00001) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function insetPoly(pts, amount) {
  if (amount === 0) return pts;
  let [cx, cy] = polyCentroid(pts);
  return pts.map(p => {
    let dx = p[0] - cx, dy = p[1] - cy;
    let d = hypot(dx, dy);
    if (d < 0.001) return [p[0], p[1]];
    let scale = Math.max(0.2, (d - amount) / d);
    return [cx + dx * scale, cy + dy * scale];
  });
}

function addTessera(layer, stoneKey, rawPts, opts = {}) {
  let pts = cleanPoly(rawPts, opts.minDist || 1.1);
  if (pts.length < 3) return;
  let centroid = polyCentroid(pts);
  let bounds = polyBounds(pts);
  tesserae.push({
    layer,
    stoneKey,
    pts,
    centroid,
    bounds,
    curvature: opts.curvature ?? 0.04,
    veinAngle: opts.veinAngle ?? random(0, 180),
    veinPhase: opts.veinPhase ?? random(0, 100),
    seamWeight: opts.seamWeight ?? 0.34,
    bevel: opts.bevel ?? true,
    noVeins: opts.noVeins ?? false
  });
}

// =============================================================================
// LAYER 0: NERO MARQUINA SLAB & FLORENTINE GEOMETRIC BORDER
// =============================================================================

function buildTabletopAndBorder() {
  // Central Nero Marquina slab divided into 16 radial-octagonal fitted plates
  let cx = 600, cy = 600;
  let rInner = 155, rMid = 345, rOuter = 504;
  let nSec = 16;
  let neroKeys = ["nero_deep", "nero_mid", "nero_slate", "nero_deep", "nero_mid", "nero_deep", "nero_slate", "nero_mid"];

  for (let i = 0; i < nSec; i++) {
    let a0 = i * (360 / nSec);
    let a1 = (i + 1) * (360 / nSec);
    let sk1 = neroKeys[i % neroKeys.length];
    let sk2 = neroKeys[(i + 3) % neroKeys.length];

    // Inner ring of black marble plates
    let pIn = [
      [cx + rInner * cos(a0), cy + rInner * sin(a0)],
      [cx + rInner * cos(a1), cy + rInner * sin(a1)],
      [cx + rMid * cos(a1),   cy + rMid * sin(a1)],
      [cx + rMid * cos(a0),   cy + rMid * sin(a0)]
    ];
    addTessera(0, sk1, pIn, { curvature: 0, seamWeight: 0.3, bevel: false, veinAngle: 28 + (i % 3) * 6 });

    // Outer ring reaching to the border frame
    let pOut = [
      [cx + rMid * cos(a0),   cy + rMid * sin(a0)],
      [cx + rMid * cos(a1),   cy + rMid * sin(a1)],
      projectToSquare(cx, cy, a1, rOuter),
      projectToSquare(cx, cy, a0, rOuter)
    ];
    addTessera(0, sk2, pOut, { curvature: 0, seamWeight: 0.3, bevel: false, veinAngle: 30 - (i % 2) * 8 });
  }

  // Central socket under blood orange
  let centerPoly = [];
  for (let i = 0; i < 16; i++) {
    let a = i * (360 / 16);
    centerPoly.push([cx + rInner * cos(a), cy + rInner * sin(a)]);
  }
  addTessera(0, "nero_deep", centerPoly, { curvature: 0, seamWeight: 0.3, bevel: false, noVeins: true });

  // Four Florentine Corner Spandrels inside the central field (at corners of 96..1104)
  let cOff = 96;
  let corners = [
    { x: cOff,      y: cOff,      ang: 0 },
    { x: 1200-cOff, y: cOff,      ang: 90 },
    { x: 1200-cOff, y: 1200-cOff, ang: 180 },
    { x: cOff,      y: 1200-cOff, ang: 270 }
  ];
  for (let c of corners) {
    buildCornerSpandrel(c.x, c.y, c.ang);
  }

  // Outer Molding (0..34)
  let m0 = 0, m1 = 34;
  addTessera(0, "nero_deep",  [[m0,m0], [1200,m0], [1200-m1,m1], [m1,m1]], { curvature: 0, seamWeight: 0.4 });
  addTessera(0, "nero_slate", [[1200,m0], [1200,1200], [1200-m1,1200-m1], [1200-m1,m1]], { curvature: 0, seamWeight: 0.4 });
  addTessera(0, "nero_deep",  [[1200,1200], [m0,1200], [m1,1200-m1], [1200-m1,1200-m1]], { curvature: 0, seamWeight: 0.4 });
  addTessera(0, "nero_mid",   [[m0,1200], [m0,m0], [m1,m1], [m1,1200-m1]], { curvature: 0, seamWeight: 0.4 });

  // Outer Stringing Fillet (34..42) in Chalcedony Milk & Giallo Pastel
  buildFrameFillet(34, 42, "chalcedony_milk", "giallo_pastel");

  // Inner Stringing Fillet (88..96) in Giallo Pastel & Chalcedony Warm
  buildFrameFillet(88, 96, "giallo_pastel", "chalcedony_warm");

  // Four Corner Rosette Cartouches (42..88 at all 4 corners)
  let b0 = 42, b1 = 88;
  buildCornerRosette(b0, b0, b1, b1);
  buildCornerRosette(1200 - b1, b0, 1200 - b0, b1);
  buildCornerRosette(1200 - b1, 1200 - b1, 1200 - b0, 1200 - b0);
  buildCornerRosette(b0, 1200 - b1, b1, 1200 - b0);

  // Four Symmetric Side Frieze Bands (between 88 and 1112 along all 4 sides)
  buildSideFrieze(88, 42, 1112, 88, true);           // Top
  buildSideFrieze(88, 1112, 1112, 1158, true);       // Bottom
  buildSideFrieze(42, 88, 88, 1112, false);          // Left
  buildSideFrieze(1112, 88, 1158, 1112, false);      // Right
}

function projectToSquare(cx, cy, ang, halfSize) {
  let c = cos(ang), s = sin(ang);
  let scale = halfSize / Math.max(Math.abs(c), Math.abs(s));
  return [cx + c * scale, cy + s * scale];
}

function buildFrameFillet(r0, r1, stoneA, stoneB) {
  let segs = 8;
  let span = (1200 - 2 * r1) / segs;
  for (let i = 0; i < segs; i++) {
    let st = i % 2 === 0 ? stoneA : stoneB;
    let xA = r1 + i * span, xB = r1 + (i + 1) * span;
    // Top
    addTessera(0, st, [[xA, r0], [xB, r0], [xB, r1], [xA, r1]], { curvature: 0, seamWeight: 0.3, noVeins: true });
    // Bottom
    addTessera(0, st, [[xA, 1200-r1], [xB, 1200-r1], [xB, 1200-r0], [xA, 1200-r0]], { curvature: 0, seamWeight: 0.3, noVeins: true });
    // Left
    addTessera(0, st, [[r0, xA], [r1, xA], [r1, xB], [r0, xB]], { curvature: 0, seamWeight: 0.3, noVeins: true });
    // Right
    addTessera(0, st, [[1200-r1, xA], [1200-r0, xA], [1200-r0, xB], [1200-r1, xB]], { curvature: 0, seamWeight: 0.3, noVeins: true });
  }
  // 4 corners of the fillet
  addTessera(0, stoneA, [[r0,r0],[r1,r0],[r1,r1],[r0,r1]], { curvature: 0, seamWeight: 0.3, noVeins: true });
  addTessera(0, stoneA, [[1200-r1,r0],[1200-r0,r0],[1200-r0,r1],[1200-r1,r1]], { curvature: 0, seamWeight: 0.3, noVeins: true });
  addTessera(0, stoneA, [[1200-r1,1200-r1],[1200-r0,1200-r1],[1200-r0,1200-r0],[1200-r1,1200-r0]], { curvature: 0, seamWeight: 0.3, noVeins: true });
  addTessera(0, stoneA, [[r0,1200-r1],[r1,1200-r1],[r1,1200-r0],[r0,1200-r0]], { curvature: 0, seamWeight: 0.3, noVeins: true });
}

function buildCornerRosette(x0, y0, x1, y1) {
  let cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
  let r = (x1 - x0) / 2;
  // Background square in Lapis Royal
  addTessera(0, "lapis_royal", [[x0,y0],[x1,y0],[x1,y1],[x0,y1]], { curvature: 0, seamWeight: 0.35 });
  // Inlaid diamond in Carnelian Peach
  let dPts = [[cx, y0+3], [x1-3, cy], [cx, y1-3], [x0+3, cy]];
  addTessera(0, "carnelian_peach", dPts, { curvature: 0, seamWeight: 0.35 });
  // Central Chalcedony & Malachite 8-sided cabochon
  let oct = [];
  for (let i = 0; i < 8; i++) {
    let a = i * 45 + 22.5;
    oct.push([cx + r * 0.46 * cos(a), cy + r * 0.46 * sin(a)]);
  }
  addTessera(0, "malachite_mint", oct, { curvature: 0.05, seamWeight: 0.32 });
  let inner = [];
  for (let i = 0; i < 8; i++) {
    let a = i * 45;
    inner.push([cx + r * 0.22 * cos(a), cy + r * 0.22 * sin(a)]);
  }
  addTessera(0, "chalcedony_pure", inner, { curvature: 0.08, seamWeight: 0.3, noVeins: true });
}

function buildSideFrieze(x0, y0, x1, y1, isHoriz) {
  let nPanels = 9;
  let panelStones = [
    "malachite_mint", "lapis_pastel", "carnelian_blush", "violane_lavender",
    "jasper_coral_red",
    "violane_lavender", "carnelian_blush", "lapis_pastel", "malachite_mint"
  ];
  let accentStones = [
    "lapis_periwinkle", "malachite_sage", "rose_quartz", "giallo_pastel",
    "chalcedony_pure",
    "giallo_pastel", "rose_quartz", "malachite_sage", "lapis_periwinkle"
  ];

  for (let i = 0; i < nPanels; i++) {
    let t0 = i / nPanels, t1 = (i + 1) / nPanels;
    let px0 = isHoriz ? lerp(x0, x1, t0) : x0;
    let px1 = isHoriz ? lerp(x0, x1, t1) : x1;
    let py0 = isHoriz ? y0 : lerp(y0, y1, t0);
    let py1 = isHoriz ? y1 : lerp(y0, y1, t1);
    let cx = (px0 + px1) / 2, cy = (py0 + py1) / 2;

    // Dark surround tablet
    addTessera(0, "nero_slate", [[px0,py0],[px1,py0],[px1,py1],[px0,py1]], { curvature: 0, seamWeight: 0.35, noVeins: true });

    // Inset chamfered tablet of pastel mineral stone
    let m = 5;
    let ch = 8;
    let octTablet = [
      [px0 + m + ch, py0 + m],
      [px1 - m - ch, py0 + m],
      [px1 - m, py0 + m + ch],
      [px1 - m, py1 - m - ch],
      [px1 - m - ch, py1 - m],
      [px0 + m + ch, py1 - m],
      [px0 + m, py1 - m - ch],
      [px0 + m, py0 + m + ch]
    ];
    addTessera(0, panelStones[i], octTablet, { curvature: 0, seamWeight: 0.34, veinAngle: i * 35 });

    // Central lozenge inlay inside tablet
    let lw = (px1 - px0) * 0.24, lh = (py1 - py0) * 0.24;
    let loz = [[cx, cy - lh], [cx + lw, cy], [cx, cy + lh], [cx - lw, cy]];
    addTessera(0, accentStones[i], loz, { curvature: 0.04, seamWeight: 0.3 });
  }
}

function buildCornerSpandrel(vx, vy, baseAng) {
  function tr(dx, dy) {
    let c = cos(baseAng), s = sin(baseAng);
    return [vx + dx * c - dy * s, vy + dx * s + dy * c];
  }
  let L = 128;
  // Outer triangle bracket in Giallo Pastel & Lapis Periwinkle
  let pOuter = [tr(0, 0), tr(L, 0), tr(L * 0.68, L * 0.32), tr(L * 0.32, L * 0.68), tr(0, L)];
  addTessera(0, "lapis_periwinkle", pOuter, { curvature: 0.04, seamWeight: 0.36 });

  let pInner = [tr(0, 0), tr(L * 0.72, 0), tr(L * 0.42, L * 0.42), tr(0, L * 0.72)];
  addTessera(0, "nero_deep", pInner, { curvature: 0, seamWeight: 0.34 });

  // Inlaid Florentine lily-bud in corner
  let petalC = [tr(8, 8), tr(42, 16), tr(62, 62), tr(16, 42)];
  addTessera(0, "rose_quartz", petalC, { curvature: 0.12, seamWeight: 0.32 });

  let leafA = [tr(12, 5), tr(68, 8), tr(46, 22), tr(20, 14)];
  addTessera(0, "malachite_mint", leafA, { curvature: 0.1, seamWeight: 0.32 });

  let leafB = [tr(5, 12), tr(14, 20), tr(22, 46), tr(8, 68)];
  addTessera(0, "malachite_mint", leafB, { curvature: 0.1, seamWeight: 0.32 });

  let tip = [tr(48, 48), tr(72, 56), tr(80, 80), tr(56, 72)];
  addTessera(0, "chalcedony_pure", tip, { curvature: 0.1, seamWeight: 0.3 });
}

// =============================================================================
// LAYER 1: INLAID MALACHITE FIG & CITRUS LEAVES (4 DIAGONAL AXES)
// =============================================================================

function buildAllMalachiteLeaves() {
  let diags = [45, 135, 225, 315];
  for (let d = 0; d < 4; d++) {
    let ang = diags[d];
    buildMalachiteLeafCluster(600, 600, ang);
  }
}

function buildMalachiteLeafCluster(cx, cy, axisAng) {
  function toWorld(r, lateral) {
    let c = cos(axisAng), s = sin(axisAng);
    return [cx + r * c - lateral * s, cy + r * s + lateral * c];
  }

  // Contact shadow on the Nero Marquina slab
  let shPts = [
    toWorld(155, -35), toWorld(270, -108), toWorld(385, -82),
    toWorld(455, 6),   toWorld(385, 92),   toWorld(270, 114), toWorld(155, 42)
  ].map(p => [p[0] + 6, p[1] + 6]);
  addTessera(1, "obsidian_shadow", shPts, { curvature: 0.12, seamWeight: 0.2, bevel: false, noVeins: true });

  // Central Three-Lobed Malachite Leaf subdivided into 10 chevron tesserae along lateral veins
  let rSteps = [156, 215, 275, 335, 392, 446];
  let widths = [28,  98,  72,  84,  48,  4];
  let stonesL = ["malachite_deep", "malachite_mid", "malachite_sage", "malachite_mint", "serpentine_pistachio"];
  let stonesR = ["malachite_mid", "malachite_sage", "malachite_mint", "malachite_sage", "malachite_mint"];

  for (let i = 0; i < rSteps.length - 1; i++) {
    let r0 = rSteps[i], r1 = rSteps[i + 1];
    let rMid = (r0 + r1) * 0.5;
    let w0 = widths[i], w1 = widths[i + 1];
    let wNotch = (w0 + w1) * 0.5 + (i === 1 || i === 3 ? 16 : -10);
    let veinShift = 18; // chevron slant of lateral leaf veins

    // Left blade tessera
    let pL = [
      toWorld(r0, -2.2),
      toWorld(r0 + veinShift, -w0),
      toWorld(rMid + veinShift, -wNotch),
      toWorld(r1 + (i === rSteps.length - 2 ? 0 : veinShift), -w1),
      toWorld(r1, -1.5)
    ];
    addTessera(1, stonesL[i], pL, {
      curvature: 0.08,
      seamWeight: 0.36,
      veinAngle: axisAng - 42 + i * 15
    });

    // Right blade tessera
    let pR = [
      toWorld(r0, 2.2),
      toWorld(r1, 1.5),
      toWorld(r1 + (i === rSteps.length - 2 ? 0 : veinShift), w1),
      toWorld(rMid + veinShift, wNotch),
      toWorld(r0 + veinShift, w0)
    ];
    addTessera(1, stonesR[i], pR, {
      curvature: 0.08,
      seamWeight: 0.36,
      veinAngle: axisAng + 42 - i * 15
    });
  }

  // Central inlaid midrib vein in Serpentine Pistachio & Chalcedony Warm
  let ribPts = [
    toWorld(152, -3.2), toWorld(310, -2.2), toWorld(444, 0),
    toWorld(310, 2.2),  toWorld(152, 3.2)
  ];
  addTessera(1, "serpentine_pistachio", ribPts, { curvature: 0.02, seamWeight: 0.3, noVeins: true });

  // Two smaller flanking Citrus Leaves at axisAng ± 23°
  for (let side of [-1, 1]) {
    let subAng = axisAng + side * 23;
    buildSmallCitrusLeaf(cx, cy, subAng, 175, 335, side);
  }
}

function buildSmallCitrusLeaf(cx, cy, ang, rStart, rEnd, side) {
  function tr(r, lat) {
    let c = cos(ang), s = sin(ang);
    return [cx + r * c - lat * s, cy + r * s + lat * c];
  }
  let rMid = (rStart + rEnd) * 0.52;
  let wMax = 34;

  // Base half
  let pL1 = [tr(rStart, 0), tr(rStart + 25, -wMax * 0.7), tr(rMid, -wMax), tr(rMid - 12, 0)];
  let pR1 = [tr(rStart, 0), tr(rMid - 12, 0), tr(rMid, wMax), tr(rStart + 25, wMax * 0.7)];
  // Tip half
  let pL2 = [tr(rMid - 12, 0), tr(rMid, -wMax), tr(rEnd - 24, -wMax * 0.45), tr(rEnd, 0)];
  let pR2 = [tr(rMid - 12, 0), tr(rEnd, 0), tr(rEnd - 24, wMax * 0.45), tr(rMid, wMax)];

  addTessera(1, side > 0 ? "malachite_deep" : "malachite_mid", pL1, { curvature: 0.08, seamWeight: 0.34, veinAngle: ang - 35 });
  addTessera(1, "malachite_sage", pR1, { curvature: 0.08, seamWeight: 0.34, veinAngle: ang + 35 });
  addTessera(1, "malachite_mint", pL2, { curvature: 0.08, seamWeight: 0.34, veinAngle: ang - 25 });
  addTessera(1, "serpentine_pistachio", pR2, { curvature: 0.08, seamWeight: 0.34, veinAngle: ang + 25 });
}

// =============================================================================
// LAYER 2 & 3: CENTRAL HALVED BLOOD ORANGE (AT 600, 600)
// =============================================================================

function buildCentralBloodOrange(cx, cy) {
  let nRind = 20;
  let ringShadow = [];
  let ringZest = [];
  let ringPithOut = [];
  let ringPithIn = [];

  for (let i = 0; i < nRind; i++) {
    let a = i * (360 / nRind);
    let wobble1 = 2.2 * sin(a * 3) + 1.5 * cos(a * 5);
    let wobble2 = 1.8 * cos(a * 4) + 1.2 * sin(a * 7);
    let rZ = 164 + wobble1;
    let rPO = 153 + wobble2;
    // Every 2nd vertex is a carpel septum root dipping inward
    let isSeptum = (i % 2 === 0);
    let rPI = (isSeptum ? 128 : 138) + 1.6 * sin(a * 3);

    ringShadow.push([cx + 7 + (rZ + 2) * cos(a), cy + 7 + (rZ + 2) * sin(a)]);
    ringZest.push([cx + rZ * cos(a), cy + rZ * sin(a)]);
    ringPithOut.push([cx + rPO * cos(a), cy + rPO * sin(a)]);
    ringPithIn.push([cx + rPI * cos(a), cy + rPI * sin(a)]);
  }

  // Contact shadow on slab
  addTessera(2, "obsidian_shadow", ringShadow, { curvature: 0.1, seamWeight: 0.2, bevel: false, noVeins: true });

  // 20 Outer Zest tesserae (Carnelian & Tangerine Agate) and 20 White Pith tesserae (Chalcedony)
  let zestStones = ["carnelian_deep", "carnelian_warm", "carnelian_peach", "carnelian_warm"];
  let pithStones = ["chalcedony_pure", "chalcedony_milk", "chalcedony_warm", "chalcedony_milk"];

  for (let i = 0; i < nRind; i++) {
    let ni = (i + 1) % nRind;
    let zPoly = [ringZest[i], ringZest[ni], ringPithOut[ni], ringPithOut[i]];
    addTessera(2, zestStones[i % zestStones.length], zPoly, {
      curvature: 0.05,
      seamWeight: 0.36,
      veinAngle: i * 18 + 90
    });

    let pPoly = [ringPithOut[i], ringPithOut[ni], ringPithIn[ni], ringPithIn[i]];
    addTessera(2, pithStones[i % pithStones.length], pPoly, {
      curvature: 0.04,
      seamWeight: 0.32,
      veinAngle: i * 18
    });
  }

  // Central Pith Core (Columella)
  let rCoreOut = 21, rCoreIn = 8;
  let coreOutPts = [], coreInPts = [];
  for (let s = 0; s < 10; s++) {
    let a = s * 36;
    let aMid = a + 18;
    coreOutPts.push([cx + (rCoreOut + 3) * cos(a), cy + (rCoreOut + 3) * sin(a)]);
    coreOutPts.push([cx + (rCoreOut - 2) * cos(aMid), cy + (rCoreOut - 2) * sin(aMid)]);
    coreInPts.push([cx + rCoreIn * cos(a), cy + rCoreIn * sin(a)]);
  }
  for (let i = 0; i < 10; i++) {
    let i2 = i * 2;
    let ni2 = (i2 + 2) % 20;
    let ni = (i + 1) % 10;
    let cWedge = [coreInPts[i], coreOutPts[i2], coreOutPts[i2 + 1], coreOutPts[ni2], coreInPts[ni]];
    addTessera(2, i % 2 === 0 ? "chalcedony_pure" : "chalcedony_milk", cWedge, {
      curvature: 0.04,
      seamWeight: 0.3
    });
  }
  addTessera(2, "chalcedony_warm", coreInPts, { curvature: 0.08, seamWeight: 0.3 });

  // 10 Septa Membranes + 10 Segments packed with individual Juice Vesicles
  for (let s = 0; s < 10; s++) {
    let i0 = s * 2;
    let i1 = s * 2 + 1;
    let i2 = (s * 2 + 2) % nRind;

    let aStart = s * 36;
    let aEnd = (s + 1) * 36;
    let sepHalfAng = 1.15; // Angular half-width of chalcedony septum wall

    // Radial Septum Wall at aStart
    let sepPoly = [
      [cx + rCoreOut * cos(aStart - sepHalfAng), cy + rCoreOut * sin(aStart - sepHalfAng)],
      [cx + rCoreOut * cos(aStart + sepHalfAng), cy + rCoreOut * sin(aStart + sepHalfAng)],
      [ringPithIn[i0][0] + 2.2 * cos(aStart + 90), ringPithIn[i0][1] + 2.2 * sin(aStart + 90)],
      [ringPithIn[i0][0] - 2.2 * cos(aStart + 90), ringPithIn[i0][1] - 2.2 * sin(aStart + 90)]
    ];
    addTessera(2, "chalcedony_milk", sepPoly, { curvature: 0.02, seamWeight: 0.3, noVeins: true });

    // Build packed cellular lattice of Juice Vesicles inside Segment s
    buildBloodOrangeSegmentVesicles(
      cx, cy, s,
      aStart + sepHalfAng,
      aEnd - sepHalfAng,
      rCoreOut,
      ringPithIn[i0],
      ringPithIn[i1],
      ringPithIn[i2]
    );
  }
}

function buildBloodOrangeSegmentVesicles(cx, cy, segIdx, a0, a1, rIn, pOuter0, pOuterMid, pOuter1) {
  // 4 radial tiers × 4 angular columns = 16 watertight spindle-shaped juice vesicles per carpel
  let nR = 4, nA = 4;
  let rFracs = [0.0, 0.24, 0.50, 0.76, 1.0];

  // Outer boundary point helper along the 2-segment pith arc
  function outerPt(u) {
    let a = lerp(a0, a1, u);
    // Interpolate radius smoothly from pOuter0 -> pOuterMid -> pOuter1
    let r0 = hypot(pOuter0[0] - cx, pOuter0[1] - cy);
    let rM = hypot(pOuterMid[0] - cx, pOuterMid[1] - cy);
    let r1 = hypot(pOuter1[0] - cx, pOuter1[1] - cy);
    let rOut = u < 0.5 ? lerp(r0, rM, u * 2) : lerp(rM, r1, (u - 0.5) * 2);
    // Slight inward cushion for membrane
    rOut -= 1.5;
    return [cx + rOut * cos(a), cy + rOut * sin(a), rOut, a];
  }

  // Construct 2D vertex grid [j][k]
  let grid = [];
  for (let j = 0; j <= nR; j++) {
    let row = [];
    let rf = rFracs[j];
    for (let k = 0; k <= nA; k++) {
      let u = k / nA;
      // Add organic cellular jitter to interior vertices
      let jR = 0, jU = 0;
      if (j > 0 && j < nR && k > 0 && k < nA) {
        jR = (noise(segIdx * 10 + j * 3, k * 3) - 0.5) * 7.5;
        jU = (noise(segIdx * 10 + k * 5, j * 5) - 0.5) * 0.08;
      }
      let uAdj = constrain(u + jU, 0.02, 0.98);
      if (k === 0) uAdj = 0;
      if (k === nA) uAdj = 1;

      let [, , rOut, ang] = outerPt(uAdj);
      let r = lerp(rIn + 1.5, rOut, rf) + jR;
      row.push([cx + r * cos(ang), cy + r * sin(ang)]);
    }
    grid.push(row);
  }

  // Color progression for blood orange vesicles (Moro garnet/crimson at outer rind -> coral/blush near core)
  let tierPalettes = [
    ["carnelian_blush", "carnelian_peach", "rose_quartz", "giallo_pastel"],
    ["carnelian_warm", "jasper_coral_red", "carnelian_peach", "jasper_pastel_rose"],
    ["jasper_crimson", "jasper_coral_red", "carnelian_deep", "jasper_garnet"],
    ["jasper_moro", "jasper_garnet", "jasper_crimson", "jasper_moro"]
  ];

  let hasSeed = (segIdx === 1 || segIdx === 3 || segIdx === 6 || segIdx === 8);

  for (let j = 0; j < nR; j++) {
    for (let k = 0; k < nA; k++) {
      // If this inner cell holds a cut citrus seed, render a 3-piece seed inlay
      if (hasSeed && j === 0 && (k === 1 || k === 2)) {
        if (k === 1) {
          let sPoly = [
            grid[0][1], grid[0][3],
            grid[1][3], grid[1][2], grid[1][1]
          ];
          buildInlaidCitrusSeed(sPoly, segIdx * 36 + 18);
        }
        continue;
      }

      let p00 = grid[j][k];
      let p10 = grid[j + 1][k];
      let p11 = grid[j + 1][k + 1];
      let p01 = grid[j][k + 1];

      // Midpoints along radial sides to give each vesicle a plump spindle/teardrop contour
      let mL = [(p00[0] + p10[0]) * 0.5, (p00[1] + p10[1]) * 0.5];
      let mR = [(p01[0] + p11[0]) * 0.5, (p01[1] + p11[1]) * 0.5];

      let pal = tierPalettes[j];
      let stoneKey = pal[(segIdx + k * 2 + j) % pal.length];

      // Determine whether this vesicle has a razor-sharp white chalcedony specular glint facet
      let hasGlint = ((j === 2 && k === (segIdx % 2 === 0 ? 1 : 2)) ||
                      (j === 1 && k === 2 && segIdx % 3 === 0));

      if (hasGlint) {
        // Split off a crisp geometric specular highlight sliver in the upper-left corner of the vesicle
        let gPt1 = [lerp(p00[0], p10[0], 0.65), lerp(p00[1], p10[1], 0.65)];
        let gPt2 = [lerp(p10[0], p11[0], 0.55), lerp(p10[1], p11[1], 0.55)];
        let gPt3 = [lerp(p00[0], p11[0], 0.48), lerp(p00[1], p11[1], 0.48)];

        let glintPoly = [gPt1, p10, gPt2, gPt3];
        let bodyPoly  = [p00, gPt1, gPt3, gPt2, p11, mR, p01];

        addTessera(3, stoneKey, bodyPoly, {
          curvature: 0.08,
          seamWeight: 0.3,
          veinAngle: segIdx * 36 + 18
        });
        addTessera(4, (segIdx + j) % 2 === 0 ? "chalcedony_pure" : "chalcedony_pearl", glintPoly, {
          curvature: 0.02,
          seamWeight: 0.28,
          noVeins: true
        });
      } else {
        let vesPoly = [p00, mL, p10, p11, mR, p01];
        addTessera(3, stoneKey, vesPoly, {
          curvature: 0.09,
          seamWeight: 0.3,
          veinAngle: segIdx * 36 + 18 + (k - 1.5) * 8
        });
      }
    }
  }
}

function buildInlaidCitrusSeed(outerQuad, ang) {
  let [cx, cy] = polyCentroid(outerQuad);
  // Outer ivory chalcedony seed husk
  addTessera(3, "chalcedony_pure", outerQuad, { curvature: 0.12, seamWeight: 0.34, veinAngle: ang });
  // Inner pistachio/citrine cotyledon kernel
  let innerKernel = insetPoly(outerQuad, 3.2);
  addTessera(4, "citrine_pale", innerKernel, { curvature: 0.12, seamWeight: 0.28, veinAngle: ang + 45 });
}

// =============================================================================
// LAYER 2, 3 & 4: FOUR SYMMETRIC SPLIT FIGS (CARDINAL AXES)
// =============================================================================

function buildAllSplitFigs() {
  // Placed symmetrically along the 4 cardinal axes: Top, Right, Bottom, Left
  // Plump ruby bottoms facing inward toward the blood orange, tapered necks & stems pointing outward
  let figSpecs = [
    { cx: 600, cy: 262, rot: 0   }, // Top fig (neck at -Y pointing up to top border)
    { cx: 938, cy: 600, rot: 90  }, // Right fig (neck pointing right)
    { cx: 600, cy: 938, rot: 180 }, // Bottom fig (neck pointing down)
    { cx: 262, cy: 600, rot: 270 }  // Left fig (neck pointing left)
  ];

  for (let i = 0; i < figSpecs.length; i++) {
    let f = figSpecs[i];
    buildSplitFig(f.cx, f.cy, f.rot, i);
  }
}

function figLocalPoint(theta, rScale, neckScale = 1.0) {
  // theta = -90 is narrow stem neck (pointing outward), theta = +90 is plump bottom ostiole
  let s = sin(theta), c = cos(theta);
  let wFactor;
  if (s < 0) {
    // Graceful pyriform concave waist tapering into the fig neck
    wFactor = (0.19 * neckScale) + (1.0 - 0.19 * neckScale) * Math.pow(1.0 + s, 1.55);
  } else {
    // Plump lower globe of the fig
    wFactor = 1.0 - 0.10 * Math.pow(s, 2.2);
  }
  let rx = 76 * wFactor * rScale;
  let ry = (s < 0 ? 94 : 74) * (0.15 + 0.85 * rScale);
  // Shift interior center slightly downward into the plump belly of the fig
  let yCenterShift = (1.0 - rScale) * 14;
  return [c * rx, yCenterShift + s * ry];
}

function buildSplitFig(cx, cy, rotAng, figIdx) {
  function toWorld(lx, ly) {
    let c = cos(rotAng), s = sin(rotAng);
    return [cx + lx * c - ly * s, cy + lx * s + ly * c];
  }

  let M = 20; // Angular subdivisions around the pyriform contour
  let ringShadow = [];
  let ringSkinOut = [];
  let ringPithOut = [];
  let ringFleshOut = [];
  let ringFleshMid = [];
  let ringCore = [];

  for (let i = 0; i < M; i++) {
    let theta = -90 + i * (360 / M);
    let wob = 1.4 * sin(theta * 4 + figIdx * 45);

    let pSO = figLocalPoint(theta, 1.00, 1.0);
    let pPO = figLocalPoint(theta, 0.89, 0.85);
    let pFO = figLocalPoint(theta, 0.76, 0.65);
    let pFM = figLocalPoint(theta, 0.49, 0.45);
    let pCO = figLocalPoint(theta, 0.18, 0.35);

    let wSO = toWorld(pSO[0] + wob, pSO[1] + wob);
    ringShadow.push([wSO[0] + 6, wSO[1] + 6]);
    ringSkinOut.push(wSO);
    ringPithOut.push(toWorld(pPO[0], pPO[1]));
    ringFleshOut.push(toWorld(pFO[0], pFO[1]));
    ringFleshMid.push(toWorld(pFM[0], pFM[1]));
    ringCore.push(toWorld(pCO[0], pCO[1]));
  }

  // Contact shadow on Nero Marquina slab
  addTessera(2, "obsidian_shadow", ringShadow, { curvature: 0.1, seamWeight: 0.2, bevel: false, noVeins: true });

  // Curved Malachite Peduncle (Stem) at the neck (theta = -90, i = 0)
  let stBaseL = toWorld(-14, -90), stBaseR = toWorld(14, -90);
  let stMidL  = toWorld(-9, -108), stMidR  = toWorld(11, -106);
  let stTipL  = toWorld(2,  -124), stTipR  = toWorld(16, -118);
  addTessera(2, "malachite_sage", [stBaseL, stBaseR, stMidR, stMidL], { curvature: 0.08, seamWeight: 0.34, veinAngle: rotAng });
  addTessera(2, "malachite_mid",  [stMidL, stMidR, stTipR, stTipL],   { curvature: 0.08, seamWeight: 0.34, veinAngle: rotAng + 35 });

  // Ring 1: Outer Lapis, Violane & Damson Porphyry Skin + Ring 2: Creamy Chalcedony Inner Rind
  let skinPalette = [
    "malachite_sage", "lapis_pastel", "violane_lavender", "lapis_periwinkle", "violane_plum",
    "lapis_royal", "porphyry_damson", "lapis_royal", "violane_plum", "jasper_pastel_rose",
    "rose_quartz", "violane_plum", "lapis_royal", "porphyry_damson", "lapis_royal",
    "violane_plum", "lapis_periwinkle", "violane_lavender", "lapis_pastel", "malachite_mint"
  ];
  let pithPalette = ["chalcedony_pure", "chalcedony_milk", "chalcedony_warm", "chalcedony_milk"];

  // Ring 3 & Ring 4: Jammy Syconium Flesh (Pastel Rose Quartz outer florets -> Crimson & Garnet inner cavity)
  let outerFleshPal = ["rose_quartz", "carnelian_blush", "jasper_pastel_rose", "carnelian_peach"];
  let innerFleshPal = ["jasper_crimson", "jasper_coral_red", "jasper_garnet", "jasper_moro", "jasper_crimson"];

  for (let i = 0; i < M; i++) {
    let ni = (i + 1) % M;

    // 1. Skin tessera
    let skinPoly = [ringSkinOut[i], ringSkinOut[ni], ringPithOut[ni], ringPithOut[i]];
    addTessera(2, skinPalette[i], skinPoly, {
      curvature: 0.06,
      seamWeight: 0.36,
      veinAngle: rotAng + i * 18
    });

    // 2. White Chalcedony inner rind (mesocarp)
    let pithPoly = [ringPithOut[i], ringPithOut[ni], ringFleshOut[ni], ringFleshOut[i]];
    addTessera(2, pithPalette[i % pithPalette.length], pithPoly, {
      curvature: 0.05,
      seamWeight: 0.32,
      veinAngle: rotAng + i * 18 + 45
    });

    // 3. Outer syconium flesh ring (radiating pastel rose & blush carnelian florets)
    let fOutPoly = [ringFleshOut[i], ringFleshOut[ni], ringFleshMid[ni], ringFleshMid[i]];
    addTessera(3, outerFleshPal[(i + figIdx) % outerFleshPal.length], fOutPoly, {
      curvature: 0.07,
      seamWeight: 0.3,
      veinAngle: rotAng + i * 18
    });

    // 4. Inner jammy cavity ring (deep crimson, coral & garnet jasper florets)
    let fInPoly = [ringFleshMid[i], ringFleshMid[ni], ringCore[ni], ringCore[i]];
    addTessera(3, innerFleshPal[(i + figIdx * 2) % innerFleshPal.length], fInPoly, {
      curvature: 0.07,
      seamWeight: 0.3,
      veinAngle: rotAng + i * 18
    });

    // 5. Inlaid Golden Citrine Fig Seeds (Achenes) & White Chalcedony Syrup Glints
    // Skip the very narrow top neck indices (i = 0, 19)
    if (i >= 2 && i <= 18) {
      let seedPt = ringFleshMid[i];
      if (i % 3 === 1) {
        // Crisp white chalcedony specular glint sliver on the wet fig jelly
        let gPoly = makeDiamondFacet(seedPt[0], seedPt[1], 5.5, 3.2, rotAng + i * 18);
        addTessera(4, i % 2 === 0 ? "chalcedony_pure" : "chalcedony_pearl", gPoly, {
          curvature: 0.02,
          seamWeight: 0.28,
          noVeins: true
        });
      } else {
        // Plump golden-amber fig achene seed
        let sPoly = makeSeedDroplet(seedPt[0], seedPt[1], 4.2, rotAng + i * 18 + 90);
        let seedStone = (i % 2 === 0) ? "citrine_pale" : "giallo_pastel";
        addTessera(4, seedStone, sPoly, {
          curvature: 0.12,
          seamWeight: 0.28,
          noVeins: true
        });
      }

      // Inner ring of seeds & glints near the syconium hollow
      if (i % 2 === 0 && i >= 3 && i <= 17) {
        let inPt = [
          lerp(ringFleshMid[i][0], ringCore[i][0], 0.55),
          lerp(ringFleshMid[i][1], ringCore[i][1], 0.55)
        ];
        if (i === 6 || i === 12 || i === 16) {
          let gPoly2 = makeDiamondFacet(inPt[0], inPt[1], 6.2, 3.0, rotAng + i * 18 + 20);
          addTessera(4, "chalcedony_pure", gPoly2, { curvature: 0.02, seamWeight: 0.26, noVeins: true });
        } else {
          let sPoly2 = makeSeedDroplet(inPt[0], inPt[1], 3.8, rotAng + i * 18);
          addTessera(4, "giallo_amber", sPoly2, { curvature: 0.12, seamWeight: 0.26, noVeins: true });
        }
      }
    }
  }

  // Central jammy syconium hollow divided into 4 dark ruby-garnet pieces
  let [ccx, ccy] = polyCentroid(ringCore);
  for (let q = 0; q < 4; q++) {
    let idx0 = q * 5;
    let subCore = [[ccx, ccy]];
    for (let k = 0; k <= 5; k++) {
      subCore.push(ringCore[(idx0 + k) % M]);
    }
    addTessera(3, q % 2 === 0 ? "jasper_moro" : "jasper_garnet", subCore, {
      curvature: 0.06,
      seamWeight: 0.3
    });
  }
}

function makeDiamondFacet(x, y, rx, ry, ang) {
  let c = cos(ang), s = sin(ang);
  function tr(lx, ly) { return [x + lx * c - ly * s, y + lx * s + ly * c]; }
  return [tr(-rx, 0), tr(0, -ry), tr(rx, 0), tr(0, ry * 0.85)];
}

function makeSeedDroplet(x, y, r, ang) {
  let c = cos(ang), s = sin(ang);
  function tr(lx, ly) { return [x + lx * c - ly * s, y + lx * s + ly * c]; }
  return [
    tr(-r * 1.25, 0),
    tr(-r * 0.3, -r * 0.78),
    tr(r * 0.85, -r * 0.52),
    tr(r * 1.15, 0),
    tr(r * 0.85, r * 0.52),
    tr(-r * 0.3, r * 0.78)
  ];
}

// =============================================================================
// LAYER 4 & 5: POMEGRANATE SEEDS (ARILS) & INLAID PITH SHARDS
// =============================================================================

function buildAllPomegranateClusters() {
  // 1. Four opulent diagonal clusters of pomegranate arils + curled white pith shards
  let diagAngles = [45, 135, 225, 315];

  // Relative offsets (r, lateral, radius, rot, variant) for each symmetric diagonal cluster
  let clusterLayout = [
    { r: 222, lat: -36, rad: 13.5, rot: 15,  v: 0 },
    { r: 222, lat:  36, rad: 13.5, rot: -20, v: 1 },
    { r: 252, lat: -14, rad: 14.5, rot: 40,  v: 2 },
    { r: 254, lat:  16, rad: 14.0, rot: -35, v: 3 },
    { r: 278, lat: -42, rad: 13.0, rot: 10,  v: 1 },
    { r: 280, lat:  42, rad: 13.0, rot: 65,  v: 0 },
    { r: 284, lat:   0, rad: 15.0, rot: -10, v: 2 },
    { r: 312, lat: -22, rad: 13.5, rot: 25,  v: 3 },
    { r: 312, lat:  24, rad: 13.5, rot: -45, v: 1 },
    { r: 340, lat: -48, rad: 12.5, rot: 50,  v: 0 },
    { r: 340, lat:  48, rad: 12.5, rot: -15, v: 2 },
    { r: 345, lat:   2, rad: 13.5, rot: 30,  v: 3 },
    { r: 375, lat: -20, rad: 12.0, rot: -25, v: 1 },
    { r: 375, lat:  20, rad: 12.0, rot: 40,  v: 0 }
  ];

  // Escaped jewel arils resting directly on the polished Nero Marquina slab
  let looseArils = [
    { r: 418, lat: -128, rad: 13.0, rot: 22,  v: 2 },
    { r: 418, lat:  128, rad: 13.0, rot: -35, v: 0 },
    { r: 448, lat: -108, rad: 11.8, rot: 55,  v: 1 },
    { r: 448, lat:  108, rad: 11.8, rot: -18, v: 3 },
    { r: 196, lat: -68,  rad: 12.2, rot: 12,  v: 0 },
    { r: 196, lat:  68,  rad: 12.2, rot: -28, v: 2 }
  ];

  for (let d = 0; d < 4; d++) {
    let ang = diagAngles[d];
    let c = cos(ang), s = sin(ang);
    function toWorld(r, lat) {
      return [600 + r * c - lat * s, 600 + r * s + lat * c];
    }

    // Curled cream pomegranate pith/membrane shards nestled under the aril cluster
    let pithShard1 = [
      toWorld(236, -62), toWorld(268, -74), toWorld(298, -58),
      toWorld(292, -44), toWorld(264, -56), toWorld(240, -48)
    ];
    let pithShard2 = [
      toWorld(236, 62), toWorld(240, 48), toWorld(264, 56),
      toWorld(292, 44), toWorld(298, 58), toWorld(268, 74)
    ];
    addTessera(4, "chalcedony_warm", pithShard1, { curvature: 0.1, seamWeight: 0.32, veinAngle: ang });
    addTessera(4, "citrine_pale",    pithShard2, { curvature: 0.1, seamWeight: 0.32, veinAngle: ang + 40 });

    // Build main cluster arils
    for (let item of clusterLayout) {
      let [ax, ay] = toWorld(item.r, item.lat);
      buildPomegranateAril(ax, ay, item.rad, ang + item.rot, (item.v + d) % 4);
    }

    // Build loose escaped arils on the black slab
    for (let item of looseArils) {
      let [ax, ay] = toWorld(item.r, item.lat);
      buildPomegranateAril(ax, ay, item.rad, ang + item.rot, (item.v + d) % 4);
    }
  }
}

function buildPomegranateAril(ax, ay, rad, rotAng, variant) {
  let c = cos(rotAng), s = sin(rotAng);
  function tr(lx, ly) {
    return [ax + lx * c - ly * s, ay + lx * s + ly * c];
  }

  // Polyhedral 7-vertex gem silhouette of a plump pomegranate aril
  let P = [
    tr(-rad * 0.92, -rad * 0.32), // P0: upper-left shoulder
    tr(-rad * 0.25, -rad * 0.88), // P1: top ridge
    tr( rad * 0.62, -rad * 0.72), // P2: upper-right corner
    tr( rad * 1.05, -rad * 0.08), // P3: right apex
    tr( rad * 0.72,  rad * 0.74), // P4: lower-right belly
    tr(-rad * 0.22,  rad * 0.88), // P5: bottom ridge
    tr(-rad * 0.96,  rad * 0.42)  // P6: lower-left base
  ];

  // Contact shadow offset to lower-right
  let shPoly = P.map(pt => [pt[0] + 3.8, pt[1] + 3.8]);
  addTessera(4, "obsidian_shadow", shPoly, { curvature: 0.08, seamWeight: 0.2, bevel: false, noVeins: true });

  // Internal crystal-facet junction vertex (dividing the aril into 3 fitted stone pieces)
  let V = tr(-rad * 0.12, -rad * 0.08);

  // Stone pairings for the 3 facets: [BodyStone, TranslucentCoreStone, GlintStone]
  let palettes = [
    ["jasper_crimson",   "carnelian_blush",    "chalcedony_pure"],
    ["jasper_garnet",    "jasper_pastel_rose", "chalcedony_pearl"],
    ["jasper_coral_red", "rose_quartz",        "chalcedony_pure"],
    ["jasper_moro",      "carnelian_peach",    "chalcedony_pearl"]
  ];
  let [bodyStone, glowStone, glintStone] = palettes[variant % palettes.length];

  // Facet 1: Main deep ruby/garnet jasper body
  let facetBody = [V, P[2], P[3], P[4], P[5]];
  addTessera(5, bodyStone, facetBody, {
    curvature: 0.06,
    seamWeight: 0.3,
    veinAngle: rotAng + 20
  });

  // Facet 2: Translucent inner seed-glow cheek (pastel rose quartz / blush carnelian)
  let facetGlow = [V, P[5], P[6], P[0]];
  addTessera(5, glowStone, facetGlow, {
    curvature: 0.06,
    seamWeight: 0.28,
    veinAngle: rotAng - 35
  });

  // Facet 3: Upper-left snow-white chalcedony specular glint
  let facetGlint = [V, P[0], P[1], P[2]];
  addTessera(5, glintStone, facetGlint, {
    curvature: 0.03,
    seamWeight: 0.28,
    noVeins: true
  });
}

// =============================================================================
// RENDERING ENGINE: BATCHED WATERCOLOR FILLS, MINERAL VEINING & HAIRLINE SEAMS
// =============================================================================

function renderLayer(layerIdx) {
  let items = tesserae.filter(t => t.layer === layerIdx);
  if (items.length === 0) return;

  // Group items by stoneKey for optimal p5.brush fill caching
  let groups = {};
  for (let t of items) {
    if (!groups[t.stoneKey]) groups[t.stoneKey] = [];
    groups[t.stoneKey].push(t);
  }

  // PASS A: Opaque flat hard-edged mineral wash base per stone batch
  brush.noStroke();
  brush.noFill();
  for (let stoneKey in groups) {
    let stone = STONES[stoneKey];
    let batch = groups[stoneKey];
    brush.wash(stone.base, 250);
    for (let t of batch) {
      drawPolyShape(t.pts, t.curvature);
    }
  }
  brush.noWash();

  // PASS B: Hard-edged watercolor fill per stone batch (subtle granulation & border pooling)
  brush.noStroke();
  brush.fillBleed(0.012, "in");
  brush.fillTexture(0.48, 0.36);
  for (let stoneKey in groups) {
    let stone = STONES[stoneKey];
    let batch = groups[stoneKey];
    brush.fill(stone.fill, stone.alpha);
    for (let t of batch) {
      drawPolyShape(t.pts, t.curvature);
    }
  }
  brush.noFill();

  // PASS C: Subtle internal stone veining, agate banding & pyrite flecks clipped to each piece
  for (let t of items) {
    if (!t.noVeins) {
      drawInternalStoneVeins(t, STONES[t.stoneKey]);
    }
  }

  // PASS D: Hairline pen seams separating every piece + cold diamond-lapped bevel glints
  for (let t of items) {
    drawTesseraSeamAndBevel(t, STONES[t.stoneKey]);
  }
}

function drawPolyShape(pts, curvature = 0.04) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// =============================================================================
// SUBTLE INTERNAL MINERAL VEINING & MOTTLING (CLIPPED TO EACH TESSERA)
// =============================================================================

function clipCurveToPoly(curvePts, polyPts) {
  let segments = [];
  let current = [];
  let insetP = insetPoly(polyPts, 1.4);

  for (let i = 0; i < curvePts.length - 1; i++) {
    let p0 = curvePts[i], p1 = curvePts[i + 1];
    let d = hypot(p1[0] - p0[0], p1[1] - p0[1]);
    let steps = Math.max(1, Math.ceil(d / 3.0));
    for (let s = 0; s <= steps; s++) {
      if (i > 0 && s === 0) continue;
      let t = s / steps;
      let x = lerp(p0[0], p1[0], t);
      let y = lerp(p0[1], p1[1], t);
      if (pointInPoly(x, y, insetP)) {
        current.push([x, y]);
      } else {
        if (current.length >= 2) segments.push(current);
        current = [];
      }
    }
  }
  if (current.length >= 2) segments.push(current);
  return segments;
}

function drawClippedCurve(curvePts, polyPts, brushName, col, weight) {
  let segs = clipCurveToPoly(curvePts, polyPts);
  if (segs.length === 0) return;
  brush.set(brushName, col, weight);
  for (let seg of segs) {
    if (seg.length === 2) {
      brush.line(seg[0][0], seg[0][1], seg[1][0], seg[1][1]);
    } else if (seg.length > 2) {
      // Subsample to clean spline control points
      let sp = [seg[0]];
      let step = Math.max(1, Math.floor(seg.length / 4));
      for (let i = step; i < seg.length - 1; i += step) {
        sp.push(seg[i]);
      }
      sp.push(seg[seg.length - 1]);
      if (sp.length >= 3) {
        brush.spline(sp, 0.35);
      } else {
        brush.line(sp[0][0], sp[0][1], sp[1][0], sp[1][1]);
      }
    }
  }
}

function drawInternalStoneVeins(t, stone) {
  let style = stone.style;
  if (!style || style === "none") return;

  let [cx, cy] = t.centroid;
  let span = Math.max(t.bounds.w, t.bounds.h);
  if (span < 7) return;

  let ang = t.veinAngle;
  let ca = cos(ang), sa = sin(ang);
  let pa = -sa, qa = ca; // perpendicular unit vector

  if (style === "malachite") {
    // Concentric botryoidal malachite bands clipped to the leaf tessera
    let nBands = constrain(Math.floor(span / 11), 2, 5);
    let eyeDist = span * 0.75;
    let ex = cx + pa * eyeDist, ey = cy + qa * eyeDist;

    for (let b = 0; b < nBands; b++) {
      let rBand = eyeDist * 0.45 + (b + 0.5) * (span * 0.85 / nBands);
      let arcPts = [];
      for (let a = -55; a <= 55; a += 11) {
        let theta = ang + 90 + a;
        let wob = 2.0 * sin(a * 4 + t.veinPhase);
        arcPts.push([
          ex - (rBand + wob) * cos(theta),
          ey - (rBand + wob) * sin(theta)
        ]);
      }
      let col = (b % 2 === 0) ? stone.veinL : stone.veinD;
      drawClippedCurve(arcPts, t.pts, "2H", col, 0.38);
    }
  } else if (style === "agate_band") {
    // Parallel undulating agate striation lines in carnelian & chalcedony
    let nLines = constrain(Math.floor(span / 12), 1, 3);
    for (let i = 0; i < nLines; i++) {
      let off = (i - (nLines - 1) * 0.5) * (span * 0.28);
      let linePts = [];
      for (let s = -span * 0.6; s <= span * 0.6; s += 6) {
        let wave = 1.8 * sin(s * 6 + t.veinPhase + i * 50);
        linePts.push([
          cx + s * ca + (off + wave) * pa,
          cy + s * sa + (off + wave) * qa
        ]);
      }
      let col = (i % 2 === 0) ? stone.veinL : stone.veinD;
      drawClippedCurve(linePts, t.pts, "2H", col, 0.34);
    }
  } else if (style === "jasper_vein") {
    // Stepped crystalline quartz/iron-oxide hairline vein inside jasper
    let vPts = [];
    let steps = 5;
    for (let i = 0; i <= steps; i++) {
      let u = (i / steps - 0.5) * span * 0.95;
      let jag = (noise(t.veinPhase + i * 1.3) - 0.5) * (span * 0.26);
      vPts.push([cx + u * ca + jag * pa, cy + u * sa + jag * qa]);
    }
    drawClippedCurve(vPts, t.pts, "2H", stone.veinL, 0.32);
  } else if (style === "pyrite") {
    // Calcite cloud wisp + golden pyrite flecks in Lapis & Violane
    let wPts = [
      [cx - span * 0.35 * ca, cy - span * 0.35 * sa],
      [cx + span * 0.08 * pa, cy + span * 0.08 * qa],
      [cx + span * 0.35 * ca, cy + span * 0.35 * sa]
    ];
    drawClippedCurve(wPts, t.pts, "2H", stone.veinL, 0.32);

    // Pyrite mineral specks
    let insetP = insetPoly(t.pts, 2.0);
    brush.set("rotring", "#E8CF82", 0.35);
    let nSpecks = constrain(Math.floor(span / 10), 2, 5);
    for (let k = 0; k < nSpecks; k++) {
      let rx = cx + (random(-0.35, 0.35)) * t.bounds.w;
      let ry = cy + (random(-0.35, 0.35)) * t.bounds.h;
      if (pointInPoly(rx, ry, insetP)) {
        brush.line(rx, ry, rx + 1.1, ry + 0.7);
      }
    }
  } else if (style === "cloudy" || style === "shimmer") {
    let wPts = [
      [cx - span * 0.3 * ca, cy - span * 0.3 * sa],
      [cx + span * 0.1 * pa, cy + span * 0.1 * qa],
      [cx + span * 0.3 * ca, cy + span * 0.3 * sa]
    ];
    drawClippedCurve(wPts, t.pts, "2H", stone.veinL, 0.35);
  }
}

