function drawNeroMarquinaMasterVeins() {
  // Sweeping geological white calcite veins across the polished Nero Marquina field (96..1104)
  let veins = [
    { x0: 102, y0: 210, x1: 1096, y1: 790, w: 0.75, seed: 11 },
    { x0: 145, y0: 102, x1: 1096, y1: 635, w: 0.50, seed: 23 },
    { x0: 102, y0: 540, x1: 890,  y1: 1096, w: 0.65, seed: 37 },
    { x0: 360, y0: 102, x1: 1096, y1: 995, w: 0.42, seed: 51 },
    { x0: 102, y0: 820, x1: 610,  y1: 1096, w: 0.55, seed: 67 },
    { x0: 710, y0: 102, x1: 1096, y1: 380, w: 0.48, seed: 83 }
  ];

  for (let v of veins) {
    let pts = [];
    let steps = 22;
    let dx = v.x1 - v.x0, dy = v.y1 - v.y0;
    let len = hypot(dx, dy);
    let nx = -dy / len, ny = dx / len;

    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      // Stepped geological fault-like displacement
      let nVal = noise(v.seed + i * 0.35) - 0.5;
      let stepJag = (i % 5 === 0 ? (noise(v.seed * 3 + i) - 0.5) * 18 : 0);
      let offset = nVal * 42 + stepJag;
      let px = constrain(lerp(v.x0, v.x1, t) + nx * offset, 98, 1102);
      let py = constrain(lerp(v.y0, v.y1, t) + ny * offset, 98, 1102);
      pts.push([px, py]);
    }

    // Soft cloudy mineral halo along the calcite vein
    brush.set("2H", "#4A515E", v.w * 1.15);
    brush.spline(pts, 0.25);

    // Razor-sharp white chalcedony/calcite fissure
    brush.set("rotring", "#EAE4D8", v.w * 0.68);
    brush.spline(pts, 0.25);

    // Secondary branching hairline fracture
    let bIdx = Math.floor(steps * 0.45);
    let branch = [pts[bIdx]];
    for (let k = 1; k <= 5; k++) {
      let bt = (bIdx + k) / steps;
      let boff = (noise(v.seed * 7 + k * 0.6) - 0.3) * 55;
      branch.push([
        constrain(lerp(v.x0, v.x1, bt) + nx * boff, 98, 1102),
        constrain(lerp(v.y0, v.y1, bt) + ny * boff, 98, 1102)
      ]);
    }
    brush.set("rotring", "#B8B2A6", 0.32);
    brush.spline(branch, 0.3);
  }
}

// =============================================================================
// HAIRLINE PEN SEAMS & COLD MINERAL BEVEL GLINTS
// =============================================================================

function drawTesseraSeamAndBevel(t, stone) {
  let pts = t.pts;
  let n = pts.length;

  // 1. Cold diamond-lapped bevel highlight along upper-left-facing stone edges
  if (t.bevel && t.stoneKey !== "obsidian_shadow") {
    let insetPts = insetPoly(pts, 0.75);
    let [cx, cy] = t.centroid;
    brush.set("rotring", "#FFFDF9", 0.22);

    for (let i = 0; i < n; i++) {
      let ni = (i + 1) % n;
      let p0 = insetPts[i], p1 = insetPts[ni];
      let edx = p1[0] - p0[0], edy = p1[1] - p0[1];
      let elen = hypot(edx, edy);
      if (elen < 5.5) continue;

      // Midpoint vector from centroid to edge
      let mx = (p0[0] + p1[0]) * 0.5 - cx;
      let my = (p0[1] + p1[1]) * 0.5 - cy;
      // If this edge sits on the upper-left side of the stone piece, light catches the cut bevel
      if (mx * -0.707 + my * -0.707 > 0) {
        brush.line(p0[0], p0[1], p1[0], p1[1]);
      }
    }
  }

  // 2. Razor-sharp hairline pen seam separating every cut stone piece
  brush.set("rotring", stone.seam || "#121419", t.seamWeight);
  for (let i = 0; i < n; i++) {
    let ni = (i + 1) % n;
    brush.line(pts[i][0], pts[i][1], pts[ni][0], pts[ni][1]);
  }
}

// =============================================================================
// FINAL COLD GLOSSY MINERAL TABLETOP REFLECTION SHEEN
// =============================================================================

function drawTabletopMineralPolish() {
  // Subtle diagonal architectural window-light sheen across the mirror-polished hardstone slab
  let sheenBands = [
    { offset: -260, halfW: 32, weight: 0.22 },
    { offset:  -20, halfW: 54, weight: 0.25 },
    { offset:  275, halfW: 28, weight: 0.20 }
  ];

  let ang = -38;
  let ca = cos(ang), sa = sin(ang);
  let pa = -sa, qa = ca;

  for (let band of sheenBands) {
    for (let d = -band.halfW; d <= band.halfW; d += 7) {
      let falloff = 1.0 - Math.abs(d) / band.halfW;
      let col = ( Math.abs(d) < band.halfW * 0.35 ) ? "#FFFFFF" : "#DCE6F2";
      brush.set("2H", col, band.weight * (0.55 + 0.45 * falloff));

      let bx = 600 + (band.offset + d) * pa;
      let by = 600 + (band.offset + d) * qa;
      let L = 470;
      let x0 = constrain(bx - L * ca, 44, 1156);
      let y0 = constrain(by - L * sa, 44, 1156);
      let x1 = constrain(bx + L * ca, 44, 1156);
      let y1 = constrain(by + L * sa, 44, 1156);

      if (hypot(x1 - x0, y1 - y0) > 20) {
        brush.line(x0, y0, x1, y1);
      }
    }
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
