// ANATOMICAL GEOMETRY HELPERS
// ---------------------------------------------------------------------------

// Profile control points (left-facing elderly temple, cheekbone, hollow cheek, jaw, jowl, and neck)
const PROFILE_PTS = [
  [378, -30],
  [345, 55],
  [322, 155],
  [254, 285], // Zygomatic arch (cheekbone)
  [260, 395], // Sub-zygomatic hollow
  [242, 515], // Buccal plane
  [214, 635], // Aged jowl / lower cheek
  [202, 742], // Anterior mandible / chin curve
  [244, 808], // Sub-chin curve
  [348, 848], // Submental slack skin
  [468, 888], // Elderly submental wattle
  [586, 926], // Cervico-mental junction
  [592, 982], // Upper anterior neck
  [568, 1048], // Thyroid cartilage (Adam's apple)
  [590, 1125], // Lower neck hollow
  [618, 1230]
];

function getProfileX(y) {
  if (y <= PROFILE_PTS[0][1]) return PROFILE_PTS[0][0];
  if (y >= PROFILE_PTS[PROFILE_PTS.length - 1][1]) return PROFILE_PTS[PROFILE_PTS.length - 1][0];
  for (let i = 0; i < PROFILE_PTS.length - 1; i++) {
    let p0 = PROFILE_PTS[Math.max(0, i - 1)];
    let p1 = PROFILE_PTS[i];
    let p2 = PROFILE_PTS[i + 1];
    let p3 = PROFILE_PTS[Math.min(PROFILE_PTS.length - 1, i + 2)];
    if (y >= p1[1] && y <= p2[1]) {
      let t = (y - p1[1]) / (p2[1] - p1[1]);
      // Catmull-Rom spline interpolation for smooth organic skin contour
      let t2 = t * t;
      let t3 = t2 * t;
      let x =
        0.5 *
        (2 * p1[0] +
          (-p0[0] + p2[0]) * t +
          (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
          (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
      return x;
    }
  }
  return 300;
}

