// Helper to draw a watercolor fill polygon safely using beginShape/vertex/endShape
function washPoly(pts, col, opacity, bleed = 0.25, tex = 0.45, border = 0.35, curv = 0.55, dir = "out") {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, dir);
  brush.fillTexture(tex, border);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

// Fast flat wash pass helper for luminous under-glows
function flatWashPoly(pts, col, opacity, curv = 0.5) {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.wash(col, opacity);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm sunlit paper ground (pale Naples cream)
  background("#fdf3d2");

  // =========================================================================
  // 1. OUT-OF-FOCUS BACKGROUND WASH (APRICOT & NAPLES YELLOW, NO DETAIL)
  // =========================================================================
  renderOutOfFocusBackground();

  // =========================================================================
  // 2. LAYERED WATERCOLOUR WASHES: HEAD, JAW & NECK (SIENNA TO ROSE MADDER)
  // =========================================================================
  renderFaceAndJawWatercolors();

  // =========================================================================
  // 3. TRANSLUCENT EAR CARTILAGE WASHES (CADMIUM-RED, CORAL & ROSE MADDER)
  // =========================================================================
  renderEarWatercolors();

  // =========================================================================
  // 4. DENSE COLOURED PENCIL: ANATOMICAL SHADING, CREASES & RHYTIDS
  // =========================================================================
  renderColouredPencilModeling();
  renderSkinCreasesAndFolds();

  // =========================================================================
  // 5. LIVER SPOTS (SOLAR LENTIGINES), PORES & MICRO-CAPILLARIES
  // =========================================================================
  renderLiverSpots();
  renderPoresAndMicroTexture();

  // =========================================================================
  // 6. HIGH-CONTRAST SUNLIT RIM GLOW & TRANSLUCENT CARTILAGE HIGHLIGHTS
  // =========================================================================
  renderSunlitRimAndCartilageGlow();

  // =========================================================================
  // 7. SILVER PEACH FUZZ & STRAY HAIRS (SINGLE HAIR-THIN PENCIL STROKES)
  // =========================================================================
  renderSilverPeachFuzzAndHairs();

  noLoop();
}

