// ---------------------------------------------------------------------------
// 4. DENSE COLOURED PENCIL: ANATOMICAL SHADING, CREASES & RHYTIDS
// ---------------------------------------------------------------------------
function renderColouredPencilModeling() {
  // Dense cross-contour colored pencil strokes modeling the 3D form of the cheek,
  // jaw, neck, and the complex sculptural topography of the ear.

  // A. Cheek, Zygomatic Arch, Jowl & Jaw Modeling
  const faceTones = ["#8c2d2b", "#a64228", "#701b24", "#b85a32", "#4d1418", "#d46a3f"];
  for (let i = 0; i < 1150; i++) {
    let y = random(30, 915);
    let profX = getProfileX(y);
    // Concentrate strokes between the sunlit rim and the ear
    let maxX = y < 800 ? 605 : 780;
    let x = profX + pow(random(), 0.82) * (maxX - profX);
    if (x > maxX) continue;

    // Determine local anatomical contour angle
    let distFromRim = x - profX;
    let baseAngle = map(y, 50, 900, -25, 32) + sin(y * 0.4) * 14;
    if (y > 700) {
      // Follow sweep of the jawline and submental sag
      baseAngle = map(x, 220, 620, 35, -18);
    }

    // Select color based on shadow core vs sunlit transition
    let col;
    if (distFromRim < 38) {
      col = random(["#e88b48", "#d66035", "#f2a855", "#c2492c"]);
    } else if (distFromRim > 75 && distFromRim < 230 && y > 310 && y < 860) {
      // High-contrast core shadow zone on cheek and jaw
      col = random(["#3b0e12", "#52151b", "#6b1d26", "#421210"]);
    } else {
      col = random(faceTones);
    }

    brush.set(random(["cpencil", "dermal_pencil", "2B"]), col, random(0.45, 0.95));
    let len = random(18, 48);
    let ang = baseAngle + random(-14, 14);
    let x2 = x + cos(ang) * len;
    let y2 = y + sin(ang) * len;
    let xm = (x + x2) * 0.5 + random(-4, 4);
    let ym = (y + y2) * 0.5 + random(-4, 4);
    brush.spline([[x, y, 0.3], [xm, ym, 0.9], [x2, y2, 0.2]], 0.5);
  }

  // B. Neck & Sternocleidomastoid Diagonal Cross-Hatching
  for (let i = 0; i < 650; i++) {
    let y = random(780, 1195);
    let minX = getProfileX(y) + 8;
    let x = random(minX, 1190);

    // Diagonal neck cords (sternocleidomastoid sweeps from mastoid (920, 720) to (610, 1200))
    let isShadowHollow = x > 680 && x < 1120;
    let col = isShadowHollow
      ? random(["#2b090c", "#3d1014", "#54181c", "#69221f"])
      : random(["#8c3523", "#a84b2b", "#732024", "#c76838"]);

    brush.set(random(["cpencil", "dermal_pencil", "2B"]), col, random(0.5, 1.05));
    let ang = (i % 2 === 0 ? 118 : 68) + random(-12, 12);
    let len = random(24, 58);
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // C. Dense Coloured Pencil Sculpting of the Ear Cartilage & Lobule
  for (let i = 0; i < 1350; i++) {
    // Sample within ear bounding region
    let t = random(360);
    let rFrac = sqrt(random());
    // Ear center ~ (835, 430), radii ~ (245, 375)
    let cx = 835;
    let cy = 430;
    let x = cx + cos(t) * rFrac * 245;
    let y = cy + sin(t) * rFrac * 370;

    // Determine ear zone for color & stroke direction
    let dx = x - 770;
    let dy = (y - 425) * 0.72;
    let dCenter = sqrt(dx * dx + dy * dy);
    let ang = atan2(dy, dx) + 90 + random(-18, 18);

    let col;
    let bName = random(["cpencil", "dermal_pencil", "glaze_pencil"]);
    let w = random(0.4, 0.88);

    if (x > 910 && y > 110 && y < 560 && dCenter > 135) {
      // Scapha & outer helix translucent cadmium-red & coral zone
      col = random(["#e82514", "#ff5c36", "#ff8438", "#c91912", "#ffa647"]);
    } else if (y > 610 && x < 890) {
      // Fleshy earlobe (warm rose madder, coral, sienna)
      col = random(["#b82b28", "#d9462f", "#8a1c29", "#ff6d48", "#6e1722"]);
      ang = map(x, 600, 880, 75, 115) + random(-15, 15);
    } else if (dCenter < 95 && x > 715) {
      // Glowing cavum conchae wall
      col = random(["#eb2a17", "#ff663b", "#ff943b", "#b81818"]);
    } else if (x < 725 && y > 365 && y < 520) {
      // Ear canal & tragus contrast zone
      col = x < 660 ? random(["#d94f30", "#ff7c4d", "#962426"]) : random(["#1f0608", "#360c10"]);
    } else {
      // Antihelix ridges and folds
      col = random(["#d42317", "#961b28", "#ff623d", "#6e1320", "#eb4728"]);
    }

    brush.set(bName, col, w);
    let len = random(12, 32);
    let x2 = x + cos(ang) * len;
    let y2 = y + sin(ang) * len;
    brush.line(x, y, x2, y2);
  }
}

// ---------------------------------------------------------------------------
// SKIN CREASES, WRINKLES, PRE-AURICULAR FOLDS & FRANK'S SIGN
// ---------------------------------------------------------------------------
function renderSkinCreasesAndFolds() {
  // Helper to draw a realistic 3D skin crease: a dark rose-madder/umber trough
  // paired with a soft sunlit coral/gold upper-lip highlight.
  function drawCrease3D(pts, darkCol, lightCol, weight = 0.65, offset = 2.2) {
    brush.set("crease_needle", darkCol, weight);
    brush.spline(pts, 0.55);

    // Subtle softer shadow halo along the crease
    brush.set("dermal_pencil", "#6e1a24", weight * 0.85);
    let shadowPts = pts.map((p) => [p[0] + 1.2, p[1] + 1.0, (p[2] || 0.6) * 0.7]);
    brush.spline(shadowPts, 0.55);

    // Sunlit ridge highlight on the side facing the low sun
    if (lightCol) {
      brush.set("crease_needle", lightCol, weight * 0.75);
      let hiPts = pts.map((p) => [p[0] - offset, p[1] - offset * 0.5, (p[2] || 0.6) * 0.8]);
      brush.spline(hiPts, 0.55);
    }
  }

  // 1. Deep Pre-Auricular Vertical Creases (in front of the tragus, helix root & earlobe)
  const preAuricularCreases = [
    [[572, 225, 0.2], [562, 315, 0.85], [558, 415, 0.95], [564, 515, 0.75], [575, 595, 0.2]],
    [[546, 260, 0.2], [536, 360, 0.8], [534, 465, 0.9], [542, 575, 0.85], [558, 675, 0.3]],
    [[518, 330, 0.15], [510, 440, 0.75], [512, 555, 0.8], [528, 665, 0.7], [552, 745, 0.2]],
    [[582, 520, 0.3], [576, 610, 0.9], [582, 695, 0.85], [602, 762, 0.3]]
  ];
  for (let c of preAuricularCreases) {
    drawCrease3D(c, "#2d090d", "#f08c4b", 0.82, 2.4);
  }

  // 2. Frank's Sign (Diagonal Earlobe Crease characteristic of elderly ears) + Lobe Folds
  const earlobeCreases = [
    // Primary Frank's sign diagonal crease across the lobule
    [[688, 552, 0.4], [728, 612, 1.0], [772, 672, 0.95], [818, 725, 0.65], [848, 755, 0.2]],
    // Secondary radial earlobe creases
    [[648, 615, 0.2], [685, 665, 0.8], [715, 728, 0.7], [732, 778, 0.2]],
    [[745, 575, 0.2], [785, 625, 0.75], [828, 668, 0.65], [865, 695, 0.2]],
    [[620, 668, 0.2], [658, 705, 0.7], [688, 755, 0.5], [702, 792, 0.2]]
  ];
  for (let c of earlobeCreases) {
    drawCrease3D(c, "#380a10", "#ff7e4f", 0.78, 2.0);
  }

  // 3. Crisp Anatomical Contour Creases of the Ear (Helix Overhang, Antihelix Crura, Tragus)
  const earStructuralCreases = [
    // Inner rolled edge of the helix overhang
    [
      [642, 228, 0.4], [678, 148, 0.9], [758, 102, 1.0], [868, 106, 0.95],
      [965, 152, 0.9], [1012, 245, 0.85], [1005, 365, 0.8], [965, 478, 0.65], [908, 565, 0.2]
    ],
    // Inferior crus of the antihelix (sharp shelf above cymba conchae)
    [[648, 244, 0.5], [715, 242, 1.0], [785, 252, 0.95], [845, 272, 0.5]],
    // Superior crus internal fold
    [[742, 138, 0.2], [778, 185, 0.75], [822, 238, 0.8], [855, 278, 0.4]],
    // Crus of the helix entering the concha bowl
    [[608, 225, 0.4], [635, 285, 0.9], [678, 338, 0.95], [738, 355, 0.6], [782, 352, 0.2]],
    // Tragus & intertragic notch contour
    [
      [602, 368, 0.3], [652, 388, 0.9], [666, 432, 1.0], [662, 482, 0.95],
      [678, 538, 0.9], [712, 558, 0.9], [755, 535, 0.8], [805, 528, 0.4]
    ]
  ];
  for (let c of earStructuralCreases) {
    drawCrease3D(c, "#240609", "#ff854d", 0.88, 2.2);
  }

  // 4. Crow's-Feet Extensions & Zygomatic / Cheek Creases
  const cheekAndTempleCreases = [
    // Temple / lateral canthus crow's-feet extensions entering from upper-left profile
    [[318, 175, 0.3], [375, 192, 0.85], [438, 218, 0.75], [495, 248, 0.2]],
    [[292, 215, 0.4], [358, 232, 0.9], [428, 255, 0.8], [488, 282, 0.2]],
    [[268, 255, 0.4], [342, 268, 0.85], [418, 292, 0.7], [478, 325, 0.2]],
    [[260, 295, 0.3], [335, 315, 0.8], [405, 348, 0.65], [462, 388, 0.15]],
    // Long weathered cheek & jowl folds sweeping down toward the jaw angle
    [[285, 385, 0.2], [338, 455, 0.8], [385, 545, 0.85], [418, 645, 0.75], [435, 735, 0.2]],
    [[258, 465, 0.3], [305, 545, 0.85], [342, 638, 0.9], [368, 732, 0.75], [382, 808, 0.3]],
    [[232, 565, 0.3], [272, 642, 0.85], [305, 725, 0.85], [332, 798, 0.6]],
    // Mandibular border & submental wattle creases
    [[245, 775, 0.3], [335, 805, 0.85], [435, 818, 0.9], [538, 808, 0.8], [628, 778, 0.3]],
    [[345, 835, 0.3], [442, 858, 0.85], [545, 862, 0.9], [648, 835, 0.7], [735, 795, 0.2]],
    [[455, 878, 0.3], [552, 902, 0.9], [648, 892, 0.85], [748, 852, 0.6], [825, 802, 0.2]]
  ];
  for (let c of cheekAndTempleCreases) {
    drawCrease3D(c, "#360c11", "#e87a42", 0.72, 2.0);
  }

  // 5. Neck Creases & Rhomboid Dermal Grid (Aged Skin Cross-Creases on Jaw & Neck)
  const neckRings = [
    [[585, 928, 0.4], [678, 932, 0.9], [775, 908, 0.85], [875, 862, 0.6], [965, 805, 0.2]],
    [[588, 985, 0.3], [685, 992, 0.85], [792, 968, 0.8], [895, 922, 0.5], [985, 868, 0.2]],
    [[572, 1052, 0.3], [672, 1062, 0.85], [785, 1038, 0.75], [895, 992, 0.4]],
    [[588, 1122, 0.3], [692, 1132, 0.8], [805, 1108, 0.7], [915, 1062, 0.3]]
  ];
  for (let c of neckRings) {
    drawCrease3D(c, "#28080b", "#c95830", 0.75, 2.0);
  }

  // Fine diamond-shaped micro-rhytid mesh across cheek, pre-auricular skin, and neck
  for (let i = 0; i < 420; i++) {
    let y = random(160, 1150);
    let minX = getProfileX(y) + 18;
    let maxX = y < 780 ? 585 : 1050;
    if (minX >= maxX) continue;
    let x = random(minX, maxX);

    let ang1 = random(22, 48);
    let ang2 = random(112, 145);
    let len = random(10, 26);

    brush.set("crease_needle", random(["#471216", "#5e1a1f", "#752422"]), random(0.32, 0.58));
    let ang = i % 2 === 0 ? ang1 : ang2;
    let xm = x + cos(ang) * len * 0.5 + random(-2, 2);
    let ym = y + sin(ang) * len * 0.5 + random(-2, 2);
    brush.spline([[x, y, 0.2], [xm, ym, 0.85], [x + cos(ang) * len, y + sin(ang) * len, 0.15]], 0.5);
  }
}

// ---------------------------------------------------------------------------
// 5. LIVER SPOTS (SOLAR LENTIGINES), PORES & MICRO-CAPILLARIES
// ---------------------------------------------------------------------------
function renderLiverSpots() {
  // Curated + procedural solar lentigines (age spots / liver spots) across the sun-damaged
  // cheekbone, temple, jaw, pre-auricular skin, and upper outer helix.
  const primarySpots = [
    { x: 355, y: 275, r: 22, rot: 25 },  // Prominent cheekbone lentigo
    { x: 412, y: 318, r: 15, rot: -15 },
    { x: 325, y: 342, r: 12, rot: 40 },
    { x: 458, y: 238, r: 18, rot: 12 },  // Temple lentigo
    { x: 392, y: 162, r: 14, rot: -30 },
    { x: 485, y: 382, r: 19, rot: 55 },  // Mid-cheek lentigo
    { x: 368, y: 448, r: 13, rot: 18 },
    { x: 438, y: 512, r: 21, rot: -22 }, // Buccal / pre-jowl lentigo
    { x: 315, y: 538, r: 11, rot: 35 },
    { x: 495, y: 588, r: 16, rot: 10 },
    { x: 382, y: 658, r: 17, rot: -40 }, // Jawline lentigo
    { x: 465, y: 712, r: 24, rot: 28 },  // Large mandibular angle liver spot
    { x: 312, y: 718, r: 13, rot: 15 },
    { x: 535, y: 685, r: 12, rot: -10 },
    { x: 525, y: 455, r: 14, rot: 65 },
    { x: 545, y: 185, r: 16, rot: -25 },
    // Liver spots on the sun-exposed superior & posterior helix and earlobe
    { x: 785, y: 82, r: 13, rot: 12 },
    { x: 895, y: 92, r: 16, rot: 32 },
    { x: 1025, y: 188, r: 15, rot: 72 },
    { x: 1058, y: 295, r: 18, rot: 85 },
    { x: 1022, y: 428, r: 14, rot: 65 },
    { x: 755, y: 685, r: 15, rot: 42 },
    { x: 678, y: 642, r: 11, rot: -18 },
    { x: 662, y: 865, r: 17, rot: 20 },
    { x: 745, y: 945, r: 14, rot: -15 }
  ];

  // Add smaller satellite age spots & freckles around the primary ones
  let allSpots = [...primarySpots];
  for (let i = 0; i < 38; i++) {
    let base = random(primarySpots);
    let ang = random(360);
    let dist = random(22, 68);
    let sx = base.x + cos(ang) * dist;
    let sy = base.y + sin(ang) * dist;
    if (sx > getProfileX(sy) + 14) {
      allSpots.push({ x: sx, y: sy, r: random(4.5, 9.5), rot: random(360) });
    }
  }

  // First pass: soft watercolor stain for each liver spot
  for (let s of allSpots) {
    let pts = [];
    let steps = 10;
    for (let k = 0; k < steps; k++) {
      let a = (k / steps) * 360;
      let rad = s.r * random(0.72, 1.25);
      let px = s.x + cos(a) * rad * 1.15;
      let py = s.y + sin(a) * rad * 0.85;
      pts.push([px, py]);
    }
    washPoly(pts, random(["#5e2416", "#4d1c12", "#6e2c1a"]), 58, 0.22, 0.55, 0.45, 0.55);
  }

  // Second pass: dense colored pencil micro-hatching & mottled pigment border inside each spot
  for (let s of allSpots) {
    let count = Math.floor(s.r * 3.2);
    for (let j = 0; j < count; j++) {
      let a = random(360);
      let d = sqrt(random()) * s.r;
      let px = s.x + cos(a) * d * 1.1;
      let py = s.y + sin(a) * d * 0.85;
      let col = random(["#3d150c", "#542014", "#6b2b1a", "#471812"]);
      brush.set("dermal_pencil", col, random(0.35, 0.65));
      let stAng = s.rot + random(-25, 25);
      let stLen = random(3, 8);
      brush.line(px, py, px + cos(stAng) * stLen, py + sin(stAng) * stLen);
    }
  }
}

function renderPoresAndMicroTexture() {
  // 1. Thousands of fine dermal pores across the cheek, temple, tragus, concha, and earlobe
  for (let i = 0; i < 1900; i++) {
    let isEar = random() < 0.46;
    let x, y, darkCol, rimCol;

    if (isEar) {
      // Sample on the ear (lobule, tragus, antitragus, antihelix, concha)
      let zone = random();
      if (zone < 0.45) {
        // Earlobe pores (prominent in elderly skin)
        x = random(608, 875);
        y = random(565, 795);
        if (dist(x, y, 745, 685) > 140) continue;
      } else if (zone < 0.75) {
        // Antihelix, concha & tragus pores
        x = random(595, 945);
        y = random(220, 565);
      } else {
        // Upper helix & triangular fossa
        x = random(650, 1065);
        y = random(75, 320);
      }
      darkCol = random(["#541118", "#781921", "#3d0b10", "#9c221c"]);
      rimCol = random(["#ff8e52", "#ffa866", "#ff6d42"]);
    } else {
      // Sample on cheek, cheekbone, pre-auricular skin, and jaw
      y = random(120, 895);
      let profX = getProfileX(y);
      x = profX + random(10, 360);
      if (x > 595 && y < 760) continue;
      darkCol = random(["#3b0e12", "#59191b", "#70241d", "#2b090c"]);
      rimCol = random(["#e88b4d", "#f5ac62", "#c95b35"]);
    }

    // Draw pore micro-crescent
    brush.set("crease_needle", darkCol, random(0.28, 0.52));
    let len = random(1.6, 3.8);
    let ang = random(360);
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);

    // Every ~4th pore gets a tiny specular skin-lipid micro-highlight next to it
    if (i % 4 === 0) {
      brush.set("crease_needle", rimCol, random(0.25, 0.45));
      brush.line(x - 1.4, y - 1.0, x - 0.2, y + 0.6);
    }
  }

  // 2. Delicate Telangiectasia (Broken Capillaries / Thread Veins) on Cheekbone & Earlobe
  const capillaryClusters = [
    { cx: 315, cy: 315, count: 6 },
    { cx: 365, cy: 375, count: 5 },
    { cx: 295, cy: 585, count: 5 },
    { cx: 685, cy: 675, count: 6 },
    { cx: 775, cy: 725, count: 6 },
    { cx: 885, cy: 395, count: 5 }
  ];
  for (let cl of capillaryClusters) {
    for (let k = 0; k < cl.count; k++) {
      let x0 = cl.cx + random(-28, 28);
      let y0 = cl.cy + random(-28, 28);
      let a1 = random(360);
      let x1 = x0 + cos(a1) * random(8, 16);
      let y1 = y0 + sin(a1) * random(8, 16);
      let a2 = a1 + random(-45, 45);
      let x2 = x1 + cos(a2) * random(7, 14);
      let y2 = y1 + sin(a2) * random(7, 14);

      brush.set("crease_needle", random(["#9e172a", "#bd1e2c", "#7d1122"]), random(0.25, 0.42));
      brush.spline([[x0, y0, 0.2], [x1, y1, 0.9], [x2, y2, 0.15]], 0.6);
    }
  }
}

// ---------------------------------------------------------------------------
// 6. HIGH-CONTRAST SUNLIT RIM GLOW & TRANSLUCENT CARTILAGE HIGHLIGHTS
// ---------------------------------------------------------------------------
function renderSunlitRimAndCartilageGlow() {
  // 1. Intense Translucent Cartilage Glow inside the Ear (Glazed Colored Pencil)
  // Reinforcing the incandescent cadmium-red, coral, and sunlit amber core where light passes through
  for (let i = 0; i < 420; i++) {
    let zone = random();
    let x, y, ang, col;
    if (zone < 0.48) {
      // Scapha & outer-right helix translucent band
      let t = random(-65, 55);
      let r = random(168, 225);
      x = 825 + cos(t) * r;
      y = 335 + sin(t) * r * 1.18;
      ang = t + 90 + random(-12, 12);
      col = random(["#ff4d26", "#ff753d", "#ff9e42", "#e82214", "#ffbf5e"]);
    } else if (zone < 0.78) {
      // Cavum conchae glowing central bowl
      let t = random(360);
      let r = sqrt(random()) * 58;
      x = 795 + cos(t) * r;
      y = 425 + sin(t) * r * 1.1;
      ang = random(360);
      col = random(["#ff562e", "#ff883b", "#eb2313", "#ffb24d"]);
    } else {
      // Triangular fossa & antihelix crura
      x = random(675, 835);
      y = random(155, 255);
      ang = random(-25, 35);
      col = random(["#ff6238", "#ff8f42", "#e62917"]);
    }

    brush.set(random(["glaze_pencil", "cpencil"]), col, random(0.55, 1.1));
    let len = random(12, 26);
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // 2. Blazing Sunlit Rim along the Facial Profile, Jawline & Chin
  for (let y = 0; y <= 1190; y += 3.5) {
    let px = getProfileX(y);
    // Width of the sunlit rim is widest on the cheekbone (y~285), jowl/chin (y~620..810), and submental edge
    let rimWidth = 18;
    if (y > 220 && y < 360) rimWidth = 28;
    if (y > 580 && y < 855) rimWidth = 34;

    // Warm golden-coral inner rim transition
    brush.set("cpencil", random(["#f5a456", "#eb7e42", "#fad178"]), random(0.55, 0.95));
    let ang = y > 745 && y < 925 ? 22 + random(-10, 10) : 78 + random(-12, 12);
    let rx = px + random(4, rimWidth);
    brush.line(rx, y, rx + cos(ang) * 16, y + sin(ang) * 16);

    // Brilliant Naples-yellow & ivory outer skin rim right on the profile contour
    brush.set("dermal_pencil", random(["#fff4b8", "#fffdf0", "#fce288"]), random(0.5, 0.88));
    let edgeX = px + random(-1.5, 6.5);
    brush.line(edgeX, y, edgeX + cos(ang) * 12, y + sin(ang) * 12);
  }

  // 3. Sunlit Rim along the Superior & Posterior Helix, Tragus & Earlobe
  for (let i = 0; i < EAR_OUTER_PTS.length - 1; i++) {
    let p1 = EAR_OUTER_PTS[i];
    let p2 = EAR_OUTER_PTS[i + 1];
    for (let s = 0; s < 1; s += 0.08) {
      let x = lerp(p1[0], p2[0], s) + random(-3, 3);
      let y = lerp(p1[1], p2[1], s) + random(-3, 3);
      let tang = atan2(p2[1] - p1[1], p2[0] - p1[0]) + random(-10, 10);

      // Warm coral-gold subsurface edge
      brush.set("cpencil", random(["#ff8347", "#ffad52", "#ffd678"]), random(0.5, 0.85));
      brush.line(x, y, x + cos(tang) * 14, y + sin(tang) * 14);

      // Crisp pale gold-ivory rim highlight along the outer edge
      if (i >= 1 && i <= 16) {
        brush.set("crease_needle", random(["#fff7cc", "#fffef2", "#fce38d"]), random(0.45, 0.78));
        brush.line(x, y, x + cos(tang) * 9, y + sin(tang) * 9);
      }
    }
  }
}

// ---------------------------------------------------------------------------
// 7. SILVER PEACH FUZZ & STRAY HAIRS (SINGLE HAIR-THIN PENCIL STROKES)
// ---------------------------------------------------------------------------
function renderSilverPeachFuzzAndHairs() {
  // Single hair-thin pencil strokes forming a luminous silver-white & pale-gold
  // rim halo along the profile, jawline, ear helix, earlobe, tragus, and temple.

  const silverPalette = ["#ffffff", "#fffef5", "#fcf4dc", "#fff0be", "#f2ead8"];

  // Helper to draw a single delicate, slightly curved hair stroke
  function drawSingleHair(x, y, angle, length, curveAmt, weightMult = 1.0, col = null) {
    let c = col || random(silverPalette);
    brush.set("silver_hair", c, random(0.24, 0.48) * weightMult);
    let midA = angle + curveAmt * 0.5;
    let endA = angle + curveAmt;
    let xm = x + cos(midA) * (length * 0.52);
    let ym = y + sin(midA) * (length * 0.52);
    let x2 = x + cos(endA) * length;
    let y2 = y + sin(endA) * length;
    brush.spline([[x, y, 0.25], [xm, ym, 0.95], [x2, y2, 0.05]], 0.55);
  }

  // A. Rim Halo of Fine Silver Peach Fuzz (Vellus Hair) Along the Entire Facial & Jaw Profile
  for (let y = 5; y <= 1185; y += 2.2) {
    let px = getProfileX(y);

    // Determine outward normal / natural vellus hair growth direction along the profile
    let dy = 6;
    let dx = getProfileX(y + dy) - getProfileX(y - dy);
    let tangent = atan2(2 * dy, dx);
    // Outward normal points left/down-left into the sunlit sky
    let outAngle = tangent + 90;

    // Dense velvety peach fuzz right along the rim (2 to 3 fine hairs per step)
    let count = y > 220 && y < 920 ? 3 : 2;
    for (let k = 0; k < count; k++) {
      let startX = px + random(-2.5, 5.5);
      let startY = y + random(-2.5, 2.5);
      let hairLen = random(9, 24);
      // On the jawline and chin, some hairs are slightly longer elderly beard/jaw stubble & fuzz
      if (y > 580 && y < 910 && random() < 0.35) {
        hairLen = random(18, 36);
      }
      let ang = outAngle + random(-28, 28);
      let curve = random(-22, 28);
      drawSingleHair(startX, startY, ang, hairLen, curve, random(0.75, 1.15));
    }
  }

  // Soft foreshortened silver peach fuzz catching the raking light just inside the cheek & jaw rim
  for (let i = 0; i < 420; i++) {
    let y = random(60, 910);
    let px = getProfileX(y);
    let x = px + random(4, 52);
    let len = random(7, 18);
    let ang = random(115, 215);
    drawSingleHair(x, y, ang, len, random(-18, 18), 0.72, random(["#fff8dc", "#f7ebd2", "#ffffff"]));
  }

  // B. Rim Halo of Silver Peach Fuzz & Stray Hairs Around the Entire Outer Ear Helix & Earlobe
  for (let i = 0; i < EAR_OUTER_PTS.length - 1; i++) {
    let p1 = EAR_OUTER_PTS[i];
    let p2 = EAR_OUTER_PTS[i + 1];
    let segDist = dist(p1[0], p1[1], p2[0], p2[1]);
    let steps = Math.floor(segDist * 0.95);

    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let bx = lerp(p1[0], p2[0], t);
      let by = lerp(p1[1], p2[1], t);

      // Outward angle from ear center (815, 430)
      let outAng = atan2(by - 430, bx - 815);

      // 2-3 fine backlit vellus hairs per step forming a continuous luminous silver halo
      for (let k = 0; k < 2; k++) {
        let hx = bx + random(-3, 3);
        let hy = by + random(-3, 3);
        let len = random(9, 23);
        let ang = outAng + random(-32, 32);
        let curve = random(-24, 24);
        drawSingleHair(hx, hy, ang, len, curve, random(0.75, 1.1));
      }

      // Stray longer wiry auricular hairs along the helix rim, Darwin's tubercle & earlobe
      if (random() < 0.24) {
        let strayLen = random(24, 54);
        let strayAng = outAng + random(-25, 35);
        let strayCurve = random(-42, 42);
        drawSingleHair(
          bx + random(-4, 4),
          by + random(-4, 4),
          strayAng,
          strayLen,
          strayCurve,
          random(0.95, 1.35),
          "#ffffff"
        );
      }
    }
  }

  // C. Characteristic Elderly Auricular Hairs (Tragus, Antitragus & Intertragic Notch Tufts)
  // In elderly men, long, wiry silver-white hairs sprout prominently from the tragus and antitragus
  for (let i = 0; i < 68; i++) {
    let zone = random();
    let hx, hy, baseAng;
    if (zone < 0.55) {
      // Tragus tuft (pointing left/down-left and right across the dark ear canal!)
      hx = random(598, 665);
      hy = random(385, 498);
      baseAng = random() < 0.55 ? random(-35, 45) : random(135, 225);
    } else if (zone < 0.85) {
      // Antitragus & intertragic notch stray hairs
      hx = random(672, 795);
      hy = random(505, 578);
      baseAng = random(165, 285);
    } else {
      // Inner helix root & antihelix stray hairs
      hx = random(635, 895);
      hy = random(125, 365);
      baseAng = random(0, 360);
    }
    let len = random(22, 62);
    let curve = random(-48, 48);
    drawSingleHair(hx, hy, baseAng, len, curve, random(0.9, 1.3), random(["#ffffff", "#fffdf2", "#f5eedc"]));
  }

  // D. Wispy Silver Temple, Sideburn & Nape Hairs Catching the Setting Sun
  // 1. Temple & sideburn silver hairs above and in front of the ear
  for (let i = 0; i < 210; i++) {
    let hx = random(355, 650);
    let hy = random(-15, 285);
    // Keep away from lower cheekbone
    if (hy > 180 && hx < 465) continue;
    let len = random(32, 85);
    let ang = map(hy, 0, 280, 115, 92) + random(-22, 22);
    let curve = random(-35, 35);
    let col = random(["#ffffff", "#fffdf0", "#f0e6d2", "#fce8b2", "#ded6c8"]);
    drawSingleHair(hx, hy, ang, len, curve, random(0.85, 1.3), col);
  }

  // 2. Backlit silver hairs at the crown/upper-head above the ear and along the nape of the neck
  for (let i = 0; i < 165; i++) {
    let isUpper = random() < 0.55;
    let hx, hy, ang, len;
    if (isUpper) {
      hx = random(620, 965);
      hy = random(-15, 85);
      ang = random(-35, 45);
      len = random(28, 72);
    } else {
      // Nape / retro-auricular hairline catching stray golden-silver light
      hy = random(520, 1150);
      hx = random(980, 1195);
      ang = random(45, 125);
      len = random(25, 65);
    }
    let col = random(["#ffffff", "#fff8dc", "#f7e3a8", "#e8dfd0"]);
    drawSingleHair(hx, hy, ang, len, random(-38, 38), random(0.8, 1.25), col);
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4219);
  noiseSeed(4219);
}

// ============================================================================
// 3D PROJECTION & GEOMETRY ENGINE
// ============================================================================
// World coordinates:
//   wx: front-right axis (-back-left to +front-right)
//   wy: vertical height axis (0 = tabletop, +upwards)
//   wz: front-left axis (-back-right to +front-left)
const CX = 555;
const CY = 815;

function proj(wx, wy, wz) {
  const sx = CX + wx * 0.87 - wz * 0.79;
  const sy = CY + wx * 0.34 + wz * 0.40 - wy * 0.95;
  return [sx, sy];
}

function lerp2(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

function lerp3(a, b, t) {
  return [
    a[0] + (b[0] - a[0]) * t,
    a[1] + (b[1] - a[1]) * t,
    a[2] + (b[2] - a[2]) * t
  ];
}

function bilerp2(p00, p10, p11, p01, u, v) {
  const top = lerp2(p00, p10, u);
  const bot = lerp2(p01, p11, u);
  return lerp2(top, bot, v);
}

// Draw a 2D quad with brush.wash
function washQuad2D(p0, p1, p2, p3, col, alpha) {
  brush.noStroke();
  brush. noFill();
  brush.wash(col, alpha);
  brush.beginShape(0);
  brush.vertex(p0[0], p0[1]);
  brush.vertex(p1[0], p1[1]);
  brush.vertex(p2[0], p2[1]);
  brush.vertex(p3[0], p3[1]);
  brush.endShape(true);
  brush.noWash();
}

// Draw a 2D triangle with brush.wash
function washTri2D(p0, p1, p2, col, alpha) {
  brush.noStroke();
  brush.noFill();
  brush.wash(col, alpha);
  brush.beginShape(0);
  brush.vertex(p0[0], p0[1]);
  brush.vertex(p1[0], p1[1]);
  brush.vertex(p2[0], p2[1]);
  brush.endShape(true);
  brush.noWash();
}

// Perspective-aware directional hatching across a 2D projected quad
// dir: "u" (along p0->p1), "v" (along p0->p3), "diag1" (p0->p2), "diag2" (p1->p3)
function hatchQuad2D(p0, p1, p2, p3, opts) {
  const {
    brushName = "cpencil",
    col = "#5a361b",
    weight = 0.45,
    steps = 10,
    dir = "u",
    jitter = 0.8,
    skipProb = 0.0,
    gradStart = 1.0,
    gradEnd = 1.0
  } = opts;

  brush.noFill();
  brush.noWash();
  brush.set(brushName, col, weight);

  if (dir === "u") {
    for (let i = 0; i <= steps; i++) {
      if (skipProb > 0 && random() < skipProb) continue;
      const v = i / max(1, steps);
      const prob = lerp(gradStart, gradEnd, v);
      if (random() > prob) continue;
      const a = lerp2(p0, p3, v);
      const b = lerp2(p1, p2, v);
      brush.line(
        a[0] + random(-jitter, jitter),
        a[1] + random(-jitter, jitter),
        b[0] + random(-jitter, jitter),
        b[1] + random(-jitter, jitter)
      );
    }
  } else if (dir === "v") {
    for (let i = 0; i <= steps; i++) {
      if (skipProb > 0 && random() < skipProb) continue;
      const u = i / max(1, steps);
      const prob = lerp(gradStart, gradEnd, u);
      if (random() > prob) continue;
      const a = lerp2(p0, p1, u);
      const b = lerp2(p3, p2, u);
      brush.line(
        a[0] + random(-jitter, jitter),
        a[1] + random(-jitter, jitter),
        b[0] + random(-jitter, jitter),
        b[1] + random(-jitter, jitter)
      );
    }
  } else if (dir === "diag1") {
    for (let i = 1; i < steps * 2; i++) {
      const t = i / (steps * 2);
      const a = t < 0.5 ? lerp2(p0, p3, t * 2) : lerp2(p3, p2, (t - 0.5) * 2);
      const b = t < 0.5 ? lerp2(p0, p1, t * 2) : lerp2(p1, p2, (t - 0.5) * 2);
      brush.line(
        a[0] + random(-jitter, jitter),
        a[1] + random(-jitter, jitter),
        b[0] + random(-jitter, jitter),
        b[1] + random(-jitter, jitter)
      );
    }
  } else if (dir === "diag2") {
    for (let i = 1; i < steps * 2; i++) {
      const t = i / (steps * 2);
      const a = t < 0.5 ? lerp2(p1, p0, t * 2) : lerp2(p0, p3, (t - 0.5) * 2);
      const b = t < 0.5 ? lerp2(p1, p2, t * 2) : lerp2(p2, p3, (t - 0.5) * 2);
      brush.line(
        a[0] + random(-jitter, jitter),
        a[1] + random(-jitter, jitter),
        b[0] + random(-jitter, jitter),
        b[1] + random(-jitter, jitter)
      );
    }
  }
}

// Perspective-aware hatching across a triangle p0, p1, p2 (lines parallel to p1-p2 from p0)
function hatchTri2D(p0, p1, p2, opts) {
  const {
    brushName = "rotring",
    col = "#3b2110",
    weight = 0.4,
    steps = 8,
    jitter = 0.5
  } = opts;

  brush.noFill();
  brush.noWash();
  brush.set(brushName, col, weight);

  for (let i = 1; i <= steps; i++) {
    const t = i / (steps + 1);
    const a = lerp2(p0, p1, t);
    const b = lerp2(p0, p2, t);
    brush.line(
      a[0] + random(-jitter, jitter),
      a[1] + random(-jitter, jitter),
      b[0] + random(-jitter, jitter),
      b[1] + random(-jitter, jitter)
    );
  }
}

// ============================================================================
// BACKGROUND, PAPER TEXTURE & RAKING TABLETOP SHADOWS
// ============================================================================
function drawBackgroundAndTable(tiers) {
  // Base aged rag paper
  background("#e7dcc6");

  // Watercolor atmospheric washes (grouped by color for speed)
  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.55, 0.35);

  // Upper wall warm sepia-buff gradient behind pyramid so the daylight flame pops
  brush.fill("#cbb898", 95);
  brush.rect(60, 40, 1080, 620, "corner");
  brush.fill("#b8a07e", 85);
  brush.circle(555, 310, 320, 0.25);

  // Lower tabletop warm ochre-wood wash
  brush.fill("#d8c39e", 110);
  brush.rect(50, 620, 1100, 530, "corner");

  // Deep shadow aura on the right side of the tabletop
  brush.fill("#9c7e5b", 90);
  brush.beginShape(0.2);
  brush.vertex(560, 600);
  brush.vertex(1150, 640);
  brush.vertex(1150, 990);
  brush.vertex(630, 960);
  brush.endShape(true);
  brush.noFill();

  // Subtle background wall vertical hatching in warm brown pencil
  brush.set("2H", "#b59e7d", 0.38);
  for (let x = 80; x < 1120; x += 9) {
    const topY = 55 + random(-10, 15);
    const botY = 610 + (x - 600) * 0.08 + random(-15, 15);
    brush.line(x + random(-2, 2), topY, x + random(-2, 2), botY);
  }
  // Darker vertical hatching behind the upper pyramid and match flame
  brush.set("HB", "#967c5c", 0.36);
  for (let x = 350; x < 780; x += 6) {
    const distFromCenter = abs(x - 555);
    if (random() < map(distFromCenter, 0, 220, 0.85, 0.15)) {
      brush.line(
        x + random(-1.5, 1.5),
        90 + distFromCenter * 0.35 + random(-15, 15),
        x + random(-1.5, 1.5),
        520 + random(-20, 20)
      );
    }
  }

  // Tabletop plank lines and wood grain following perspective (+wx axis)
  const plankZ = [-380, -240, -105, 35, 175, 315, 450];
  for (let p = 0; p < plankZ.length - 1; p++) {
    const zA = plankZ[p];
    const zB = plankZ[p + 1];
    // Plank seam
    const s0 = proj(-520, 0, zB);
    const s1 = proj(650, 0, zB);
    brush.set("rotring", "#7a5b3e", 0.42);
    brush.line(s0[0], s0[1], s1[0], s1[1]);
    brush.set("cpencil", "#efe3cc", 0.35);
    brush.line(s0[0], s0[1] + 1.5, s1[0], s1[1] + 1.5);

    // Fine wood grain lines along each plank
    const grainSteps = 18;
    for (let g = 1; g < grainSteps; g++) {
      const zG = lerp(zA, zB, g / grainSteps);
      const g0 = proj(-500 + random(-20, 20), 0, zG);
      const g1 = proj(640 + random(-20, 20), 0, zG);
      const col = g % 3 === 0 ? "#9c7c58" : "#bfa37e";
      brush.set("cpencil", col, random(0.28, 0.45));
      // Slight wave in wood grain
      const mid1 = lerp2(g0, g1, 0.33);
      const mid2 = lerp2(g0, g1, 0.67);
      const wave = sin(g * 28 + p * 50) * 3.5;
      brush.spline(
        [
          [g0[0], g0[1]],
          [mid1[0], mid1[1] + wave],
          [mid2[0], mid2[1] - wave * 0.7],
          [g1[0], g1[1]]
        ],
        0.4
      );
    }
  }

  // Cast stepped pyramid shadow onto the tabletop (wy = 0)
  // Light vector: for height wy, shadow projects by (+1.18 * wy, 0, -0.42 * wy)
  const shDx = 1.18;
  const shDz = -0.42;

  for (let t = 0; t < tiers.length; t++) {
    const tr = tiers[t];
    const y0 = tr.y0;
    const y1 = tr.y1;
    // Project the 4 top corners of this tier onto the table plane wy = 0
    const pFL_b = proj(tr.x1 + y0 * shDx, 0, tr.z1 + y0 * shDz);
    const pFR_b = proj(tr.x1 + y0 * shDx, 0, tr.z0 + y0 * shDz);
    const pBR_b = proj(tr.x0 + y0 * shDx, 0, tr.z0 + y0 * shDz);

    const pFL_t = proj(tr.x1 + y1 * shDx, 0, tr.z1 + y1 * shDz);
    const pFR_t = proj(tr.x1 + y1 * shDx, 0, tr.z0 + y1 * shDz);
    const pBR_t = proj(tr.x0 + y1 * shDx, 0, tr.z0 + y1 * shDz);

    // Shadow quad for front-right slope
    washQuad2D(pFL_b, pFL_t, pFR_t, pFR_b, "#5c3d24", 105);
    // Shadow quad for back-right slope
    washQuad2D(pFR_b, pFR_t, pBR_t, pBR_b, "#5c3d24", 95);

    // Crisp pen and pencil hatching inside the cast tabletop shadow
    hatchQuad2D(pFL_b, pFL_t, pFR_t, pFR_b, {
      brushName: "HB",
      col: "#472c18",
      weight: 0.45,
      steps: 24,
      dir: "u",
      jitter: 1.2
    });
    hatchQuad2D(pFR_b, pFR_t, pBR_t, pBR_b, {
      brushName: "rotring",
      col: "#3b2210",
      weight: 0.35,
      steps: 18,
      dir: "v",
      jitter: 1.0
    });

    // Sawtooth notch-edge Along the shadow boundary
    const numShadowTeeth = max(5, floor((tr.z1 - tr.z0) / 18));
    for (let k = 0; k < numShadowTeeth; k++) {
      const uA = k / numShadowTeeth;
      const uM = (k + 0.5) / numShadowTeeth;
      const uB = (k + 1) / numShadowTeeth;
      const sA = lerp2(pFL_t, pFR_t, uA);
      const sM = lerp2(pFL_t, pFR_t, uM);
      const sB = lerp2(pFL_t, pFR_t, uB);
      washTri2D(sA, [sM[0] + 10, sM[1] + 3], sB, "#4a2e19", 95);
    }
  }

  // Deep contact shadow directly around the base of Tier 0 on the right & front
  const baseT = tiers[0];
  const cFL = proj(baseT.x1, 0, baseT.z1);
  const cFR = proj(baseT.x1, 0, baseT.z0);
  const cFL_out = proj(baseT.x1 + 38, 0, baseT.z1 - 12);
  const cFR_out = proj(baseT.x1 + 45, 0, baseT.z0 - 18);
  washQuad2D(cFL, cFL_out, cFR_out, cFR, "#2b170a", 150);
  hatchQuad2D(cFL, cFL_out, cFR_out, cFR, {
    brushName: "rotring",
    col: "#1f0f05",
    weight: 0.5,
    steps: 26,
    dir: "v",
    jitter: 0.6
  });

  // Subtle foxing spots and aged paper speckles
  for (let i = 0; i < 65; i++) {
    const fx = random(70, 1130);
    const fy = random(60, 1130);
    const r = random(1.5, 6.5);
    brush.noStroke();
    brush.wash(random() < 0.5 ? "#b58e62" : "#9c7144", random(25, 55));
    brush.circle(fx, fy, r, 0.35);
    brush.noWash();
  }
}

// ============================================================================
// TRAMP-ART CHIP-CARVED NOTCHED WAFER LAYER
// ============================================================================
// Renders a 3D horizontal slab [x0, x1] x [y0, y1] x [z0, z1] whose edges
// are whittled into 3D sawtooth chevrons (protruding V-ridges & recessed V-cuts)
function drawTrampArtWafer(x0, x1, y0, y1, z0, z1, opts = {}) {
  const {
    notchPitch = 18,
    notchDepth = 8.5,
    phase = 0, // 0 or 0.5 for alternating Crown-of-Thorns stagger
    drawTop = true,
    topShadowX = null, // x-coordinate where upper tier casts shadow onto top
    castUnderShadow = true
  } = opts;

  const nx = max(4, round((x1 - x0) / notchPitch));
  const nz = max(3, round((z1 - z0) / notchPitch));
  const dx = (x1 - x0) / nx;
  const dz = (z1 - z0) / nz;

  // 1. TOP FACE OF THE WAFER (with sawtooth notched margins)
  if (drawTop) {
    const t00 = proj(x0, y1, z0);
    const t10 = proj(x1, y1, z0);
    const t11 = proj(x1, y1, z1);
    const t01 = proj(x0, y1, z1);

    // Sunlit warm wood top surface
    washQuad2D(t00, t10, t11, t01, "#e2c391", 190);
    hatchQuad2D(t00, t10, t11, t01, {
      brushName: "cpencil",
      col: "#b88a51",
      weight: 0.36,
      steps: max(8, round((z1 - z0) / 7)),
      dir: "u",
      jitter: 0.5
    });

    // If an upper tier sits on this wafer, cast its stepped shadow to the right
    if (topShadowX !== null) {
      const shX0 = constrain(topShadowX, x0, x1);
      const s00 = proj(shX0, y1, z0);
      const s10 = proj(x1, y1, z0);
      const s11 = proj(x1, y1, z1);
      const s01 = proj(shX0, y1, z1);
      washQuad2D(s00, s10, s11, s01, "#704828", 130);
      hatchQuad2D(s00, s10, s11, s01, {
        brushName: "rotring",
        col: "#3d220e",
        weight: 0.38,
        steps: 14,
        dir: "v",
        jitter: 0.5
      });
    }
  }

  // 2. FRONT-LEFT FACE (wz = z1, wx from x0 to x1) — IN RAKING SIDE LIGHT!
  // Every chevron has a brightly lit left facet and a crisp dark sepia right facet
  for (let i = 0; i < nx; i++) {
    const wxA = x0 + i * dx;
    const wxB = wxA + dx;
    const wxM = wxA + dx * (0.48 + (phase ? 0.08 : -0.04));

    // Valley points recede in Z; ridge peak protrudes in Z
    const zVal = z1 - notchDepth * 0.55;
    const zPeak = z1 + notchDepth * 0.55;

    // Slight vertical bevel so the notch looks hand-whittled with a pocketknife
    const zPeakBot = zPeak - 1.8;
    const zValTop = zVal + 1.2;

    // 3D points of Left Facet (facing into left raking light)
    const L_tl = proj(wxA, y1, zValTop);
    const L_tr = proj(wxM, y1, zPeak);
    const L_br = proj(wxM, y0, zPeakBot);
    const L_bl = proj(wxA, y0, zVal);

    // 3D points of Right Facet (turned away from left raking light -> crisp shadow!)
    const R_tl = L_tr;
    const R_tr = proj(wxB, y1, zValTop);
    const R_br = proj(wxB, y0, zVal);
    const R_bl = L_br;

    // Top sawtooth lip triangle on wy = y1
    if (drawTop) {
      const T_backL = proj(wxA, y1, z1 - notchDepth * 0.8);
      const T_backR = proj(wxB, y1, z1 - notchDepth * 0.8);
      washQuad2D(T_backL, T_backR, R_tr, L_tl, "#ebd2a7", 170);
      washTri2D(L_tl, L_tr, R_tr, "#f5e4c3", 210);
      brush.set("cpencil", "#fff6e3", 0.45);
      brush.line(L_tl[0], L_tl[1], L_tr[0], L_tr[1]);
    }

    // Cast sawtooth shadow onto the vertical wall immediately below wy = y0
    if (castUnderShadow) {
      const shDrop = (y1 - y0) * 0.62;
      const S_l = proj(wxA + 2, y0 - shDrop * 0.25, zVal);
      const S_m = proj(wxM + 4.5, y0 - shDrop, zVal);
      const S_r = proj(wxB + 2, y0 - shDrop * 0.35, zVal);
      washTri2D(L_bl, S_m, R_br, "#2c1709", 165);
      hatchTri2D(S_m, L_bl, R_br, {
        brushName: "rotring",
        col: "#1e0e04",
        weight: 0.36,
        steps: 4,
        jitter: 0.3
      });
    }

    // Render LEFT FACET (Sunlit whittled wood)
    const litCol = i % 2 === 0 ? "#edd4aa" : "#e5c898";
    washQuad2D(L_tl, L_tr, L_br, L_bl, litCol, 225);
    hatchQuad2D(L_tl, L_tr, L_br, L_bl, {
      brushName: "cpencil",
      col: "#b88952",
      weight: 0.38,
      steps: 5,
      dir: "u",
      jitter: 0.35
    });

    // Render RIGHT FACET (Crisp raking chevron shadow)
    const shCol = i % 3 === 0 ? "#59351a" : "#663e20";
    washQuad2D(R_tl, R_tr, R_br, R_bl, shCol, 230);
    hatchQuad2D(R_tl, R_tr, R_br, R_bl, {
      brushName: "rotring",
      col: "#2d180a",
      weight: 0.42,
      steps: 7,
      dir: "u",
      jitter: 0.3
    });
    hatchQuad2D(R_tl, R_tr, R_br, R_bl, {
      brushName: "HB",
      col: "#3d2210",
      weight: 0.35,
      steps: 5,
      dir: "v",
      jitter: 0.3
    });

    // Crisp whittled ridge highlight & valley sepia crease
    brush.set("cpencil", "#fbf0d9", 0.55);
    brush.line(L_tr[0], L_tr[1], L_br[0], L_br[1]);
    brush.set("rotring", "#2b1608", 0.48);
    brush.line(R_tr[0], R_tr[1], R_br[0], R_br[1]);
    brush.line(L_tl[0], L_tl[1], L_bl[0], L_bl[1]);
    // Bottom knife-cut bevel outline
    brush.set("rotring", "#331b0b", 0.45);
    brush.line(L_bl[0], L_bl[1], L_br[0], L_br[1]);
    brush.line(R_bl[0], R_bl[1], R_br[0], R_br[1]);
  }

  // 3. FRONT-RIGHT FACE (wx = x1, wz from z0 to z1) — IN GLOBAL CORE SHADOW
  // Receives warm bounce light on facets angled toward front, deep umber on facets angled back
  for (let j = 0; j < nz; j++) {
    const wzA = z0 + j * dz;
    const wzB = wzA + dz;
    const wzM = wzA + dz * (0.5 + (phase ? -0.06 : 0.06));

    const xVal = x1 - notchDepth * 0.55;
    const xPeak = x1 + notchDepth * 0.55;
    const xPeakBot = xPeak - 1.6;
    const xValTop = xVal + 1.0;

    // Back-ward facet (wzA -> wzM): turned into deep shadow
    const B_tl = proj(xValTop, y1, wzA);
    const B_tr = proj(xPeak, y1, wzM);
    const B_br = proj(xPeakBot, y0, wzM);
    const B_bl = proj(xVal, y0, wzA);

    // Front-ward facet (wzM -> wzB): catches warm tabletop bounce light
    const F_tl = B_tr;
    const F_tr = proj(xValTop, y1, wzB);
    const F_br = proj(xVal, y0, wzB);
    const F_bl = B_br;

    if (drawTop) {
      washTri2D(B_tl, B_tr, F_tr, "#9e7348", 195);
    }

    if (castUnderShadow) {
      const shDrop = (y1 - y0) * 0.58;
      const S_m = proj(xVal, y0 - shDrop, wzM);
      washTri2D(B_bl, S_m, F_br, "#1f0f05", 180);
    }

    // Deep shadow facet
    washQuad2D(B_tl, B_tr, B_br, B_bl, "#3d2310", 235);
    hatchQuad2D(B_tl, B_tr, B_br, B_bl, {
      brushName: "rotring",
      col: "#1f0f05",
      weight: 0.44,
      steps: 7,
      dir: "u",
      jitter: 0.3
    });

    // Bounce-lit shadow facet
    washQuad2D(F_tl, F_tr, F_br, F_bl, "#784e2c", 225);
    hatchQuad2D(F_tl, F_tr, F_br, F_bl, {
      brushName: "cpencil",
      col: "#4d2e16",
      weight: 0.38,
      steps: 6,
      dir: "u",
      jitter: 0.35
    });

    // Ridge and valley lines on shadow side
    brush.set("cpencil", "#9e7247", 0.42);
    brush.line(B_tr[0], B_tr[1], B_br[0], B_br[1]);
    brush.set("rotring", "#1c0d04", 0.5);
    brush.line(B_tl[0], B_tl[1], B_bl[0], B_bl[1]);
    brush.line(B_bl[0], B_bl[1], B_br[0], B_br[1]);
    brush.line(F_bl[0], F_bl[1], F_br[0], F_br[1]);
  }
}

// ============================================================================
// VINTAGE PAPER LABELS (BRICK RED & MUSTARD WITH PEELING / FOXED DETAIL)
// ============================================================================
function drawMatchboxLabelFrontLeft(x0, x1, y0, y1, zFace, styleIdx, peelCorner) {
  // Inset slightly from the raw whittled wood margins of the matchbox
  const mx = (x1 - x0) * 0.06;
  const my = (y1 - y0) * 0.11;
  const lx0 = x0 + mx;
  const lx1 = x1 - mx;
  const ly0 = y0 + my;
  const ly1 = y1 - my;
  const lz = zFace + 0.4;

  const pTL = proj(lx0, ly1, lz);
  const pTR = proj(lx1, ly1, lz);
  const pBR = proj(lx1, ly0, lz);
  const pBL = proj(lx0, ly0, lz);

  const brickLit = "#a83e2d";
  const brickMid = "#8c2f20";
  const brickDark = "#5e1c12";
  const mustLit = "#d49c3d";
  const mustMid = "#b58029";
  const creamPaper = "#e6d4b5";
  const sepiaInk = "#331b0c";

  if (styleIdx % 3 === 0) {
    // STYLE 0: Brick-Red Field with Mustard Border & Central Mustard Diamond
    washQuad2D(pTL, pTR, pBR, pBL, brickLit, 225);
    hatchQuad2D(pTL, pTR, pBR, pBL, {
      brushName: "cpencil",
      col: brickMid,
      weight: 0.36,
      steps: 14,
      dir: "u",
      jitter: 0.4
    });

    // Mustard inner border frame
    const b0 = bilerp2(pTL, pTR, pBR, pBL, 0.07, 0.12);
    const b1 = bilerp2(pTL, pTR, pBR, pBL, 0.93, 0.12);
    const b2 = bilerp2(pTL, pTR, pBR, pBL, 0.93, 0.88);
    const b3 = bilerp2(pTL, pTR, pBR, pBL, 0.07, 0.88);
    brush.set("cpencil", mustLit, 0.75);
    brush.line(b0[0], b0[1], b1[0], b1[1]);
    brush.line(b1[0], b1[1], b2[0], b2[1]);
    brush.line(b2[0], b2[1], b3[0], b3[1]);
    brush.line(b3[0], b3[1], b0[0], b0[1]);

    // Central Mustard Diamond Medallion
    const dTop = bilerp2(pTL, pTR, pBR, pBL, 0.5, 0.16);
    const dRight = bilerp2(pTL, pTR, pBR, pBL, 0.82, 0.5);
    const dBot = bilerp2(pTL, pTR, pBR, pBL, 0.5, 0.84);
    const dLeft = bilerp2(pTL, pTR, pBR, pBL, 0.18, 0.5);
    washQuad2D(dTop, dRight, dBot, dLeft, mustLit, 230);
    hatchQuad2D(dTop, dRight, dBot, dLeft, {
      brushName: "cpencil",
      col: mustMid,
      weight: 0.32,
      steps: 8,
      dir: "u",
      jitter: 0.3
    });
    brush.set("rotring", sepiaInk, 0.38);
    brush.line(dTop[0], dTop[1], dRight[0], dRight[1]);
    brush.line(dRight[0], dRight[1], dBot[0], dBot[1]);
    brush.line(dBot[0], dBot[1], dLeft[0], dLeft[1]);
    brush.line(dLeft[0], dLeft[1], dTop[0], dTop[1]);

    // Tiny vintage emblem inside diamond (three stars / torch lines)
    const cMid = bilerp2(pTL, pTR, pBR, pBL, 0.5, 0.5);
    const cL = bilerp2(pTL, pTR, pBR, pBL, 0.37, 0.5);
    const cR = bilerp2(pTL, pTR, pBR, pBL, 0.63, 0.5);
    brush.set("rotring", brickDark, 0.42);
    for (const pt of [cL, cMid, cR]) {
      brush.line(pt[0] - 3, pt[1], pt[0] + 3, pt[1]);
      brush.line(pt[0], pt[1] - 3, pt[0], pt[1] + 3);
    }
  } else if (styleIdx % 3 === 1) {
    // STYLE 1: Mustard Field with Brick-Red Side Bands & Sunburst Medallion
    washQuad2D(pTL, pTR, pBR, pBL, mustLit, 225);
    hatchQuad2D(pTL, pTR, pBR, pBL, {
      brushName: "cpencil",
      col: mustMid,
      weight: 0.36,
      steps: 13,
      dir: "u",
      jitter: 0.4
    });

    // Left and right brick-red vertical bands
    const l1 = lerp2(pTL, pTR, 0.22);
    const l2 = lerp2(pBL, pBR, 0.22);
    const r1 = lerp2(pTL, pTR, 0.78);
    const r2 = lerp2(pBL, pBR, 0.78);
    washQuad2D(pTL, l1, l2, pBL, brickLit, 225);
    washQuad2D(r1, pTR, pBR, r2, brickMid, 225);

    // Central brick-red medallion
    const mTL = bilerp2(pTL, pTR, pBR, pBL, 0.36, 0.24);
    const mTR = bilerp2(pTL, pTR, pBR, pBL, 0.64, 0.24);
    const mBR = bilerp2(pTL, pTR, pBR, pBL, 0.64, 0.76);
    const mBL = bilerp2(pTL, pTR, pBR, pBL, 0.36, 0.76);
    washQuad2D(mTL, mTR, mBR, mBL, brickLit, 225);

    // Sepia typographic lines & border rules
    brush.set("rotring", sepiaInk, 0.35);
    brush.line(l1[0], l1[1], l2[0], l2[1]);
    brush.line(r1[0], r1[1], r2[0], r2[1]);
    const tL = bilerp2(pTL, pTR, pBR, pBL, 0.27, 0.16);
    const tR = bilerp2(pTL, pTR, pBR, pBL, 0.73, 0.16);
    const bL = bilerp2(pTL, pTR, pBR, pBL, 0.27, 0.84);
    const bR = bilerp2(pTL, pTR, pBR, pBL, 0.73, 0.84);
    brush.line(tL[0], tL[1], tR[0], tR[1]);
    brush.line(bL[0], bL[1], bR[0], bR[1]);
  } else {
    // STYLE 2: Cream & Mustard Frame with Brick-Red Center Banner
    washQuad2D(pTL, pTR, pBR, pBL, creamPaper, 225);
    const inTL = bilerp2(pTL, pTR, pBR, pBL, 0.08, 0.15);
    const inTR = bilerp2(pTL, pTR, pBR, pBL, 0.92, 0.15);
    const inBR = bilerp2(pTL, pTR, pBR, pBL, 0.92, 0.85);
    const inBL = bilerp2(pTL, pTR, pBR, pBL, 0.08, 0.85);
    washQuad2D(inTL, inTR, inBR, inBL, mustLit, 220);

    const banTL = bilerp2(pTL, pTR, pBR, pBL, 0.08, 0.34);
    const banTR = bilerp2(pTL, pTR, pBR, pBL, 0.92, 0.34);
    const banBR = bilerp2(pTL, pTR, pBR, pBL, 0.92, 0.68);
    const banBL = bilerp2(pTL, pTR, pBR, pBL, 0.08, 0.68);
    washQuad2D(banTL, banTR, banBR, banBL, brickLit, 230);
    hatchQuad2D(banTL, banTR, banBR, banBL, {
      brushName: "cpencil",
      col: brickDark,
      weight: 0.34,
      steps: 6,
      dir: "u",
      jitter: 0.3
    });

    // Simulated fine print ticks along the banner
    brush.set("rotring", creamPaper, 0.4);
    for (let k = 0; k < 9; k++) {
      const u = 0.18 + k * 0.08;
      const a = bilerp2(pTL, pTR, pBR, pBL, u, 0.44);
      const b = bilerp2(pTL, pTR, pBR, pBL, u + 0.04, 0.58);
      brush.line(a[0], a[1], b[0], b[1]);
    }
  }

  // Foxing spots & worn abrasion marks on the paper label
  for (let f = 0; f < 5; f++) {
    const fu = random(0.12, 0.88);
    const fv = random(0.15, 0.85);
    const fp = bilerp2(pTL, pTR, pBR, pBL, fu, fv);
    brush.noStroke();
    brush.wash("#7a4921", random(50, 95));
    brush.circle(fp[0], fp[1], random(1.8, 4.2), 0.3);
    brush.noWash();
  }

  // Paper edge outline in fine sepia ink
  brush.set("rotring", "#4a2a14", 0.35);
  brush.line(pTL[0], pTL[1], pTR[0], pTR[1]);
  brush.line(pTR[0], pTR[1], pBR[0], pBR[1]);
  brush.line(pBR[0], pBR[1], pBL[0], pBL[1]);
  brush.line(pBL[0], pBL[1], pTL[0], pTL[1]);

  // Hyperreal peeling corner detail (exposing raw wood underneath + cast shadow + curled paper underside)
  if (peelCorner === "TR") {
    const cA = lerp2(pTL, pTR, 0.72);
    const cB = lerp2(pTR, pBR, 0.52);
    // Exposed darker glue-stained wood under the peeled corner
    washTri2D(cA, pTR, cB, "#855831", 235);
    // Dark cast shadow of the curling flap
    const shTip = [pTR[0] - 4, pTR[1] + 11];
    washTri2D(cA, shTip, cB, "#261307", 190);
    // Curled cream paper underside sticking out in 3D
    const flapTip = proj(lx1 - (lx1 - lx0) * 0.08, ly1 - (ly1 - ly0) * 0.38, lz + 6.5);
    washTri2D(cA, flapTip, cB, "#efe0c4", 240);
    brush.set("rotring", "#331a0a", 0.42);
    brush.line(cA[0], cA[1], flapTip[0], flapTip[1]);
    brush.line(flapTip[0], flapTip[1], cB[0], cB[1]);
  } else if (peelCorner === "BL") {
    const cA = lerp2(pTL, pBL, 0.48);
    const cB = lerp2(pBL, pBR, 0.28);
    washTri2D(cA, cB, pBL, "#855831", 235);
    const flapTip = proj(lx0 + (lx1 - lx0) * 0.12, ly0 + (ly1 - ly0) * 0.35, lz + 6.0);
    const shTip = [flapTip[0] + 6, flapTip[1] + 4];
    washTri2D(cA, shTip, cB, "#241105", 190);
    washTri2D(cA, flapTip, cB, "#ede0c7", 240);
    brush.set("rotring", "#331a0a", 0.42);
    brush.line(cA[0], cA[1], flapTip[0], flapTip[1]);
    brush.line(flapTip[0], flapTip[1], cB[0], cB[1]);
  }
}

// ============================================================================
// INDIVIDUAL WOODEN MATCHBOX (WITH SLEEVE, V-NOTCHES, STRIKER & AJAR DRAWER)
// ============================================================================
function drawMatchbox(x0, x1, y0, y1, z0, z1, opts = {}) {
  const {
    labelStyle = 0,
    peelCorner = "none",
    sideType = "striker", // "striker", "label", or "drawerOutX"
    drawerOutZ = 0, // if > 0, drawer slides out the front-left face (+wz)
    drawerOutX = 0 // if > 0, drawer slides out the front-right face (+wx)
  } = opts;

  // 1. Front-Left Face (wz = z1)
  const fl_tl = proj(x0, y1, z1);
  const fl_tr = proj(x1, y1, z1);
  const fl_br = proj(x1, y0, z1);
  const fl_bl = proj(x0, y0, z1);

  // Warm sunlit wood sleeve base
  washQuad2D(fl_tl, fl_tr, fl_br, fl_bl, "#deb987", 225);
  hatchQuad2D(fl_tl, fl_tr, fl_br, fl_bl, {
    brushName: "cpencil",
    col: "#b08048",
    weight: 0.36,
    steps: 12,
    dir: "u",
    jitter: 0.4
  });

  if (drawerOutZ > 0) {
    // This matchbox is oriented with its hollow sleeve opening on the Front-Left face,
    // and its wooden inner drawer is pulled slightly out by drawerOutZ!
    const wallT = 3.2;
    const cav_tl = proj(x0 + wallT, y1 - wallT, z1);
    const cav_tr = proj(x1 - wallT, y1 - wallT, z1);
    const cav_br = proj(x1 - wallT, y0 + wallT, z1);
    const cav_bl = proj(x0 + wallT, y0 + wallT, z1);
    // Dark hollow interior of sleeve
    washQuad2D(cav_tl, cav_tr, cav_br, cav_bl, "#211106", 240);

    // Protruding drawer box [x0+wallT .. x1-wallT] x [y0+wallT .. y1-wallT*2.2] x [z1 .. z1+drawerOutZ]
    const dx0 = x0 + wallT;
    const dx1 = x1 - wallT;
    const dy0 = y0 + wallT;
    const dy1 = y1 - wallT * 2.1;
    const dz1 = z1 + drawerOutZ;

    // Cast shadow of protruding drawer to the right onto the box face and tier below
    const sh0 = proj(dx1, dy1, z1);
    const sh1 = proj(dx1 + drawerOutZ * 0.9, dy1 - drawerOutZ * 0.3, z1);
    const sh2 = proj(dx1 + drawerOutZ * 0.9, y0 - 8, z1);
    const sh3 = proj(dx0 + 6, y0 - 8, z1);
    washQuad2D(sh0, sh1, sh2, sh3, "#261306", 175);

    // Inside of the pulled-out drawer (showing packed wooden matchsticks & red heads!)
    const in_tl = proj(dx0, dy1, z1);
    const in_tr = proj(dx1, dy1, z1);
    const in_br = proj(dx1, dy1, dz1);
    const in_bl = proj(dx0, dy1, dz1);
    washQuad2D(in_tl, in_tr, in_br, in_bl, "#381e0d", 235);

    // Draw nested matches inside the open drawer!
    const numMatches = 7;
    for (let m = 0; m < numMatches; m++) {
      const mx = lerp(dx0 + 4, dx1 - 4, m / (numMatches - 1));
      const mStart = proj(mx, dy1 - 1, z1 + 2);
      const mEnd = proj(mx + random(-1.5, 1.5), dy1 - 0.5, dz1 - 3.5);
      brush.set("cpencil", "#ebd0a4", 0.65);
      brush.line(mStart[0], mStart[1], mEnd[0], mEnd[1]);
      brush.noStroke();
      brush.wash(m % 2 === 0 ? "#8f2b1e" : "#4a241b", 235);
      brush.circle(mEnd[0], mEnd[1], 2.6, 0.2);
      brush.noWash();
    }

    // Drawer Front-Left face & Front-Right side wall
    const dFL_tl = proj(dx0, dy1, dz1);
    const dFL_tr = proj(dx1, dy1, dz1);
    const dFL_br = proj(dx1, dy0, dz1);
    const dFL_bl = proj(dx0, dy0, dz1);
    washQuad2D(dFL_tl, dFL_tr, dFL_br, dFL_bl, "#9e6d3e", 235);
    hatchQuad2D(dFL_tl, dFL_tr, dFL_br, dFL_bl, {
      brushName: "rotring",
      col: "#4d2c14",
      weight: 0.36,
      steps: 8,
      dir: "u",
      jitter: 0.3
    });

    const dFR_tl = dFL_tr;
    const dFR_tr = proj(dx1, dy1, z1);
    const dFR_br = proj(dx1, dy0, z1);
    const dFR_bl = dFL_br;
    washQuad2D(dFR_tl, dFR_tr, dFR_br, dFR_bl, "#4a2912", 240);
    hatchQuad2D(dFR_tl, dFR_tr, dFR_br, dFR_bl, {
      brushName: "rotring",
      col: "#241105",
      weight: 0.4,
      steps: 7,
      dir: "u",
      jitter: 0.3
    });
  } else {
    // Draw vintage brick-red & mustard paper label on the Front-Left face
    drawMatchboxLabelFrontLeft(x0, x1, y0, y1, z1, labelStyle, peelCorner);
  }

  // Carved V-chip notches along the top and bottom wooden rims of the Front-Left box sleeve
  const numRimChips = max(4, round((x1 - x0) / 20));
  const chipW = (x1 - x0) / numRimChips;
  const chipH = (y1 - y0) * 0.16;
  for (let c = 0; c < numRimChips; c++) {
    const cxA = x0 + c * chipW + chipW * 0.15;
    const cxB = x0 + (c + 1) * chipW - chipW * 0.15;
    const cxM = (cxA + cxB) * 0.5;
    // Recessed V-chip at top edge: left triangle is in shadow, right triangle is lit!
    const tL = proj(cxA, y1, z1);
    const tR = proj(cxB, y1, z1);
    const tMidIn = proj(cxM, y1 - chipH * 0.3, z1 - 3.5);
    const tBot = proj(cxM, y1 - chipH, z1 + 0.5);
    washTri2D(tL, tMidIn, tBot, "#472812", 225);
    washTri2D(tMidIn, tR, tBot, "#f5e3c1", 225);
    brush.set("rotring", "#2b1608", 0.38);
    brush.line(tL[0], tL[1], tBot[0], tBot[1]);
    brush.line(tBot[0], tBot[1], tR[0], tR[1]);
  }

  // 2. Front-Right Face (wx = x1, wz from z0 to z1) — Shadow Side
  const fr_tl = proj(x1, y1, z0);
  const fr_tr = proj(x1, y1, z1);
  const fr_br = proj(x1, y0, z1);
  const fr_bl = proj(x1, y0, z0);

  washQuad2D(fr_tl, fr_tr, fr_br, fr_bl, "#6e4726", 235);
  hatchQuad2D(fr_tl, fr_tr, fr_br, fr_bl, {
    brushName: "HB",
    col: "#3d2310",
    weight: 0.4,
    steps: 14,
    dir: "u",
    jitter: 0.4
  });

  if (drawerOutX > 0) {
    // Drawer slides slightly out the Front-Right face (+wx)
    const wallT = 3.0;
    const dz0 = z0 + wallT;
    const dz1 = z1 - wallT;
    const dy0 = y0 + wallT;
    const dy1 = y1 - wallT * 2.0;
    const dx1 = x1 + drawerOutX;

    // Dark cavity inside sleeve
    washQuad2D(
      proj(x1, y1 - wallT, dz0),
      proj(x1, y1 - wallT, dz1),
      proj(x1, dy0, dz1),
      proj(x1, dy0, dz0),
      "#1c0d04",
      245
    );

    // Top of open drawer with matches peeking out
    const dt0 = proj(x1, dy1, dz0);
    const dt1 = proj(dx1, dy1, dz0);
    const dt2 = proj(dx1, dy1, dz1);
    const dt3 = proj(x1, dy1, dz1);
    washQuad2D(dt0, dt1, dt2, dt3, "#2e180a", 240);
    for (let m = 0; m < 5; m++) {
      const mz = lerp(dz0 + 4, dz1 - 4, m / 4);
      const ms = proj(x1 + 2, dy1 - 1, mz);
      const me = proj(dx1 - 2, dy1 - 0.5, mz);
      brush.set("cpencil", "#cfa978", 0.55);
      brush.line(ms[0], ms[1], me[0], me[1]);
      brush.noStroke();
      brush.wash("#6e2016", 230);
      brush.circle(me[0], me[1], 2.3, 0.2);
      brush.noWash();
    }

    // Drawer Front-Left side & Front-Right end
    const dFL0 = proj(x1, dy1, dz1);
    const dFL1 = proj(dx1, dy1, dz1);
    const dFL2 = proj(dx1, dy0, dz1);
    const dFL3 = proj(x1, dy0, dz1);
    washQuad2D(dFL0, dFL1, dFL2, dFL3, "#b58550", 230);

    const dFR0 = proj(dx1, dy1, dz0);
    const dFR1 = proj(dx1, dy1, dz1);
    const dFR2 = proj(dx1, dy0, dz1);
    const dFR3 = proj(dx1, dy0, dz0);
    washQuad2D(dFR0, dFR1, dFR2, dFR3, "#472813", 240);
    hatchQuad2D(dFR0, dFR1, dFR2, dFR3, {
      brushName: "rotring",
      col: "#211005",
      weight: 0.42,
      steps: 9,
      dir: "u",
      jitter: 0.3
    });
  } else if (sideType === "striker") {
    // Dark gritty phosphorus striker strip along the side of the matchbox
    const st_tl = bilerp2(fr_tl, fr_tr, fr_br, fr_bl, 0.08, 0.22);
    const st_tr = bilerp2(fr_tl, fr_tr, fr_br, fr_bl, 0.92, 0.22);
    const st_br = bilerp2(fr_tl, fr_tr, fr_br, fr_bl, 0.92, 0.78);
    const st_bl = bilerp2(fr_tl, fr_tr, fr_br, fr_bl, 0.08, 0.78);

    washQuad2D(st_tl, st_tr, st_br, st_bl, "#2e1a14", 235);
    hatchQuad2D(st_tl, st_tr, st_br, st_bl, {
      brushName: "2B",
      col: "#1c0e0a",
      weight: 0.48,
      steps: 12,
      dir: "diag1",
      jitter: 0.5
    });
    // Pale worn strike scratch marks across the phosphorus strip
    brush.set("cpencil", "#a88765", 0.35);
    for (let s = 0; s < 6; s++) {
      const u1 = random(0.1, 0.55);
      const u2 = u1 + random(0.2, 0.4);
      const pA = bilerp2(st_tl, st_tr, st_br, st_bl, u1, random(0.2, 0.8));
      const pB = bilerp2(st_tl, st_tr, st_br, fr_bl, u2, random(0.2, 0.8));
      brush.line(pA[0], pA[1], pB[0], pB[1]);
    }
  } else {
    // Shadowed brick-red & mustard end label
    const el_tl = bilerp2(fr_tl, fr_tr, fr_br, fr_bl, 0.1, 0.16);
    const el_tr = bilerp2(fr_tl, fr_tr, fr_br, fr_bl, 0.9, 0.16);
    const el_br = bilerp2(fr_tl, fr_tr, fr_br, fr_bl, 0.9, 0.84);
    const el_bl = bilerp2(fr_tl, fr_tr, fr_br, fr_bl, 0.1, 0.84);
    washQuad2D(el_tl, el_tr, el_br, el_bl, "#5e2218", 230);
    hatchQuad2D(el_tl, el_tr, el_br, el_bl, {
      brushName: "rotring",
      col: "#2b0f0a",
      weight: 0.38,
      steps: 10,
      dir: "u",
      jitter: 0.3
    });
  }

  // Crisp vertical corner spine between lit Front-Left and shadowed Front-Right
  brush.set("cpencil", "#f5e3c1", 0.5);
  brush.line(fl_tr[0] - 0.8, fl_tr[1], fl_br[0] - 0.8, fl_br[1]);
  brush.set("rotring", "#2b1608", 0.48);
  brush.line(fl_tr[0] + 0.6, fl_tr[1], fl_br[0] + 0.6, fl_br[1]);
}

// ============================================================================
// SCATTERED SPENT MATCH HEADS & WOOD CHIPS AT THE BASE
// ============================================================================
function drawSpentMatchOnTable(wx, wz, len, angleDeg, isBurnt = true, curlUp = 4) {
  const rad = angleDeg * (PI / 180);
  const dx = cos(rad) * len;
  const dz = sin(rad) * len;
  const wx1 = wx + dx;
  const wz1 = wz + dz;

  // Cast shadow on tabletop (wy = 0)
  const s0 = proj(wx + 3, 0, wz - 1.5);
  const s1 = proj(wx1 + 6 + curlUp * 1.1, 0, wz1 - 2.5 - curlUp * 0.4);
  brush.set("HB", "#452a16", 1.1);
  brush.line(s0[0], s0[1], s1[0], s1[1]);
  brush.set("rotring", "#291609", 0.65);
  brush.line(s0[0], s0[1], s1[0], s1[1]);

  // 3D points along the matchstick shaft (slight upward curl near burnt tip)
  const pBase = proj(wx, 2.2, wz);
  const pMid = proj(wx + dx * 0.62, 2.2 + curlUp * 0.25, wz + dz * 0.62);
  const pNeck = proj(wx + dx * 0.84, 2.4 + curlUp * 0.65, wz + dz * 0.84);
  const pHead = proj(wx1, 2.8 + curlUp, wz1);

  // Wooden shaft (lit top edge + shaded lower edge)
  brush.set("cpencil", "#edd2a6", 0.95);
  brush.line(pBase[0], pBase[1] - 1.2, pMid[0], pMid[1] - 1.2);
  brush.set("cpencil", "#9c6d3e", 0.85);
  brush.line(pBase[0], pBase[1] + 0.8, pMid[0], pMid[1] + 0.8);
  brush.set("rotring", "#472913", 0.42);
  brush.line(pBase[0], pBase[1] + 1.8, pMid[0], pMid[1] + 1.8);

  if (isBurnt) {
    // Toasted amber transition -> blackened char neck
    brush.set("cpencil", "#7d451b", 0.9);
    brush.line(pMid[0], pMid[1], pNeck[0], pNeck[1]);
    brush.set("charcoal", "#1c1613", 0.95);
    brush.line(pNeck[0], pNeck[1], pHead[0], pHead[1]);

    // Bulbous porous spent match head
    brush.noStroke();
    brush.wash("#1c1512", 245);
    brush.circle(pHead[0], pHead[1], 4.8, 0.35);
    brush.wash("#362b26", 210);
    brush.circle(pHead[0] - 1.2, pHead[1] - 1.0, 3.1, 0.3);
    brush.noWash();

    // Tiny ash-gray blister highlight & crisp pen contour
    brush.set("cpencil", "#9e9489", 0.45);
    brush.circle(pHead[0] - 1.5, pHead[1] - 1.4, 1.4, 0.2);
    brush.set("rotring", "#120c0a", 0.42);
    brush.circle(pHead[0], pHead[1], 4.8, 0.3);
  } else {
    // Unburnt wooden shaft + brick-red match head
    brush.set("cpencil", "#e6c797", 0.9);
    brush.line(pMid[0], pMid[1] - 0.8, pHead[0], pHead[1] - 0.8);
    brush.noStroke();
    brush.wash("#8f2b1e", 240);
    brush.circle(pHead[0], pHead[1], 4.5, 0.22);
    brush.noWash();
    brush.set("cpencil", "#d46a59", 0.45);
    brush.line(pHead[0] - 2, pHead[1] - 1.5, pHead[0] + 0.5, pHead[1] - 1.5);
    brush.set("rotring", "#3d120c", 0.4);
    brush.circle(pHead[0], pHead[1], 4.5, 0.2);
  }
}

function drawWoodChipOnTable(wx, wz, sz, rot) {
  const rad = rot * (PI / 180);
  const p0 = proj(wx, 1.5, wz);
  const p1 = proj(wx + cos(rad) * sz, 2.8, wz + sin(rad) * sz);
  const p2 = proj(wx + cos(rad + 2.1) * sz * 0.8, 0.5, wz + sin(rad + 2.1) * sz * 0.8);
  const sh = [p1[0] + 4, p1[1] + 2];

  washTri2D(p0, sh, p2, "#3d2412", 160);
  washTri2D(p0, p1, p2, "#ecd2a6", 230);
  brush.set("rotring", "#422612", 0.35);
  brush.line(p0[0], p0[1], p1[0], p1[1]);
  brush.line(p1[0], p1[1], p2[0], p2[1]);
  brush.line(p2[0], p2[1], p0[0], p0[1]);
}

// ============================================================================
// CROWNING FLARING MATCH AT THE APEX IN DAYLIGHT
// ============================================================================
function drawFlaringApexMatch(topY) {
  const baseW = 3.2;
  const mY0 = topY - 4;
  const mY1 = topY + 76;

  // Slight organic tilt
  const tipX = -3.5;
  const tipZ = -2.0;

  // 1. Warm golden daylight glow on the top surface of the apex matchbox
  const glowCenter = proj(0, topY, 0);
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fill("#f5b841", 85);
  brush.circle(glowCenter[0], glowCenter[1], 48, 0.25);

  // Luminous atmospheric flame halo against the shaded sepia wall
  const headPt = proj(tipX, mY1, tipZ);
  brush.fill("#f2a433", 75);
  brush.circle(headPt[0] + 6, headPt[1] - 24, 66, 0.3);
  brush.fill("#fff2ad", 115);
  brush.circle(headPt[0] + 3, headPt[1] - 18, 36, 0.25);
  brush.noFill();

  // 2. Delicate daylight smoke wisps curling upward from the flame tip
  const smokeBaseX = headPt[0] + 10;
  const smokeBaseY = headPt[1] - 82;
  const smokePaths = [
    [
      [smokeBaseX, smokeBaseY],
      [smokeBaseX + 14, smokeBaseY - 38],
      [smokeBaseX - 8, smokeBaseY - 82],
      [smokeBaseX + 22, smokeBaseY - 130],
      [smokeBaseX + 48, smokeBaseY - 175]
    ],
    [
      [smokeBaseX + 4, smokeBaseY - 8],
      [smokeBaseX + 24, smokeBaseY - 46],
      [smokeBaseX + 6, smokeBaseY - 94],
      [smokeBaseX + 38, smokeBaseY - 142]
    ],
    [
      [smokeBaseX - 3, smokeBaseY + 6],
      [smokeBaseX + 8, smokeBaseY - 30],
      [smokeBaseX - 14, smokeBaseY - 68],
      [smokeBaseX + 10, smokeBaseY - 112]
    ]
  ];
  for (let s = 0; s < smokePaths.length; s++) {
    brush.set("charcoal", s === 0 ? "#dfd5c5" : "#b8a896", s === 0 ? 0.85 : 0.6);
    brush.spline(smokePaths[s], 0.55);
    brush.set("cpencil", "#f7f0e4", 0.45);
    brush.spline(smokePaths[s], 0.55);
  }

  // 3. Outer translucent flame tongue (terracotta-orange & cadmium mustard)
  const fBot = [headPt[0], headPt[1] + 12];
  const fL1 = [headPt[0] - 20, headPt[1] - 6];
  const fL2 = [headPt[0] - 14, headPt[1] - 44];
  const fTip = [headPt[0] + 11, headPt[1] - 84];
  const fR2 = [headPt[0] + 24, headPt[1] - 38];
  const fR1 = [headPt[0] + 18, headPt[1] - 4];

  brush.noStroke();
  brush.wash("#d95b22", 135);
  brush.beginShape(0.45);
  brush.vertex(fBot[0], fBot[1]);
  brush.vertex(fL1[0], fL1[1]);
  brush.vertex(fL2[0], fL2[1]);
  brush.vertex(fTip[0], fTip[1]);
  brush.vertex(fR2[0], fR2[1]);
  brush.vertex(fR1[0], fR1[1]);
  brush.endShape(true);

  // Mid flame body (warm saffron-gold)
  brush.wash("#f5b538", 185);
  brush.beginShape(0.45);
  brush.vertex(fBot[0], fBot[1] + 7);
  brush.vertex(headPt[0] - 14, headPt[1] - 5);
  brush.vertex(headPt[0] - 9, headPt[1] - 36);
  brush.vertex(headPt[0] + 8, headPt[1] - 66);
  brush.vertex(headPt[0] + 17, headPt[1] - 30);
  brush.vertex(headPt[0] + 13, headPt[1] - 4);
  brush.endShape(true);

  // Inner incandescent core (brilliant lemon-white)
  brush.wash("#fff9cc", 235);
  brush.beginShape(0.45);
  brush.vertex(headPt[0], headPt[1] + 4);
  brush.vertex(headPt[0] - 9, headPt[1] - 4);
  brush.vertex(headPt[0] - 5, headPt[1] - 25);
  brush.vertex(headPt[0] + 4, headPt[1] - 44);
  brush.vertex(headPt[0] + 10, headPt[1] - 22);
  brush.vertex(headPt[0] + 8, headPt[1] - 3);
  brush.endShape(true);
  brush.noWash();

  // Directional colored-pencil flame strokes for hyperreal fibrous flicker
  const flameStrokes = [
    { col: "#c94518", w: 0.45, dx: -16, dy: -36 },
    { col: "#e67e22", w: 0.55, dx: -11, dy: -52 },
    { col: "#e67e22", w: 0.55, dx: 16, dy: -46 },
    { col: "#f7c844", w: 0.65, dx: -6, dy: -58 },
    { col: "#f7c844", w: 0.65, dx: 11, dy: -56 },
    { col: "#fffdf0", w: 0.8, dx: 2, dy: -38 },
    { col: "#fffdf0", w: 0.75, dx: -3, dy: -30 }
  ];
  for (const fs of flameStrokes) {
    brush.set("cpencil", fs.col, fs.w);
    brush.spline(
      [
        [headPt[0], headPt[1] + 5],
        [headPt[0] + fs.dx * 0.75, headPt[1] + fs.dy * 0.5],
        [headPt[0] + fs.dx * 0.4 + 4, headPt[1] + fs.dy]
      ],
      0.5
    );
  }

  // 4. The upright wooden matchstick & blistering igniting match head
  // Cast shadow of the vertical matchstick onto the apex box top
  const ms0 = proj(0, mY0, 0);
  const ms1 = proj(32, mY0, -12);
  brush.set("rotring", "#331b0b", 0.75);
  brush.line(ms0[0], ms0[1], ms1[0], ms1[1]);

  // Square-section wooden splint (lit left face, dark right face)
  const bL = proj(-baseW, mY0, baseW);
  const bM = proj(baseW, mY0, baseW);
  const bR = proj(baseW, mY0, -baseW);

  const nY = lerp(mY0, mY1, 0.74);
  const nL = proj(tipX * 0.7 - baseW * 0.85, nY, tipZ * 0.7 + baseW * 0.85);
  const nM = proj(tipX * 0.7 + baseW * 0.85, nY, tipZ * 0.7 + baseW * 0.85);
  const nR = proj(tipX * 0.7 + baseW * 0.85, nY, tipZ * 0.7 - baseW * 0.85);

  washQuad2D(nL, nM, bM, bL, "#f2d8ac", 240);
  washQuad2D(nM, nR, bR, bM, "#7a502a", 240);
  brush.set("rotring", "#2b1608", 0.42);
  brush.line(bL[0], bL[1], nL[0], nL[1]);
  brush.line(bM[0], bM[1], nM[0], nM[1]);
  brush.line(bR[0], bR[1], nR[0], nR[1]);

  // Charred upper neck entering the flame core
  brush.set("charcoal", "#1f1510", 1.15);
  brush.line(nM[0], nM[1], headPt[0], headPt[1]);

  // Blistering, flaring match head with incandescent orange-white fissures
  brush.noStroke();
  brush.wash("#2b160e", 240);
  brush.circle(headPt[0], headPt[1], 5.6, 0.3);
  brush.wash("#ff9b2e", 220);
  brush.circle(headPt[0] - 1.5, headPt[1] - 2.0, 3.4, 0.25);
  brush.wash("#fffef2", 245);
  brush.circle(headPt[0] - 2.0, headPt[1] - 2.5, 2.0, 0.15);
  brush.noWash();

  // 5. Popping phosphorus sparks shooting out in daylight
  const sparkAngles = [-155, -130, -108, -72, -42, -18, 12, 38, 165, -172];
  for (let i = 0; i < sparkAngles.length; i++) {
    const a = sparkAngles[i] * (PI / 180);
    const d1 = random(8, 16);
    const d2 = d1 + random(12, 26);
    const sx1 = headPt[0] + cos(a) * d1;
    const sy1 = headPt[1] - 6 + sin(a) * d1;
    const sx2 = headPt[0] + cos(a) * d2;
    const sy2 = headPt[1] - 6 + sin(a) * d2 + 4; // slight gravity arc

    brush.set("cpencil", "#e86f20", 0.55);
    brush.line(sx1, sy1, sx2, sy2);
    brush.set("cpencil", "#fffbd6", 0.7);
    brush.line(sx1, sy1, lerp(sx1, sx2, 0.6), lerp(sy1, sy2, 0.6));
    // Tiny puff at end of spark
    brush.noStroke();
    brush.wash("#d6c7b4", 160);
    brush.circle(sx2, sy2, random(1.5, 2.8), 0.2);
    brush.noWash();
  }
}

// ============================================================================
// MAIN DRAW LOOP
// ============================================================================
function draw() {
  translate(-width / 2, -height / 2);

  // Define the 7 stepped tiers of the matchbox pyramid
  const tiers = [
    { x0: -252, x1: 252, z0: -198, z1: 198, y0: 0, y1: 62, nx: 3, nz: 2 },
    { x0: -206, x1: 206, z0: -162, z1: 162, y0: 62, y1: 122, nx: 2, nz: 2 },
    { x0: -164, x1: 164, z0: -128, z1: 128, y0: 122, y1: 180, nx: 2, nz: 1 },
    { x0: -124, x1: 124, z0: -98, z1: 98, y0: 180, y1: 236, nx: 1, nz: 1 },
    { x0: -88, x1: 88, z0: -70, z1: 70, y0: 236, y1: 290, nx: 1, nz: 1 },
    { x0: -58, x1: 58, z0: -46, z1: 46, y0: 290, y1: 340, nx: 1, nz: 1 },
    { x0: -34, x1: 34, z0: -27, z1: 27, y0: 340, y1: 386, nx: 1, nz: 1 }
  ];

  // 1. Background, aged paper, wood tabletop, and raking pyramid cast shadows
  drawBackgroundAndTable(tiers);

  // 2. Back-left wood chips & spent matches (behind the front of the pyramid)
  drawWoodChipOnTable(-290, 140, 12, 25);
  drawWoodChipOnTable(-275, 210, 10, 110);
  drawSpentMatchOnTable(-305, 175, 48, 32, true, 3);

  // 3. Build the Stepped Pyramid from Tier 0 (Base) up to Tier 6 (Apex)
  let labelCounter = 0;
  for (let t = 0; t < tiers.length; t++) {
    const tr = tiers[t];
    const nextTr = t < tiers.length - 1 ? tiers[t + 1] : null;
    const totalH = tr.y1 - tr.y0;
    const botWaferH = totalH * 0.21;
    const topWaferH = totalH * 0.22;
    const boxY0 = tr.y0 + botWaferH;
    const boxY1 = tr.y1 - topWaferH;

    // A. Bottom Tramp-Art Chip-Carved Wafer of this Tier
    drawTrampArtWafer(
      tr.x0 - 4,
      tr.x1 + 4,
      tr.y0,
      boxY0,
      tr.z0 - 4,
      tr.z1 + 4,
      {
        notchPitch: max(12, 20 - t * 1.3),
        notchDepth: max(5.5, 9.5 - t * 0.5),
        phase: t % 2 === 0 ? 0 : 0.5,
        drawTop: true,
        topShadowX: tr.x0 + 10,
        castUnderShadow: t > 0
      }
    );

    // B. Grid of Wooden Matchboxes in this Tier (drawn in strict back-to-front order)
    const cellW = (tr.x1 - tr.x0) / tr.nx;
    const cellD = (tr.z1 - tr.z0) / tr.nz;

    for (let ix = 0; ix < tr.nx; ix++) {
      for (let iz = 0; iz < tr.nz; iz++) {
        // Only boxes on the visible outer faces (ix === nx-1 or iz === nz-1) need full rendering
        if (ix < tr.nx - 1 && iz < tr.nz - 1) continue;

        const bx0 = tr.x0 + ix * cellW + 1.2;
        const bx1 = tr.x0 + (ix + 1) * cellW - 1.2;
        const bz0 = tr.z0 + iz * cellD + 1.2;
        const bz1 = tr.z0 + (iz + 1) * cellD - 1.2;

        // Configure specific storytelling incidents on certain matchboxes
        let drawerOutZ = 0;
        let drawerOutX = 0;
        let peel = "none";
        let sideType = (t + iz) % 2 === 0 ? "striker" : "label";

        if (t === 0 && ix === 1 && iz === tr.nz - 1) {
          drawerOutZ = 18; // Middle base box has its drawer pulled out toward front-left!
        } else if (t === 1 && ix === tr.nx - 1 && iz === 1) {
          drawerOutX = 16; // Tier 1 corner box has its drawer pulled out toward front-right!
        } else if (t === 4) {
          drawerOutX = 12; // Upper-mid box slightly ajar
        }

        if (t === 0 && ix === 0) peel = "TR";
        if (t === 1 && ix === 0) peel = "BL";
        if (t === 2 && ix === 1) peel = "TR";
        if (t === 3) peel = "BL";

        drawMatchbox(bx0, bx1, boxY0, boxY1, bz0, bz1, {
          labelStyle: labelCounter++,
          peelCorner: peel,
          sideType: sideType,
          drawerOutZ: drawerOutZ,
          drawerOutX: drawerOutX
        });
      }
    }

    // C. Upper Tramp-Art Chip-Carved Crown Wafer of this Tier
    // Staggered phase (Crown-of-Thorns interlock) + stepped ledge shadow from next tier
    drawTrampArtWafer(
      tr.x0 - 3,
      tr.x1 + 3,
      boxY1,
      tr.y1,
      tr.z0 - 3,
      tr.z1 + 3,
      {
        notchPitch: max(11, 19 - t * 1.3),
        notchDepth: max(5.5, 9.2 - t * 0.5),
        phase: t % 2 === 0 ? 0.5 : 0,
        drawTop: true,
        topShadowX: nextTr ? nextTr.x1 - 12 : null,
        castUnderShadow: true
      }
    );

    // Extra intermediate notched collar on upper tiers to emphasize the obsessive whittled rhythm
    if (t >= 2 && nextTr) {
      const collarH = 6.5;
      drawTrampArtWafer(
        lerp(tr.x0, nextTr.x0, 0.55),
        lerp(tr.x1, nextTr.x1, 0.55),
        tr.y1,
        tr.y1 + collarH,
        lerp(tr.z0, nextTr.z0, 0.55),
        lerp(tr.z1, nextTr.z1, 0.55),
        {
          notchPitch: max(10, 16 - t),
          notchDepth: 6.5,
          phase: t % 2,
          drawTop: true,
          topShadowX: nextTr.x1 - 6,
          castUnderShadow: true
        }
      );
      nextTr.y0 += collarH;
    }
  }

  // 4. Crowning flaring matchstick at the apex of the pyramid
  const apexTier = tiers[tiers.length - 1];
  drawFlaringApexMatch(apexTier.y1);

  // 5. Foreground scattered spent match heads & whittled wood V-chips at the base
  const foregroundChips = [
    [-190, 245, 11, 15],
    [-145, 232, 9, 75],
    [-65, 255, 13, 140],
    [35, 248, 10, 45],
    [95, 265, 12, 195],
    [185, 238, 11, 88],
    [245, 225, 9, 130],
    [285, 155, 12, 22],
    [295, 75, 10, 64],
    [278, -45, 11, 115],
    [140, 285, 8, 10],
    [-25, 275, 9, 55]
  ];
  for (const ch of foregroundChips) {
    drawWoodChipOnTable(ch[0], ch[1], ch[2], ch[3]);
  }

  // Scattered spent & unburnt matches around the base
  const matches = [
    // [wx, wz, length, angleDeg, isBurnt, curlUp]
    [-225, 245, 52, 18, true, 4.5],
    [-165, 268, 46, -24, true, 3.5],
    [-95, 242, 50, 42, false, 1.0], // Unburnt brick-red match head
    [-35, 285, 54, -12, true, 5.5],
    [22, 262, 44, 65, true, 4.0],
    [78, 298, 52, -38, true, 5.0],
    [145, 260, 48, 14, true, 3.0],
    [195, 292, 36, 128, true, 2.5], // Broken half-match
    [255, 248, 52, -19, true, 4.8],
    [292, 195, 50, 34, false, 1.0], // Unburnt match on shadow side
    [315, 115, 48, -45, true, 3.8],
    [295, 25, 52, 12, true, 4.2],
    [335, -35, 45, 72, true, 3.2],
    [-120, 310, 40, 155, true, 3.6]
  ];
  for (const m of matches) {
    drawSpentMatchOnTable(m[0], m[1], m[2], m[3], m[4], m[5]);
  }

  //Tiny crumbled char/ash specks near the spent match heads
  brush.set("rotring", "#241914", 0.55);
  for (let i = 0; i < 45; i++) {
