// ============================================================================
// COORDINATE TRANSFORM & GEOMETRY HELPERS
// ============================================================================

// Maps local hot dog coordinates (u along length, v perpendicular) to canvas (x, y)
function dogPt(u, v, plate = PLATES.ink) {
  const cx = 602;
  const cy = 626;
  const ang = -19.5 * (Math.PI / 180);
  // Subtle 3D smile curve along the length of the hot dog
  const vc = v + 0.00015 * (u * u) - 16;
  const x = cx + u * Math.cos(ang) - vc * Math.sin(ang) + (plate.dx || 0);
  const y = cy + u * Math.sin(ang) + vc * Math.cos(ang) + (plate.dy || 0);
  return [x, y];
}

function drawPoly(pts, curvature = 0.12, close = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(close);
}

function clampToPanel(pt, pad = 0, plate = PLATES.ink) {
  const x = constrain(pt[0], PANEL.x1 + pad + plate.dx, PANEL.x2 - pad + plate.dx);
  const y = constrain(pt[1], PANEL.y1 + pad + plate.dy, PANEL.y2 - pad + plate.dy);
  return [x, y];
}

// Anatomical envelope functions in (u, v) space
function upperBunTopV(u) {
  const t = Math.min(1, Math.abs(u) / 378);
  return -172 + 124 * Math.pow(t, 2.35) + 3 * Math.sin(u * 0.045);
}

function upperBunBotV(u) {
  const t = Math.min(1, Math.abs(u) / 378);
  return -36 + 14 * Math.pow(t, 1.8) + 4 * Math.sin(u * 0.03);
}

function lowerBunTopV(u) {
  const t = Math.min(1, Math.abs(u) / 380);
  return 26 - 14 * Math.pow(t, 1.9) + 3 * Math.cos(u * 0.035);
}

function lowerBunBotV(u) {
  const t = Math.min(1, Math.abs(u) / 380);
  return 98 - 22 * Math.pow(t, 2.2) + 4 * Math.sin(u * 0.04);
}

function sausageCenterV(u) {
  return -7 - 11 * Math.cos(u * 0.0042);
}

function sausageRadius(u) {
  const norm = Math.abs(u) / 442;
  if (norm >= 1) return 0;
  // Blunt, plump frankfurter cylinder with rounded hemispherical tips
  return 47 * Math.pow(1 - Math.pow(norm, 5.5), 0.38);
}

function trayFrontLipV(u) {
  // Scalloped fluted top edge of the paper boat front wall
  const base = 66 + 18 * Math.pow(u / 430, 2);
  const flute = 6.5 * Math.cos(u * 0.095);
  return base + flute;
}

function trayBottomV(u) {
  return 196 - 14 * Math.pow(u / 390, 2) + 2.5 * Math.cos(u * 0.095);
}

// Mustard zigzag centerline (7 bold ballpark switchbacks)
function mustardCenterV(u) {
  const freq = (u / 355) * 3.5 * Math.PI;
  // Rounded triangle wave for realistic squeezed mustard physics
  const tri = Math.asin(Math.sin(freq)) / (Math.PI / 2);
  const env = 1 - 0.18 * Math.pow(u / 365, 2);
  return -9 + (44 * tri + 9 * Math.sin(freq)) * env;
}

// Ketchup ribbon centerline (glossy undulating wave counter-rhythm)
function ketchupCenterV(u) {
  const freq = (u / 350) * 2.6 * Math.PI + 0.85;
  const env = 1 - 0.15 * Math.pow(u / 360, 2);
  return -5 + 31 * Math.sin(freq) * env + 6 * Math.cos(freq * 2);
}

// Build polygon point arrays for major shapes given a plate offset
function getUpperBunPts(plate, vTopOffset = 0, vBotOffset = 0) {
  const pts = [];
  for (let u = -376; u <= 376; u += 16) {
    pts.push(dogPt(u, upperBunTopV(u) + vTopOffset, plate));
  }
  for (let u = 376; u >= -376; u -= 16) {
    pts.push(dogPt(u, upperBunBotV(u) + vBotOffset, plate));
  }
  return pts;
}

function getLowerBunPts(plate, vTopOffset = 0, vBotOffset = 0) {
  const pts = [];
  for (let u = -378; u <= 378; u += 16) {
    pts.push(dogPt(u, lowerBunTopV(u) + vTopOffset, plate));
  }
  for (let u = 378; u >= -378; u -= 16) {
    pts.push(dogPt(u, lowerBunBotV(u) + vBotOffset, plate));
  }
  return pts;
}

function getSausagePts(plate, scaleR = 1.0, vShift = 0) {
  const pts = [];
  for (let u = -438; u <= 438; u += 14) {
    pts.push(dogPt(u, sausageCenterV(u) - sausageRadius(u) * scaleR + vShift, plate));
  }
  for (let u = 438; u >= -438; u -= 14) {
    pts.push(dogPt(u, sausageCenterV(u) + sausageRadius(u) * scaleR + vShift, plate));
  }
  return pts;
}

function getTrayFrontPts(plate) {
  const pts = [];
  // Left corner accordion flare
  pts.push(dogPt(-472, -18, plate));
  pts.push(dogPt(-442, 36, plate));
  for (let u = -410; u <= 410; u += 14) {
    pts.push(dogPt(u, trayFrontLipV(u), plate));
  }
  // Right corner accordion flare
  pts.push(dogPt(442, 36, plate));
  pts.push(dogPt(472, -18, plate));
  pts.push(dogPt(435, 118, plate));
  for (let u = 385; u >= -385; u -= 18) {
    pts.push(dogPt(u, trayBottomV(u), plate));
  }
  pts.push(dogPt(-435, 118, plate));
  return pts;
}

function getTrayBackLeftPts(plate) {
  return [
    dogPt(-472, -18, plate),
    dogPt(-455, -88, plate),
    dogPt(-412, -102, plate),
    dogPt(-345, -96, plate),
    dogPt(-335, -30, plate),
    dogPt(-410, 42, plate)
  ];
}

function getTrayBackRightPts(plate) {
  return [
    dogPt(335, -30, plate),
    dogPt(345, -96, plate),
    dogPt(412, -102, plate),
    dogPt(455, -88, plate),
    dogPt(472, -18, plate),
    dogPt(410, 42, plate)
  ];
}

function getRibbonPts(centerFn, uStart, uEnd, halfW, plate, vOffset = 0) {
  const topPts = [];
  const botPts = [];
  const step = 6;
  for (let u = uStart; u <= uEnd; u += step) {
    const v0 = centerFn(u) + vOffset;
    const v1 = centerFn(u + 2) + vOffset;
    const du = 2;
    const dv = v1 - v0;
    const len = Math.sqrt(du * du + dv * dv) || 1;
    // Normal vector in (u, v)
    const nu = -dv / len;
    const nv = du / len;
    // Taper at ends and swell at turns
    const endTaper = Math.sin(constrain((u - uStart) / (uEnd - uStart), 0, 1) * Math.PI);
    const turnSwell = 1 + 0.25 * (1 - Math.abs(dv / len));
    const w = halfW * (0.35 + 0.65 * Math.pow(endTaper, 0.35)) * turnSwell;
    topPts.push(dogPt(u + nu * w, v0 + nv * w, plate));
    botPts.push(dogPt(u - nu * w, v0 - nv * w, plate));
  }
  return topPts.concat(botPts.reverse());
}

// ============================================================================
// PROCEDURAL HYPERREAL MICRO-FEATURES GENERATOR
// ============================================================================

function generateSceneData() {
  // 1. Generate ~140 glistening diced pickle relish cubes along upper & lower troughs
  for (let i = 0; i < 142; i++) {
    const isUpper = random() < 0.72;
    const u = random(-350, 350);
    const baseV = isUpper
      ? random(-54, -14) + 5 * Math.sin(u * 0.04)
      : random(16, 44) + 4 * Math.cos(u * 0.05);
    const sizeU = random(9, 21);
    const sizeV = random(8, 17);
    const sides = int(random(4, 6));
    const localPts = [];
    for (let s = 0; s < sides; s++) {
      const a = (s / sides) * Math.PI * 2 + random(-0.25, 0.25);
      const ru = sizeU * random(0.45, 0.65);
      const rv = sizeV * random(0.45, 0.65);
      localPts.push([u + Math.cos(a) * ru, baseV + Math.sin(a) * rv]);
    }
    relishCubes.push({
      u,
      v: baseV,
      sizeU,
      sizeV,
      localPts,
      shade: int(random(3)), // 0 = bright lime, 1 = mid pickle, 2 = deep rind
      hasSeed: random() < 0.18,
      hasGlint: random() < 0.68
    });
  }

  // 2. Generate ~34 hyperreal char-blisters on the frankfurter skin
  for (let i = 0; i < 34; i++) {
    const u = random(-405, 405);
    const maxR = sausageRadius(u) * 0.78;
    const v = sausageCenterV(u) + random(-maxR, maxR);
    const ru = random(6, 19);
    const rv = ru * random(0.55, 0.88);
    const tilt = random(-0.4, 0.4);
    blisters.push({
      u,
      v,
      ru,
      rv,
      tilt,
      isDark: random() < 0.55,
      hasSplit: random() < 0.65
    });
  }

  // 3. Generate ~220 porous bread crumb cells at the exposed bun hinge & ends
  for (let i = 0; i < 220; i++) {
    let u, v;
    const zone = random();
    if (zone < 0.35) {
      // Left split bun hinge
      u = random(-372, -230);
      v = random(lowerBunTopV(u) - 8, lowerBunBotV(u) - 18);
    } else if (zone < 0.70) {
      // Right split bun hinge
      u = random(230, 372);
      v = random(lowerBunTopV(u) - 8, lowerBunBotV(u) - 18);
    } else if (zone < 0.85) {
      // Upper bun underside crumb edge (left & right)
      u = (random() < 0.5 ? -1 : 1) * random(245, 368);
      v = upperBunBotV(u) + random(-22, 4);
    } else {
      // Inner lower bun lip along center
      u = random(-230, 230);
      v = lowerBunTopV(u) + random(2, 24);
    }
    bunPores.push({
      u,
      v,
      ru: random(1.8, 5.5),
      rv: random(1.4, 4.2),
      isDeep: random() < 0.35
    });
  }

  // 4. Stray droplets of mustard, ketchup, and bread crumbs on tray/bun
  condimentDrops = [
    { u: -378, v: 12, r: 7.5, type: "mustard" },
    { u: -215, v: 54, r: 6.0, type: "mustard" },
    { u: 95,   v: -62, r: 5.5, type: "mustard" },
    { u: 372,  v: -18, r: 8.0, type: "mustard" },
    { u: 265,  v: 68, r: 5.0, type: "mustard" },
    { u: -135, v: -52, r: 6.5, type: "ketchup" },
    { u: 185,  v: 46, r: 7.0, type: "ketchup" },
    { u: 360,  v: 14, r: 6.0, type: "ketchup" }
  ];
}

// ============================================================================
// LAYER 1: AGED NEWSPRINT GROUND
// ============================================================================

function drawNewsprintGround() {
  background(PAL.paper);

  // Subtle aged yellowing washes near margins
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.2);
  brush.fill(PAL.paperEdge, 65);
  drawPoly([[0, 0], [W, 0], [W, 130], [0, 130]], 0.05);
  drawPoly([[0, H - 130], [W, H - 130], [W, H], [0, H]], 0.05);
  drawPoly([[0, 0], [130, 0], [130, H], [0, H]], 0.05);
  drawPoly([[W - 130, 0], [W, 0], [W, H], [W - 130, H]], 0.05);
  brush.noFill();

  // Fine newsprint wood-pulp fibers & grain
  brush.set("2H", PAL.paperFiber, 0.45);
  for (let i = 0; i < 420; i++) {
    const x = random(20, W - 20);
    const y = random(20, H - 20);
    const a = random(0, 180) * (Math.PI / 180);
    const len = random(3, 14);
    brush.line(x, y, x + Math.cos(a) * len, y + Math.sin(a) * len);
  }

  brush.set("spray", PAL.paperEdge, 0.7);
  for (let i = 0; i < 45; i++) {
    const x = random(60, W - 60);
    const y = random(60, H - 60);
    brush.line(x, y, x + random(-35, 35), y + random(-35, 35));
  }
}

// ============================================================================
// LAYER 2: PROCESS YELLOW PLATE
// ============================================================================

function drawYellowPlate(plate) {
  brush.noStroke();

  // 2A. Cheerful Sunday comic sunbeams in upper panel sky
  const burstOrigin = dogPt(0, -10, plate);
  const numRays = 14;
  brush.fillBleed(0.08, "out");
  brush.fillTexture(0.25, 0.15);
  brush.fill(PAL.yellowLight, 95);

  for (let i = 0; i < numRays; i += 2) {
    const a1 = (-175 + (i / numRays) * 170) * (Math.PI / 180);
    const a2 = (-175 + ((i + 0.85) / numRays) * 170) * (Math.PI / 180);
    const r = 820;
    const p1 = clampToPanel(burstOrigin, 4, plate);
    const p2 = clampToPanel([burstOrigin[0] + Math.cos(a1) * r, burstOrigin[1] + Math.sin(a1) * r], 4, plate);
    const p3 = clampToPanel([burstOrigin[0] + Math.cos(a2) * r, burstOrigin[1] + Math.sin(a2) * r], 4, plate);
    drawPoly([p1, p2, p3], 0.02);
  }

  // 2B. Warm tabletop counter glow & tray grease spots
  brush.fill(PAL.yellowLight, 70);
  drawPoly([
    [PANEL.x1 + plate.dx, 760 + plate.dy],
    [PANEL.x2 + plate.dx, 520 + plate.dy],
    [PANEL.x2 + plate.dx, PANEL.y2 + plate.dy],
    [PANEL.x1 + plate.dx, PANEL.y2 + plate.dy]
  ], 0.02);

  // Translucent yellow grease spots on the paper boat tray
  brush.fill(PAL.trayGrease, 120);
  for (let u = -290; u <= 290; u += 140) {
    const greasePts = [];
    for (let a = 0; a < 8; a++) {
      const ang = (a / 8) * Math.PI * 2;
      greasePts.push(dogPt(u + Math.cos(ang) * 58, 118 + Math.sin(ang) * 28, plate));
    }
    drawPoly(greasePts, 0.25);
  }

  // 2C. Upper & Lower Bun Full Yellow Base Plate
  brush.fillBleed(0.12, "out");
  brush.fillTexture(0.35, 0.25);
  brush.fill(PAL.yellowMid, 175);
  drawPoly(getUpperBunPts(plate), 0.15);
  drawPoly(getLowerBunPts(plate), 0.15);

  // 2D. Sausage Yellow Under-Plate (creates warm orange-red when Red plate overprints)
  brush.fill(PAL.yellowMid, 145);
  drawPoly(getSausagePts(plate, 0.96, -2), 0.15);

  // 2E. Relish Bed Yellow Under-Plate (creates vivid pickle green when Cyan overprints)
  brush.fill(PAL.yellowDeep, 185);
  const relishBedUpper = [];
  for (let u = -355; u <= 355; u += 20) {
    relishBedUpper.push(dogPt(u, -56 + 6 * Math.sin(u * 0.06), plate));
  }
  for (let u = 355; u >= -355; u -= 20) {
    relishBedUpper.push(dogPt(u, -8 + 6 * Math.cos(u * 0.05), plate));
  }
  drawPoly(relishBedUpper, 0.2);

  // Individual relish cubes yellow plate
  for (let i = 0; i < relishCubes.length; i++) {
    const rc = relishCubes[i];
    const pts = rc.localPts.map(p => dogPt(p[0], p[1], plate));
    drawPoly(pts, 0.08);
  }

  // 2F. THE MUSTARD ZIGZAG (Double-hit saturated Process Yellow)
  const mustardPts = getRibbonPts(mustardCenterV, -362, 362, 13.5, plate);
  brush.fillBleed(0.06, "out");
  brush.fill(PAL.yellowDeep, 235);
  drawPoly(mustardPts, 0.18);
  brush.noFill();

  // Dense marker hatch pass inside the mustard ribbon for comic print richness
  brush.hatchStyle("news_marker", PAL.yellowDeep, 0.9);
  brush.hatch(5, 25, { rand: 0.03 });
  drawPoly(mustardPts, 0.18);
  brush.noHatch();

  // Mustard droplets in yellow plate
  brush.fill(PAL.yellowDeep, 225);
  for (let d of condimentDrops) {
    if (d.type === "mustard") {
      const c = dogPt(d.u, d.v, plate);
      brush.circle(c[0], c[1], d.r * 1.15, 0.15);
    }
  }
  brush.noFill();
}

// ============================================================================
// LAYER 3: FLAT CYAN PLATE
// ============================================================================

function drawCyanPlate(plate) {
  brush.noStroke();

  // 3A. Retro Sunday Comic Sky (Cyan wash + Ben-Day style diagonal hatching)
  const skyPoly = [
    [PANEL.x1 + plate.dx, PANEL.y1 + plate.dy],
    [PANEL.x2 + plate.dx, PANEL.y1 + plate.dy],
    [PANEL.x2 + plate.dx, 510 + plate.dy],
    [PANEL.x1 + plate.dx, 750 + plate.dy]
  ];
  brush.fillBleed(0.1, "out");
  brush.fillTexture(0.3, 0.2);
  brush.fill(PAL.cyanLight, 85);
  drawPoly(skyPoly, 0.02);
  brush.noFill();

  // Comic halftone / line screen in upper sky corners
  brush.hatchStyle("rotring", PAL.cyanMid, 0.65);
  brush.hatch(10, -20, { rand: 0.02, gradient: 0.45 });
  drawPoly([
    [PANEL.x1 + plate.dx, PANEL.y1 + plate.dy],
    [PANEL.x2 + plate.dx, PANEL.y1 + plate.dy],
    [PANEL.x2 + plate.dx, 320 + plate.dy],
    [PANEL.x1 + plate.dx, 480 + plate.dy]
  ], 0.02);
  brush.noHatch();

  // 3B. Bold Cast Shadow under Paper Tray on Table (Cyan Plate)
  const shadowPts = [];
  for (let u = -420; u <= 410; u += 25) {
    shadowPts.push(dogPt(u, trayBottomV(u) - 10, plate));
  }
  for (let u = 430; u >= -445; u -= 25) {
    const swell = 95 * Math.pow(Math.cos((u / 460) * (Math.PI / 2)), 0.7);
    shadowPts.push(dogPt(u - 25, trayBottomV(u) + 22 + swell, plate));
  }

  brush.fillBleed(0.08, "out");
  brush.fill(PAL.cyanMid, 135);
  drawPoly(shadowPts, 0.15);
  brush.noFill();

  brush.hatchStyle("news_marker", PAL.cyanDeep, 0.65);
  brush.hatch(7, -19.5, { rand: 0.02 });
  drawPoly(shadowPts, 0.15);
  brush.noHatch();

  // 3C. Paper Tray Fluted Pleat Shadows & Back Wall Cyan Shade
  brush.fill(PAL.cyanLight, 110);
  drawPoly(getTrayBackLeftPts(plate), 0.08);
  drawPoly(getTrayBackRightPts(plate), 0.08);

  // Alternating cyan shadow flutes along the front wall of the paper tray
  for (let u = -390; u <= 360; u += 66) {
    const fluteShadow = [
      dogPt(u, trayFrontLipV(u), plate),
      dogPt(u + 26, trayFrontLipV(u + 26), plate),
      dogPt(u + 22, trayBottomV(u + 22), plate),
      dogPt(u - 4, trayBottomV(u - 4), plate)
    ];
    brush.fill(PAL.cyanLight, 95);
    drawPoly(fluteShadow, 0.04);
  }

  // 3D. Cool Cyan Core Shadow along Lower Bun & Sausage Underside
  const sausageShadowPts = [];
  for (let u = -420; u <= 420; u += 18) {
    sausageShadowPts.push(dogPt(u, sausageCenterV(u) + sausageRadius(u) * 0.42, plate));
  }
  for (let u = 420; u >= -420; u -= 18) {
    sausageShadowPts.push(dogPt(u, sausageCenterV(u) + sausageRadius(u) * 0.98, plate));
  }
  brush.fill(PAL.cyanMid, 95);
  drawPoly(sausageShadowPts, 0.12);

  // Lower bun shadow crease where it tucks into the paper tray
  const bunShadowPts = [];
  for (let u = -365; u <= 365; u += 20) {
    bunShadowPts.push(dogPt(u, lowerBunBotV(u) - 26, plate));
  }
  for (let u = 365; u >= -365; u -= 20) {
    bunShadowPts.push(dogPt(u, lowerBunBotV(u) + 4, plate));
  }
  brush.fill(PAL.cyanLight, 105);
  drawPoly(bunShadowPts, 0.12);

  // 3E. Relish Cyan Plate (Overprinting the Yellow Plate to create Pickle Green!)
  brush.fill(PAL.cyanMid, 165);
  for (let i = 0; i < relishCubes.length; i++) {
    const rc = relishCubes[i];
    if (rc.shade >= 1) {
      const pts = rc.localPts.map(p => dogPt(p[0], p[1], plate));
      drawPoly(pts, 0.08);
    }
  }
  brush.noFill();
}

// ============================================================================
// LAYER 4: PRIMARY RED PLATE
// ============================================================================

function drawRedPlate(plate) {
  brush.noStroke();

  // 4A. Cast Shadow Red Overlap (Red + Cyan = Vintage Comic Violet Shadow)
  const shadowOverlapPts = [];
  for (let u = -395; u <= 385; u += 25) {
    shadowOverlapPts.push(dogPt(u, trayBottomV(u) - 6, plate));
  }
  for (let u = 395; u >= -410; u -= 25) {
    const swell = 62 * Math.pow(Math.cos((u / 430) * (Math.PI / 2)), 0.7);
    shadowOverlapPts.push(dogPt(u - 15, trayBottomV(u) + 12 + swell, plate));
  }
  brush.fillBleed(0.08, "out");
  brush.fill(PAL.redLight, 95);
  drawPoly(shadowOverlapPts, 0.15);

  // 4B. Vintage Ballpark Red Checkered Motif on Paper Tray Front Wall
  brush.fill(PAL.redMid, 165);
  for (let row = 0; row < 2; row++) {
    for (let u = -363; u <= 350; u += 66) {
      const uOff = u + (row % 2) * 33;
      if (uOff > 355) continue;
      const v1 = trayFrontLipV(uOff) + 28 + row * 26;
      const v2 = v1 + 24;
      const checkPts = [
        dogPt(uOff, v1, plate),
        dogPt(uOff + 28, v1 + 1, plate),
        dogPt(uOff + 26, v2 + 1, plate),
        dogPt(uOff - 2, v2, plate)
      ];
      drawPoly(checkPts, 0.02);
    }
  }

  // 4C. Upper & Lower Bun Toasted Crust Red Glaze (Red + Yellow = Golden Orange Crust)
  const upperCrustPts = [];
  for (let u = -368; u <= 368; u += 16) {
    upperCrustPts.push(dogPt(u, upperBunTopV(u), plate));
  }
  for (let u = 368; u >= -368; u -= 16) {
    // Leaves bottom rim of upper bun lighter yellow crumb
    upperCrustPts.push(dogPt(u, upperBunBotV(u) - 18, plate));
  }
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.4, 0.25);
  brush.fill(PAL.redLight, 130);
  drawPoly(upperCrustPts, 0.15);

  // Deeper toasted crown along the top ridge of upper bun
  const crownToastPts = [];
  for (let u = -325; u <= 325; u += 18) {
    crownToastPts.push(dogPt(u, upperBunTopV(u) + 2, plate));
  }
  for (let u = 325; u >= -325; u -= 18) {
    crownToastPts.push(dogPt(u, upperBunTopV(u) + 52, plate));
  }
  brush.fill(PAL.redMid, 95);
  drawPoly(crownToastPts, 0.15);

  // Lower bun outer toasted crust
  const lowerCrustPts = [];
  for (let u = -345; u <= 345; u += 18) {
    lowerCrustPts.push(dogPt(u, lowerBunTopV(u) + 22, plate));
  }
  for (let u = 345; u >= -345; u -= 18) {
    lowerCrustPts.push(dogPt(u, lowerBunBotV(u), plate));
  }
  brush.fill(PAL.redLight, 115);
  drawPoly(lowerCrustPts, 0.15);

  // 4D. Frankfurter Sausage Primary Red Plate
  brush.fillBleed(0.1, "out");
  brush.fill(PAL.redMid, 195);
  drawPoly(getSausagePts(plate, 1.0, 0), 0.15);

  // Deeper crimson core along the lower curve & blunt ends of the sausage
  const dogDeepRedPts = [];
  for (let u = -435; u <= 435; u += 16) {
    dogDeepRedPts.push(dogPt(u, sausageCenterV(u) + 2, plate));
  }
  for (let u = 435; u >= -435; u -= 16) {
    dogDeepRedPts.push(dogPt(u, sausageCenterV(u) + sausageRadius(u) * 0.98, plate));
  }
  brush.fill(PAL.redDeep, 135);
  drawPoly(dogDeepRedPts, 0.15);
  brush.noFill();

  // Diagonal roller-grill sear bands on the frankfurter in red-carmine hatch
  brush.hatchStyle("news_marker", PAL.redDeep, 0.75);
  brush.hatch(5.5, 42, { rand: 0.04 });
  for (let u = -310; u <= 310; u += 125) {
    const searPts = [
      dogPt(u - 22, sausageCenterV(u) - 34, plate),
      dogPt(u + 16, sausageCenterV(u) - 34, plate),
      dogPt(u - 6,  sausageCenterV(u) + 36, plate),
      dogPt(u - 44, sausageCenterV(u) + 36, plate)
    ];
    drawPoly(searPts, 0.12);
  }
  brush.noHatch();

  // 4E. THE KETCHUP RIBBON (Double-hit glossy Primary Red)
  const ketchupPts = getRibbonPts(ketchupCenterV, -352, 352, 12.0, plate);
  brush.fillBleed(0.05, "out");
  brush.fill(PAL.redDeep, 235);
  drawPoly(ketchupPts, 0.18);
  brush.noFill();

  brush.hatchStyle("news_marker", PAL.redDeep, 0.9);
  brush.hatch(4.5, -35, { rand: 0.02 });
  drawPoly(ketchupPts, 0.18);
  brush.noHatch();

  // Ketchup droplets
  brush.fill(PAL.redDeep, 225);
  for (let d of condimentDrops) {
    if (d.type === "ketchup") {
      const c = dogPt(d.u, d.v, plate);
      brush.circle(c[0], c[1], d.r * 1.15, 0.15);
    }
  }
  brush.noFill();
}

// ============================================================================
// LAYER 5: OPTICAL OVERLAPS & HYPERREAL TONAL MODELING
// ============================================================================

function drawOverlapTones() {
  brush.noStroke();

  // 5A. Paper Tray Clean White-Cream Highlights on Sunlit Flutes
  brush.fillBleed(0.04, "out");
  brush.fill(PAL.trayCream, 170);
  for (let u = -357; u <= 360; u += 66) {
    const fluteLight = [
      dogPt(u - 4, trayFrontLipV(u - 4), PLATES.ink),
      dogPt(u + 26, trayFrontLipV(u + 26), PLATES.ink),
      dogPt(u + 22, trayBottomV(u + 22), PLATES.ink),
      dogPt(u - 8, trayBottomV(u - 8), PLATES.ink)
    ];
    drawPoly(fluteLight, 0.04);
  }

  // 5B. Exposed Spongy Bun Crumb at Split Ends & Trough
  brush.fillBleed(0.12, "out");
  brush.fill(PAL.bunCrumb, 210);
  // Left & Right exposed bun hinge pillows
  for (let side of [-1, 1]) {
    const u1 = side * 235;
    const u2 = side * 375;
    const crumbPillow = [
      dogPt(u1, lowerBunTopV(u1) - 6, PLATES.orange),
      dogPt(u2, lowerBunTopV(u2) - 10, PLATES.orange),
      dogPt(u2, lowerBunBotV(u2) - 12, PLATES.orange),
      dogPt(u1, lowerBunTopV(u1) + 28, PLATES.orange)
    ];
    drawPoly(crumbPillow, 0.2);
  }

  // 5C. Relish Optical Green Facets (Mint, Pickle Green, Deep Emerald)
  for (let i = 0; i < relishCubes.length; i++) {
    const rc = relishCubes[i];
    const col = rc.shade === 0 ? PAL.relishLight : (rc.shade === 1 ? PAL.relishMid : PAL.relishDeep);
    brush.fill(col, 210);
    const pts = rc.localPts.map(p => dogPt(p[0], p[1], PLATES.green));
    drawPoly(pts, 0.1);
  }

  // Mustard seeds nestled in the relish
  brush.fill(PAL.mustardGold, 225);
  for (let i = 0; i < relishCubes.length; i++) {
    if (relishCubes[i].hasSeed) {
      const c = dogPt(relishCubes[i].u + 2, relishCubes[i].v - 1, PLATES.green);
      brush.circle(c[0], c[1], 3.2, 0.1);
    }
  }

  // 5D. Hyperreal Sausage Skin Blisters (Color Layer)
  for (let i = 0; i < blisters.length; i++) {
    const b = blisters[i];
    const bPts = [];
    for (let s = 0; s < 8; s++) {
      const a = (s / 8) * Math.PI * 2;
      const du = Math.cos(a) * b.ru * Math.cos(b.tilt) - Math.sin(a) * b.rv * Math.sin(b.tilt);
      const dv = Math.cos(a) * b.ru * Math.sin(b.tilt) + Math.sin(a) * b.rv * Math.cos(b.tilt);
      bPts.push(dogPt(b.u + du, b.v + dv, PLATES.orange));
    }
    brush.fill(b.isDark ? PAL.dogSear : PAL.bunCrust, 195);
    drawPoly(bPts, 0.25);

    if (b.isDark) {
      const innerPts = [];
      for (let s = 0; s < 6; s++) {
        const a = (s / 6) * Math.PI * 2;
        innerPts.push(dogPt(b.u + Math.cos(a) * b.ru * 0.52, b.v + Math.sin(a) * b.rv * 0.52, PLATES.ink));
      }
      brush.fill(PAL.shadowSlate, 180);
      drawPoly(innerPts, 0.2);
    }
  }

  // 5E. 3D Underside Shadow Modeling on Ketchup & Mustard Ribbons
  // Ketchup maroon-violet underside shadow
  const ketchupShadowPts = getRibbonPts(ketchupCenterV, -348, 348, 6.5, PLATES.ink, 7.5);
  brush.fill(PAL.ketchupDark, 185);
  drawPoly(ketchupShadowPts, 0.15);

  // Mustard warm golden-amber underside ridge
  const mustardShadowPts = getRibbonPts(mustardCenterV, -358, 358, 7.5, PLATES.orange, 6.5);
  brush.fill(PAL.mustardGold, 195);
  drawPoly(mustardShadowPts, 0.15);

  // Re-reinforce bright yellow top ridge of mustard so it sits cleanly on top of ketchup
  const mustardTopCore = getRibbonPts(mustardCenterV, -360, 360, 9.5, PLATES.yellow, -1.5);
  brush.fill(PAL.yellowMid, 225);
  drawPoly(mustardTopCore, 0.18);

  brush.noFill();
}

// ============================================================================
// LAYER 6: BLACK INK KEY PLATE (HYPERREAL PRECISION + CONFIDENT COMIC LINE)
// ============================================================================

function drawInkKeyPlate(plate) {
  // --------------------------------------------------------------------------
  // 6A. Paper Tray Ink Contours, Accordion Pleats & Fluted Hatching
  // --------------------------------------------------------------------------
  brush.noFill();
  brush.set("comic_brush", PAL.ink, 1.35);

  // Back tray corners
  drawPoly(getTrayBackLeftPts(plate), 0.05, true);
  drawPoly(getTrayBackRightPts(plate), 0.05, true);

  // Accordion fan pleats on left & right tray corners
  brush.set("crowquill", PAL.ink, 1.0);
  const leftCornerBase = dogPt(-418, 52, plate);
  const leftFanTips = [[-466, -32], [-458, -68], [-432, -94], [-392, -98], [-358, -88]];
  for (let t of leftFanTips) {
    const tip = dogPt(t[0], t[1], plate);
    brush.line(leftCornerBase[0], leftCornerBase[1], tip[0], tip[1]);
  }

  const rightCornerBase = dogPt(418, 52, plate);
  const rightFanTips = [[466, -32], [458, -68], [432, -94], [392, -98], [358, -88]];
  for (let t of rightFanTips) {
    const tip = dogPt(t[0], t[1], plate);
    brush.line(rightCornerBase[0], rightCornerBase[1], tip[0], tip[1]);
  }

  // Front tray wall bold outer contour
  brush.set("comic_brush", PAL.ink, 1.5);
  drawPoly(getTrayFrontPts(plate), 0.06, true);

  // Rolled paper lip double-line along scalloped top edge of front tray
  brush.set("crowquill", PAL.ink, 0.95);
  const lipInnerPts = [];
  for (let u = -410; u <= 410; u += 12) {
    lipInnerPts.push(dogPt(u, trayFrontLipV(u) + 7.5, plate));
  }
  brush.spline(lipInnerPts, 0.25);

  // Vertical flute crease lines & fine cardboard shadow hatching on each pleat
  for (let u = -390; u <= 390; u += 33) {
    const topP = dogPt(u, trayFrontLipV(u) + 7.5, plate);
    const botP = dogPt(u * 0.93, trayBottomV(u * 0.93), plate);
    brush.set("crowquill", PAL.ink, 0.85);
    brush.line(topP[0], topP[1], botP[0], botP[1]);

    // Fine diagonal ink hatching along the shadow side of every second flute
    if (Math.round((u + 390) / 33) % 2 === 0 && u < 365) {
      brush.set("crowquill", PAL.inkSoft, 0.65);
      for (let f = 0.12; f <= 0.88; f += 0.11) {
        const vL = lerp(trayFrontLipV(u) + 10, trayBottomV(u * 0.93) - 4, f);
        const p1 = dogPt(u, vL, plate);
        const p2 = dogPt(u + 16, vL + 5, plate);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }
  }

  // Grounding cast shadow cross-hatching under the tray bottom fold
  brush.set("crowquill", PAL.ink, 0.85);
  for (let u = -400; u <= 390; u += 12) {
    const p1 = dogPt(u, trayBottomV(u) + 1, plate);
    const len = 24 + 38 * Math.cos((u / 420) * (Math.PI / 2));
    const p2 = dogPt(u - 16, trayBottomV(u) + len, plate);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // --------------------------------------------------------------------------
  // 6B. Upper & Lower Bun Contours, Crust Wrinkles & Hyperreal Crumb Pores
  // --------------------------------------------------------------------------
  brush.set("comic_brush", PAL.ink, 1.45);
  drawPoly(getUpperBunPts(plate), 0.15, true);
  drawPoly(getLowerBunPts(plate), 0.15, true);

  // Soft bread compression wrinkles along upper bun crown & flanks
  brush.set("crowquill", PAL.ink, 0.78);
  for (let u = -330; u <= 330; u += 38) {
    const vTop = upperBunTopV(u);
    const vBot = upperBunBotV(u);
    // Short curved tension creases radiating from the bun trough
    const c1 = dogPt(u, vBot - 2, plate);
    const c2 = dogPt(u + random(-8, 8), vBot - random(16, 32), plate);
    const c3 = dogPt(u + random(-14, 14), vBot - random(34, 52), plate);
    brush.spline([c1, c2, c3], 0.4);

    // Subtle contour-hugging shading lines along top curve of upper bun
    if (Math.abs(u) < 310) {
      const t1 = dogPt(u - 14, vTop + 7, plate);
      const t2 = dogPt(u + 14, vTop + 7, plate);
      brush.line(t1[0], t1[1], t2[0], t2[1]);
    }
  }

  // Lower bun contour-wrapping form hatching
  for (let u = -350; u <= 350; u += 16) {
    const v1 = lowerBunBotV(u) - 3;
    const v2 = v1 - random(14, 28);
    const p1 = dogPt(u, v1, plate);
    const p2 = dogPt(u + 5, v2, plate);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // HYPERREAL BUN CRUMB: Hundreds of tiny cellular air pockets & stipples
  brush.set("crowquill", PAL.inkSoft, 0.65);
  for (let i = 0; i < bunPores.length; i++) {
    const bp = bunPores[i];
    const c = dogPt(bp.u, bp.v, plate);
    if (bp.isDeep) {
      brush.circle(c[0], c[1], bp.ru, 0.35);
    } else {
      // Tiny crescent pore arc
      brush.arc(c[0], c[1], bp.ru, -30, 145);
    }
  }

  // --------------------------------------------------------------------------
  // 6C. The Frankfurter: Confident Casing Contour, Pinched Tips & Blisters
  // --------------------------------------------------------------------------
  brush.set("comic_brush", PAL.ink, 1.6);
  drawPoly(getSausagePts(plate, 1.0, 0), 0.15, true);

  // Pinched, puckered casing twists at both left (-432) and right (+432) ends
  for (let side of [-1, 1]) {
    const tipU = side * 426;
    const tipV = sausageCenterV(tipU);
    const puckerCenter = dogPt(tipU, tipV, plate);

    brush.set("comic_brush", PAL.ink, 1.15);
    const numFolds = 7;
    for (let f = 0; f < numFolds; f++) {
      const ang = ((f - 3) / 3.5) * 1.15;
      const du = -side * Math.cos(ang) * random(18, 34);
      const dv = Math.sin(ang) * random(16, 30);
      const midP = dogPt(tipU + du * 0.5, tipV + dv * 0.4 + random(-3, 3), plate);
      const endP = dogPt(tipU + du, tipV + dv, plate);
      brush.spline([puckerCenter, midP, endP], 0.35);
    }
  }

  // Cylindrical cross-contour shading ribs along the bottom shadow of the sausage
  brush.set("crowquill", PAL.ink, 0.78);
  for (let u = -415; u <= 415; u += 10) {
    const r = sausageRadius(u);
    if (r < 12) continue;
    const vc = sausageCenterV(u);
    const p1 = dogPt(u, vc + r * 0.96, plate);
    const p2 = dogPt(u + 3, vc + r * 0.62, plate);
    const p3 = dogPt(u + 1, vc + r * 0.32, plate);
    brush.spline([p1, p2, p3], 0.35);
  }

  // HYPERREAL SAUSAGE BLISTERS: Crisp split-skin rings, radial tension lines & char stipple
  for (let i = 0; i < blisters.length; i++) {
    const b = blisters[i];
    const bPts = [];
    for (let s = 0; s < 10; s++) {
      const a = (s / 10) * Math.PI * 2;
      const du = Math.cos(a) * b.ru * Math.cos(b.tilt) - Math.sin(a) * b.rv * Math.sin(b.tilt);
      const dv = Math.cos(a) * b.ru * Math.sin(b.tilt) + Math.sin(a) * b.rv * Math.cos(b.tilt);
      bPts.push(dogPt(b.u + du, b.v + dv, plate));
    }
    brush.set("crowquill", PAL.ink, 0.82);
    drawPoly(bPts, 0.25, true);

    // Inner split ring or char cross-hatch
    if (b.hasSplit) {
      const pL = dogPt(b.u - b.ru * 0.65, b.v, plate);
      const pM = dogPt(b.u, b.v + b.rv * 0.25, plate);
      const pR = dogPt(b.u + b.ru * 0.65, b.v - b.rv * 0.1, plate);
      brush.spline([pL, pM, pR], 0.3);

      // Tiny radial skin-tension micro-crinkles outside blister rim
      for (let k = 0; k < 4; k++) {
        const ka = (k / 4) * Math.PI * 2 + 0.4;
        const r1 = dogPt(b.u + Math.cos(ka) * b.ru * 1.02, b.v + Math.sin(ka) * b.rv * 1.02, plate);
        const r2 = dogPt(b.u + Math.cos(ka) * b.ru * 1.45, b.v + Math.sin(ka) * b.rv * 1.35, plate);
        brush.line(r1[0], r1[1], r2[0], r2[1]);
      }
    }
  }

  // --------------------------------------------------------------------------
  // 6D. Glistening Diced Pickle Relish Facet Contours
  // --------------------------------------------------------------------------
  for (let i = 0; i < relishCubes.length; i++) {
    const rc = relishCubes[i];
    const pts = rc.localPts.map(p => dogPt(p[0], p[1], plate));
    brush.set("crowquill", PAL.ink, 0.85);
    drawPoly(pts, 0.1, true);

    // Internal cube facet crease to make each pickle dice look 3D and translucent
    if (pts.length >= 4) {
      const centerFacet = dogPt(rc.u + 1.5, rc.v + 1.5, plate);
      brush.set("crowquill", PAL.inkSoft, 0.6);
      brush.line(pts[0][0], pts[0][1], centerFacet[0], centerFacet[1]);
      brush.line(pts[2][0], pts[2][1], centerFacet[0], centerFacet[1]);
    }
  }

  // --------------------------------------------------------------------------
  // 6E. Ketchup & Mustard Ribbons: Calligraphic Comic Ink Outlines
  // --------------------------------------------------------------------------
  // Ketchup ribbon contour
  const ketchupInkPts = getRibbonPts(ketchupCenterV, -352, 352, 12.0, plate);
  brush.set("comic_brush", PAL.ink, 1.35);
  drawPoly(ketchupInkPts, 0.18, true);

  // Mustard zigzag ribbon contour (drawn last so it overlaps ketchup & relish cleanly)
  const mustardInkPts = getRibbonPts(mustardCenterV, -362, 362, 13.5, plate);
  brush.set("comic_brush", PAL.ink, 1.5);
  drawPoly(mustardInkPts, 0.18, true);

  // 3D shadow hatching along the lower edge of the mustard zigzag
  brush.set("crowquill", PAL.ink, 0.78);
  for (let u = -345; u <= 345; u += 9) {
    const v0 = mustardCenterV(u) + 11.5;
    const p1 = dogPt(u, v0, plate);
    const p2 = dogPt(u + 2, v0 + 6.5, plate);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Ink contours around stray condiment drops
  brush.set("crowquill", PAL.ink, 0.95);
  for (let d of condimentDrops) {
    const c = dogPt(d.u, d.v, plate);
