function drawRegistrationTarget(cx, cy) {
  const r = 13;
  // Misregistered C, M, Y rings
  const plates = [
    { col: PAL.yellowDeep, dx: 2.5, dy: -2.0 },
    { col: PAL.cyanMid,    dx: 2.0, dy: 2.2 },
    { col: PAL.redMid,     dx: -2.2, dy: 1.8 }
  ];
  for (let p of plates) {
    brush.set("rotring", p.col, 0.85);
    brush.circle(cx + p.dx, cy + p.dy, r, 0.05);
  }

  // Black key target & crosshairs
  brush.set("rotring", PAL.ink, 0.9);
  brush.circle(cx, cy, r, 0.04);
  brush.circle(cx, cy, r * 0.45, 0.04);
  brush.line(cx - r * 1.55, cy, cx + r * 1.55, cy);
  brush.line(cx, cy - r * 1.55, cx, cy + r * 1.55);
}

// Hyperreal Frozen Strawberries in an Ice-Cube Tray with Feathery Frost Ferns
// Rendered with p5.js v2 + p5.brush in WEBGL

const TRAY_ANGLE = -3.2;
const RAD = Math.PI / 180;
const COS_A = Math.cos(TRAY_ANGLE * RAD);
const SIN_A = Math.sin(TRAY_ANGLE * RAD);

// Transform tray-space coordinates (x, y) around canvas center (600, 600)
function TX(x, y) {
  let dx = x - 600, dy = y - 600;
  return 600 + dx * COS_A - dy * SIN_A;
}
function TY(x, y) {
  let dx = x - 600, dy = y - 600;
  return 600 + dx * SIN_A + dy * COS_A;
}

// Helper for transformed line
function tLine(x1, y1, x2, y2) {
  brush.line(TX(x1, y1), TY(x1, y1), TX(x2, y2), TY(x2, y2));
}

// Helper for transformed spline
function tSpline(pts, curv = 0.5) {
  if (!pts || pts.length < 2) return;
  let out = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (p.length > 2) out.push([TX(p[0], p[1]), TY(p[0], p[1]), p[2]]);
    else out.push([TX(p[0], p[1]), TY(p[0], p[1])]);
  }
  brush.spline(out, curv);
}

// Helper for transformed closed/open shape
function tShape(pts, curv = 0.45, close = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    brush.vertex(TX(p[0], p[1]), TY(p[0], p[1]));
  }
  brush.endShape(close);
}

// Generate rounded-rectangle points in tray-space
function roundedRectPts(cx, cy, w, h, r, nPerCorner = 5, jitter = 0) {
  let pts = [];
  let hw = w / 2, hh = h / 2;
  r = Math.min(r, hw * 0.9, hh * 0.9);
  let corners = [
    { x: cx + hw - r, y: cy - hh + r, a0: -90, a1: 0 },
    { x: cx + hw - r, y: cy + hh - r, a0: 0, a1: 90 },
    { x: cx - hw + r, y: cy + hh - r, a0: 90, a1: 180 },
    { x: cx - hw + r, y: cy - hh + r, a0: 180, a1: 270 }
  ];
  for (let c = 0; c < 4; c++) {
    let cr = corners[c];
    for (let i = 0; i < nPerCorner; i++) {
      let t = i / nPerCorner;
      let ang = (cr.a0 + t * (cr.a1 - cr.a0)) * RAD;
      let jx = jitter ? (random(-1, 1) * jitter) : 0;
      let jy = jitter ? (random(-1, 1) * jitter) : 0;
      pts.push([cr.x + Math.cos(ang) * r + jx, cr.y + Math.sin(ang) * r + jy]);
    }
  }
  return pts;
}

// Generate organic blob/cloud points
function blobPts(cx, cy, rx, ry, rotDeg, nPts = 16, irreg = 0.15, seedOff = 0) {
  let pts = [];
  let ca = Math.cos(rotDeg * RAD), sa = Math.sin(rotDeg * RAD);
  for (let i = 0; i < nPts; i++) {
    let a = (i / nPts) * Math.PI * 2;
    let nv = noise(Math.cos(a) * 1.3 + seedOff, Math.sin(a) * 1.3 + seedOff);
    let m = 1 + (nv - 0.5) * 2 * irreg;
    let lx = Math.cos(a) * rx * m;
    let ly = Math.sin(a) * ry * m;
    pts.push([cx + lx * ca - ly * sa, cy + lx * sa + ly * ca]);
  }
  return pts;
}

// Parametric Strawberry 3D Surface Evaluator
// u in [0, 1] from stem shoulder (0) to apex tip (1)
// v in [-1, 1] across width
function berrySurface(u, v, b) {
  // Realistic strawberry profile: broad rounded shoulder near u=0.26, tapering to a conical/heart apex
  let uClamped = Math.max(0.001, Math.min(0.999, u));
  let baseProfile = Math.pow(Math.sin(uClamped * Math.PI), 0.58) * (1.0 - 0.36 * Math.pow(uClamped, 1.15)) * 1.22;
  // Slight shoulder indentation right at u -> 0 (where stem attaches)
  if (uClamped < 0.08) {
    baseProfile *= (0.72 + 0.28 * (uClamped / 0.08));
  }
  // Subtle organic asymmetry per berry
  let asym = (noise(uClamped * 2.2 + b.seed, (v + 1) * 1.2 + b.seed) - 0.5) * 0.12;
  let halfW = (b.w * 0.5) * (baseProfile + asym);

  // Longitudinal coordinate along berry axis (centered around u = 0.45)
  let localY = (uClamped - 0.44) * b.len;
  // Slight heart-creased dip along center line v=0 near shoulder/tip
  let heartDip = (1 - v * v) * b.heart * (uClamped < 0.25 ? -4 * (0.25 - uClamped) : 5 * Math.pow(uClamped, 2));
  localY += heartDip;

  let localX = v * halfW;
  // 3D elevation z in [0, 1]
  let z = Math.max(0, baseProfile * Math.sqrt(Math.max(0, 1 - v * v)));

  // Rotate by berry orientation angle
  let ca = Math.cos(b.ang * RAD), sa = Math.sin(b.ang * RAD);
  let wx = b.x + localX * ca - localY * sa;
  let wy = b.y + localX * sa + localY * ca;

  return { x: wx, y: wy, z: z, halfW: halfW, localX: localX, localY: localY };
}

// Generate outline contour points for a strawberry layer
function berryContourPts(b, uMin = 0.02, uMax = 0.99, vScaleL = 1.0, vScaleR = 1.0, uOffset = 0, vOffset = 0, steps = 14) {
  let pts = [];
  // Right flank from shoulder to tip
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let u = uMin + t * (uMax - uMin) + uOffset;
    let v = Math.min(1, Math.max(-1, vOffset + vScaleR * Math.sin(t * Math.PI * 0.92 + 0.04)));
    let p = berrySurface(u, v, b);
    pts.push([p.x, p.y]);
  }
  // Left flank from tip back to shoulder
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let u = uMin + t * (uMax - uMin) + uOffset;
    let v = Math.min(1, Math.max(-1, vOffset - vScaleL * Math.sin(t * Math.PI * 0.92 + 0.04)));
    let p = berrySurface(u, v, b);
    pts.push([p.x, p.y]);
  }
  return pts;
}

