      tShape(berryContourPts(b, 0.20, 0.72, 0.26, 0.26, 0, 0, 10), 0.48, true);

      // Hollow central chamber shadow slit
      brush.fill("#8c3547", 120);
      brush.fillBleed(0.15, "in");
      tShape(berryContourPts(b, 0.28, 0.58, 0.08, 0.08, 0, 0, 8), 0.45, true);
    }
  }

  // =========================================================================
  // PHASE 3: STRAWBERRY SKIN DIMPLES, VASCULAR FIBERS, SEEDS & CALYX LEAVES
  // =========================================================================
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  for (let b of berries) {
    if (b.type === "whole") {
      drawWholeStrawberryDetails(b);
    } else {
      drawHalvedStrawberryDetails(b);
    }
  }

  // Draw Submerged Calyx (Sepals & Stems) — Batched fills then crisp venation
  drawAllCalyxes(berries);
  // Floating detached sepal in Cell 8 (Bottom-Right)
  drawFloatingSepal(cells[8].cx + 42, cells[8].cy + 44, 38);

  // =========================================================================
  // PHASE 4: SUBMERSION — MISTY ICE BLOOM, VEILS, CRACKS & TRAPPED BUBBLES
  // =========================================================================
  brush.noStroke();
  brush.noHatch();

  // 4A: Cool Twilight Blue-Grey Submersion Wash over deeper parts of the berries
  brush.fill("#3d5570", 110);
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.65, 0.22);
  for (let b of berries) {
    let c = cells[b.cellIdx];
    let sx = b.x + (b.submergeDir * 32);
    let sy = b.y + 24;
    let rx = b.w * (0.55 + b.submergeAmt * 0.35);
    let ry = b.len * (0.48 + b.submergeAmt * 0.32);
    // Clamp roughly inside cell
    sx = constrain(sx, c.cx - 65, c.cx + 65);
    sy = constrain(sy, c.cy - 65, c.cy + 65);
    tShape(blobPts(sx, sy, rx, ry, b.ang + 25, 14, 0.22, b.seed + 3), 0.5, true);
  }

  // 4B: Thick Misty Ice Bloom in cell corners & cloudy freeze zones
  brush.fill("#7596b5", 95);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.7, 0.25);
  for (let c of cells) {
    // 2 misty bloom clouds per cell where ice is thicker
    for (let k = 0; k < 2; k++) {
      let ang = (c.idx * 67 + k * 155) * RAD;
      let dist = 62 + (k * 18);
      let mx = c.cx + Math.cos(ang) * dist;
      let my = c.cy + Math.sin(ang) * dist;
      tShape(blobPts(mx, my, 78 - k * 12, 58 - k * 8, c.idx * 35 + k * 50, 14, 0.25, c.idx * 13 + k), 0.5, true);
    }
  }

  // 4C: Milky Pale Cerulean Core Bloom in thickest ice pockets
  brush.fill("#aecbe6", 82);
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.6, 0.2);
  for (let c of cells) {
    let ang = (c.idx * 67 + 20) * RAD;
    let mx = c.cx + Math.cos(ang) * 54;
    let my = c.cy + Math.sin(ang) * 54;
    tShape(blobPts(mx, my, 52, 40, c.idx * 40, 12, 0.22, c.idx * 19), 0.5, true);
  }

  // 4D: Fine Ice Mist Spray & Internal Cleavage Fractures + Trapped Bubbles
  brush.noFill();
  brush.noWash();
  for (let c of cells) {
    drawCellIceTextureAndCracks(c, berries);
  }

  // =========================================================================
  // PHASE 5: MOLDED PLASTIC ICE-CUBE TRAY ARCHITECTURE (Walls, Bridges, Rim)
  // =========================================================================
  drawTrayStructure(cells);

  // =========================================================================
  // PHASE 6: FRACTAL, FEATHERED & CRYSTALLINE FROST FERNS
  // =========================================================================
  drawAllFrostFerns(cells, berries);

  noLoop();
}

// ===========================================================================
// STRAWBERRY BOTANICAL DETAIL FUNCTIONS
// ===========================================================================

function drawWholeStrawberryDetails(b) {
  // 1. Subtle 3D Meridian Contour Shading in Alizarin & Dusky Claret
  let nMeridians = 11;
  for (let m = 0; m < nMeridians; m++) {
    let v = map(m, 0, nMeridians - 1, -0.88, 0.88);
    let col = v > 0.15 ? "#4f0a19" : (v < -0.2 ? "#b5283e" : "#851428");
    let wt = v > 0.2 ? 0.55 : 0.38;
    brush.set("cpencil", col, wt);

    let pts = [];
    for (let s = 0; s <= 8; s++) {
      let u = map(s, 0, 8, 0.08, 0.94);
      // Slight wave around seed pockets
      let vWave = v + Math.sin(s * Math.PI) * 0.03;
      let p = berrySurface(u, constrain(vWave, -0.95, 0.95), b);
      pts.push([p.x, p.y]);
    }
    tSpline(pts, 0.45);
  }

  // 2. Generate Fibonacci/Diamond Lattice of Achenes (Seeds) on the 3D surface
  let seeds = [];
  let nRows = 11;
  for (let r = 1; r <= nRows; r++) {
    let u = map(r, 0.6, nRows + 0.4, 0.09, 0.93);
    // Fewer seeds near the narrow tip
    let profileFactor = Math.pow(Math.sin(u * Math.PI), 0.55) * (1 - 0.32 * u);
    let nCols = Math.max(2, Math.round(profileFactor * 9.5));
    for (let c = 0; c < nCols; c++) {
      let stagger = (r % 2 === 0) ? 0.5 : 0.0;
      let v = map(c + stagger, -0.2, nCols - 0.3, -0.86, 0.86);
      if (Math.abs(v) > 0.90) continue;

      let uJit = u + (noise(r * 1.7 + b.seed, c * 2.3) - 0.5) * 0.025;
      let vJit = v + (noise(c * 1.9 + b.seed, r * 2.1) - 0.5) * 0.04;
      let pos = berrySurface(uJit, vJit, b);

      // Compute local meridian tangent angle for seed orientation
      let posNext = berrySurface(Math.min(0.99, uJit + 0.03), vJit, b);
      let tangAng = Math.atan2(posNext.y - pos.y, posNext.x - pos.x);

      // Depth under ice combines 3D elevation z and berry submersion
      let iceClearness = constrain(pos.z * 1.15 - (b.submergeAmt * 0.45) - (vJit * b.submergeDir * 0.22), 0, 1);
      seeds.push({
        x: pos.x, y: pos.y,
        u: uJit, v: vJit, z: pos.z,
        ang: tangAng,
        clearness: iceClearness
      });
    }
  }

  // 3. Quilted Flesh Pillows between seeds on the upper dome (hyperreal glossy skin under ice)
  for (let s of seeds) {
    if (s.z > 0.42 && s.clearness > 0.35) {
      let pillowCol = s.clearness > 0.62 ? "#e87684" : "#c76b7d";
      brush.set("cpencil", pillowCol, 0.48);
      // Small arched flesh pillow just above-left of the seed pocket
      let px = s.x - Math.cos(b.ang * RAD) * 3.5;
      let py = s.y - Math.sin(b.ang * RAD) * 3.5;
      let p1 = [px - 3.5, py + 1.5];
      let p2 = [px, py - 2.2];
      let p3 = [px + 3.5, py + 1.5];
      tSpline([p1, p2, p3], 0.6);
    }
  }

  // 4. Sunken Dimple Shadows for every seed pocket
  for (let s of seeds) {
    let dimpleCol = s.v > 0.15 ? "#33040e" : "#5e0c1d";
    brush.set("pen", dimpleCol, 0.42);
    let dx = Math.cos(s.ang) * 2.6;
    let dy = Math.sin(s.ang) * 2.6;
    let nx = -Math.sin(s.ang) * 1.6;
    let ny = Math.cos(s.ang) * 1.6;
    tSpline([
      [s.x - dx + nx * 0.4, s.y - dy + ny * 0.4],
      [s.x - nx * 0.8, s.y - ny * 0.8],
      [s.x + dx + nx * 0.4, s.y + dy + ny * 0.4]
    ], 0.5);
  }

  // 5. Seed-Yellow Achenes (Muted under deeper ice, warm golden-yellow on the dome)
  for (let s of seeds) {
    let dx = Math.cos(s.ang) * 2.1;
    let dy = Math.sin(s.ang) * 2.1;

    // Warm amber-ochre seed base
    let baseCol = s.clearness > 0.45 ? "#9c681e" : "#6c6952";
    brush.set("pen", baseCol, 0.48);
    tLine(s.x - dx * 0.8, s.y - dy * 0.8, s.x + dx * 0.9, s.y + dy * 0.9);

    // Bright seed-yellow teardrop core
    let seedCol = s.clearness > 0.60 ? "#ebd06b" : (s.clearness > 0.35 ? "#c9b059" : "#8d9678");
    brush.set("rotring", seedCol, 0.42);
    tLine(s.x - dx * 0.55, s.y - dy * 0.55, s.x + dx * 0.55, s.y + dy * 0.55);

    // Pinpoint specular highlight on seeds closest to the surface
    if (s.clearness > 0.68) {
      brush.set("rotring", "#fff7d6", 0.28);
      tLine(s.x - dx * 0.2, s.y - dy * 0.2, s.x + dx * 0.15, s.y + dy * 0.15);
    }
  }

  // 6. Subtle Crisp Outer Rim Definition in Alizarin & Cool Twilight Violet
  brush.set("2B", "#4d0918", 0.48);
  let rimPtsR = [];
  let rimPtsL = [];
  for (let i = 0; i <= 10; i++) {
    let u = map(i, 0, 10, 0.06, 0.98);
    let pr = berrySurface(u, 0.98, b);
    let pl = berrySurface(u, -0.98, b);
    rimPtsR.push([pr.x, pr.y]);
    rimPtsL.push([pl.x, pl.y]);
  }
  tSpline(rimPtsR, 0.45);
  brush.set("2B", "#7a162c", 0.40);
  tSpline(rimPtsL, 0.45);
}

function drawHalvedStrawberryDetails(b) {
  // 1. Radiating Vascular Bundles from central pith out to cortex
  let nBundles = 26;
  for (let i = 0; i < nBundles; i++) {
    let t = i / (nBundles - 1);
    let uPith = map(t, 0, 1, 0.18, 0.72);
    let uRim = map(t, 0, 1, 0.08, 0.94);

    for (let side of [-1, 1]) {
      let p0 = berrySurface(uPith, side * 0.12, b);
      let p1 = berrySurface((uPith + uRim) * 0.5 - 0.03, side * 0.48, b);
      let p2 = berrySurface(uRim, side * 0.84, b);

      brush.set("2H", "#c4354b", 0.36);
      tSpline([[p0.x, p0.y], [p1.x, p1.y], [p2.x, p2.y]], 0.5);

      // Pale fibrous sheen alongside the carmine vascular bundle
      if (i % 2 === 0) {
        let p1b = berrySurface((uPith + uRim) * 0.5, side * 0.44, b);
        let p2b = berrySurface(uRim, side * 0.76, b);
        brush.set("rotring", "#f5dce2", 0.25);
        tSpline([[p0.x, p0.y], [p1b.x, p1b.y], [p2b.x, p2b.y]], 0.5);
      }
    }
  }

  // 2. Central Pith V-structure and subtle internal striations
  brush.set("cpencil", "#b54357", 0.42);
  let pithL = [], pithR = [];
  for (let s = 0; s <= 7; s++) {
    let u = map(s, 0, 7, 0.18, 0.74);
    let pl = berrySurface(u, -0.18 * (1 - s / 9), b);
    let pr = berrySurface(u, 0.18 * (1 - s / 9), b);
    pithL.push([pl.x, pl.y]);
    pithR.push([pr.x, pr.y]);
  }
  tSpline(pithL, 0.4);
  tSpline(pithR, 0.4);

  // 3. Peripheral Achenes (Seeds) embedded along the cut skin margin
  for (let side of [-1, 1]) {
    for (let s = 1; s <= 11; s++) {
      let u = map(s, 0, 12, 0.08, 0.95);
      let pEdge = berrySurface(u, side * 0.96, b);
      let pIn = berrySurface(u + 0.01, side * 0.87, b);

      // Recessed dark crimson notch at skin edge
      brush.set("pen", "#4a0817", 0.45);
      tLine(pEdge.x, pEdge.y, pIn.x, pIn.y);

      // Golden seed-yellow achene on the edge
      brush.set("rotring", "#e6c863", 0.40);
      tLine(pEdge.x, pEdge.y, (pEdge.x + pIn.x) * 0.5, (pEdge.y + pIn.y) * 0.5);
    }
  }
}

function drawAllCalyxes(berries) {
  let darkSepals = [];
  let midSepals = [];
  let lightSepals = [];
  let stems = [];
  let veinLines = [];

  for (let b of berries) {
    if (!b.hasStem) continue;
    let basePos = berrySurface(0.03, 0, b);
    let axisAng = (b.ang - 90) * RAD; // Points out from the stem end

    // Generate 6 pointed curving sepals hugging the berry shoulder
    let nSepals = 6;
    for (let k = 0; k < nSepals; k++) {
      let spread = map(k, 0, nSepals - 1, -118, 118) + random(-8, 8);
      let sAng = axisAng + spread * RAD;
      let sLen = b.w * random(0.28, 0.42);
      let sWid = sLen * random(0.24, 0.32);
      let curveBend = (spread > 0 ? 1 : -1) * random(0.18, 0.35);

      let pts = buildSepalPolygon(basePos.x, basePos.y, sAng, sLen, sWid, curveBend);
      if (k % 3 === 0) darkSepals.push(pts.poly);
      else if (k % 3 === 1) midSepals.push(pts.poly);
      else lightSepals.push(pts.poly);

      veinLines.push(pts.midrib);
    }

    // Short curved woody-green stem (pedicel)
    let stemLen = b.idx === 7 ? 56 : random(26, 40);
    let sCurve = random(-0.4, 0.4);
    let p0 = [basePos.x, basePos.y];
    let p1 = [
      basePos.x + Math.cos(axisAng + sCurve * 0.5) * (stemLen * 0.5),
      basePos.y + Math.sin(axisAng + sCurve * 0.5) * (stemLen * 0.5)
    ];
    let p2 = [
      basePos.x + Math.cos(axisAng + sCurve) * stemLen,
      basePos.y + Math.sin(axisAng + sCurve) * stemLen
    ];
    stems.push([p0, p1, p2]);
  }

  // Batch watercolor fills for calyx leaves
  brush.noStroke();
  brush.noHatch();

  brush.fill("#193029", 165);
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.55, 0.4);
  for (let poly of darkSepals) tShape(poly, 0.4, true);

  brush.fill("#2b4f41", 155);
  brush.fillBleed(0.20, "out");
  brush.fillTexture(0.55, 0.35);
  for (let poly of midSepals) tShape(poly, 0.4, true);

  brush.fill("#48705c", 145);
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.5, 0.3);
  for (let poly of lightSepals) tShape(poly, 0.4, true);

  // Crisp botanical venation & stems
  brush.noFill();
  brush.noWash();
  for (let st of stems) {
    brush.set("2B", "#1c3329", 1.15);
    tSpline(st, 0.5);
    brush.set("pen", "#5c856d", 0.55);
    tSpline(st, 0.5);
  }

  for (let v of veinLines) {
    brush.set("pen", "#162922", 0.38);
    tSpline(v, 0.45);
    brush.set("rotring", "#749e86", 0.25);
    tLine(v[0][0], v[0][1], v[1][0], v[1][1]);
  }
}

function buildSepalPolygon(ox, oy, ang, len, wid, bend) {
  let leftPts = [];
  let rightPts = [];
  let midrib = [];
  let steps = 5;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let curAng = ang + bend * t * t;
    let r = len * t;
    let cx = ox + Math.cos(curAng) * r;
    let cy = oy + Math.sin(curAng) * r;
    midrib.push([cx, cy]);

    let w = wid * Math.sin(Math.pow(t, 0.7) * Math.PI) * (1 - 0.25 * t);
    let nx = -Math.sin(curAng) * w;
    let ny = Math.cos(curAng) * w;
    leftPts.push([cx + nx, cy + ny]);
    rightPts.push([cx - nx, cy - ny]);
  }
  let poly = leftPts.concat(rightPts.reverse());
  return { poly, midrib };
}

function drawFloatingSepal(x, y, angDeg) {
  let pts = buildSepalPolygon(x, y, angDeg * RAD, 56, 17, 0.28);
  brush.noStroke();
  brush.fill("#284a3e", 140);
  brush.fillBleed(0.25, "out");
  tShape(pts.poly, 0.45, true);

  brush.noFill();
  brush.set("pen", "#658f7a", 0.35);
  tSpline(pts.midrib, 0.45);
}

// ===========================================================================
// SUBMERSION, INTERNAL ICE FRACTURES & TRAPPED AIR BUBBLES
// ===========================================================================

function drawCellIceTextureAndCracks(c, berries) {
  // 1. Soft misty glaze strokes across the compartment
  brush.set("ice_mist", "#8eb2d1", 0.9);
  for (let i = 0; i < 5; i++) {
    let x1 = c.cx + random(-95, 95);
    let y1 = c.cy + random(-95, 95);
    let a = random(0, 360) * RAD;
    let d = random(45, 95);
    tLine(x1, y1, x1 + Math.cos(a) * d, y1 + Math.sin(a) * d);
  }

  // 2. Internal Thermal-Shock Cleavage Cracks inside the ice cube
  let nCracks = 2 + (c.idx % 2);
  for (let k = 0; k < nCracks; k++) {
    let startAng = (c.idx * 83 + k * 137) * RAD;
    let r0 = random(85, 115);
    let x = c.cx + Math.cos(startAng) * r0;
    let y = c.cy + Math.sin(startAng) * r0;
    let dir = startAng + Math.PI + random(-0.45, 0.45);

    let crackPts = [[x, y]];
    let shadowPts = [[x + 2.2, y + 2.8]];
    let segs = 5;
    for (let s = 0; s < segs; s++) {
      let stepL = random(24, 42);
      dir += random(-0.38, 0.38);
      x = constrain(x + Math.cos(dir) * stepL, c.cx - 118, c.cx + 118);
      y = constrain(y + Math.sin(dir) * stepL, c.cy - 118, c.cy + 118);
      crackPts.push([x, y]);
      shadowPts.push([x + 2.2, y + 2.8]);

      // Secondary fracture fork
      if (s === 2) {
        let forkDir = dir + (random() > 0.5 ? 0.55 : -0.55);
        let fx = x + Math.cos(forkDir) * 32;
        let fy = y + Math.sin(forkDir) * 32;
        brush.set("2H", "#4e7091", 0.40);
        tLine(x + 1.5, y + 1.8, fx + 1.5, fy + 1.8);
        brush.set("rotring", "#d4ecff", 0.28);
        tLine(x, y, fx, fy);
      }
    }

    // Refractive shadow veil beside cleavage plane
    brush.set("2B", "#37516e", 0.65);
    tSpline(shadowPts, 0.2);
    // Razor-sharp crystalline fracture edge
    brush.set("rotring", "#e3f3ff", 0.34);
    tSpline(crackPts, 0.2);
  }

  // 3. Trapped Frozen Air Bubbles (Streams & Pearl Clusters around the fruit)
  let nBubbles = 24;
  for (let i = 0; i < nBubbles; i++) {
    let ang = random(0, 360) * RAD;
    let rad = random(12, 108);
    let bx = c.cx + Math.cos(ang) * rad;
    let by = c.cy + Math.sin(ang) * rad;
    let br = random() < 0.22 ? random(3.2, 6.2) : random(1.1, 2.6);

    // Dark twilight refractive rim on bottom-right of bubble
    brush.set("pen", "#23374f", 0.35);
    brush.arc(TX(bx, by), TY(bx, by), br, 20, 210);

    // Crisp cerulean-white upper crescent & highlight
    brush.set("rotring", "#eef9ff", 0.32);
    brush.arc(TX(bx, by), TY(bx, by), br * 0.9, 195, 380);
  }
}

// ===========================================================================
// MOLDED PLASTIC ICE-CUBE TRAY ARCHITECTURE
// ===========================================================================

function drawTrayStructure(cells) {
  // 1. Outer Molded Rim & Flange of the Ice-Cube Tray
  let outerFlange = roundedRectPts(600, 600, 1070, 1070, 80, 7);
  let innerFlange = roundedRectPts(600, 600, 1012, 1012, 68, 7);

  brush.set("2B", "#31455e", 1.1);
  tSpline(outerFlange.concat([outerFlange[0]]), 0.35);

  brush.set("cpencil", "#698bb0", 0.75);
  tSpline(innerFlange.concat([innerFlange[0]]), 0.35);

  // Top-left specular skylight along outer tray flange
  brush.set("rotring", "#b5d6f2", 0.50);
  tSpline(outerFlange.slice(14, 28), 0.35);
  tSpline(outerFlange.slice(0, 7), 0.35);

  // 2. Individual Compartment Bevels, Walls & Ice Meniscus
  for (let c of cells) {
    let outerPts = roundedRectPts(c.cx, c.cy, c.outerW, c.outerH, c.outerR, 6);
    let innerPts = roundedRectPts(c.innerCx, c.innerCy, c.innerW, c.innerH, c.innerR, 6);
    let meniscusPts = roundedRectPts(c.cx + 1.5, c.cy + 2.0, c.outerW - 14, c.outerH - 14, c.outerR - 5, 6, 0.8);

    // Bevel shading lines connecting outer lip corners to inner floor corners
    for (let i = 0; i < outerPts.length; i += 2) {
      let pOut = outerPts[i];
      let pIn = innerPts[i];
      // Top and left walls are in shadow from top-left lip overhang; bottom and right catch skylight
      let isLitWall = (pOut[0] > c.cx + 20) || (pOut[1] > c.cy + 20);
      brush.set("2B", isLitWall ? "#5b7b9e" : "#1c2a3d", 0.65);
      tLine(pOut[0], pOut[1], pIn[0], pIn[1]);
    }

    // Inner floor boundary crease
    brush.set("pen", "#1a2738", 0.45);
    tSpline(innerPts.concat([innerPts[0]]), 0.4);

    // Frosty Ice Meniscus Rim (where the frozen water clings to the plastic wall)
    brush.set("cpencil", "#8ab4d9", 0.62);
    tSpline(meniscusPts.concat([meniscusPts[0]]), 0.4);

    // Bright specular meniscus arcs on bottom-right & top-left
    brush.set("rotring", "#dff2ff", 0.38);
    tSpline(meniscusPts.slice(3, 13), 0.4);
    tSpline(meniscusPts.slice(16, 22), 0.4);

    // Outer plastic cell lip (dark slate recess + crisp twilight rim highlight)
    brush.set("2B", "#223247", 0.85);
    tSpline(outerPts.concat([outerPts[0]]), 0.4);

    brush.set("pen", "#9ec2e3", 0.42);
    tSpline(outerPts.slice(4, 15), 0.4);
  }

  // 3. Plastic Grid Bridges & Circular Ejector/Molding Dimples at the 4 Inner Intersections
  const gridStep = 294 + 41;
  const startC = 118 + 294 / 2;

  // Subtle plastic sheen along horizontal and vertical tray bridges
  for (let i = 0; i < 2; i++) {
    let bridgeCoord = 118 + 294 + i * gridStep + 41 / 2;
    // Horizontal bridge highlight
    brush.set("cpencil", "#5f80a3", 0.55);
    tLine(125, bridgeCoord - 5, 1075, bridgeCoord - 5);
    brush.set("rotring", "#a8cae8", 0.32);
    tLine(135, bridgeCoord - 8, 1065, bridgeCoord - 8);
    brush.set("2B", "#1d2b3d", 0.65);
    tLine(125, bridgeCoord + 7, 1075, bridgeCoord + 7);

    // Vertical bridge highlight
    brush.set("cpencil", "#5f80a3", 0.55);
    tLine(bridgeCoord - 5, 125, bridgeCoord - 5, 1075);
