    tLine(bridgeCoord + 7, 125, bridgeCoord + 7, 1075);
  }

  // 4 Circular Molded Intersection Rings between the 9 cubes
  for (let r = 0; r < 2; r++) {
    for (let c = 0; c < 2; c++) {
