// Recursive / Procedural Feathery Frost Fern Generator
function drawFrostFernPlume(ox, oy, startAng, totalLen, curl, scale, seedVal) {
  let stepLen = 4.2;
  let nSteps = Math.max(8, Math.round(totalLen / stepLen));
  let spinePts = [[ox, oy]];
  let x = ox, y = oy;
  let ang = startAng;

  // Build curving primary rachis path
  let spineData = [];
  for (let i = 0; i < nSteps; i++) {
    let t = i / nSteps;
    // Smooth organic fern curl + subtle crystalline drift
    let nDrift = (noise(i * 0.08 + seedVal, seedVal * 0.3) - 0.5) * 0.055;
    ang += (curl * (0.65 + 0.7 * t) / nSteps) + nDrift;
    x += Math.cos(ang) * stepLen;
    y += Math.sin(ang) * stepLen;
    spinePts.push([x, y]);
    spineData.push({ x, y, ang, t });
  }

  // 1. Soft Cerulean Sub-Glow along the main stem
  brush.set("2H", "#6ea5d1", 0.55 * scale);
  tSpline(spinePts, 0.5);

  // 2. Secondary Feathery Pinnae (Side Fronds) along both sides of the spine
  for (let i = 1; i < spineData.length - 1; i++) {
    let sd = spineData[i];
    let t = sd.t;

    // Envelope of pinna length along the frond (arched like an ostrich plume / fern)
    let env = Math.sin(Math.pow(t, 0.68) * Math.PI) * (1.0 - 0.15 * t);

    for (let side of [-1, 1]) {
      // Stagger left and right pinnae slightly
      if ((i + (side === 1 ? 0 : 1)) % 2 !== 0 && t < 0.85) continue;

      // Acute crystalline branching angle (~52 to 62 degrees)
      let branchOffset = side * (54 + random(-6, 7)) * RAD;
      // Outer side of a curving fern plume has slightly longer, more sweeping feathers
      let sideBoost = (side * curl > 0) ? 1.18 : 0.88;
      let secLen = (48 * scale) * env * sideBoost * random(0.82, 1.18);

      if (secLen < 5) continue;

      let secAng = sd.ang + branchOffset;
      let secCurl = side * 0.32 + curl * 0.25;
      drawSecondaryPinna(sd.x, sd.y, secAng, secLen, secCurl, scale);

      // Occasional fractal codominant bifurcation near the lower-middle of large plumes
      if (scale > 0.92 && (i === Math.floor(nSteps * 0.32) || i === Math.floor(nSteps * 0.54)) && side * curl > 0) {
        drawFrostFernPlume(
          sd.x, sd.y,
          sd.ang + side * 42 * RAD,
          totalLen * 0.48,
          curl * 1.15,
          scale * 0.72,
          seedVal + i * 3.7
        );
      }
    }
  }

  // 3. Crisp Pale Cerulean & Pure Frost White Main Spine Filigree
  brush.set("pen", "#a6d8fa", 0.42 * scale);
  tSpline(spinePts, 0.5);

  brush.set("frost_needle", "#ffffff", 0.48 * scale);
  tSpline(spinePts.slice(0, Math.max(3, Math.floor(spinePts.length * 0.88))), 0.5);
}

// Secondary Feathery Pinna with Tertiary Crystalline Barbules
function drawSecondaryPinna(ox, oy, startAng, len, curl, scale) {
  let stepLen = 3.6;
  let nSteps = Math.max(3, Math.round(len / stepLen));
  let pts = [[ox, oy]];
  let x = ox, y = oy;
  let ang = startAng;

  for (let i = 0; i < nSteps; i++) {
    let t = i / nSteps;
    ang += (curl / nSteps) * (0.8 + 0.4 * t);
    x += Math.cos(ang) * stepLen;
    y += Math.sin(ang) * stepLen;
    pts.push([x, y]);

    // Spawn Tertiary Feathery Barbules & Crystalline Spicules along the pinna
    if (len > 11 && i < nSteps - 1) {
      let barbEnv = Math.sin(Math.pow(t, 0.6) * Math.PI);
      let barbLen = Math.min(18 * scale, len * 0.36) * barbEnv * random(0.8, 1.2);

      if (barbLen > 2.5) {
        for (let bSide of [-1, 1]) {
          let bAng = ang + bSide * (56 + random(-5, 5)) * RAD;
          let bx1 = x + Math.cos(bAng) * (barbLen * 0.55);
          let by1 = y + Math.sin(bAng) * (barbLen * 0.55);
          let bx2 = x + Math.cos(bAng + bSide * 0.14) * barbLen;
          let by2 = y + Math.sin(bAng + bSide * 0.14) * barbLen;

          // Alternating pale cerulean and crisp frost white needles
          let isWhite = (i + (bSide > 0 ? 1 : 0)) % 2 === 0;
          brush.set("rotring", isWhite ? "#f0f9ff" : "#97cdf5", (isWhite ? 0.26 : 0.24) * scale);
          tSpline([[x, y], [bx1, by1], [bx2, by2]], 0.35);

          // Tiny quaternary crystalline spur on longer tertiary barbs
          if (barbLen > 9.5 && isWhite) {
            let qAng = bAng + bSide * 52 * RAD;
            let qLen = barbLen * 0.42;
            brush.set("rotring", "#ffffff", 0.20 * scale);
            tLine(bx1, by1, bx1 + Math.cos(qAng) * qLen, by1 + Math.sin(qAng) * qLen);
          }
        }
      }
    }
  }

  // Draw the secondary pinna stem in pale cerulean + crisp white core
  brush.set("pen", "#9ed3f7", 0.32 * scale);
  tSpline(pts, 0.45);

  if (pts.length >= 3) {
    brush.set("frost_needle", "#f5fbff", 0.34 * scale);
    tSpline(pts, 0.45);
  }
}

// 6-Rayed Dendritic Frost Star / Crystalline Rosette
function drawFrostRosette(cx, cy, radius, baseRotDeg) {
  for (let r = 0; r < 6; r++) {
    let ang = (baseRotDeg + r * 60) * RAD;
    let rLen = radius * random(0.85, 1.15);
    let ex = cx + Math.cos(ang) * rLen;
    let ey = cy + Math.sin(ang) * rLen;

    // Pale cerulean ray base
    brush.set("pen", "#93caf2", 0.28);
    tLine(cx, cy, ex, ey);

    // Crisp white crystalline core needle
    brush.set("rotring", "#ffffff", 0.24);
    tLine(cx, cy, cx + Math.cos(ang) * (rLen * 0.85), cy + Math.sin(ang) * (rLen * 0.85));

    // Feathered dendritic side-barbs at 60 degrees
    for (let f = 1; f <= 2; f++) {
      let frac = f * 0.36;
      let bx = cx + Math.cos(ang) * (rLen * frac);
      let by = cy + Math.sin(ang) * (rLen * frac);
      let bLen = rLen * (0.45 - f * 0.12);
      for (let side of [-1, 1]) {
        let bAng = ang + side * 60 * RAD;
        brush.set("rotring", f === 1 ? "#eef8ff" : "#9fd4f7", 0.20);
        tLine(bx, by, bx + Math.cos(bAng) * bLen, by + Math.sin(bAng) * bLen);
      }
    }
  }
}

