// Returns 0.0 (deep viridian shade) to 1.0 (blazing golden sun-coin)
function getLight(x, y) {
  let maxSun = 0;
  for (let i = 0; i < sunCoins.length; i++) {
    let c = sunCoins[i];
    let dx = x - c.x;
    let dy = y - c.y;
    let ca = cos(-c.ang);
    let sa = sin(-c.ang);
    let rx = (dx * ca - dy * sa) / c.rx;
    let ry = (dx * sa + dy * ca) / c.ry;
    let d2 = rx * rx + ry * ry;
    if (d2 < 1.35) {
      let d = sqrt(d2);
      // Crisp coin rim with soft penumbra
      let val = constrain(map(d, 0.72, 1.12, 1.0, 0.0), 0.0, 1.0);
      val = val * val * (3 - 2 * val) * c.power;
      if (val > maxSun) maxSun = val;
    }
  }

  let shadePull = 0;
  for (let i = 0; i < shadeCoins.length; i++) {
    let s = shadeCoins[i];
    let dx = x - s.x;
    let dy = y - s.y;
    let d = sqrt((dx * dx) / (s.rx * s.rx) + (dy * dy) / (s.ry * s.ry));
    if (d < 1.2) {
      let sv = constrain(map(d, 0.4, 1.15, 0.35, 0.0), 0.0, 0.35) * s.depth;
      if (sv > shadePull) shadePull = sv;
    }
  }

  return constrain(0.14 + maxSun * 0.92 - shadePull, 0.0, 1.0);
}

// Natural ripples and folds in the cotton picnic blanket
function fabricWarp(u, v) {
  // Diagonal fold ridges running across the blanket
  let fold1 = sin((u * 0.42 + v * 0.35) * 0.8) * 11;
  let fold2 = cos((u * 0.25 - v * 0.55) * 0.9) * 8;
  let pinch = exp(- (pow(u - 520, 2) + pow(v - 480, 2)) / 95000) * 14;
  let du = fold1 + fold2 * 0.5 + pinch * 0.6;
  let dv = fold2 - fold1 * 0.4 + pinch * 0.8;

  // Convert blanket-space (u, v) to canvas-space (x, y)
  let cx = 600, cy = 600;
  let ca = cos(BLANKET_ANGLE), sa = sin(BLANKET_ANGLE);
  let wu = u + du - cx;
  let wv = v + dv - cy;
  return [cx + wu * ca - wv * sa, cy + wu * sa + wv * ca];
}

// Derivative of fold height for subtle fabric hill/valley shading
function getFoldLight(u, v) {
  let f = cos((u * 0.42 + v * 0.35) * 0.8) * 0.5 + sin((u * 0.25 - v * 0.55) * 0.9) * 0.5;
  return constrain(f * 0.5 + 0.5, 0, 1);
}

function getSplinePoints(ctrlPts, stepsPerSeg = 7, closed = true) {
  let pts = [];
  let n = ctrlPts.length;
  let limit = closed ? n : n - 1;
  for (let i = 0; i < limit; i++) {
    let p0 = closed ? ctrlPts[(i - 1 + n) % n] : ctrlPts[max(0, i - 1)];
    let p1 = ctrlPts[i];
    let p2 = closed ? ctrlPts[(i + 1) % n] : ctrlPts[min(n - 1, i + 1)];
    let p3 = closed ? ctrlPts[(i + 2) % n] : ctrlPts[min(n - 1, i + 2)];
    for (let s = 0; s < stepsPerSeg; s++) {
      let t = s / stepsPerSeg;
      let t2 = t * t;
      let t3 = t2 * t;
      let x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t +
        (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
        (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
      let y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t +
        (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
        (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
      pts.push([x, y]);
    }
  }
  if (!closed) pts.push(ctrlPts[n - 1]);
  return pts;
}

function drawPolyShape(pts, closeShape = true) {
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closeShape ? CLOSE : undefined);
}

// ============================================================================
// 1. WATERCOLOUR GINGHAM BLANKET & HYPERREAL WOVEN TEXTURE
// ============================================================================

function drawGinghamBlanket() {
  // Base warm paper / sunlit linen wash
  brush.noStroke();
  brush.wash("#f6eedc", 255);
  brush.rect(0, 0, 1200, 1200);
  brush.noWash();

  // Subtle watercolor base modulation across canvas
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.65, 0.35);
  brush.fill("#e8dec6", 90);
  brush.rect(-40, -40, 1280, 1280);
  brush.noFill();

  let minIdx = -4;
  let maxIdx = 17;

  // A. WATERCOLOUR WARP STRIPES (Vertical in blanket space, even columns)
  brush.fillBleed(0.16, "out");
  brush.fillTexture(0.72, 0.45);
  for (let col = minIdx; col <= maxIdx; col++) {
    if (abs(col) % 2 === 0) {
      let u0 = col * CELL_SIZE;
      let u1 = (col + 1) * CELL_SIZE;
      let ribbonPts = [];
      for (let step = minIdx * 2; step <= (maxIdx + 1) * 2; step++) {
        let v = step * (CELL_SIZE * 0.5);
        ribbonPts.push(fabricWarp(u0, v));
      }
      for (let step = (maxIdx + 1) * 2; step >= minIdx * 2; step--) {
        let v = step * (CELL_SIZE * 0.5);
        ribbonPts.push(fabricWarp(u1, v));
      }
      brush.fill("#cf232b", 125);
      drawPolyShape(ribbonPts, true);
    }
  }

  // B. WATERCOLOUR WEFT STRIPES (Horizontal in blanket space, even rows)
  // Where warp and weft cross, watercolor pigment naturally doubles into deep crimson!
  for (let row = minIdx; row <= maxIdx; row++) {
    if (abs(row) % 2 === 0) {
      let v0 = row * CELL_SIZE;
      let v1 = (row + 1) * CELL_SIZE;
      let ribbonPts = [];
      for (let step = minIdx * 2; step <= (maxIdx + 1) * 2; step++) {
        let u = step * (CELL_SIZE * 0.5);
        ribbonPts.push(fabricWarp(u, v0));
      }
      for (let step = (maxIdx + 1) * 2; step >= minIdx * 2; step--) {
        let u = step * (CELL_SIZE * 0.5);
        ribbonPts.push(fabricWarp(u, v1));
      }
      brush.fill("#c71c24", 128);
      drawPolyShape(ribbonPts, true);
    }
  }
  brush.noFill();

  // C. CELL-BY-CELL HIGH CONTRAST VALUE MODULATION & WOVEN THREAD TEXTURE
  for (let col = minIdx; col <= maxIdx; col++) {
    for (let row = minIdx; row <= maxIdx; row++) {
      let u0 = col * CELL_SIZE;
      let u1 = (col + 1) * CELL_SIZE;
      let v0 = row * CELL_SIZE;
      let v1 = (row + 1) * CELL_SIZE;

      let pTL = fabricWarp(u0, v0);
      let pTR = fabricWarp(u1, v0);
      let pBR = fabricWarp(u1, v1);
      let pBL = fabricWarp(u0, v1);

      let cx = (pTL[0] + pTR[0] + pBR[0] + pBL[0]) * 0.25;
      let cy = (pTL[1] + pTR[1] + pBR[1] + pBL[1]) * 0.25;

      // Skip off-screen cells
      if (cx < -110 || cx > 1310 || cy < -110 || cy > 1310) continue;

      let isWarpRed = abs(col) % 2 === 0;
      let isWeftRed = abs(row) % 2 === 0;
      let light = getLight(cx, cy);
      let fold = getFoldLight((u0 + u1) * 0.5, (v0 + v1) * 0.5);

      let cellPoly = [pTL, pTR, pBR, pBL];

      // High-contrast shade vs. sun wash per square
      brush.noStroke();
      if (light < 0.48) {
        // In cool viridian canopy shade: push values dark and cool
        let shadeAlpha = map(light, 0.0, 0.48, 185, 35) + (1 - fold) * 28;
        if (isWarpRed && isWeftRed) {
          brush.wash("#1f0910", shadeAlpha);
        } else if (isWarpRed || isWeftRed) {
          brush.wash("#2a222b", shadeAlpha * 0.92);
        } else {
          brush.wash("#274d46", shadeAlpha * 0.88);
        }
        drawPolyShape(cellPoly, true);
        brush.noWash();
      } else {
        // In warm coin-shaped sun pools: brighten whites and saturate reds
        let sunAlpha = map(light, 0.48, 1.0, 15, 135) * (0.7 + fold * 0.3);
        if (isWarpRed && isWeftRed) {
          brush.wash("#a81118", sunAlpha * 0.65);
        } else if (!isWarpRed && !isWeftRed) {
          brush.wash("#fffdf5", sunAlpha * 0.9);
        } else {
          brush.wash("#f04d4d", sunAlpha * 0.35);
        }
        drawPolyShape(cellPoly, true);
        brush.noWash();
      }

      // WOVEN TEXTURE: Hyperreal warp & weft threads inside sunlit squares, softer in shade
      let threadSteps = light > 0.52 ? 11 : 5;
      let threadWeight = light > 0.52 ? 0.48 : 0.35;

      // Warp threads (along v, stepping u)
      for (let s = 1; s < threadSteps; s++) {
        let t = s / threadSteps;
        let sx = lerp(pTL[0], pTR[0], t);
        let sy = lerp(pTL[1], pTR[1], t);
        let ex = lerp(pBL[0], pBR[0], t);
        let ey = lerp(pBL[1], pBR[1], t);

        if (isWarpRed) {
          let colStr = light > 0.52
            ? (s % 2 === 0 ? "#8f0d14" : "#d9252d")
            : "#361219";
          brush.set(light > 0.55 ? "2H" : "cpencil", colStr, threadWeight);
          brush.line(sx, sy, ex, ey);
        } else if (light > 0.45) {
          let colStr = s % 2 === 0 ? "#fffef8" : "#d9ccb8";
          brush.set("2H", colStr, threadWeight * 0.95);
          brush.line(sx, sy, ex, ey);
        }
      }

      // Weft threads (along u, stepping v)
      for (let s = 1; s < threadSteps; s++) {
        let t = s / threadSteps;
        let sx = lerp(pTL[0], pBL[0], t);
        let sy = lerp(pTL[1], pBL[1], t);
        let ex = lerp(pTR[0], pBR[0], t);
        let ey = lerp(pTR[1], pBR[1], t);

        if (isWeftRed) {
          let colStr = light > 0.52
            ? (s % 2 === 0 ? "#7a080f" : "#c91c24")
            : "#2e0f15";
          brush.set(light > 0.55 ? "2H" : "cpencil", colStr, threadWeight);
          brush.line(sx, sy, ex, ey);
        } else if (light > 0.45) {
          let colStr = s % 2 === 0 ? "#fffdf6" : "#d4c5b0";
          brush.set("2H", colStr, threadWeight * 0.95);
          brush.line(sx, sy, ex, ey);
        }
      }
    }
  }

  // Subtle fabric fold shadows & highlights across the blanket
  for (let i = 0; i < 18; i++) {
    let v = -120 + i * 82;
    let pts = [];
    for (let u = -120; u <= 1320; u += 80) {
      pts.push(fabricWarp(u, v + sin(u * 0.3) * 18));
    }
    brush.set("charcoal", i % 2 === 0 ? "#16332e" : "#fff7e6", 0.45);
    brush.spline(pts, 0.4);
  }
}

