      brush.spline(cr.map(p => [p[0] - 1.2, p[1] - 1.5]), 0.4);
    }

    // Translucent pinkish-ivory toenail
    let nailPoly = getSplinePoints(t.nail, 4, true);
    brush.noStroke();
    brush.wash("#fce2d7", 230);
    drawPolyShape(nailPoly, true);
    brush.noWash();

    // Pale crescent lunula at nail base & creamy free edge at nail tip
    brush.set("cpencil", "#fffdf9", 0.85);
    brush.line(t.nail[0][0] + 2, t.nail[0][1] + 2, t.nail[1][0] - 2, t.nail[1][1] + 2);
    brush.line(t.nail[3][0] + 1, t.nail[3][1] - 1, t.nail[2][0] - 1, t.nail[2][1] - 1);

    // Delicate cuticle outline & lateral nail fold
    brush.set("rotring", "#7a2e24", 0.38);
    brush.spline([t.nail[3], t.nail[0], t.nail[1], t.nail[2]], 0.35);

    // Sharp specular glint on the glossy nail plate
    brush.set("pen", "#ffffff", 0.55);
    brush.line(
      lerp(t.nail[0][0], t.nail[2][0], 0.35),
      lerp(t.nail[0][1], t.nail[2][1], 0.35),
      lerp(t.nail[0][0], t.nail[2][0], 0.65),
      lerp(t.nail[0][1], t.nail[2][1], 0.65)
    );
  }

  // Subtle green grass smudge on the medial edge of the right big toe & instep
  drawGrassStainPatch(566, 362, 16, 10, 68, 0.72);
  drawGrassStainPatch(534, 292, 18, 11, 55, 0.55);

  // Tendon & ankle bone highlights in the sunlit instep
  for (let i = 0; i < 4; i++) {
    let tx0 = 528 + i * 24;
    let ty0 = 235 - i * 6;
    let tx1 = 568 + i * 28;
    let ty1 = 318 - i * 10;
    brush.set("cpencil", "#fff6e6", 0.52);
    brush.line(tx0, ty0, tx1, ty1);
    brush.set("2H", "#d48a70", 0.35);
    brush.line(tx0 + 4, ty0 + 2, tx1 + 4, ty1 + 2);
  }
}

function drawGrassStainPatch(cx, cy, rx, ry, ang, intensity) {
  let ca = cos(ang), sa = sin(ang);
  // Soft watercolor chlorophyll stain base
  let stainPoly = getEllipsePoly(cx, cy, rx, ry, ang, 20);
  brush.noStroke();
  brush.fillBleed(0.15, "out");
  brush.fill("#4d7c2b", 95 * intensity);
  drawPolyShape(stainPoly, true);
  brush.noFill();

  // Streaky directional sap-green & olive marks rubbed into the skin grain
  let count = floor(28 * intensity);
  for (let i = 0; i < count; i++) {
    let u = random(-rx * 0.9, rx * 0.9);
    let v = random(-ry * 0.75, ry * 0.75);
    if ((u * u) / (rx * rx) + (v * v) / (ry * ry) > 1.0) continue;
    let len = random(6, 18);
    let x0 = cx + (u - len * 0.5) * ca - v * sa;
    let y0 = cy + (u - len * 0.5) * sa + v * ca;
    let x1 = cx + (u + len * 0.5) * ca - v * sa;
    let y1 = cy + (u + len * 0.5) * sa + v * ca;

    let colChoice = i % 3 === 0 ? "#2e591c" : (i % 3 === 1 ? "#639432" : "#8cb548");
    brush.set(i % 2 === 0 ? "cpencil" : "2H", colChoice, random(0.32, 0.58));
    brush.line(x0, y0, x1, y1);
  }
}

function getEllipsePoly(cx, cy, rx, ry, ang, steps = 28) {
  let pts = [];
  let ca = cos(ang), sa = sin(ang);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let ex = cos(a) * rx;
    let ey = sin(a) * ry;
    pts.push([cx + ex * ca - ey * sa, cy + ex * sa + ey * ca]);
  }
  return pts;
}

