  for (let i = 0; i < shadeCoins.length; i++) {
    let s = shadeCoins[i];
    let ringPts = getEllipsePoly(s.x, s.y, s.rx * 0.85, s.ry * 0.85, s.ang, 22);

    // Soft viridian spray rings
    brush.set("canopy_spray", i % 2 === 0 ? "#0f4a3f" : "#185e51", 1.15);
    brush.spline(ringPts, 0.5);

    let innerPts = getEllipsePoly(s.x, s.y, s.rx * 0.48, s.ry * 0.48, s.ang, 18);
    brush.set("canopy_spray", "#092e27", 1.0);
    brush.spline(innerPts, 0.5);
  }

  // B. Warm golden-ivory sun-coins (luminous sprayed halation at coin rims)
  for (let i = 0; i < sunCoins.length; i++) {
