    // Crisp coin-edge shimmer where warm light meets cool viridian shade
    if (i < 9) {
      brush.set("cpencil", "#ffdf80", 0.35);
      brush.arc(c.x, c.y, (c.rx + c.ry) * 0.48, -45, 75);
    }
  }
}

