  drawSinglePenAnt(636, 668, 24, 1.15);
}

function drawSinglePenAnt(ax, ay, ang, sc) {
  let ca = cos(ang), sa = sin(ang);
  function tr(lx, ly) {
    return [ax + (lx * ca - ly * sa) * sc, ay + (lx * sa + ly * ca) * sc];
  }

  // 1. High-contrast cast shadow of the ant on the sunlit gingham threads
  let shOff = [3.5 * sc, 5.5 * sc];
  brush.set("2H", "#2a1412", 0.65);
  let gasterSh = getEllipsePoly(ax + shOff[0] - 14 * ca * sc, ay + shOff[1] - 14 * sa * sc, 8 * sc, 5.2 * sc, ang, 14);
  brush.noStroke();
  brush.wash("#261210", 145);
  drawPolyShape(gasterSh, true);
  let headSh = getEllipsePoly(ax + shOff[0] + 12 * ca * sc, ay + shOff[1] + 12 * sa * sc, 5 * sc, 4 * sc, ang, 12);
  drawPolyShape(headSh, true);
  brush.noWash();

  // Leg shadows on the cloth
  let legs = [
    // Front pair
    [[6, -2], [11, -11], [18, -16], [22, -15]],
    [[6, 2], [10, 12], [17, 17], [21, 16]],
    // Middle pair
    [[0, -2.5], [1, -14], [-3, -21], [-6, -23]],
    [[0, 2.5], [2, 14], [-2, 21], [-5, 23]],
    // Rear pair
    [[-5, -2.5], [-12, -13], [-22, -19], [-27, -18]],
    [[-5, 2.5], [-11, 14], [-21, 20], [-26, 19]]
  ];

  brush.set("2H", "#381c18", 0.35);
  for (let i = 0; i < legs.length; i++) {
    let shLeg = legs[i].map(p => {
      let tp = tr(p[0], p[1]);
      return [tp[0] + shOff[0] * 0.7, tp[1] + shOff[1] * 0.7];
    });
    brush.spline(shLeg, 0.25);
  }

  // 2. Six Jointed Legs in Razor-Sharp Fine Pen
  for (let i = 0; i < legs.length; i++) {
    let lPts = legs[i].map(p => tr(p[0], p[1]));
    // Femur & tibia in dark sepia-black ink
    brush.set("rotring", "#140806", 0.52);
    brush.line(lPts[0][0], lPts[0][1], lPts[1][0], lPts[1][1]);
    brush.set("rotring", "#240e0a", 0.42);
    brush.line(lPts[1][0], lPts[1][1], lPts[2][0], lPts[2][1]);
    // Delicate tarsus & claw gripping the weave
    brush.set("pen", "#2e120c", 0.32);
    brush.line(lPts[2][0], lPts[2][1], lPts[3][0], lPts[3][1]);
  }

  // 3. Segmented Body: Gaster (Abdomen), Petiole Node, Thorax (Mesosoma), Head
  let gasterC = tr(-14.5, 0);
  let petioleC = tr(-6.5, 0);
  let thoraxC = tr(1.5, 0);
  let headC = tr(11.5, 0);

  let gasterPoly = getEllipsePoly(gasterC[0], gasterC[1], 8.2 * sc, 5.4 * sc, ang, 18);
  let thoraxPoly = getEllipsePoly(thoraxC[0], thoraxC[1], 6.2 * sc, 3.0 * sc, ang, 16);
  let headPoly = getEllipsePoly(headC[0], headC[1], 4.8 * sc, 3.8 * sc, ang, 16);
  let petiolePoly = getEllipsePoly(petioleC[0], petioleC[1], 2.0 * sc, 1.8 * sc, ang, 10);

  brush.noStroke();
  brush.wash("#1f0a07", 255);
  drawPolyShape(gasterPoly, true);
  drawPolyShape(thoraxPoly, true);
  drawPolyShape(headPoly, true);
  drawPolyShape(petiolePoly, true);
  brush.noWash();

  // Warm chestnut-mahogany translucent chitin glow on thorax and gaster edge
  brush.set("cpencil", "#7a2814", 0.55);
  brush.arc(gasterC[0], gasterC[1], 5.8 * sc, ang + 20, ang + 150);
  brush.arc(thoraxC[0], thoraxC[1], 3.5 * sc, ang - 40, ang + 120);

  // Crisp fine pen ink contours & chitin segmentation lines
  brush.set("rotring", "#0d0403", 0.55);
  drawPolyShape(gasterPoly, true);
  drawPolyShape(thoraxPoly, true);
  drawPolyShape(headPoly, true);

  // Elbowed Antennae & Mandibles reaching toward the peach juice
  let antL = [tr(15, -1.8), tr(20, -6.5), tr(26, -4.2)];
  let antR = [tr(15, 1.8), tr(20, 6.5), tr(26, 4.2)];
  brush.set("rotring", "#120604", 0.38);
  brush.line(antL[0][0], antL[0][1], antL[1][0], antL[1][1]);
  brush.line(antL[1][0], antL[1][1], antL[2][0], antL[2][1]);
  brush.line(antR[0][0], antR[0][1], antR[1][0], antR[1][1]);
  brush.line(antR[1][0], antR[1][1], antR[2][0], antR[2][1]);

  // Mandibles
  let mL = [tr(15.5, -1.5), tr(18, -0.5)];
  let mR = [tr(15.5, 1.5), tr(18, 0.5)];
  brush.line(mL[0][0], mL[0][1], mL[1][0], mL[1][1]);
  brush.line(mR[0][0], mR[0][1], mR[1][0], mR[1][1]);

  // Pinprick white specular glints on glossy chitin gaster, thorax & head
  let gGlint1 = tr(-16, -2.0);
  let gGlint2 = tr(-12, -1.8);
  let tGlint = tr(1.5, -1.2);
  let hGlint = tr(11.5, -1.4);
  brush.set("pen", "#ffffff", 0.65);
  brush.line(gGlint1[0], gGlint1[1], gGlint2[0], gGlint2[1]);
  brush.line(tGlint[0], tGlint[1], tGlint[0] + 2, tGlint[1] + 0.8);
  brush.line(hGlint[0], hGlint[1], hGlint[0] + 1.5, hGlint[1] + 0.6);
}

