    { spine: [[1135, -15], [1095, 65], [1062, 138], [1038, 195]], w: [12, 9, 5.5, 1] }
  ];

  for (let i = 0; i < cornerBlades.length; i++) {
    drawDetailedGrassBlade(cornerBlades[i].spine, cornerBlades[i].w, true);
  }
}

function drawDetailedGrassBlade(spineCtrl, widths, castShadow) {
  let steps = 24;
  let spine = getSplinePoints(spineCtrl, 8, false);
  let leftEdge = [];
  let rightEdge = [];

  for (let i = 0; i < spine.length; i++) {
    let t = i / (spine.length - 1);
    // Interpolate width along the blade
    let wIdx = t * (widths.length - 1);
    let i0 = floor(wIdx);
    let i1 = min(widths.length - 1, i0 + 1);
    let w = lerp(widths[i0], widths[i1], wIdx - i0);

    let pPrev = spine[max(0, i - 1)];
    let pNext = spine[min(spine.length - 1, i + 1)];
    let dx = pNext[0] - pPrev[0];
    let dy = pNext[1] - pPrev[1];
    let len = sqrt(dx * dx + dy * dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;

    leftEdge.push([spine[i][0] + nx * w * 0.5, spine[i][1] + ny * w * 0.5]);
    rightEdge.push([spine[i][0] - nx * w * 0.5, spine[i][1] - ny * w * 0.5]);
  }

  let bladePoly = leftEdge.concat(rightEdge.slice().reverse());

  // Crisp cast shadow beneath the grass blade
  if (castShadow) {
    let shPoly = bladePoly.map(p => [p[0] + 4.5, p[1] + 6.5]);
    brush.noStroke();
    brush.wash("#142622", 135);
    drawPolyShape(shPoly, true);
    brush.noWash();
  }

  // Sample light at blade midpoint
  let midPt = spine[floor(spine.length * 0.5)];
  let L = getLight(midPt[0], midPt[1]);

  // Opaque botanical green base wash
  brush.noStroke();
  brush.wash(L > 0.48 ? "#6ba336" : "#254f3c", 245);
  drawPolyShape(bladePoly, true);
  brush.noWash();

  // Sunlit yellow-green highlight on one half of the blade
  if (L > 0.45) {
    brush.set("cpencil", "#b8e05a", 0.75);
    brush.spline(leftEdge, 0.3);
  }

  // Fine pen parallel botanical venation & midrib (signature fine-pen hyperrealism)
  brush.set("rotring", "#112414", 0.52);
  brush.spline(spine, 0.3);

  // Outer edges in crisp fine pen ink
  brush.set("rotring", "#0c1c0f", 0.58);
  brush.spline(leftEdge, 0.3);
  brush.spline(rightEdge, 0.3);

  // Parallel vein hatching inside the blade
  for (let v = -0.3; v <= 0.3; v += 0.2) {
    if (abs(v) < 0.05) continue;
    let veinPts = [];
    for (let i = 2; i < spine.length - 2; i += 2) {
      let lx = lerp(leftEdge[i][0], rightEdge[i][0], 0.5 + v);
      let ly = lerp(leftEdge[i][1], rightEdge[i][1], 0.5 + v);
      veinPts.push([lx, ly]);
    }
    brush.set("pen", L > 0.48 ? "#284d1a" : "#0d2118", 0.32);
    brush.spline(veinPts, 0.3);
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(88314);
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm aged hydrographic chart rag paper ground
  background("#efe6d5");

  // -------------------------------------------------------------------------
  // 1. ANATOMICAL & BATHYMETRIC HEIGHTFIELD MODEL OF TWO CUPPED HANDS
  // -------------------------------------------------------------------------
  // Smooth-max and smooth-min helpers for organic anatomical blending
  const smax = (a, b, k) => {
    let h = Math.max(k - Math.abs(a - b), 0.0) / k;
    return Math.max(a, b) + h * h * k * 0.25;
  };

  // Distance & projection parameter to segment AB
  const segProj = (px, py, ax, ay, bx, by) => {
    let dx = bx - ax, dy = by - ay;
    let len2 = dx * dx + dy * dy;
    let t = len2 > 0 ? ((px - ax) * dx + (py - ay) * dy) / len2 : 0;
    let tc = t < 0 ? 0 : (t > 1 ? 1 : t);
    let cx = ax + tc * dx, cy = ay + tc * dy;
    let dist = Math.hypot(px - cx, py - cy);
    return { t: tc, rawT: t, d: dist, cx, cy };
  };

  // Define the 10 articulated digits (5 per hand: Thumb, Index, Middle, Ring, Pinky)
  // Each digit has 4 joints [MCP/CMC, PIP/MCP, DIP/IP, Tip], radii, and base elevations
  const leftDigits = [
    { // 0: Left Thumb (forms the outer left wall of the cup)
      pts: [[372, 755], [306, 610], [292, 495], [312, 408]],
      rad: [54, 41, 34, 30],
      elev: [0.46, 0.68, 0.88, 1.10],
      isThumb: true, whorlType: 1
    },
    { // 1: Left Index
      pts: [[375, 484], [368, 368], [372, 282], [380, 218]],
      rad: [34, 31, 28, 26],
      elev: [0.26, 0.54, 0.82, 1.08],
      isThumb: false, whorlType: 0
    },
    { // 2: Left Middle
      pts: [[440, 460], [437, 336], [440, 244], [445, 176]],
      rad: [35, 32, 29, 27],
      elev: [0.24, 0.56, 0.86, 1.14],
      isThumb: false, whorlType: 1
    },
    { // 3: Left Ring
      pts: [[505, 468], [503, 356], [505, 272], [508, 206]],
      rad: [33, 30, 28, 25.5],
      elev: [0.22, 0.52, 0.80, 1.06],
      isThumb: false, whorlType: 0
    },
    { // 4: Left Pinky (along the central ulnar seam)
      pts: [[566, 492], [567, 400], [566, 330], [564, 272]],
      rad: [31, 28, 25.5, 23.5],
      elev: [0.20, 0.46, 0.70, 0.94],
      isThumb: false, whorlType: -1
    }
  ];

  // Mirror with slight natural organic asymmetry for Right Hand
  const rightDigits = leftDigits.map((d, idx) => {
    return {
      pts: d.pts.map((p, j) => [
        1200 - p[0] + (idx === 0 ? -2 : 2) * Math.sin(j + idx),
        p[1] + 4 + 2.5 * Math.cos(idx * 1.3 + j)
      ]),
      rad: d.rad.slice(),
      elev: d.elev.map(e => e + 0.015 * Math.sin(idx)),
      isThumb: d.isThumb,
      whorlType: -d.whorlType
    };
  });

  const allDigits = [...leftDigits, ...rightDigits];

  // Palm & Wrist structural capsules for smooth anatomical silhouette and base volume
  // [ax, ay, bx, by, rA, rB, elevA, elevB]
  const palmCapsules = [
    // Left metacarpal fan & palm plate
    [495, 835, 375, 484, 58, 36, 0.35, 0.22],
    [508, 840, 440, 460, 62, 38, 0.36, 0.18],
    [525, 842, 505, 468, 60, 36, 0.34, 0.18],
    [548, 838, 566, 492, 52, 33, 0.34, 0.20],
    // Left thenar web & thumb base
    [475, 805, 342, 585, 68, 48, 0.44, 0.42],
    [352, 650, 375, 490, 52, 38, 0.45, 0.28],
    // Right metacarpal fan & palm plate
    [705, 839, 825, 488, 58, 36, 0.35, 0.22],
    [692, 844, 760, 464, 62, 38, 0.36, 0.18],
    [675, 846, 695, 472, 60, 36, 0.34, 0.18],
    [652, 842, 634, 496, 52, 33, 0.34, 0.20],
    // Right thenar web & thumb base
    [725, 809, 858, 589, 68, 48, 0.44, 0.42],
    [848, 654, 825, 494, 52, 38, 0.45, 0.28],
    // Central ulnar bridge uniting both cupped palms
    [600, 495, 600, 848, 46, 54, 0.15, 0.32],
    // Left and Right wrists extending downward
    [505, 845, 472, 1042, 84, 74, 0.34, 0.18],
    [695, 849, 728, 1044, 84, 74, 0.34, 0.18]
  ];

  // Major anatomical flexion creases (polylines with width and depth)
  const makeCrease = (pts, width, depth) => ({ pts, width, depth });
  const creases = [
    // Left Thenar Crease (Life Line)
    makeCrease([[362, 526], [418, 592], [468, 682], [496, 775], [504, 832]], 13, 0.22),
    // Right Thenar Crease (Life Line)
    makeCrease([[838, 530], [780, 596], [730, 686], [702, 778], [694, 835]], 13, 0.22),
    // Left Proximal Transverse Crease (Head Line)
    makeCrease([[366, 532], [435, 578], [505, 632], [568, 672]], 12, 0.21),
    // Right Proximal Transverse Crease (Head Line)
    makeCrease([[834, 536], [762, 582], [692, 638], [630, 676]], 12, 0.21),
    // Left Distal Transverse Crease (Heart Line)
    makeCrease([[592, 566], [534, 550], [472, 524], [416, 492]], 11, 0.20),
    // Right Distal Transverse Crease (Heart Line)
    makeCrease([[608, 570], [666, 554], [728, 528], [784, 496]], 11, 0.20),
    // Left Central Longitudinal Crease (Fate Line)
    makeCrease([[502, 810], [492, 705], [470, 600], [446, 504]], 10, 0.17),
    // Right Central Longitudinal Crease (Fate Line)
    makeCrease([[698, 814], [708, 708], [730, 604], [754, 508]], 10, 0.17),
    // Secondary diagonal palmar & hypothenar creases
    makeCrease([[546, 785], [568, 695], [585, 610]], 8, 0.13),
    makeCrease([[654, 788], [632, 698], [615, 614]], 8, 0.13),
    makeCrease([[338, 632], [385, 655], [432, 668]], 8, 0.14),
    makeCrease([[862, 636], [815, 659], [768, 672]], 8, 0.14),
    // Wrist Rascette Creases (Bracelets)
    makeCrease([[426, 858], [505, 868], [578, 856]], 9, 0.16),
    makeCrease([[422, 892], [502, 902], [574, 888]], 8, 0.13),
    makeCrease([[418, 926], [496, 936], [566, 922]], 7, 0.10),
    makeCrease([[622, 860], [695, 872], [774, 862]], 9, 0.16),
    makeCrease([[626, 892], [698, 906], [778, 896]], 8, 0.13),
    makeCrease([[634, 926], [704, 940], [782, 930]], 7, 0.10),
    // Central Ulnar Seam between the two pressed hands
    makeCrease([[600, 270], [598, 410], [602, 560], [599, 710], [600, 865], [600, 955]], 11, 0.25)
  ];

  // Evaluate a single articulated digit at (x, y)
  const evalDigit = (x, y, dig) => {
    let bestU = 999, bestS = 0, bestD = 999, bestR = 1;
    for (let i = 0; i < 3; i++) {
      let A = dig.pts[i], B = dig.pts[i + 1];
      let pr = segProj(x, y, A[0], A[1], B[0], B[1]);
      let s = i + pr.t;
      let r = dig.rad[i] * (1 - pr.t) + dig.rad[i + 1] * pr.t;
      // Slight physiological belly on each phalanx segment
      r += 1.6 * Math.sin(Math.PI * pr.t);
      let u = pr.d / r;
      if (u < bestU) {
        bestU = u;
        bestS = s;
        bestD = pr.d;
        bestR = r;
      }
    }
    if (bestU >= 1.25) return { mask: -1, elev: -1 };

    let mask = 1.0 - bestU; // > 0 inside digit
    if (mask <= 0) return { mask, elev: 0 };

    // Interpolate spine elevation
    let segIdx = Math.min(2, Math.floor(bestS));
    let frac = bestS - segIdx;
    let baseE = dig.elev[segIdx] * (1 - frac) + dig.elev[segIdx + 1] * frac;

    // Cross-sectional 3D dome (steep sides so contours pack tightly on finger edges)
    let dome = Math.pow(Math.max(0, 1.0 - bestU * bestU), 0.66) * (0.38 + 0.06 * bestS);

    // Fleshy phalanx belly cushion
    let belly = 0.095 * Math.sin(Math.PI * frac) * (1.0 - 0.6 * bestU * bestU);

    // Transverse knuckle/interphalangeal joint creases (MCP, PIP, DIP)
    let jCrease = 0;
    let d0 = (bestS - 0.06) / 0.085;
    let d1a = (bestS - 0.97) / 0.065;
    let d1b = (bestS - 1.06) / 0.060;
    let d2 = (bestS - 1.98) / 0.065;
    jCrease -= 0.14 * Math.exp(-d0 * d0);
    jCrease -= 0.16 * Math.exp(-d1a * d1a) + 0.12 * Math.exp(-d1b * d1b);
    jCrease -= 0.16 * Math.exp(-d2 * d2);
    jCrease *= (1.0 - 0.4 * bestU * bestU);

    // Distal fingertip pad cushion & subtle dermatoglyphic wave
    let fpPad = 0;
    if (bestS > 1.95) {
      let P2 = dig.pts[2], P3 = dig.pts[3];
      let cx = P2[0] * 0.32 + P3[0] * 0.68;
      let cy = P2[1] * 0.32 + P3[1] * 0.68;
      let dx = P3[0] - P2[0], dy = P3[1] - P2[1];
      let len = Math.hypot(dx, dy) || 1;
      let ux = dx / len, uy = dy / len;
      let vx = -uy, vy = ux;
      let lx = (x - cx) * vx + (y - cy) * vy;
      let ly = (x - cx) * ux + (y - cy) * uy;
      let rFp = Math.hypot(lx * 1.15, ly * 0.85);
      let ang = Math.atan2(ly, lx);
      fpPad += 0.13 * Math.exp(-(rFp * rFp) / 260);
      fpPad += 0.026 * Math.cos(rFp * 0.95 + dig.whorlType * ang) * Math.exp(-(rFp * rFp) / 310);
    }

    return {
      mask,
      elev: baseE + dome + belly + jCrease + fpPad
    };
  };

  // Master heightfield & anatomical mask evaluator at canvas coordinate (x, y)
  const getHandData = (x, y) => {
    // Fast bounding box reject
    if (x < 210 || x > 990 || y < 135 || y > 1070) {
      return { inside: false, mask: -1, h: 0, inBasin: false };
    }

    // Subtle organic warp so contour lines have living hand-drawn biological character
    let n1 = noise(x * 0.007, y * 0.007) - 0.5;
    let n2 = noise(x * 0.022 + 50, y * 0.022 + 50) - 0.5;
    let wx = x + n1 * 7.5 + n2 * 2.2;
    let wy = y + n1 * 6.5 + n2 * 2.2;

    // 1. Evaluate palm & wrist capsules
    let palmMask = -1.0;
    let palmElevSum = 0, palmWeightSum = 0;
    for (let i = 0; i < palmCapsules.length; i++) {
      let c = palmCapsules[i];
      let pr = segProj(wx, wy, c[0], c[1], c[2], c[3]);
      let r = c[4] * (1 - pr.t) + c[5] * pr.t;
      let u = pr.d / r;
      let m = 1.0 - u;
      palmMask = smax(palmMask, m, 0.22);
      if (u < 1.35) {
        let w = Math.pow(Math.max(0, 1.35 - u), 2.5);
        let e = (c[6] * (1 - pr.t) + c[7] * pr.t) * Math.pow(Math.max(0, 1.0 - u * u * 0.65), 0.55);
        palmElevSum += e * w;
        palmWeightSum += w;
      }
    }
    let palmH = palmWeightSum > 0 ? palmElevSum / palmWeightSum : 0;

    // Soft cutoff at bottom of wrists near chart margin (y ~ 1035)
    if (wy > 985) {
      let fade = (wy - 985) / 55.0;
      palmMask -= fade * fade * 0.85;
    }

    // Deep V-notch between the two wrists below the heel of the palm (y > 875)
    if (wy > 865) {
      let dxSeam = Math.abs(wx - 600);
      let dyWrist = (wy - 865) / 140;
      let gapW = 14 + dyWrist * 52;
      if (dxSeam < gapW) {
        let g = 1.0 - dxSeam / gapW;
        palmMask -= g * g * (0.35 + dyWrist * 0.9);
      }
    }

    // 2. Evaluate all 10 digits and blend with palm
    let bestDigMask = -1.0;
    let bestDigElev = 0;
    let secondDigMask = -1.0;
    for (let i = 0; i < allDigits.length; i++) {
      let res = evalDigit(wx, wy, allDigits[i]);
      if (res.mask > bestDigMask) {
        secondDigMask = bestDigMask;
        bestDigMask = res.mask;
        bestDigElev = res.elev;
      } else if (res.mask > secondDigMask) {
        secondDigMask = res.mask;
      }
    }

    let totalMask = smax(palmMask, bestDigMask, 0.16);

    // Sharp interdigital cleft valleys where two adjacent fingers press together
    let cleftValley = 0;
    if (bestDigMask > 0 && secondDigMask > -0.12 && wy < 515) {
      let overlap = Math.max(0, 0.20 - Math.abs(bestDigMask - secondDigMask));
      cleftValley = -1.15 * overlap;
      totalMask -= overlap * 0.35;
    }

    if (totalMask <= 0) {
      return { inside: false, mask: totalMask, h: 0, inBasin: false };
    }

    // Blend elevation between palm body and digits
    let h = palmH;
    if (bestDigMask > 0) {
      let dw = Math.min(1, Math.pow(bestDigMask / 0.28, 0.85));
      h = palmH * (1 - dw) + bestDigElev * dw;
    }
    h += cleftValley;

    // 3. Sculpt anatomical mounds (Thenar, Hypothenar, Interdigital cushions, Carpal heel, Tendons)
    // Left & Right Thenar Eminences (fleshy thumb mounds forming the outer basin walls)
    let dThL = Math.hypot((wx - 356) / 68, (wy - 668) / 108);
    let dThR = Math.hypot((wx - 844) / 68, (wy - 672) / 108);
    h += 0.56 * Math.exp(-dThL * dThL) + 0.56 * Math.exp(-dThR * dThR);

    // Left & Right Hypothenar Eminences (ulnar ridges)
    let dHyL = Math.hypot((wx - 558) / 46, (wy - 725) / 98);
    let dHyR = Math.hypot((wx - 642) / 46, (wy - 728) / 98);
    h += 0.28 * Math.exp(-dHyL * dHyL) + 0.28 * Math.exp(-dHyR * dHyR);

    // Southern Carpal Heel Dam (retains the southern edge of the water pool)
    let dHeelL = Math.hypot((wx - 505) / 78, (wy - 828) / 46);
    let dHeelR = Math.hypot((wx - 695) / 78, (wy - 832) / 46);
    let dHeelC = Math.hypot((wx - 600) / 65, (wy - 818) / 38);
    h += 0.38 * Math.exp(-dHeelL * dHeelL) + 0.38 * Math.exp(-dHeelR * dHeelR) + 0.26 * Math.exp(-dHeelC * dHeelC);

    // Interdigital Metacarpal Cushions at the northern base of the fingers
    const mcPads = [
      [386, 502], [444, 486], [504, 492], [560, 512],
      [814, 506], [756, 490], [696, 496], [640, 516]
    ];
    for (let i = 0; i < mcPads.length; i++) {
      let dm = Math.hypot((wx - mcPads[i][0]) / 32, (wy - mcPads[i][1]) / 28);
      h += 0.19 * Math.exp(-dm * dm);
    }

    // Longitudinal Wrist Tendons (palmaris longus & flexor carpi radialis)
    if (wy > 830) {
      let wt = Math.min(1, (wy - 830) / 80);
      let tL1 = Math.exp(-Math.pow((wx - (502 - (wy - 850) * 0.16)) / 13, 2));
      let tL2 = Math.exp(-Math.pow((wx - (472 - (wy - 850) * 0.16)) / 15, 2));
      let tR1 = Math.exp(-Math.pow((wx - (698 + (wy - 850) * 0.16)) / 13, 2));
      let tR2 = Math.exp(-Math.pow((wx - (728 + (wy - 850) * 0.16)) / 15, 2));
      h += wt * 0.18 * (tL1 + 0.8 * tL2 + tR1 + 0.8 * tR2);
    }

    // 4. Carve the Cupped Bathymetric Water Basin in the hollow of the palms!
    // Left palmar abyss, Right palmar abyss, and Central ulnar confluence saddle
    let bL = Math.hypot((wx - 486) / 114, (wy - 646) / 136);
    let bR = Math.hypot((wx - 714) / 114, (wy - 650) / 136);
    let bC = Math.hypot((wx - 600) / 96, (wy - 654) / 126);
    let bNorth = Math.hypot((wx - 600) / 145, (wy - 548) / 72);

    let basinDepth =
      1.18 * Math.exp(-Math.pow(bL, 2.15)) +
      1.18 * Math.exp(-Math.pow(bR, 2.15)) +
      0.74 * Math.exp(-Math.pow(bC, 2.1)) +
      0.34 * Math.exp(-Math.pow(bNorth, 2.2));

    // Add subtle hydrographic shoal undulation inside the basin
    basinDepth *= (1.0 + 0.08 * n2);
    h -= basinDepth;

    // 5. Carve Major Palmar Flexion Creases (Bathymetric & Topographic Canyons)
    for (let i = 0; i < creases.length; i++) {
      let cr = creases[i];
      let minD = 999, bestPos = 0;
      let nSeg = cr.pts.length - 1;
      for (let j = 0; j < nSeg; j++) {
        let pr = segProj(wx, wy, cr.pts[j][0], cr.pts[j][1], cr.pts[j + 1][0], cr.pts[j + 1][1]);
        if (pr.d < minD) {
          minD = pr.d;
          bestPos = (j + pr.t) / nSeg;
        }
      }
      if (minD < cr.width) {
        let u = minD / cr.width;
        let taper = Math.sin(Math.PI * Math.max(0.08, Math.min(0.92, bestPos)));
        let profile = (1.0 - u * u) * (1.0 - u * u);
        h -= cr.depth * profile * (0.45 + 0.55 * taper);
      }
    }

    // 6. Natural 3D edge roll-off near the outer silhouette so contours tighten at the limb margins
    if (totalMask < 0.24) {
      let edgeFactor = totalMask / 0.24;
      let edgeRoll = Math.pow(edgeFactor, 0.55);
      h = 0.05 + (h - 0.05) * edgeRoll;
    }

    // Prevent false water pooling outside the palm bowl (e.g. on wrists or outer fingertips)
    let inBasinZone = (wx > 315 && wx < 885 && wy > 435 && wy < 825);
    if (!inBasinZone && h < 0.04) {
      h = 0.04 + Math.abs(h) * 0.25;
    }

    return {
      inside: true,
      mask: totalMask,
      h,
      inBasin: inBasinZone && h <= 0.05
    };
  };

  // -------------------------------------------------------------------------
  // 2. EVALUATE HIGH-RESOLUTION BATHYMETRIC / TOPOGRAPHIC GRID (320 x 320)
  // -------------------------------------------------------------------------
  const GX = 320, GY = 320;
  const minX = 180, maxX = 1020;
  const minY = 130, maxY = 1070;
  const stepX = (maxX - minX) / GX;
  const stepY = (maxY - minY) / GY;

  const hGrid = new Float32Array((GX + 1) * (GY + 1));
  const mGrid = new Float32Array((GX + 1) * (GY + 1));
  const bGrid = new Uint8Array((GX + 1) * (GY + 1));

  for (let j = 0; j <= GY; j++) {
    let py = minY + j * stepY;
    for (let i = 0; i <= GX; i++) {
      let px = minX + i * stepX;
      let idx = j * (GX + 1) + i;
      let d = getHandData(px, py);
      mGrid[idx] = d.mask;
      // Outside the hands, push elevation slightly above 0 so basin contours never leak out
      hGrid[idx] = d.inside ? d.h : 0.045;
      bGrid[idx] = d.inBasin ? 1 : 0;
    }
  }

  // -------------------------------------------------------------------------
  // 3. MARCHING SQUARES WITH EXACT INTEGER EDGE-ID POLYLINE STITCHING
  // -------------------------------------------------------------------------
  // Horizontal edge ID: j * GX + i
  // Vertical edge ID: (GY + 1) * GX + j * (GX + 1) + i
  const V_OFFSET = (GY + 1) * GX;

  const extractIsoContours = (level, mode) => {
    // mode: "all" (inside hands), "basin" (water pool only), "land" (above water inside hands)
    const edgeCoords = new Map();
    const adj = new Map();

    const addEdgePoint = (eId, x, y) => {
      if (!edgeCoords.has(eId)) edgeCoords.set(eId, [x, y]);
    };
    const addSegment = (e1, e2) => {
      if (e1 === e2) return;
      if (!adj.has(e1)) adj.set(e1, []);
      if (!adj.has(e2)) adj.set(e2, []);
      adj.get(e1).push(e2);
      adj.get(e2).push(e1);
    };

    for (let j = 0; j < GY; j++) {
      let y0 = minY + j * stepY;
      let y1 = y0 + stepY;
      for (let i = 0; i < GX; i++) {
        let i00 = j * (GX + 1) + i;
        let i10 = i00 + 1;
        let i11 = i00 + (GX + 1) + 1;
        let i01 = i00 + (GX + 1);

        // Filter cells by domain
        if (mode === "basin") {
          if (y0 < 430 || y1 > 830 || (minX + i * stepX) < 310 || (minX + i * stepX) > 890) continue;
          if (mGrid[i00] <= 0 && mGrid[i10] <= 0 && mGrid[i11] <= 0 && mGrid[i01] <= 0) continue;
        } else {
          // Require all 4 corners to be inside the hand mask
          if (mGrid[i00] <= 0.01 || mGrid[i10] <= 0.01 || mGrid[i11] <= 0.01 || mGrid[i01] <= 0.01) continue;
        }

        let v0 = hGrid[i00] - level;
        let v1 = hGrid[i10] - level;
        let v2 = hGrid[i11] - level;
        let v3 = hGrid[i01] - level;

        let c0 = v0 >= 0 ? 1 : 0;
        let c1 = v1 >= 0 ? 2 : 0;
        let c2 = v2 >= 0 ? 4 : 0;
        let c3 = v3 >= 0 ? 8 : 0;
        let code = c0 | c1 | c2 | c3;
        if (code === 0 || code === 15) continue;

        let x0 = minX + i * stepX;
        let x1 = x0 + stepX;

        // Edge IDs for Top (0), Right (1), Bottom (2), Left (3)
        let eTop = j * GX + i;
        let eBottom = (j + 1) * GX + i;
        let eLeft = V_OFFSET + j * (GX + 1) + i;
        let eRight = V_OFFSET + j * (GX + 1) + (i + 1);

        const interpTop = () => {
          let t = v0 / (v0 - v1);
          addEdgePoint(eTop, x0 + t * stepX, y0);
          return eTop;
        };
        const interpRight = () => {
          let t = v1 / (v1 - v2);
          addEdgePoint(eRight, x1, y0 + t * stepY);
          return eRight;
        };
        const interpBottom = () => {
          let t = v3 / (v3 - v2);
          addEdgePoint(eBottom, x0 + t * stepX, y1);
          return eBottom;
        };
        const interpLeft = () => {
          let t = v0 / (v0 - v3);
          addEdgePoint(eLeft, x0, y0 + t * stepY);
          return eLeft;
        };

        if (code === 1 || code === 14) addSegment(interpLeft(), interpTop());
        else if (code === 2 || code === 13) addSegment(interpTop(), interpRight());
        else if (code === 4 || code === 11) addSegment(interpRight(), interpBottom());
        else if (code === 8 || code === 7) addSegment(interpBottom(), interpLeft());
        else if (code === 3 || code === 12) addSegment(interpLeft(), interpRight());
        else if (code === 6 || code === 9) addSegment(interpTop(), interpBottom());
        else if (code === 5 || code === 10) {
          let avg = 0.25 * (v0 + v1 + v2 + v3);
          if ((code === 5 && avg >= 0) || (code === 10 && avg < 0)) {
            addSegment(interpLeft(), interpBottom());
            addSegment(interpTop(), interpRight());
          } else {
            addSegment(interpLeft(), interpTop());
            addSegment(interpBottom(), interpRight());
          }
        }
      }
    }

    // Stitch adjacency graph into ordered polylines and closed loops
    const visitedEdges = new Set();
    const edgeKey = (a, b) => (a < b ? a + "_" + b : b + "_" + a);
    const polylines = [];

    // 1. Trace open paths first (starting at degree-1 nodes)
    for (let [node, neighbors] of adj.entries()) {
      if (neighbors.length === 1) {
        let curr = node;
        let path = [edgeCoords.get(curr)];
        while (true) {
          let nbrs = adj.get(curr) || [];
          let next = -1;
          for (let n of nbrs) {
            let k = edgeKey(curr, n);
            if (!visitedEdges.has(k)) {
              visitedEdges.add(k);
              next = n;
              break;
            }
          }
          if (next === -1) break;
          curr = next;
          path.push(edgeCoords.get(curr));
        }
        if (path.length >= 3) polylines.push({ pts: path, closed: false });
      }
    }

    // 2. Trace remaining closed loops
    for (let [node] of adj.entries()) {
      let nbrs = adj.get(node) || [];
      let hasUnvisited = false;
      for (let n of nbrs) {
        if (!visitedEdges.has(edgeKey(node, n))) {
          hasUnvisited = true;
          break;
        }
      }
      if (!hasUnvisited) continue;

      let curr = node;
      let path = [edgeCoords.get(curr)];
      while (true) {
        let cnbrs = adj.get(curr) || [];
        let next = -1;
        for (let n of cnbrs) {
          let k = edgeKey(curr, n);
          if (!visitedEdges.has(k)) {
            visitedEdges.add(k);
            next = n;
            break;
          }
        }
        if (next === -1) break;
        curr = next;
        if (curr === node) break;
        path.push(edgeCoords.get(curr));
      }
      if (path.length >= 5) polylines.push({ pts: path, closed: true });
    }

    return polylines;
  };

  // Helper to smooth & subsample a polyline for clean p5.brush rendering
  const simplifyAndSmooth = (pts, closed, stepDist = 6.5) => {
    let n = pts.length;
    if (n < 4) return pts;
    // 1 pass of Laplacian smoothing to remove grid quantization while keeping sharp crease bends
    let smoothed = [];
    for (let i = 0; i < n; i++) {
      if (!closed && (i === 0 || i === n - 1)) {
        smoothed.push(pts[i]);
      } else {
        let prev = pts[(i - 1 + n) % n];
        let curr = pts[i];
        let next = pts[(i + 1) % n];
        smoothed.push([
          0.22 * prev[0] + 0.56 * curr[0] + 0.22 * next[0],
          0.22 * prev[1] + 0.56 * curr[1] + 0.22 * next[1]
        ]);
      }
    }
    // Distance-based decimation
    let out = [smoothed[0]];
    let accum = 0;
    for (let i = 1; i < smoothed.length; i++) {
      let d = Math.hypot(smoothed[i][0] - smoothed[i - 1][0], smoothed[i][1] - smoothed[i - 1][1]);
      accum += d;
      if (accum >= stepDist || (!closed && i === smoothed.length - 1)) {
        out.push(smoothed[i]);
        accum = 0;
      }
    }
    return out;
  };

  // Helper to draw a filled watercolor polygon safely
  const drawFilledLoop = (pts, curvature = 0.3) => {
    if (pts.length < 4) return;
    brush.noStroke();
    brush.beginShape(curvature);
    for (let i = 0; i < pts.length; i++) {
      brush.vertex(pts[i][0], pts[i][1]);
    }
    brush.endShape(true);
  };

  // -------------------------------------------------------------------------
  // 4. STAGE 1: AGED NAUTICAL CHART PAPER WASHES, GRATICULE & RHUMB LINES
  // -------------------------------------------------------------------------
  brush.noStroke();
  brush.fillTexture(0.48, 0.22);
  brush.fillBleed(0.32, "out");

  // Warm parchment & raw umber atmospheric washes in the chart corners
  const bgWashes = [
    { col: "#e4d5be", op: 42, x: 240, y: 220, r: 340 },
    { col: "#e4d5be", op: 42, x: 960, y: 960, r: 360 },
    { col: "#dac7ac", op: 36, x: 950, y: 240, r: 310 },
    { col: "#dac7ac", op: 36, x: 230, y: 950, r: 320 },
    { col: "#d5be9e", op: 30, x: 600, y: 615, r: 440 }
  ];
  for (let w of bgWashes) {
    brush.fill(w.col, w.op);
    brush.circle(w.x, w.y, w.r, 0.35);
  }
  brush.noFill();

  // Subtle compass rhumb lines radiating from upper-left hydrographic station (225, 235)
  const rhumbX = 225, rhumbY = 235;
  brush.set("rotring", "#c4b097", 0.18);
  for (let a = 0; a < 360; a += 11.25) {
    let rad = a * Math.PI / 180;
    let rStart = (a % 45 === 0) ? 14 : 36;
    let rEnd = 1350;
    let x1 = rhumbX + Math.cos(rad) * rStart;
    let y1 = rhumbY + Math.sin(rad) * rStart;
    let x2 = rhumbX + Math.cos(rad) * rEnd;
    let y2 = rhumbY + Math.sin(rad) * rEnd;
    // Clip to chart neatline [64, 1136]
    let pts = [];
    for (let s = 0; s <= 60; s++) {
      let t = s / 60;
      let px = x1 + (x2 - x1) * t;
      let py = y1 + (y2 - y1) * t;
      if (px >= 64 && px <= 1136 && py >= 64 && py <= 1136) {
        pts.push([px, py]);
      }
    }
    if (pts.length >= 2) {
      brush.line(pts[0][0], pts[0][1], pts[pts.length - 1][0], pts[pts.length - 1][1]);
    }
  }
  // Tiny compass station rings
  brush.noFill();
  brush.set("rotring", "#a89176", 0.24);
  brush.circle(rhumbX, rhumbY, 36, 0.05);
  brush.circle(rhumbX, rhumbY, 14, 0.04);

  // Subtle chart graticule (parallels & meridians)
  brush.set("rotring", "#bfa98e", 0.20);
  for (let g = 200; g <= 1000; g += 200) {
    brush.line(58, g, 1142, g);
    brush.line(g, 58, g, 1142);
  }

  // -------------------------------------------------------------------------
  // 5. STAGE 2: MUTED EARTH-TONE SKIN & TOPOGRAPHIC WASHES
  // -------------------------------------------------------------------------
  // Soft shadow under the outer rim of the cupped hands and wrists
  brush.noStroke();
  brush.fillTexture(0.52, 0.32);
  brush.fillBleed(0.18, "out");
  brush.fill("#b89f86", 36);
  const shadowPolys = extractIsoContours(0.06, "all");
  for (let p of shadowPolys) {
    if (p.closed && p.pts.length > 35) {
      let sp = simplifyAndSmooth(p.pts, true, 14).map(pt => [pt[0] + 6, pt[1] + 9]);
      drawFilledLoop(sp, 0.35);
    }
  }

  // Stepped hypsometric earth-tone washes across the hand elevation (raw sienna, ochre, warm umber)
  const skinWashLevels = [
    { level: 0.055, col: "#e4cfb6", op: 52, bleed: 0.10 },
    { level: 0.22,  col: "#d8bc9d", op: 40, bleed: 0.09 },
    { level: 0.42,  col: "#caa483", op: 36, bleed: 0.08 },
    { level: 0.64,  col: "#bc8e6c", op: 34, bleed: 0.08 },
    { level: 0.86,  col: "#af7b59", op: 32, bleed: 0.07 }
  ];

  for (let sw of skinWashLevels) {
    brush.fill(sw.col, sw.op);
    brush.fillBleed(sw.bleed, "out");
    brush.fillTexture(0.48, 0.30);
    let polys = extractIsoContours(sw.level, "all");
    for (let p of polys) {
      if (p.closed && p.pts.length > 16) {
        let sp = simplifyAndSmooth(p.pts, true, 11);
        drawFilledLoop(sp, 0.32);
      }
    }
  }
  brush.noFill();

  // -------------------------------------------------------------------------
  // 6. STAGE 3: GRADED WATERCOLOUR DEPTH-TINTS (THE POOL OF WATER)
  // -------------------------------------------------------------------------
  // Stepped bathymetric depth bands from pale sea-glass at the shoreline
  // through cerulean to deep Prussian blue at the deepest center of the cupped palms
  const waterBands = [
    { level:  0.035, col: "#d8e5de", op: 46, bleed: 0.11, tex: 0.45, border: 0.28 }, // Wet meniscus halo
    { level: -0.025, col: "#c4dfd8", op: 62, bleed: 0.08, tex: 0.50, border: 0.36 }, // Pale sea-glass
    { level: -0.125, col: "#a7cfc9", op: 60, bleed: 0.07, tex: 0.52, border: 0.38 }, // Sea-glass
    { level: -0.235, col: "#86babb", op: 62, bleed: 0.06, tex: 0.54, border: 0.40 }, // Sea-glass to aqua
    { level: -0.345, col: "#66a1ae", op: 64, bleed: 0.06, tex: 0.55, border: 0.42 }, // Soft cerulean
    { level: -0.455, col: "#49869d", op: 66, bleed: 0.05, tex: 0.56, border: 0.44 }, // Cerulean
    { level: -0.565, col: "#316c8a", op: 70, bleed: 0.05, tex: 0.58, border: 0.45 }, // Deep cerulean
    { level: -0.680, col: "#1e5375", op: 74, bleed: 0.05, tex: 0.58, border: 0.46 }, // Cerulean-Prussian
    { level: -0.800, col: "#103b5b", op: 80, bleed: 0.04, tex: 0.60, border: 0.48 }, // Prussian blue
    { level: -0.920, col: "#07233b", op: 88, bleed: 0.04, tex: 0.62, border: 0.50 }  // Abyssal Prussian blue
  ];

  for (let wb of waterBands) {
    brush.fill(wb.col, wb.op);
    brush.fillBleed(wb.bleed, "out");
    brush.fillTexture(wb.tex, wb.border);
    let polys = extractIsoContours(wb.level, "basin");
    for (let p of polys) {
      if (p.closed && p.pts.length > 10) {
        let sp = simplifyAndSmooth(p.pts, true, 9);
        drawFilledLoop(sp, 0.32);
      }
    }
  }
  brush.noFill();

  // -------------------------------------------------------------------------
  // 7. STAGE 4: DENSE BATHYMETRIC & TOPOGRAPHIC CONTOUR ISOLINES IN SEPIA PEN
  // -------------------------------------------------------------------------
  // Collect stations for tiny unreadable sounding marks along index contours
  const soundingStations = [];
  // Collect shoreline and deep-basin contours for hydrographic slope hachures
  const hachureContours = [];

  // Generate 54 dense contour levels from -1.04 (abyssal center) to +1.30 (curled fingertips)
  const contourLevels = [];
  for (let k = -26; k <= 33; k++) {
    contourLevels.push({
      level: k * 0.04,
      isIndex: (k % 5 === 0),
      isShoreline: (k === 0),
      kIndex: k
    });
  }

  for (let cl of contourLevels) {
    let lvl = cl.level;
    let mode = lvl <= 0.03 ? "basin" : "all";
    let polylines = extractIsoContours(lvl, mode);

    // Choose sepia pen tone & stroke weight according to depth/elevation & index status
    let col, wgt;
    if (cl.isShoreline) {
      col = "#2b3836";
      wgt = 0.48;
    } else if (lvl < 0) {
      // Submerged bathymetric contours in dark sepia-umber & hydrographic slate-sepia
      col = cl.isIndex ? "#1d1a17" : (cl.kIndex % 2 === 0 ? "#3c3026" : "#4d4136");
      wgt = cl.isIndex ? 0.44 : 0.25;
    } else {
      // Skin topography contours in fine warm sepia pen
      col = cl.isIndex ? "#311d10" : (cl.kIndex % 2 === 0 ? "#573b26" : "#735239");
      wgt = cl.isIndex ? 0.45 : 0.26;
    }

    brush.set("rotring", col, wgt);

    for (let poly of polylines) {
      let sp = simplifyAndSmooth(poly.pts, poly.closed, 5.5);
      if (sp.length < 3) continue;

      if (cl.isShoreline || cl.kIndex === -10 || cl.kIndex === -20) {
        hachureContours.push({ pts: sp, level: lvl });
      }

      // On index contours that are sufficiently long, leave a small gap for a sounding mark
      if (cl.isIndex && sp.length > 26 && random() < 0.68) {
        let gapIdx = Math.floor(random(8, sp.length - 8));
        let pA = sp[gapIdx - 1], pB = sp[gapIdx + 1];
        let ang = atan2(pB[1] - pA[1], pB[0] - pA[0]);
        soundingStations.push({
          x: sp[gapIdx][0],
          y: sp[gapIdx][1],
          angle: ang,
          inWater: lvl <= 0
        });

        // Draw first part of contour before the sounding gap
        let part1 = sp.slice(0, gapIdx - 1);
        let part2 = sp.slice(gapIdx + 2);
        if (part1.length >= 3) {
          brush.beginShape(0.25);
          for (let pt of part1) brush.vertex(pt[0], pt[1]);
          brush.endShape(false);
        }
        if (part2.length >= 3) {
          brush.beginShape(0.25);
          for (let pt of part2) brush.vertex(pt[0], pt[1]);
          brush.endShape(false);
        }
      } else {
        brush.beginShape(0.25);
        for (let pt of sp) brush.vertex(pt[0], pt[1]);
        brush.endShape(poly.closed);
      }
    }
  }

  // Extra half-step micro-contours on the upper ridges, knuckles, and fingertips (lvl > 0.30)
  brush.set("rotring", "#7e5c43", 0.20);
  for (let lvl = 0.34; lvl <= 1.26; lvl += 0.08) {
    let polylines = extractIsoContours(lvl, "all");
    for (let poly of polylines) {
      let sp = simplifyAndSmooth(poly.pts, poly.closed, 6.0);
      if (sp.length < 4) continue;
      brush.beginShape(0.25);
      for (let pt of sp) brush.vertex(pt[0], pt[1]);
      brush.endShape(poly.closed);
    }
  }

  // -------------------------------------------------------------------------
  // 8. STAGE 5: FINGERPRINT WHORLS, KNUCKLE CREASES & PALMAR DERMATOGLYPHICS
  // -------------------------------------------------------------------------
  // Render dense dermatoglyphic whorl & loop isolines on all 10 distal fingertip pads
  for (let dIdx = 0; dIdx < allDigits.length; dIdx++) {
    let dig = allDigits[dIdx];
    let P2 = dig.pts[2], P3 = dig.pts[3];
    let cx = P2[0] * 0.30 + P3[0] * 0.70;
    let cy = P2[1] * 0.30 + P3[1] * 0.70;
    let dx = P3[0] - P2[0], dy = P3[1] - P2[1];
    let len = Math.hypot(dx, dy) || 1;
    let ux = dx / len, uy = dy / len; // Distal axis
    let vx = -uy, vy = ux;            // Transverse axis
    let padRx = dig.rad[3] * 0.86;
    let padRy = len * 0.48;

    // 14 concentric/spiral dermatoglyphic ridges per fingertip
    for (let rStep = 1; rStep <= 14; rStep++) {
      let normR = rStep / 14.5;
      let rx = normR * padRx;
      let ry = normR * padRy;
      let isMajor = (rStep % 4 === 0);
      brush.set("rotring", isMajor ? "#3a2415" : "#5c3f29", isMajor ? 0.26 : 0.19);

      // Construct whorl / arch loop with natural breaks
      let startAng = random(-25, 25);
      let spanAng = random(240, 330);
      let pts = [];
      for (let a = startAng; a <= startAng + spanAng; a += 10) {
        let rad = a * Math.PI / 180;
        // Whorl spiral & delta pinch near the DIP joint (bottom of pad)
        let pinch = Math.sin(rad) < 0 ? 1.0 + 0.18 * Math.pow(Math.abs(Math.sin(rad)), 1.5) : 1.0;
        let spiralShift = dig.whorlType * (a / 360) * 1.6;
        let lx = Math.cos(rad) * (rx + spiralShift) * pinch;
        let ly = Math.sin(rad) * (ry + spiralShift);
        // Flatten slightly near the DIP joint crease
        if (ly < -padRy * 0.62) ly = -padRy * 0.62 + (ly + padRy * 0.62) * 0.35;
        let wx = cx + lx * vx + ly * ux;
        let wy = cy + lx * vy + ly * uy;
        pts.push([wx, wy]);
      }
      if (pts.length >= 4) {
        brush.beginShape(0.3);
        for (let pt of pts) brush.vertex(pt[0], pt[1]);
        brush.endShape(false);
      }
    }

    // Transverse interphalangeal joint crease lines (MCP, PIP, DIP) on each digit
    const jointFracs = [0.06, 0.96, 1.04, 1.97, 2.03];
    for (let jf of jointFracs) {
      let sIdx = Math.min(2, Math.floor(jf));
      let f = jf - sIdx;
      let A = dig.pts[sIdx], B = dig.pts[sIdx + 1];
      let jx = A[0] * (1 - f) + B[0] * f;
      let jy = A[1] * (1 - f) + B[1] * f;
      let sdx = B[0] - A[0], sdy = B[1] - A[1];
      let slen = Math.hypot(sdx, sdy) || 1;
      let sux = sdx / slen, suy = sdy / slen;
      let svx = -suy, svy = sux;
      let jr = (dig.rad[sIdx] * (1 - f) + dig.rad[sIdx + 1] * f) * 0.82;

      brush.set("rotring", "#331f11", 0.28);
      let cPts = [];
      for (let t = -1; t <= 1; t += 0.2) {
        let bow = (1 - t * t) * 3.2 * (jf > 1.5 ? -1 : 1);
        let px = jx + t * jr * svx + bow * sux;
        let py = jy + t * jr * svy + bow * suy;
        cPts.push([px, py]);
      }
      brush.beginShape(0.3);
      for (let pt of cPts) brush.vertex(pt[0], pt[1]);
      brush.endShape(false);
    }
  }

  // Fine etched sepia lines & cross-contours along the major palmar creases
  for (let i = 0; i < creases.length; i++) {
    let cr = creases[i];
    brush.set("rotring", "#2b190d", 0.34);
    brush.beginShape(0.35);
    for (let pt of cr.pts) {
      brush.vertex(pt[0], pt[1]);
    }
    brush.endShape(false);

    // Subtle secondary parallel crease hairlines & fine feathered offshoots
    brush.set("rotring", "#4e3422", 0.21);
    let nSeg = cr.pts.length - 1;
    for (let j = 0; j < nSeg; j++) {
      let A = cr.pts[j], B = cr.pts[j + 1];
      let dx = B[0] - A[0], dy = B[1] - A[1];
      let len = Math.hypot(dx, dy) || 1;
      let nx = -dy / len, ny = dx / len;
      for (let s = 0.15; s < 0.9; s += 0.22) {
        let px = A[0] + dx * s, py = A[1] + dy * s;
        let ang = atan2(dy, dx) + random(-32, 32);
        let brLen = random(9, 22);
        brush.line(
          px + nx * random(-2, 2),
          py + ny * random(-2, 2),
          px + cos(ang) * brLen,
          py + sin(ang) * brLen
        );
      }
    }
  }

  // Delicate graphite tonal shading in the deep anatomical clefts & outer hand curve
  brush.set("2B", "#473222", 0.28);
  for (let dIdx = 0; dIdx < allDigits.length; dIdx++) {
    let dig = allDigits[dIdx];
    for (let i = 0; i < 3; i++) {
      let A = dig.pts[i], B = dig.pts[i + 1];
      let dx = B[0] - A[0], dy = B[1] - A[1];
      let len = Math.hypot(dx, dy) || 1;
      let nx = -dy / len, ny = dx / len;
      let rA = dig.rad[i], rB = dig.rad[i + 1];
      // Shade along the steep lateral margins of each finger
      for (let side of [-1, 1]) {
        for (let s = 0.1; s < 0.95; s += 0.09) {
          let r = (rA * (1 - s) + rB * s) * 0.88;
          let bx = A[0] + dx * s + nx * r * side;
          let by = A[1] + dy * s + ny * r * side;
          let inX = bx - nx * side * random(5, 11);
          let inY = by - ny * side * random(5, 11) + 2;
          brush.line(bx, by, inX, inY);
        }
      }
    }
  }

  // -------------------------------------------------------------------------
  // 9. STAGE 6: HYDROGRAPHIC HACHURES, TINY UNREADABLE SOUNDING MARKS & WET GLINTS
  // -------------------------------------------------------------------------
  // Draw fine bathymetric slope hachure ticks pointing down-slope into the basin
  brush.set("rotring", "#2d261f", 0.21);
  for (let hc of hachureContours) {
    let pts = hc.pts;
    for (let i = 2; i < pts.length - 2; i += 4) {
      let pPrev = pts[i - 1], pNext = pts[i + 1], p = pts[i];
      let tx = pNext[0] - pPrev[0], ty = pNext[1] - pPrev[1];
      let tlen = Math.hypot(tx, ty) || 1;
      // Normal pointing toward the basin center (600, 650)
      let nx = -ty / tlen, ny = tx / tlen;
      let toCenter = (600 - p[0]) * nx + (650 - p[1]) * ny;
      if (toCenter < 0) { nx = -nx; ny = -ny; }
      let tickLen = hc.level === 0 ? 4.5 : 3.5;
      brush.line(p[0], p[1], p[0] + nx * tickLen, p[1] + ny * tickLen);
    }
  }

  // Add scattered hydrographic sounding stations inside the water pool & palm shoals
  for (let n = 0; n < 48; n++) {
    let sx = random(345, 855);
    let sy = random(465, 815);
    let d = getHandData(sx, sy);
    if (d.inside && d.mask > 0.25) {
      soundingStations.push({
        x: sx,
        y: sy,
        angle: random(-12, 12),
        inWater: d.h <= 0,
        hasDot: true
      });
    }
  }

  // Helper to scribe a tiny, unreadable engraved hydrographic sounding mark
  const drawMicroSounding = (sx, sy, degAngle, inWater, hasDot) => {
    push();
    translate(sx, sy);
    rotate(degAngle);

    let ink = inWater ? "#172026" : "#2e1c10";
    brush.set("rotring", ink, 0.22);

    if (hasDot) {
      // Tiny hydrographic sounding crosshair or dot
      brush.line(-1.8, 0, 1.8, 0);
      brush.line(0, -1.8, 0, 1.8);
      translate(5.5, 0);
    }

    // Scribe 1 or 2 minuscule archaic cipher glyphs (3.5 - 5px tall) + subscript fraction
    let glyphCount = random() < 0.65 ? 2 : 1;
    for (let g = 0; g < glyphCount; g++) {
      let gx = (g - (glyphCount - 1) * 0.5) * 4.2;
      let style = Math.floor(random(5));
      if (style === 0) {
        // Tiny hooked '1' or '7' glyph
        brush.line(gx - 1.2, -2.0, gx + 1.2, -2.0);
        brush.line(gx + 1.2, -2.0, gx - 0.5, 2.2);
      } else if (style === 1) {
        // Tiny curved '2' or '3' glyph
        brush.beginShape(0.4);
        brush.vertex(gx - 1.3, -1.6);
        brush.vertex(gx + 1.3, -2.0);
        brush.vertex(gx + 0.4, 0.2);
        brush.vertex(gx - 1.3, 2.0);
        brush.vertex(gx + 1.5, 2.0);
        brush.endShape(false);
      } else if (style === 2) {
        // Tiny '4' or angular cipher
        brush.line(gx + 0.6, -2.2, gx - 1.4, 0.6);
        brush.line(gx - 1.4, 0.6, gx + 1.5, 0.6);
        brush.line(gx + 0.6, -2.2, gx + 0.6, 2.2);
      } else if (style === 3) {
        // Tiny loop '6' or '8' glyph
        brush.circle(gx, 0.5, 1.5, 0.1);
        brush.line(gx + 1.1, -2.1, gx - 1.1, 0.5);
      } else {
        // Tiny '5' or '9' cipher
        brush.circle(gx, -0.7, 1.4, 0.1);
        brush.line(gx + 1.1, -0.7, gx - 0.6, 2.2);
      }
    }

    // Occasional tiny subscript sounding fraction bar & dot
    if (random() < 0.55) {
      let fx = glyphCount * 2.5 + 1.5;
      brush.line(fx - 1.2, 0.4, fx + 1.4, -0.4);
      brush.line(fx - 0.4, 1.5, fx + 0.8, 2.6);
    }
    pop();
  };

  for (let st of soundingStations) {
    drawMicroSounding(st.x, st.y, st.angle, st.inWater, st.hasDot);
  }

  // -------------------------------------------------------------------------
  // 10. WET SPECULAR HIGHLIGHTS, MENISCUS GLINTS & WATER DROPLETS ON SKIN
  // -------------------------------------------------------------------------
  // Crisp wet meniscus glints along the upper-left illuminated rims of the shoreline
  // and damp skin ridges so the chart resolves into living, wet hands
  brush.set("pen", "#faf7f0", 0.34);
  const wetGlintLevels = [0.0, 0.04, 0.12, 0.24, 0.44, 0.68];
  for (let wl of wetGlintLevels) {
    let polys = extractIsoContours(wl, wl <= 0.04 ? "basin" : "all");
    for (let poly of polys) {
      let pts = simplifyAndSmooth(poly.pts, poly.closed, 6.0);
      if (pts.length < 8) continue;
      for (let i = 1; i < pts.length - 2; i++) {
        let dx = pts[i + 1][0] - pts[i - 1][0];
        let dy = pts[i + 1][1] - pts[i - 1][1];
        let ang = atan2(dy, dx);
        // Catch light from upper-left (-45 deg normal)
        if (ang > -25 && ang < 55 && random() < (wl <= 0.04 ? 0.42 : 0.18)) {
          brush.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
        }
      }
    }
  }

  // Tiny glistening water droplets clinging to the damp thenar mounds & finger bases
  const droplets = [
    [352, 615, 4.2], [368, 665, 3.4], [336, 558, 3.0], [412, 488, 3.6],
    [478, 474, 3.2], [538, 486, 2.8], [492, 808, 3.8], [532, 822, 3.0],
    [842, 622, 4.0], [826, 678, 3.3], [858, 565, 3.1], [782, 492, 3.5],
    [718, 478, 3.0], [662, 490, 2.8], [706, 812, 3.7], [668, 824, 2.9],
    [388, 395, 2.8], [442, 368, 3.2], [755, 372, 3.1], [812, 402, 2.7]
  ];
  for (let dp of droplets) {
    let [dx, dy, dr] = dp;
    // Soft aqua-cerulean refract wash inside droplet
    brush.noStroke();
    brush.fill("#8abcc0", 75);
    brush.fillBleed(0.02, "out");
    brush.circle(dx, dy, dr, 0.08);
    brush.noFill();
    // Dark sepia shadow crescent on lower-right of droplet
    brush.set("rotring", "#2b1b10", 0.25);
    brush.arc(dx, dy, dr, 15, 145);
    // Bright white specular pinpoint on upper-left of droplet
    brush.set("pen", "#ffffff", 0.42);
    brush.line(dx - dr * 0.38, dy - dr * 0.38, dx - dr * 0.15, dy - dr * 0.45);
  }

  // -------------------------------------------------------------------------
  // 11. HYDROGRAPHIC CHART NEATLINE BORDER & DEGREE SUBDIVISIONS
  // -------------------------------------------------------------------------
  brush.noFill();
  brush.set("rotring", "#3d291a", 0.48);
  brush.rect(48, 48, 1104, 1104, "corner");
  brush.set("rotring", "#59402d", 0.28);
  brush.rect(58, 58, 1084, 1084, "corner");

  // Fine hydrographic degree & minute ticks along the double neatline border
  brush.set("rotring", "#4e3725", 0.24);
  for (let pos = 58; pos <= 1142; pos += 20) {
    let isMaj = ((pos - 58) % 100 === 0);
    let tLen = isMaj ? 10 : 5;
    // Top & bottom border ticks
    brush.line(pos, 58 - tLen, pos, 58);
    brush.line(pos, 1142, pos, 1142 + tLen);
    // Left & right border ticks
    brush.line(58 - tLen, pos, 58, pos);
    brush.line(1142, pos, 1142 + tLen, pos);

    // Alternating shaded minute bar segments in the border track
    if (Math.floor((pos - 58) / 100) % 2 === 0 && pos + 20 <= 1142) {
      brush.line(pos, 53, pos + 20, 53);
      brush.line(pos, 1147, pos + 20, 1147);
      brush.line(53, pos, 53, pos + 20);
      brush.line(1147, pos, 1147, pos + 20);
    }
  }

  // Subtle chart scale bar & unreadable engraved legend ticks at bottom-right margin (960, 1118)
  brush.set("rotring", "#4a3322", 0.26);
  brush.line(910, 1118, 1090, 1118);
  brush.line(910, 1122, 1090, 1122);
  for (let sx = 910; sx <= 1090; sx += 18) {
    brush.line(sx, 1114, sx, 1122);
    drawMicroSounding(sx, 1106, 0, false, false);
  }

  noLoop();
}

