// ============================================================================
// GEOMETRY & COLOR HELPERS
// ============================================================================

function evalBezierPoint(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let b0 = u * u * u;
  let b1 = 3 * u * u * t;
  let b2 = 3 * u * t * t;
  let b3 = t * t * t;
  return {
    x: b0 * p0.x + b1 * p1.x + b2 * p2.x + b3 * p3.x,
    y: b0 * p0.y + b1 * p1.y + b2 * p2.y + b3 * p3.y
  };
}

function evalBezierTangent(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let dx = 3 * u * u * (p1.x - p0.x) + 6 * u * t * (p2.x - p1.x) + 3 * t * t * (p3.x - p2.x);
  let dy = 3 * u * u * (p1.y - p0.y) + 6 * u * t * (p2.y - p1.y) + 3 * t * t * (p3.y - p2.y);
  let len = Math.hypot(dx, dy) || 1;
  return { tx: dx / len, ty: dy / len, nx: -dy / len, ny: dx / len };
}

function drawFilledPoly(pts, curvature = 0.2) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(CLOSE);
}

// Characteristic SEM secondary-electron intensity curve:
// Center (|u| ~ 0) is dark charcoal; grazing rims (|u| -> 1) glow bright silver
function semToneColor(u, depthFog = 0, detectorBias = -0.15) {
  let absU = Math.min(1, Math.abs(u));
  // Grazing angle secant-like response
  let rim = Math.pow(absU, 2.35) * 0.65 + Math.pow(absU, 6.5) * 0.45;
  // Primary detector on upper-left makes left edge (u < 0) slightly hotter
  if (u < 0) rim *= (1.0 - detectorBias);
  else rim *= (1.0 + detectorBias * 0.5);

  let val = constrain(rim, 0, 1);
  // Mix with fog if in background
  if (depthFog > 0) {
    val = lerp(val * 0.7 + 0.18, 0.52, depthFog * 0.65);
  }

  if (val < 0.12) return PAL.inkBlack;
  if (val < 0.24) return PAL.charcoalDeep;
  if (val < 0.38) return PAL.charcoalDark;
  if (val < 0.52) return PAL.charcoalMid;
  if (val < 0.66) return PAL.taupeMid;
  if (val < 0.78) return PAL.silverDim;
  if (val < 0.88) return PAL.silverMid;
  if (val < 0.95) return PAL.silverBright;
  return PAL.silverGlow;
}

// ============================================================================
// 1. ATMOSPHERIC SEM FOG & FINGER-SMUDGED GROUND
// ============================================================================

function renderAtmosphericFog() {
  brush.noStroke();

  // Upper receding fog washes batched by tone
  const fogBands = [
    { y1: -30, y2: 260, col: PAL.fogMid, op: 150 },
    { y1: 120, y2: 430, col: PAL.fogDark, op: 140 },
    { y1: 300, y2: 640, col: PAL.taupeMid, op: 135 },
    { y1: 480, y2: 860, col: PAL.charcoalMid, op: 145 },
    { y1: 700, y2: 1230, col: PAL.inkBlack, op: 190 }
  ];

  for (let b of fogBands) {
    brush.wash(b.col, b.op);
    drawFilledPoly([
      [-30, b.y1],
      [1230, b.y1 - 15],
      [1230, b.y2 + 15],
      [-30, b.y2]
    ], 0.05);
  }
  brush.noWash();

  // Soft watercolor-style textured charcoal clouds for finger-blended depth
  brush.fillBleed(0.4, "out");
  brush.fillTexture(0.65, 0.15);

  const clouds = [
    { x: 250, y: 140, rx: 340, ry: 150, col: PAL.fogLight, op: 75 },
    { x: 680, y: 110, rx: 420, ry: 160, col: PAL.fogLight, op: 80 },
    { x: 1020, y: 170, rx: 290, ry: 150, col: PAL.fogMid, op: 70 },
    { x: 480, y: 310, rx: 450, ry: 180, col: PAL.fogDark, op: 65 },
    { x: 850, y: 360, rx: 380, ry: 170, col: PAL.taupeMid, op: 65 },
    { x: 300, y: 580, rx: 380, ry: 200, col: PAL.charcoalDark, op: 90 },
    { x: 780, y: 620, rx: 420, ry: 220, col: PAL.charcoalDeep, op: 100 }
  ];

  for (let c of clouds) {
    brush.fill(c.col, c.op);
    let pts = [];
    for (let a = 0; a < 360; a += 30) {
      let radNoise = 0.82 + 0.35 * noise(c.x * 0.01 + cos(a), c.y * 0.01 + sin(a));
      pts.push([
        c.x + cos(a) * c.rx * radNoise,
        c.y + sin(a) * c.ry * radNoise
      ]);
    }
    drawFilledPoly(pts, 0.35);
  }
  brush.noFill();

  // Horizontal & diagonal finger-smudge sweeps across the upper fog
  for (let i = 0; i < 160; i++) {
    let y = map(i, 0, 160, 0, 820) + random(-25, 25);
    let x1 = random(-60, 900);
    let x2 = x1 + random(180, 480);
    let dy = random(-35, 35);

    let col = PAL.charcoalDark;
    if (y < 180) col = random([PAL.fogLight, PAL.fogMid, PAL.silverDim]);
    else if (y < 360) col = random([PAL.fogMid, PAL.fogDark, PAL.taupeMid]);
    else if (y < 560) col = random([PAL.taupeMid, PAL.charcoalMid, PAL.charcoalDark]);

    brush.set("velvet_smudge", col, random(1.2, 2.8));
    brush.spline([
      [x1, y],
      [(x1 + x2) * 0.5, y + dy * 0.6 + random(-12, 12)],
      [x2, y + dy]
    ], 0.4);
  }
}

