      p2: {x: 805, y: 460},
      p3: {x: 855, y: 185},
      r0: 72, r1: 65, fog: 0.0, seed: 305,
      clefts: [-0.46, -0.05, 0.32, 0.64],
      peelSide: -1
    }
  ];

  for (let b of fgSpecs) {
    drawBristleColumn(b, "fg");
  }
}

function drawBristleColumn(cfg, tier) {
  randomSeed(cfg.seed);
  const { p0, p1, p2, p3, r0, r1, fog } = cfg;

  // Build cylinder boundary polygon for solid occlusion
  let leftEdge = [];
  let rightEdge = [];
  let steps = 28;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let pt = evalBezierPoint(p0, p1, p2, p3, t);
    let tg = evalBezierTangent(p0, p1, p2, p3, t);
    // Slight mushrooming flare near the worn tip (t > 0.78)
    let flare = t > 0.78 ? 1 + 0.18 * Math.pow((t - 0.78) / 0.22, 1.6) : 1.0;
    let r = lerp(r0, r1, t) * flare;
    leftEdge.push([pt.x - tg.nx * r, pt.y - tg.ny * r]);
    rightEdge.push([pt.x + tg.nx * r, pt.y + tg.ny * r]);
  }

  let polyPts = leftEdge.concat(rightEdge.slice().reverse());

  // 1. Base Occlusion Wash (Dark core of the SEM cylinder)
  brush.noStroke();
  let baseCol = tier === "distant" ? PAL.taupeMid : (tier === "mid" ? PAL.charcoalDark : PAL.inkBlack);
  let baseOp = tier === "distant" ? 165 : 235;
  brush.wash(baseCol, baseOp);
  drawFilledPoly(polyPts, 0.15);
  brush.noWash();

  // For foreground/midground, add dry charcoal mass along the dark central core
  if (tier !== "distant") {
    let corePts = [];
    for (let i = 0; i <= 16; i++) {
      let t = (i / 16) * 0.92;
      let pt = evalBezierPoint(p0, p1, p2, p3, t);
      let tg = evalBezierTangent(p0, p1, p2, p3, t);
      let r = lerp(r0, r1, t) * 0.55;
      corePts.push([pt.x - tg.nx * r, pt.y - tg.ny * r]);
    }
    for (let i = 16; i >= 0; i--) {
      let t = (i / 16) * 0.92;
      let pt = evalBezierPoint(p0, p1, p2, p3, t);
      let tg = evalBezierTangent(p0, p1, p2, p3, t);
      let r = lerp(r0, r1, t) * 0.55;
      corePts.push([pt.x + tg.nx * r, pt.y + tg.ny * r]);
    }
    brush.mass("charcoal", tier === "fg" ? PAL.voidBlack : PAL.charcoalDeep, {
      precision: 0.65,
      strength: tier === "fg" ? 0.75 : 0.45,
      gradient: 0.25,
      outline: false
    });
    drawFilledPoly(corePts, 0.15);
    brush.noMass();
  }

  // 2. Longitudinal Velvety Smudge Bands (Cylindrical SEM Shading)
  let smudgeStrips = tier === "fg" ? 18 : (tier === "mid" ? 11 : 7);
  for (let s = 0; s < smudgeStrips; s++) {
    let u = map(s, 0, smudgeStrips - 1, -0.96, 0.96);
    let col = semToneColor(u, fog);
    let w = tier === "fg" ? map(Math.abs(u), 0, 1, 1.8, 0.7) : 1.3;
    brush.set("velvet_smudge", col, w);

    let splinePts = [];
    for (let k = 0; k <= 10; k++) {
      let t = (k / 10) * 0.93;
      let pt = evalBezierPoint(p0, p1, p2, p3, t);
      let tg = evalBezierTangent(p0, p1, p2, p3, t);
      let flare = t > 0.78 ? 1 + 0.18 * Math.pow((t - 0.78) / 0.22, 1.6) : 1.0;
      let r = lerp(r0, r1, t) * flare;
      splinePts.push([pt.x + tg.nx * r * u, pt.y + tg.ny * r * u]);
    }
    brush.spline(splinePts, 0.35);
  }

  // 3. Longitudinal Extrusion Micro-Striations & Grazing Rim Glow
  let numLines = tier === "fg" ? 58 : (tier === "mid" ? 30 : 14);
  for (let i = 0; i < numLines; i++) {
    // Concentrate lines more densely near the glowing edges (|u| -> 1)
    let raw = map(i, 0, numLines - 1, -1, 1);
    let u = Math.sign(raw) * Math.pow(Math.abs(raw), 0.72);
    let col = semToneColor(u, fog);

    let isRim = Math.abs(u) > 0.82;
    let bName = isRim ? (tier === "fg" ? "graphite_sheen" : "2H") : (Math.abs(u) < 0.4 ? "charcoal_stick" : "HB");
    let weight = isRim ? random(0.65, 1.35) : random(0.45, 0.9);
    if (tier === "distant") {
      bName = "2B";
      weight *= 0.7;
    }

    // Break extrusion lines into natural overlapping segments
    let segs = tier === "fg" ? 3 : 2;
    for (let sg = 0; sg < segs; sg++) {
      let tStart = constrain((sg / segs) * 0.9 - random(0, 0.06), 0, 0.85);
      let tEnd = constrain(((sg + 1) / segs) * 0.92 + random(-0.04, 0.04), tStart + 0.1, 0.94);

      let pts = [];
      let nSteps = 6;
      for (let k = 0; k <= nSteps; k++) {
        let t = lerp(tStart, tEnd, k / nSteps);
        let pt = evalBezierPoint(p0, p1, p2, p3, t);
        let tg = evalBezierTangent(p0, p1, p2, p3, t);
        let flare = t > 0.78 ? 1 + 0.22 * Math.pow((t - 0.78) / 0.22, 1.6) : 1.0;
        let r = lerp(r0, r1, t) * flare;
        let uJitter = u + (noise(cfg.seed + i * 0.3, t * 4) - 0.5) * 0.04;
        pts.push([
          pt.x + tg.nx * r * uJitter,
          pt.y + tg.ny * r * uJitter
        ]);
      }
      brush.set(bName, col, weight);
      brush.spline(pts, 0.3);
    }
  }

  // Intense Specular Secondary-Electron Edge-Glow along Left & Right Rims
  if (tier !== "distant") {
    for (let side of [-1, 1]) {
      let rimCol = side === -1 ? (tier === "fg" ? PAL.specular : PAL.silverBright) : (tier === "fg" ? PAL.silverGlow : PAL.silverMid);
      let passes = tier === "fg" ? 4 : 2;
      for (let p = 0; p < passes; p++) {
        let u = side * (0.985 - p * 0.025);
        let pts = [];
        for (let k = 0; k <= 14; k++) {
          let t = (k / 14) * 0.9;
          let pt = evalBezierPoint(p0, p1, p2, p3, t);
          let tg = evalBezierTangent(p0, p1, p2, p3, t);
          let flare = t > 0.78 ? 1 + 0.2 * Math.pow((t - 0.78) / 0.22, 1.6) : 1.0;
          let r = lerp(r0, r1, t) * flare;
          pts.push([pt.x + tg.nx * r * u, pt.y + tg.ny * r * u]);
        }
        brush.set(p === 0 ? "micro_fibril" : "graphite_sheen", rimCol, p === 0 ? 1.1 : 0.85);
        brush.spline(pts, 0.3);
      }
    }
  }

  // 4. Transverse Stress Cracks, Compression Wrinkles & Surface Scuffs
  if (tier === "fg" || tier === "mid") {
    let numCreases = tier === "fg" ? 28 : 12;
    for (let c = 0; c < numCreases; c++) {
      let t = random(0.12, 0.88);
      let pt = evalBezierPoint(p0, p1, p2, p3, t);
      let tg = evalBezierTangent(p0, p1, p2, p3, t);
      let r = lerp(r0, r1, t);

      let uCenter = random(-0.65, 0.65);
      let uSpan = random(0.18, 0.45);
      let u1 = constrain(uCenter - uSpan * 0.5, -0.95, 0.95);
      let u2 = constrain(uCenter + uSpan * 0.5, -0.95, 0.95);

      let arch = random(-6, 6);
      let pA = [pt.x + tg.nx * r * u1, pt.y + tg.ny * r * u1];
      let pM = [pt.x + tg.nx * r * uCenter + tg.tx * arch, pt.y + tg.ny * r * uCenter + tg.ty * arch];
      let pB = [pt.x + tg.nx * r * u2, pt.y + tg.ny * r * u2];

      // Dark micro-fissure
      brush.set("rotring", PAL.voidBlack, random(0.35, 0.65));
      brush.spline([pA, pM, pB], 0.35);

      // Bright lower lip of the fissure catching electrons
      let lipOffset = 2.2;
      brush.set("micro_fibril", Math.abs(uCenter) > 0.45 ? PAL.silverGlow : PAL.silverMid, random(0.45, 0.8));
      brush.spline([
        [pA[0] - tg.tx * lipOffset, pA[1] - tg.ty * lipOffset],
        [pM[0] - tg.tx * lipOffset, pM[1] - tg.ty * lipOffset],
        [pB[0] - tg.tx * lipOffset, pB[1] - tg.ty * lipOffset]
      ], 0.35);
    }
  }

  // Peeled Nylon Shaving curling off the side of foreground bristles
  if (tier === "fg" && cfg.peelSide) {
    let side = cfg.peelSide;
    let tBase = random(0.42, 0.62);
    let pt = evalBezierPoint(p0, p1, p2, p3, tBase);
    let tg = evalBezierTangent(p0, p1, p2, p3, tBase);
    let r = lerp(r0, r1, tBase);
    let bx = pt.x + tg.nx * r * side * 0.92;
    let by = pt.y + tg.ny * r * side * 0.92;

    let curl1 = [bx + tg.nx * side * 22 + tg.tx * 28, by + tg.ny * side * 22 + tg.ty * 28];
    let curl2 = [bx + tg.nx * side * 48 + tg.tx * 12, by + tg.ny * side * 48 + tg.ty * 12];
    let curl3 = [bx + tg.nx * side * 36 - tg.tx * 18, by + tg.ny * side * 36 - tg.ty * 18];

    // Dark underside of peeled ribbon
    brush.set("charcoal_stick", PAL.inkBlack, 0.9);
    brush.spline([[bx, by], curl1, curl2], 0.45);
    // Glowing silver edge of peeled nylon strip
    brush.set("graphite_sheen", PAL.silverGlow, 1.1);
    brush.spline([[bx, by - 2], [curl1[0], curl1[1] - 3], [curl2[0], curl2[1] - 2], curl3], 0.5);
    brush.set("micro_fibril", PAL.specular, 0.95);
    brush.spline([[bx, by - 3], [curl1[0], curl1[1] - 4], [curl2[0], curl2[1] - 3], curl3], 0.5);
  }

  // 5. Splayed, Frayed, Split Crown at the Tip (t = 0.80 .. 1.0+)
  drawFrayedBristleCrown(cfg, tier);
}

function drawFrayedBristleCrown(cfg, tier) {
  const { p0, p1, p2, p3, r1, fog } = cfg;
  let ptBase = evalBezierPoint(p0, p1, p2, p3, 0.84);
  let ptTop  = evalBezierPoint(p0, p1, p2, p3, 1.0);
  let tg     = evalBezierTangent(p0, p1, p2, p3, 0.95);
  let tipR   = r1 * 1.18;

  // Deep dark cleavage canyons where the worn bristle tip splits apart
  let clefts = cfg.clefts || [-0.35, 0.05, 0.42];
  for (let cU of clefts) {
    let depth = tier === "fg" ? random(65, 135) : random(35, 75);
    let widthCleft = tier === "fg" ? random(10, 22) : random(6, 12);

    let tipX = ptTop.x + tg.nx * tipR * cU;
    let tipY = ptTop.y + tg.ny * tipR * cU;
    let rootX = tipX - tg.tx * depth + tg.nx * random(-8, 8);
    let rootY = tipY - tg.ty * depth + tg.ny * random(-8, 8);

    // Dark V-canyon interior
    brush.noStroke();
    brush.wash(tier === "distant" ? PAL.charcoalMid : PAL.voidBlack, tier === "distant" ? 150 : 240);
    drawFilledPoly([
      [tipX - tg.nx * widthCleft, tipY - tg.ny * widthCleft],
      [rootX, rootY],
      [tipX + tg.nx * widthCleft, tipY + tg.ny * widthCleft]
    ], 0.1);
    brush.noWash();

    // Glowing silver edges along the walls of the split canyon
    if (tier !== "distant") {
      let edgeCol = tier === "fg" ? PAL.silverGlow : PAL.silverMid;
      brush.set("graphite_sheen", edgeCol, tier === "fg" ? 1.0 : 0.7);
      brush.spline([
        [rootX, rootY],
        [(rootX + tipX) * 0.5 - tg.nx * widthCleft * 0.55, (rootY + tipY) * 0.5 - tg.ny * widthCleft * 0.55],
        [tipX - tg.nx * widthCleft, tipY - tg.ny * widthCleft]
      ], 0.3);
      brush.spline([
        [rootX, rootY],
        [(rootX + tipX) * 0.5 + tg.nx * widthCleft * 0.55, (rootY + tipY) * 0.5 + tg.ny * widthCleft * 0.55],
        [tipX + tg.nx * widthCleft, tipY + tg.ny * widthCleft]
      ], 0.3);
    }
  }

  // Individual frayed prongs, split ribbons, and curling micro-fibrils
  let numProngs = tier === "fg" ? 16 : (tier === "mid" ? 10 : 5);
  for (let i = 0; i < numProngs; i++) {
    let u = map(i, 0, numProngs - 1, -0.96, 0.96) + random(-0.05, 0.05);
    let startT = random(0.83, 0.94);
    let pStart = evalBezierPoint(p0, p1, p2, p3, startT);
    let sx = pStart.x + tg.nx * tipR * u * 0.9;
    let sy = pStart.y + tg.ny * tipR * u * 0.9;

    // Outward splay of each split prong
    let splayAngle = u * random(24, 52) + random(-10, 10);
    let prongLen = (tier === "fg" ? random(55, 130) : random(30, 75)) * (1 - 0.25 * Math.abs(u));
    let baseAngle = atan2(tg.ty, tg.tx);

    let a1 = baseAngle + splayAngle * 0.45;
    let a2 = baseAngle + splayAngle;
    let a3 = a2 + (u >= 0 ? 1 : -1) * random(12, 48);

    let m1 = [sx + cos(a1) * prongLen * 0.4, sy + sin(a1) * prongLen * 0.4];
    let m2 = [m1[0] + cos(a2) * prongLen * 0.4, m1[1] + sin(a2) * prongLen * 0.4];
    let m3 = [m2[0] + cos(a3) * prongLen * 0.3, m2[1] + sin(a3) * prongLen * 0.3];

    let prongWidth = tier === "fg" ? random(6, 14) : random(4, 8);
    let nx = -sin(a2);
    let ny = cos(a2);

    // Prong dark core
    brush.set("charcoal_stick", tier === "distant" ? PAL.taupeMid : PAL.charcoalDeep, tier === "fg" ? 1.1 : 0.7);
    brush.spline([[sx, sy], m1, m2], 0.35);

    // Prong glowing SEM edges (thin structures in SEM glow brightly on both sides)
    let glowCol = tier === "distant" ? PAL.silverDim : (tier === "mid" ? PAL.silverBright : PAL.silverGlow);
    brush.set(tier === "fg" ? "graphite_sheen" : "2H", glowCol, tier === "fg" ? 0.95 : 0.65);
    brush.spline([
      [sx - nx * prongWidth * 0.5, sy - ny * prongWidth * 0.5],
      [m1[0] - nx * prongWidth * 0.35, m1[1] - ny * prongWidth * 0.35],
      [m2[0] - nx * prongWidth * 0.15, m2[1] - ny * prongWidth * 0.15],
      m3
    ], 0.4);
    brush.spline([
      [sx + nx * prongWidth * 0.5, sy + ny * prongWidth * 0.5],
      [m1[0] + nx * prongWidth * 0.35, m1[1] + ny * prongWidth * 0.35],
      [m2[0] + nx * prongWidth * 0.15, m2[1] + ny * prongWidth * 0.15],
      m3
    ], 0.4);

    // Razor-bright curling micro-fibrils at the split tip
    if (tier !== "distant") {
      let subFibs = tier === "fg" ? 3 : 1;
      for (let f = 0; f < subFibs; f++) {
        let curlDir = random([-1, 1]);
        let fLen = tier === "fg" ? random(22, 58) : random(14, 30);
        let fa1 = a2 + curlDir * random(15, 45);
        let fa2 = fa1 + curlDir * random(25, 75);
        let fPt1 = [m2[0] + cos(fa1) * fLen * 0.55, m2[1] + sin(fa1) * fLen * 0.55];
        let fPt2 = [fPt1[0] + cos(fa2) * fLen * 0.55, fPt1[1] + sin(fa2) * fLen * 0.55];

        brush.set("micro_fibril", tier === "fg" ? PAL.specular : PAL.silverBright, random(0.65, 1.15));
        brush.spline([m1, m2, fPt1, fPt2], 0.45);
      }
    }
  }

  // Soft silver-graphite halo smudge around the frayed crown (secondary electron bloom)
  if (tier === "fg") {
    brush.set("velvet_smudge", PAL.silverMid, 1.8);
    brush.spline([
      [ptTop.x - tg.nx * tipR * 0.9, ptTop.y - tg.ny * tipR * 0.9],
      [ptTop.x + tg.tx * 35, ptTop.y + tg.ty * 35],
      [ptTop.x + tg.nx * tipR * 0.9, ptTop.y + tg.ny * tipR * 0.9]
    ], 0.4);
  }
}

// ============================================================================
// 4 & 6. CRATERED TOOTHPASTE LANDSCAPE & VISCOUS MENISCUS BRIDGES
// ============================================================================

function renderPasteUnderlay() {
  // Deep background paste masses clinging between midground bristles
  brush.noStroke();
  brush.wash(PAL.charcoalDeep, 220);
  drawFilledPoly([
    [-30, 760], [180, 710], [380, 750], [560, 690],
    [790, 740], [1020, 710], [1230, 770], [1230, 1230], [-30, 1230]
  ], 0.25);
  brush.noWash();

  // Midground viscous bridges between columns
  drawViscousBridge(145, 690, 385, 660, 75, 45, 0.25);
  drawViscousBridge(535, 680, 760, 700, 65, 40, 0.20);
  drawViscousBridge(815, 720, 1020, 740, 70, 42, 0.22);
}

function drawViscousBridge(x1, y1, x2, y2, sagTop, sagBot, fog = 0) {
  let mx = (x1 + x2) * 0.5;
  let myTop = (y1 + y2) * 0.5 + sagTop;
  let myBot = (y1 + y2) * 0.5 + sagTop + sagBot;

  let bridgePts = [
    [x1, y1 - 35],
    [lerp(x1, mx, 0.5), lerp(y1 - 35, myTop, 0.75)],
    [mx, myTop],
    [lerp(x2, mx, 0.5), lerp(y2 - 35, myTop, 0.75)],
    [x2, y2 - 35],
    [x2, y2 + 55],
    [lerp(x2, mx, 0.5), lerp(y2 + 55, myBot, 0.75)],
    [mx, myBot],
    [lerp(x1, mx, 0.5), lerp(y1 + 55, myBot, 0.75)],
    [x1, y1 + 55]
  ];

  // Solid dark paste body
  brush.noStroke();
  brush.wash(PAL.inkBlack, 240);
  drawFilledPoly(bridgePts, 0.35);
  brush.noWash();

  // Velvety shading along the stretched meniscus
  for (let i = 0; i < 12; i++) {
    let f = i / 11;
    let sy1 = lerp(y1 - 32, y1 + 50, f);
    let sy2 = lerp(y2 - 32, y2 + 50, f);
    let smy = lerp(myTop + 3, myBot - 3, f);
    let edgeDist = Math.abs(f - 0.5) * 2;
    let col = semToneColor(edgeDist * 0.92, fog);
    brush.set("velvet_smudge", col, 1.3);
    brush.spline([[x1, sy1], [mx, smy], [x2, sy2]], 0.4);
  }

  // Glowing silver catenary rims (top and bottom stretched edges)
  let rimCol = fog > 0.15 ? PAL.silverMid : PAL.silverGlow;
  brush.set("graphite_sheen", rimCol, 1.1);
  brush.spline([[x1, y1 - 34], [mx, myTop], [x2, y2 - 34]], 0.4);
  brush.set("micro_fibril", fog > 0.15 ? PAL.silverBright : PAL.specular, 0.95);
  brush.spline([[x1, y1 - 35], [mx, myTop - 1.5], [x2, y2 - 35]], 0.4);

  brush.set("graphite_sheen", PAL.silverMid, 0.9);
  brush.spline([[x1, y1 + 53], [mx, myBot], [x2, y2 + 53]], 0.4);
}

function renderCrateredPasteLandscape() {
  // 1. Hero Viscous Meniscus Bridge stretching between the two central foreground bristles
  drawViscousBridge(395, 650, 775, 680, 92, 95, 0.0);

  // Secondary lower stretched web on the left & right
  drawViscousBridge(165, 790, 405, 770, 68, 85, 0.05);
  drawViscousBridge(760, 800, 975, 820, 74, 90, 0.05);

  // 2. Main Foreground Cratered Paste Continent (y = 780 .. 1200)
  // Built from overlapping amorphous mounds with glowing top ridges and dark valleys
  const mounds = [
    {
      pts: [
        [-40, 860], [90, 810], [230, 825], [375, 765], [520, 815],
        [670, 790], [835, 775], [990, 830], [1120, 805], [1240, 850],
        [1240, 1240], [-40, 1240]
      ],
      col: PAL.inkBlack
    },
    {
      pts: [
        [-40, 950], [140, 895], [310, 920], [490, 865], [660, 890],
        [840, 855], [1010, 910], [1240, 890], [1240, 1240], [-40, 1240]
      ],
      col: PAL.voidBlack
    },
    {
      pts: [
        [180, 1020], [390, 965], [590, 985], [790, 945], [980, 995],
        [1240, 975], [1240, 1240], [-40, 1240], [-40, 1035]
      ],
      col: PAL.inkBlack
    }
  ];

  for (let m of mounds) {
    brush.noStroke();
    brush.wash(m.col, 245);
    drawFilledPoly(m.pts, 0.3);
    brush.noWash();

    // Charcoal mass inside the deep paste slab
    brush.mass("charcoal", PAL.charcoalDeep, {
      precision: 0.5,
      strength: 0.65,
      gradient: 0.3,
      outline: false
    });
    drawFilledPoly(m.pts, 0.3);
    brush.noMass();

    // Glowing SEM ridge along the upper crest of each paste fold
    let crest = m.pts.slice(0, m.pts.length - 2);
    brush.set("velvet_smudge", PAL.taupeMid, 2.2);
    brush.spline(crest, 0.35);
    brush.set("velvet_smudge", PAL.silverDim, 1.3);
    brush.spline(crest, 0.35);
    brush.set("graphite_sheen", PAL.silverBright, 1.0);
    brush.spline(crest, 0.35);
  }

  // 3. Undulating Topographic Ridges & Flow Contours across the Paste
  for (let r = 0; r < 65; r++) {
    let baseY = map(r, 0, 64, 785, 1185);
    let xStart = random(-30, 850);
    let span = random(180, 480);
    let pts = [];
    for (let k = 0; k <= 6; k++) {
      let x = xStart + (k / 6) * span;
      let y = baseY + (noise(x * 0.004, baseY * 0.006) - 0.5) * 95;
      pts.push([x, y]);
    }
    let isCrest = r % 3 === 0;
    brush.set(
      isCrest ? "graphite_sheen" : "velvet_smudge",
      isCrest ? random([PAL.silverMid, PAL.silverDim, PAL.taupeMid]) : random([PAL.charcoalDark, PAL.charcoalMid, PAL.inkBlack]),
      isCrest ? random(0.6, 1.2) : random(1.1, 2.2)
    );
    brush.spline(pts, 0.4);
  }

  // 4. SEM Craters, Ruptured Vesicles & Pores
