function drawSEMCrater(c) {
  const { x, y, rx, ry, rot, rimGlow } = c;
  let ca = cos(rot);
  let sa = sin(rot);

  function toWorld(lx, ly) {
    return [x + lx * ca - ly * sa, y + lx * sa + ly * ca];
  }

  // Outer raised slope & inner pit polygon points
  let pitPts = [];
  let rimPts = [];
  let steps = 20;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let n = 0.88 + 0.24 * noise(x * 0.02 + cos(a) * 1.3, y * 0.02 + sin(a) * 1.3);
    pitPts.push(toWorld(cos(a) * rx * 0.82 * n, sin(a) * ry * 0.82 * n));
    rimPts.push(toWorld(cos(a) * rx * n, sin(a) * ry * n));
  }

  // 1. Deep Inky Black Pit Recess
  brush.noStroke();
  brush.wash(PAL.voidBlack, 250);
  drawFilledPoly(pitPts, 0.28);
  brush.noWash();

  // Inner shadow wall hatching on the upper steep drop-off inside the crater
  if (rx > 22) {
    let numShade = Math.floor(rx * 0.45);
    for (let i = 0; i < numShade; i++) {
      let a = map(i, 0, numShade - 1, 190, 350);
      let p1 = toWorld(cos(a) * rx * 0.82, sin(a) * ry * 0.82);
      let p2 = toWorld(cos(a) * rx * 0.35, sin(a) * ry * 0.35 + ry * 0.15);
      brush.set("charcoal_stick", PAL.charcoalDeep, 0.65);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // 2. Soft Silver-Taupe Outer Flank Smudge around the Raised Lip
  brush.set("velvet_smudge", PAL.taupeMid, map(rx, 10, 85, 0.7, 1.9));
  brush.spline(rimPts.concat([rimPts[0]]), 0.35);

  // 3. Glowing SEM Rim (Brightest on the upper-left and lower-right sharp ridges)
  // Draw tangential glowing arcs around the crater lip
  let arcPasses = rx > 30 ? 4 : 2;
  for (let p = 0; p < arcPasses; p++) {
    let scaleR = 0.84 + (p / arcPasses) * 0.22;
    let segPts = [];
    for (let i = 0; i <= steps; i++) {
      let idx = i % steps;
      let a = (idx / steps) * 360;
      let n = 0.88 + 0.24 * noise(x * 0.02 + cos(a) * 1.3, y * 0.02 + sin(a) * 1.3);
      segPts.push(toWorld(cos(a) * rx * scaleR * n, sin(a) * ry * scaleR * n));
    }

    let col = p === 0 ? PAL.silverGlow : (p === 1 ? PAL.silverBright : PAL.silverMid);
    let bName = p <= 1 ? "graphite_sheen" : "HB";
    brush.set(bName, col, map(rx, 10, 85, 0.5, 1.15) * (1 - p * 0.18));
    brush.spline(segPts, 0.35);
  }

  // Intense Specular Hotspot on the sharp North-West & South-East lip crests
  if (rimGlow > 0.82) {
    let hotArc1 = [];
    for (let a = 195; a <= 335; a += 18) {
      let n = 0.88 + 0.24 * noise(x * 0.02 + cos(a) * 1.3, y * 0.02 + sin(a) * 1.3);
      hotArc1.push(toWorld(cos(a) * rx * 0.87 * n, sin(a) * ry * 0.87 * n));
    }
    brush.set("micro_fibril", PAL.specular, map(rx, 10, 85, 0.65, 1.25));
    brush.spline(hotArc1, 0.35);

    let hotArc2 = [];
    for (let a = 15; a <= 145; a += 18) {
      let n = 0.88 + 0.24 * noise(x * 0.02 + cos(a) * 1.3, y * 0.02 + sin(a) * 1.3);
      hotArc2.push(toWorld(cos(a) * rx * 0.90 * n, sin(a) * ry * 0.90 * n));
    }
    brush.set("micro_fibril", PAL.silverGlow, map(rx, 10, 85, 0.55, 1.05));
    brush.spline(hotArc2, 0.35);
  }

  // 4. Radial Desiccation Micro-Cracks & Ejecta Ridges on Larger Craters
  if (rx > 35) {
    let cracks = Math.floor(random(4, 9));
    for (let k = 0; k < cracks; k++) {
      let a = random(360);
      let pStart = toWorld(cos(a) * rx * 0.9, sin(a) * ry * 0.9);
      let pMid = toWorld(cos(a + random(-12, 12)) * rx * 1.25, sin(a + random(-12, 12)) * ry * 1.25);
      let pEnd = toWorld(cos(a + random(-20, 20)) * rx * 1.55, sin(a + random(-20, 20)) * ry * 1.55);

      brush.set("rotring", PAL.voidBlack, 0.45);
      brush.spline([pStart, pMid, pEnd], 0.3);
      brush.set("micro_fibril", PAL.silverBright, 0.6);
      brush.spline([[pStart[0] + 1.5, pStart[1] + 1.5], [pMid[0] + 1.5, pMid[1] + 1.5], pEnd], 0.3);
    }
  }
}

function drawSilicaAggregate(cx, cy, rad) {
  // Amorphous crystalline toothpaste cluster clinging to a bristle shaft
  let blobs = Math.floor(random(4, 8));
  for (let i = 0; i < blobs; i++) {
    let ox = cx + random(-rad * 0.6, rad * 0.6);
    let oy = cy + random(-rad * 0.6, rad * 0.6);
    let br = random(rad * 0.35, rad * 0.75);

    let pts = [];
    for (let a = 0; a < 360; a += 45) {
      let r = br * random(0.75, 1.25);
      pts.push([ox + cos(a) * r, oy + sin(a) * r * 0.85]);
    }

    // Dark core of silica granule
    brush.noStroke();
    brush.wash(PAL.charcoalDeep, 230);
    drawFilledPoly(pts, 0.2);
    brush.noWash();

    // Bright angular SEM edge-glow around the granule facets
    brush.set("graphite_sheen", PAL.silverBright, 0.8);
    brush.spline(pts.concat([pts[0]]), 0.2);
    brush.set("micro_fibril", PAL.specular, 0.75);
    brush.spline(pts.slice(0, 5), 0.2);
  }
}

