function renderScaleBarStrip() {
  // Subtle recessed SEM corner strip in the bottom-right corner
  const sx = 935;
  const sy = 1112;
  const sw = 195;
  const sh = 34;

  // Recessed velvety dark strip ground
  brush.noStroke();
  brush.wash(PAL.voidBlack, 215);
  drawFilledPoly([
    [sx, sy],
    [sx + sw, sy],
    [sx + sw, sy + sh],
    [sx, sy + sh]
  ], 0.02);
  brush.noWash();

  // Thin pen frame around the corner strip
  brush.set("rotring", PAL.silverMid, 0.42);
  brush.line(sx, sy, sx + sw, sy);
  brush.line(sx + sw, sy, sx + sw, sy + sh);
  brush.line(sx + sw, sy + sh, sx, sy + sh);
  brush.line(sx, sy + sh, sx, sy);

  // Crisp thin pen scale bar inside the strip (with tick marks, no numbers)
  const barX1 = sx + 28;
  const barX2 = sx + sw - 28;
  const barY  = sy + sh * 0.52;

  brush.set("rotring", PAL.silverGlow, 0.6);
  brush.line(barX1, barY, barX2, barY);

  // End ticks and intermediate subdivision ticks (10 divisions, no numbers)
  const divisions = 10;
  for (let i = 0; i <= divisions; i++) {
    let tx = lerp(barX1, barX2, i / divisions);
    let tickHalf = (i === 0 || i === divisions) ? 6.5 : (i === 5 ? 4.5 : 2.6);
    brush.set("rotring", PAL.silverGlow, (i === 0 || i === divisions) ? 0.58 : 0.42);
    brush.line(tx, barY - tickHalf, tx, barY + tickHalf);
  }
}

// Hyperrealist Graphite & Constructivist Marker Photomontage
// A worker's calloused hand gripping a cordless power drill

const SEED = 48291;

// Drill coordinate frame origin and angle (steep diagonal thrust up-right)
const O_X = 465;
const O_Y = 500;
const THETA = -43; // degrees
let UX, UY, VX, VY;

// Transform from drill-local (u along barrel, v perpendicular down-right) to canvas (x, y)
function B(u, v) {
  return [O_X + u * UX + v * VX, O_Y + u * UY + v * VY];
}

// Helper to draw a closed or open shape from an array of [x, y] points
function drawShapePts(pts, curvature = 0, closed = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

// Interpolate between two 2D points
function lerpPt(p1, p2, t) {
  return [p1[0] + (p2[0] - p1[0]) * t, p1[1] + (p2[1] - p1[1]) * t];
}

// Offset an array of points by (dx, dy)
function offsetPts(pts, dx, dy) {
  return pts.map((p) => [p[0] + dx, p[1] + dy]);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  UX = cos(THETA);
  UY = sin(THETA);
  VX = -sin(THETA);
  VY = cos(THETA);

  // Custom chisel-tip marker for flat constructivist graphic wedges
  brush.add("chisel_marker", {
    type: "custom",
    weight: 6.5,
    scatter: 0.04,
    opacity: 65,
    spacing: 0.28,
    pressure: [0.95, 1.0, 0.95],
    tip: (_m) => {
      _m.rotate(-35);
      _m.rect(-2.4, -0.7, 4.8, 1.4);
    },
    rotate: "none",
    markerTip: true,
    noise: 0.15
  });

  // Custom soft graphite shader for smooth photographic tone gradations
  brush.add("graphite_soft", {
    type: "default",
    weight: 2.2,
    scatter: 0.65,
    sharpness: 0.22,
    grain: 14,
    opacity: 38,
    spacing: 0.35,
    pressure: [0.3, 1.1, 0.25],
    noise: 0.5
  });

  // Custom sharp mechanical graphite for pores, creases, and fine metal/plastic detail
  brush.add("graphite_needle", {
    type: "default",
    weight: 0.55,
    scatter: 0.08,
    sharpness: 0.88,
    grain: 6,
    opacity: 145,
    spacing: 0.2,
    pressure: [0.4, 1.0, 0.3],
    noise: 0.35
  });

  // Custom opaque white chalk/gouache pencil for sweaty sheen & plastic scratches
  brush.add("white_chalk", {
    type: "default",
    weight: 0.8,
    scatter: 0.12,
    sharpness: 0.78,
    grain: 9,
    opacity: 175,
    spacing: 0.22,
    pressure: [0.2, 1.0, 0.2],
    noise: 0.3
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. AGED EARTH-TONE PAPER GROUND
  drawPaperGround();

  // 2. CONSTRUCTIVIST FLAT MARKER PLANES & BLOCKY FAUX-LETTERING BAR
  drawConstructivistPlanes();
  drawBlockyFauxLetteringBar();

  // 3. PHOTOMONTAGE SCISSOR-CUT SILHOUETTE BACKING
  drawPhotomontageCutoutBacking();

  // 4. CORDLESS POWER DRILL IN PHOTOGRAPHIC GRAPHITE
  drawCordlessDrill();

  // 5. WORKER'S CALLOUSED HAND IN PHOTOGRAPHIC GRAPHITE
  drawWorkersHand();

  // 6. SPIRALING METAL SHAVINGS (SWARF) FROM DRILL BIT
  drawMetalShavings();

  // 7. FINAL PHOTOMONTAGE CUT-EDGE DEFINITION & SURFACE GRIT
  drawFinalCutoutEdgeAndGrit();

  noLoop();
}

