function drawPaperGround() {
  background("#ded4be");

  brush.noStroke();
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.45, 0.2);

  // Warm muted earth undertone washes
  brush.fill("#d2c4a8", 55);
  brush.rect(40, 40, 1120, 1120, "corner");

  brush.fill("#c7b697", 40);
  brush.circle(260, 960, 420, 0.3);
  brush.circle(980, 240, 360, 0.3);

  brush.noFill();

  // Fine woven paper tooth across sheet
  brush.hatchStyle("2H", "#c5b89e", 0.45);
  brush.hatch(14, 12, { rand: 0.12 });
  brush.rect(20, 20, 1160, 1160, "corner");
  brush.noHatch();

  // Subtle vintage sheet border rule
  brush.set("2H", "#9e927c", 0.55);
  brush.line(34, 34, 1166, 34);
  brush.line(1166, 34, 1166, 1166);
  brush.line(1166, 1166, 34, 1166);
  brush.line(34, 1166, 34, 34);
}

// =============================================================================
// 2. CONSTRUCTIVIST MARKER PLANES & FAUX-LETTERING
// =============================================================================
function fillMarkerPolygon(pts, baseHex, streakHex, hatchAngle, spacing = 5.5) {
  // Flat opaque base wash
  brush.noStroke();
  brush.wash(baseHex, 235);
  drawShapePts(pts, 0, true);
  brush.noWash();

  // Dense directional felt-marker streaks inside plane
  brush.hatchStyle("chisel_marker", streakHex, 1.05);
  brush.hatch(spacing, hatchAngle, { rand: 0.015, continuous: true });
  drawShapePts(pts, 0, true);
  brush.noHatch();

  // Crisp ruled marker edge
  brush.set("marker", streakHex, 0.75);
  drawShapePts(pts, 0, true);
  brush.noStroke();
}

