// 4. CORDLESS POWER DRILL (Photographic Graphite & Scuffed Plastic)
// =============================================================================
function shadeDrillCylinderBand(uStart, uEnd, vTopStart, vTopEnd, vBotStart, vBotEnd, steps = 42) {
  // Cylindrical shading profile along the barrel axis (u) across perpendicular radius (v)
  for (let i = 0; i <= steps; i++) {
    const t = i / steps; // 0 = top edge, 1 = bottom edge
    const v0 = lerp(vTopStart, vBotStart, t);
    const v1 = lerp(vTopEnd, vBotEnd, t);
    const p0 = B(uStart, v0);
    const p1 = B(uEnd, v1);

    // Specular band sits near t = 0.24, core shadow near t = 0.78, reflected light near t = 0.94
    let col, w, bName;
    if (t < 0.12) {
      col = "#4a4742";
      w = 0.75;
      bName = "HB";
    } else if (t < 0.30) {
      col = "#d8d3c8";
      w = 0.65;
      bName = "2H";
    } else if (t < 0.52) {
      col = "#6e6a63";
      w = 0.85;
      bName = "HB";
    } else if (t < 0.84) {
      col = "#22201e";
      w = 1.1;
      bName = "2B";
    } else {
      col = "#45423d";
      w = 0.85;
      bName = "HB";
    }

    brush.set(bName, col, w);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // Cross-contour curved cylindrical rings to give 3D volume
  const numRings = floor((uEnd - uStart) / 9);
  for (let j = 0; j <= numRings; j++) {
    const s = j / max(1, numRings);
    const u = lerp(uStart, uEnd, s);
    const vt = lerp(vTopStart, vTopEnd, s);
    const vb = lerp(vBotStart, vBotEnd, s);
    const bulge = (vb - vt) * 0.14;

    const ringPts = [
      B(u, vt),
      B(u + bulge * 0.6, lerp(vt, vb, 0.28)),
      B(u + bulge, lerp(vt, vb, 0.55)),
      B(u + bulge * 0.6, lerp(vt, vb, 0.82)),
      B(u, vb)
    ];
    brush.set("2H", j % 3 === 0 ? "#2b2926" : "#59554f", 0.5);
    brush.spline(ringPts, 0.5);
  }
}

