    brush.wash("#161513", 230);
    drawShapePts(ribPts, 0, true);
    brush.noWash();
    brush.set("white_chalk", "#9e988c", 0.65);
    brush.line(...B(uRib + 16, 340), ...B(uRib + 14, 444));
  }

  // Battery release latch & LED fuel gauge window on front of battery
  const latchPts = [
    B(-15, 324),
    B(48, 324),
    B(45, 352),
    B(-18, 352)
  ];
  brush.noStroke();
  brush.wash("#4f4b44", 235);
  drawShapePts(latchPts, 0, true);
  brush.noWash();
  for (let g = 0; g < 4; g++) {
    brush.set("2B", "#141311", 0.8);
    brush.line(...B(-10, 330 + g * 5), ...B(42, 330 + g * 5));
  }

  // --- F. SCUFFED PLASTIC TEXTURE, GOUGES & GRIME ON DRILL & BATTERY ---
  // Erratic job-site scratches, white stress-marks, and abraded edges
  for (let i = 0; i < 95; i++) {
    const onBattery = random() < 0.35;
    const u0 = onBattery ? random(-175, 60) : random(-220, 140);
    const v0 = onBattery ? random(328, 445) : random(-80, 78);
    const len = random(8, 36);
    const ang = THETA + random(-55, 55);
    const pStart = B(u0, v0);
    const pEnd = [pStart[0] + cos(ang) * len, pStart[1] + sin(ang) * len];

    // Dark gouge trough paired with bright scuffed plastic lip
    brush.set("graphite_needle", "#1a1816", random(0.4, 0.85));
    brush.line(pStart[0], pStart[1], pEnd[0], pEnd[1]);
    brush.set("white_chalk", "#eae5d8", random(0.35, 0.75));
    brush.line(pStart[0] + 1.2, pStart[1] + 1.2, pEnd[0] + 1.2, pEnd[1] + 1.2);
  }

  // Fine charcoal & spray grime in housing seams
  brush.set("spray", "#181715", 0.45);
  brush.line(...B(-175, -82), ...B(-175, 82));
  brush.line(...B(70, -78), ...B(70, 78));
  brush.line(...B(-160, 322), ...B(65, 322));
}

// =============================================================================
// 5. WORKER'S CALLOUSED HAND (Photographic Graphite, Knuckle Grime & Sweat)
// =============================================================================
function drawShadedLimbPolygon(pts, baseCol, hatchAng1, hatchAng2, spinePts, radiusApprox) {
  // Base tonal graphite wash
  brush.noStroke();
  brush.wash(baseCol, 240);
  drawShapePts(pts, 0.12, true);
  brush.noWash();

  // Cross-hatching for dense photographic graphite grain
  brush.hatchStyle("HB", "#5e5951", 0.65);
  brush.hatch(4.5, hatchAng1, { rand: 0.08 });
  drawShapePts(pts, 0.12, true);
  brush.noHatch();

  brush.hatchStyle("2H", "#7d776d", 0.55);
  brush.hatch(5.5, hatchAng2, { rand: 0.08 });
  drawShapePts(pts, 0.12, true);
  brush.noHatch();

  // Form-wrapping cross-contour shading along the bone spine
  if (spinePts && spinePts.length >= 2) {
    for (let s = 0; s < spinePts.length - 1; s++) {
      const pA = spinePts[s];
      const pB = spinePts[s + 1];
      const dx = pB[0] - pA[0];
      const dy = pB[1] - pA[1];
      const segLen = sqrt(dx * dx + dy * dy);
      const nx = -dy / max(1, segLen);
      const ny = dx / max(1, segLen);

      const steps = max(8, floor(segLen / 3.8));
      for (let i = 0; i <= steps; i++) {
        const t = i / steps;
        const cx = lerp(pA[0], pB[0], t);
        const cy = lerp(pA[1], pB[1], t);
        const r = radiusApprox;

        // Core shadow on lower/underside (+n), bright highlight on upper/dorsal side (-n)
        const pTop = [cx - nx * r * 0.92, cy - ny * r * 0.92];
        const pMidTop = [cx - nx * r * 0.35 + dx * 0.06, cy - ny * r * 0.35 + dy * 0.06];
        const pMidBot = [cx + nx * r * 0.4 + dx * 0.06, cy + ny * r * 0.4 + dy * 0.06];
        const pBot = [cx + nx * r * 0.95, cy + ny * r * 0.95];

        // Dark core shadow wrap on underside
        brush.set("2B", "#2b2824", 0.75);
        brush.spline([pMidBot, pBot], 0.4);

        // Midtone graphite wrap
        brush.set("HB", "#544f48", 0.6);
        brush.spline([pTop, pMidTop, pMidBot], 0.4);

        // Bright dorsal skin highlight
        brush.set("white_chalk", "#ece7da", 0.65);
        brush.line(
          cx - nx * r * 0.65,
          cy - ny * r * 0.65,
          cx - nx * r * 0.15,
          cy - ny * r * 0.15
        );
      }
    }
  }
}

function drawKnuckleGrimeCreases(centerPt, axisAngle, widthR, count = 6) {
  // Concentric oval skin folds packed with dark work grime and sweat highlights on the ridges
  const ux = cos(axisAngle);
  const uy = sin(axisAngle);
  const vx = -sin(axisAngle);
  const vy = cos(axisAngle);

  for (let i = -count; i <= count; i++) {
    const offsetAlong = i * 2.6;
    const spread = widthR * (1 - abs(i) / (count + 2.5));
    const arch = (i < 0 ? -1 : 1) * (1.8 + abs(i) * 0.7);

    const pLeft = [
      centerPt[0] + offsetAlong * ux - spread * vx,
      centerPt[1] + offsetAlong * uy - spread * vy
    ];
    const pMid = [
      centerPt[0] + (offsetAlong + arch) * ux + random(-0.8, 0.8),
      centerPt[1] + (offsetAlong + arch) * uy + random(-0.8, 0.8)
    ];
    const pRight = [
      centerPt[0] + offsetAlong * ux + spread * vx,
      centerPt[1] + offsetAlong * uy + spread * vy
    ];

    // Deep grime-filled crease line
    brush.set("graphite_needle", i % 2 === 0 ? "#141311" : "#2e2b27", random(0.65, 1.05));
    brush.spline([pLeft, pMid, pRight], 0.45);

    // Sweaty skin ridge highlight right next to crease
    if (abs(i) <= 3) {
      brush.set("white_chalk", "#f5f0e4", 0.55);
      brush.line(pLeft[0] + ux * 1.3, pLeft[1] + uy * 1.3, pRight[0] + ux * 1.3, pRight[1] + uy * 1.3);
    }
  }
}

