// =============================================================================
// 6. SPIRALING METAL SHAVINGS (SWARF) FROM THE DRILL BIT
// =============================================================================
function drawHelicalSwarf(startX, startY, dirAngle, totalLen, turns, widthRibbon, scaleTaper = 1.0) {
  const ux = cos(dirAngle);
  const uy = sin(dirAngle);
  const vx = -sin(dirAngle);
  const vy = cos(dirAngle);

  const steps = turns * 16;
  for (let i = 0; i < steps; i++) {
    const t0 = i / steps;
    const t1 = (i + 1) / steps;
    const phase0 = t0 * turns * 360;
    const phase1 = t1 * turns * 360;

    const amp0 = (4 + t0 * 14) * scaleTaper;
    const amp1 = (4 + t1 * 14) * scaleTaper;

    const x0 = startX + t0 * totalLen * ux + sin(phase0) * amp0 * vx;
    const y0 = startY + t0 * totalLen * uy + sin(phase0) * amp0 * vy;
    const x1 = startX + t1 * totalLen * ux + sin(phase1) * amp1 * vx;
    const y1 = startY + t1 * totalLen * uy + sin(phase1) * amp1 * vy;

    const w = widthRibbon * (1 - t0 * 0.35);
    const segQuad = [
      [x0 - vx * w * 0.5, y0 - vy * w * 0.5],
      [x1 - vx * w * 0.5, y1 - vy * w * 0.5],
      [x1 + vx * w * 0.5, y1 + vy * w * 0.5],
      [x0 + vx * w * 0.5, y0 + vy * w * 0.5]
    ];

    // Alternate between bright chrome outer curl and dark inner steel shadow
    const cVal = cos(phase0);
    const fillHex = cVal > 0.35 ? "#f5f1e4" : cVal > -0.2 ? "#857f73" : "#181715";

    brush.noStroke();
    brush.wash(fillHex, 245);
    drawShapePts(segQuad, 0, true);
    brush.noWash();

    // Crisp metallic serrated edges on each spiral loop
    brush.set("graphite_needle", "#11100f", 0.75);
    brush.line(segQuad[0][0], segQuad[0][1], segQuad[1][0], segQuad[1][1]);
    brush.line(segQuad[3][0], segQuad[3][1], segQuad[2][0], segQuad[2][1]);

    if (cVal > 0.2) {
      brush.set("white_chalk", "#ffffff", 0.85);
      brush.line(x0, y0, x1, y1);
    }
  }
}

function drawMetalShavings() {
  const tip = B(556, 0);
  const midBit = B(465, -6);
  const lowBit = B(395, 7);

  // Long helical ribbons corkscrewing off the spinning drill bit flutes
  drawHelicalSwarf(tip[0], tip[1], THETA - 32, 165, 4.5, 8.5, 1.15);
  drawHelicalSwarf(tip[0] - 8, tip[1] + 6, THETA + 26, 150, 4.0, 7.5, 1.05);
  drawHelicalSwarf(midBit[0], midBit[1], THETA - 58, 135, 3.5, 8.0, 0.95);
  drawHelicalSwarf(lowBit[0], lowBit[1], THETA + 52, 120, 3.2, 7.0, 0.9);
  drawHelicalSwarf(tip[0] + 18, tip[1] - 14, THETA - 8, 185, 5.0, 6.5, 1.2);

  // Detached C-curls and tight comma-shaped metal chips flying across the upper-right
  const chipConfigs = [
    [945, 95, 22, 18],
    [985, 145, -40, 22],
    [890, 62, 65, 16],
    [1045, 92, -15, 20],
    [1080, 175, 45, 15],
    [825, 95, -75, 19],
    [775, 145, 110, 14],
    [955, 225, -55, 17],
    [1025, 250, 30, 14],
    [855, 42, -20, 13],
    [1115, 118, 80, 16]
  ];

  for (let cc of chipConfigs) {
    const [cx, cy, ang, rad] = cc;
    // White photomontage backing rim on larger chips
    brush.set("white_chalk", "#f5f0e2", 1.3);
    brush.arc(cx, cy, rad + 2.5, ang, ang + 235);

    // Dark steel outer crescent
    brush.set("rotring", "#141311", 1.4);
    brush.arc(cx, cy, rad, ang, ang + 240);
    brush.set("2B", "#47433d", 1.2);
    brush.arc(cx, cy, rad - 3, ang + 10, ang + 225);

    // Specular silver inner glint
    brush.set("white_chalk", "#ffffff", 1.0);
    brush.arc(cx, cy, rad - 1.5, ang + 45, ang + 155);
  }

  // Dynamic motion trajectories & fine metal filings bursting from the bit tip
  for (let k = 0; k < 45; k++) {
    const burstAng = THETA + random(-75, 75);
    const d0 = random(12, 95);
    const d1 = d0 + random(8, 28);
    const x0 = tip[0] + cos(burstAng) * d0;
    const y0 = tip[1] + sin(burstAng) * d0;
    const x1 = tip[0] + cos(burstAng) * d1;
    const y1 = tip[1] + sin(burstAng) * d1;

    brush.set("graphite_needle", k % 3 === 0 ? "#f4efe2" : "#181715", random(0.45, 0.9));
    brush.line(x0, y0, x1, y1);
  }
}

// =============================================================================
// 7. FINAL PHOTOMONTAGE CUT-EDGE DEFINITION & SURFACE GRIT
// =============================================================================
function drawFinalCutoutEdgeAndGrit() {
  const cutoutPts = getFullCutoutOutline();

  // Re-reinforce the bright scissor-cut paper border where internal shading may have touched it
  for (let i = 0; i < cutoutPts.length; i++) {
    const p1 = cutoutPts[i];
    const p2 = cutoutPts[(i + 1) % cutoutPts.length];

    // Bright cut paper bevel
    brush.set("white_chalk", "#f5f1e5", 1.35);
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    // Razor-sharp outer scissor cut line
    brush.set("rotring", "#24221f", 0.55);
    brush.line(p1[0] + 1.5, p1[1] + 1.5, p2[0] + 1.5, p2[1] + 1.5);
  }
}
